-- BF-20 current-schema baseline. FRESH EMPTY LOCAL DATABASES ONLY.

-- No application rows, Auth accounts, Storage objects, cron jobs,

-- production bindings or historic migration-ledger entries are copied.

-- Historical supabase/migrations files remain unchanged; do not replay

-- them over this snapshot. Future migration integration is a separate gate.

BEGIN;

SET LOCAL search_path = pg_catalog;

SET LOCAL lock_timeout = '5s';

SET LOCAL statement_timeout = '120s';

DO $baseline$ BEGIN
  IF current_setting('haiedu.fresh_baseline', true) IS DISTINCT FROM 'local-empty-v1' THEN
    RAISE EXCEPTION 'fresh_baseline_explicit_local_mode_required';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname IN ('public','private') AND c.relkind IN ('r','p','v','m','S','f'))
     OR EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
      WHERE n.nspname IN ('public','private'))
     OR EXISTS (SELECT 1 FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace
      WHERE n.nspname IN ('public','private') AND t.typtype IN ('e','d')) THEN
    RAISE EXCEPTION 'fresh_baseline_requires_empty_application_schemas';
  END IF;
  IF to_regclass('auth.users') IS NULL OR to_regclass('auth.sessions') IS NULL
     OR to_regclass('storage.objects') IS NULL THEN
    RAISE EXCEPTION 'fresh_baseline_requires_initialized_supabase_services';
  END IF;
END $baseline$;

SET LOCAL check_function_bodies = false;

CREATE SCHEMA IF NOT EXISTS extensions;

CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;

CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;

CREATE EXTENSION IF NOT EXISTS btree_gist WITH SCHEMA extensions;

CREATE EXTENSION IF NOT EXISTS pg_cron WITH SCHEMA pg_catalog;

CREATE SCHEMA IF NOT EXISTS "private" AUTHORIZATION "postgres";

ALTER SCHEMA "private" OWNER TO "postgres";

CREATE SCHEMA IF NOT EXISTS "public" AUTHORIZATION "pg_database_owner";

ALTER SCHEMA "public" OWNER TO "pg_database_owner";

CREATE TYPE "public"."content_status" AS ENUM ('draft', 'review', 'published', 'archived');

ALTER TYPE "public"."content_status" OWNER TO postgres;

CREATE TYPE "public"."item_type" AS ENUM ('single_choice', 'true_false', 'numeric', 'quantity', 'typed_fields', 'matching', 'ordering');

ALTER TYPE "public"."item_type" OWNER TO postgres;

CREATE TYPE "public"."mastery_status" AS ENUM ('insufficient_evidence', 'needs_support', 'developing', 'secure');

ALTER TYPE "public"."mastery_status" OWNER TO postgres;

CREATE TYPE "public"."skill_layer" AS ENUM ('knowledge', 'application', 'transfer', 'reasoning');

ALTER TYPE "public"."skill_layer" OWNER TO postgres;

