CREATE OR REPLACE FUNCTION private.apply_configured_mastery_attempt(p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  a public.attempts%rowtype;
  m public.student_skill_mastery_by_release%rowtype;
  v_model_id uuid; v_rules jsonb; v_difficulty double precision; v_terms text[];
  v_alpha double precision; v_beta double precision; v_count integer; v_score double precision;
  v_weight double precision; v_hint_factor double precision; v_status public.mastery_status;
  v_before jsonb; v_after jsonb;
begin
  select * into strict a from public.attempts where id = p_attempt_id;
  select difficulty into strict v_difficulty from public.items
    where id = a.item_id and skill_id = a.skill_id;
  if a.learning_session_id is not null then
    select learning_model_configuration_id into v_model_id
    from public.learning_sessions where id = a.learning_session_id
      and student_id = a.student_id and curriculum_release_id = a.curriculum_release_id;
  end if;
  if v_model_id is null then
    select b.learning_model_configuration_id into strict v_model_id
    from public.learning_model_runtime_bindings b
    join public.item_curriculum_scopes s on s.item_id = a.item_id and s.is_primary
    join public.units u on u.id = s.unit_id and u.code = b.unit_code
    where b.curriculum_release_id = a.curriculum_release_id and b.status = 'active';
  end if;
  select configuration->'mastery' into strict v_rules
    from public.learning_model_configurations where id = v_model_id;
  -- Recognize a numeric intercept + numeric slope * difficulty, never execute SQL
  -- from configuration. Future different model contracts require their own adapter.
  v_terms := pg_catalog.regexp_match(v_rules#>>'{difficultyWeight,formula}',
    '^([0-9]+[.]?[0-9]*) [+] ([0-9]+[.]?[0-9]*)[*]difficulty$');
  if v_terms is null or not (v_rules ?& array['priorAlpha','priorBeta',
      'minimumEvidenceCount','needsSupportBelow','secureAtOrAbove',
      'hintedPositiveMultiplier','incorrectEvidenceHintReduction'])
     or not ((v_rules->'difficultyWeight') ?& array['difficultyMin','difficultyMax'])
     or (v_rules->>'incorrectEvidenceHintReduction')::boolean is distinct from false
     or (v_rules->>'priorAlpha')::numeric <= 0 or (v_rules->>'priorBeta')::numeric <= 0
     or (v_rules->>'minimumEvidenceCount')::integer < 1
     or (v_rules->>'hintedPositiveMultiplier')::numeric <= 0
     or (v_rules->>'hintedPositiveMultiplier')::numeric > 1
     or (v_rules->>'needsSupportBelow')::numeric < 0
     or (v_rules->>'secureAtOrAbove')::numeric > 1
     or (v_rules->>'secureAtOrAbove')::numeric <= (v_rules->>'needsSupportBelow')::numeric
     or (v_rules#>>'{difficultyWeight,difficultyMax}')::numeric < (v_rules#>>'{difficultyWeight,difficultyMin}')::numeric
  then raise exception 'unsupported_learning_model_mastery_contract'; end if;
  -- Preserve the TypeScript model's binary64 arithmetic, including band boundaries.
  v_difficulty := greatest((v_rules#>>'{difficultyWeight,difficultyMin}')::double precision,
    least((v_rules#>>'{difficultyWeight,difficultyMax}')::double precision,v_difficulty));
  v_weight := v_terms[1]::double precision + v_terms[2]::double precision * v_difficulty;
  if v_weight <= 0 then raise exception 'invalid_mastery_evidence_weight'; end if;
  v_score := greatest(0,least(1,a.score));
  v_hint_factor := case when a.hint_used and v_score > 0
    then (v_rules->>'hintedPositiveMultiplier')::double precision else 1 end;

  -- Covers absent rows and also serializes the legacy mirror across releases.
  -- A hash collision can only serialize unrelated writes, never mix their state.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'mastery-evidence:' || a.student_id::text || ':' || a.skill_id::text, 0));
  select * into m from public.student_skill_mastery_by_release
    where curriculum_release_id=a.curriculum_release_id and student_id=a.student_id
      and skill_id=a.skill_id for update;
  v_alpha := coalesce(m.alpha_evidence::double precision,(v_rules->>'priorAlpha')::double precision);
  v_beta := coalesce(m.beta_evidence::double precision,(v_rules->>'priorBeta')::double precision);
  v_count := coalesce(m.evidence_count,0);
  v_before := jsonb_build_object('alpha',v_alpha,'beta',v_beta,
    'masteryScore',v_alpha/(v_alpha+v_beta),'evidenceCount',v_count,
    'status',coalesce(m.status,'insufficient_evidence'::public.mastery_status));
  v_alpha := v_alpha + v_score*(v_weight*v_hint_factor);
  v_beta := v_beta + (1-v_score)*v_weight;
  v_count := v_count + 1;
  v_score := v_alpha/(v_alpha+v_beta);
  v_status := case
    when v_count < (v_rules->>'minimumEvidenceCount')::integer then 'insufficient_evidence'
    when v_score < (v_rules->>'needsSupportBelow')::double precision then 'needs_support'
    when v_score < (v_rules->>'secureAtOrAbove')::double precision then 'developing'
    else 'secure' end;
  insert into public.student_skill_mastery_by_release(
    curriculum_release_id,student_id,skill_id,alpha_evidence,beta_evidence,
    mastery_score,evidence_count,status,last_attempt_at,updated_at
  ) values (a.curriculum_release_id,a.student_id,a.skill_id,v_alpha::text::numeric,v_beta::text::numeric,
    v_score::text::numeric,v_count,v_status,a.created_at,a.created_at)
  on conflict (curriculum_release_id,student_id,skill_id) do update set
    alpha_evidence=excluded.alpha_evidence,beta_evidence=excluded.beta_evidence,
    mastery_score=excluded.mastery_score,evidence_count=excluded.evidence_count,
    status=excluded.status,last_attempt_at=excluded.last_attempt_at,updated_at=excluded.updated_at;
  insert into public.student_skill_mastery(student_id,skill_id,alpha_evidence,
    beta_evidence,mastery_score,evidence_count,status,last_attempt_at,updated_at)
  values (a.student_id,a.skill_id,v_alpha::text::numeric,v_beta::text::numeric,v_score::text::numeric,v_count,v_status,a.created_at,a.created_at)
  on conflict (student_id,skill_id) do update set
    alpha_evidence=excluded.alpha_evidence,beta_evidence=excluded.beta_evidence,
    mastery_score=excluded.mastery_score,evidence_count=excluded.evidence_count,
    status=excluded.status,last_attempt_at=excluded.last_attempt_at,updated_at=excluded.updated_at;
  v_after := jsonb_build_object('alpha',v_alpha,'beta',v_beta,'masteryScore',v_score,
    'evidenceCount',v_count,'status',v_status);
  return jsonb_build_object('masteryBefore',v_before,'masteryAfter',v_after,
    'hintUsed',a.hint_used,'modelConfigurationId',v_model_id);
end;
$function$;

ALTER FUNCTION "private"."apply_configured_mastery_attempt"(p_attempt_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.assert_item_version_snapshot(p_item uuid, p_version integer)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare s jsonb;
begin
 select snapshot into s from public.item_versions where item_id=p_item and version_no=p_version;
 if s is null or jsonb_typeof(s->'item') is distinct from 'object'
 or s#>>'{item,id}' is distinct from p_item::text
 or s#>>'{item,version_no}' is distinct from p_version::text
 or jsonb_typeof(s#>'{item,skill_id}') is distinct from 'string'
 or jsonb_typeof(s#>'{item,difficulty}') is distinct from 'number'
 or jsonb_typeof(s#>'{item,prompt_hy}') is distinct from 'string'
 or jsonb_typeof(s->'options') is distinct from 'array'
 or s#>'{answerKey,answer}' is null or s#>'{answerKey,answer}'='null'::jsonb
 then raise exception 'item_version_snapshot_required:%:%',p_item,p_version using errcode='23514';end if;
end;$function$;

ALTER FUNCTION "private"."assert_item_version_snapshot"(p_item uuid, p_version integer) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.assert_school_admin_successor_14b(p_school uuid, p_excluded_membership uuid DEFAULT NULL::uuid, p_excluded_person uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform pg_advisory_xact_lock(hashtextextended('school-admin-closure:'||p_school::text,0));
  if not exists (select 1 from public.institutional_memberships m join public.profiles p on p.id=m.person_id
    where m.school_id=p_school and m.role='school_admin' and m.status='active'
      and m.valid_from<=now() and (m.valid_to is null or m.valid_to>now())
      and p.role::text='school_admin' and p.account_status='active'
      and (p_excluded_membership is null or m.id<>p_excluded_membership)
      and (p_excluded_person is null or m.person_id<>p_excluded_person)) then
    raise exception 'last_active_school_admin_protected' using errcode='P0001';
  end if;
end $function$;

ALTER FUNCTION "private"."assert_school_admin_successor_14b"(p_school uuid, p_excluded_membership uuid, p_excluded_person uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.assert_student_dashboard_session(p_student uuid, p_auth uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r record; t timestamptz;
begin
 select p.role,p.account_status,u.deleted_at,u.banned_until,s.not_after into r
 from public.profiles p join auth.users u on u.id=p.id
 join auth.sessions s on s.user_id=p.id and s.id=p_auth
 where p.id=p_student for share of p,u,s;
 t:=clock_timestamp();
 if not found or r.role<>'student' or r.account_status<>'active' or r.deleted_at is not null
 or (r.banned_until is not null and r.banned_until>t) or (r.not_after is not null and r.not_after<=t)
 then raise exception 'learning_context_unavailable'; end if;
end;
$function$;

ALTER FUNCTION "private"."assert_student_dashboard_session"(p_student uuid, p_auth uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.assessed_audio_evidence(p_session uuid, p_audio uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare d public.learning_assessed_audio%rowtype; a jsonb:=private.assessed_audio_policy(p_session); family uuid;
begin
 select * into d from public.learning_assessed_audio where session_id=p_session and audio_version_id=p_audio for share;
 if not found or d.completed_plays<1 or d.completed_plays>(a->>'maximumPlays')::integer then raise exception 'audio_playback_incomplete'; end if;
 select source_family_id into family from public.learning_audio_versions where id=p_audio and revoked_at is null;
 if family is null then raise exception 'audio_unavailable'; end if;
 return jsonb_build_object('schemaVersion','haiedu-audio-evidence-v2','audioVersionId',p_audio,'sourceFamilyId',family,
 'playbackPolicy',a,'completedPlays',d.completed_plays,'transcriptUsed',false,'completionObservedAt',d.completed_at);
end;
$function$;

ALTER FUNCTION "private"."assessed_audio_evidence"(p_session uuid, p_audio uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.assessed_audio_policy(p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare p jsonb;
begin
 select b.policy_snapshot into p from public.learning_sessions s join public.assessment_policy_bindings b on b.id=s.assessment_policy_binding_id where s.id=p_session;
 return private.validate_assessed_audio_policy(p);
end;
$function$;

ALTER FUNCTION "private"."assessed_audio_policy"(p_session uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.assessed_audio_questions(p_session uuid, p_audio uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.learning_sessions%rowtype; li public.learning_session_items%rowtype; i public.items%rowtype;
 rows jsonb:='[]'; opts jsonb; presentation jsonb;
begin
 select * into strict s from public.learning_sessions where id=p_session;
 perform private.assessed_audio_policy(s.id);
 for li in select l.* from public.learning_session_items l where l.session_id=s.id order by l.ordinal loop
  select * into strict i from public.items where id=li.item_id for share;
  if private.task_set_stimulus(i.stimulus,i.id,s.curriculum_release_id,s.governed_unit_id)->>'audioVersionId' is distinct from p_audio::text then continue; end if;
  perform private.validate_assigned_source(li.id,i.id);
  if i.status<>'published' or not exists(select 1 from public.assessment_blueprint_items bi join public.assessment_blueprints bp on bp.id=bi.assessment_blueprint_id join public.assessment_pool_items pi on pi.pool_id=bp.assessment_pool_id and pi.item_id=i.id join public.assessment_pools pool on pool.id=pi.pool_id where bi.assessment_blueprint_id=s.assessment_blueprint_id and bi.item_id=i.id and bi.item_version_snapshot=i.version_no and pi.enabled and pool.status='active') then raise exception 'audio_access_denied'; end if;
  if i.item_type::text='single_choice' then
   presentation:=public.service_ensure_session_item_option_order(li.id);
   select jsonb_agg(jsonb_build_object('option_key',private.governed_presentation_key(x.ordinal::integer),'content_hy',o.content_hy) order by x.ordinal) into opts
   from jsonb_array_elements_text(presentation->'canonicalOptionOrder') with ordinality x(value,ordinal) join public.item_options o on o.item_id=i.id and o.option_key=x.value;
  else select jsonb_agg(jsonb_build_object('option_key',option_key,'content_hy',content_hy) order by display_order) into opts from public.item_options where item_id=i.id; end if;
  perform public.service_record_item_exposure(s.student_id,s.id,li.id,i.id,clock_timestamp());
  rows:=rows||jsonb_build_array(jsonb_build_object('sessionItemId',li.id,'position',li.ordinal,'type',i.item_type,'promptHy',i.prompt_hy,'options',coalesce(opts,'[]'),
   'responseDefinition',case when i.item_type::text='typed_fields' then i.config->'responseDefinition' when i.item_type::text in ('matching','ordering') then private.present_arrangement_definition(i.item_type::text,i.config->'responseDefinition',li.id::text) else null end));
 end loop;
 return rows;
end;
$function$;

ALTER FUNCTION "private"."assessed_audio_questions"(p_session uuid, p_audio uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.assessed_audio_state(p_session uuid, p_audio uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
