begin
 select * into d from public.learning_assessed_audio where session_id=p_session and audio_version_id=p_audio;
 return jsonb_build_object('schemaVersion','haiedu-assessed-audio-state-v1','maximumPlays',(a->>'maximumPlays')::integer,
 'completedPlays',coalesce(d.completed_plays,0),'remainingPlays',(a->>'maximumPlays')::integer-coalesce(d.completed_plays,0),
 'playId',d.play_id,'resumePositionMs',coalesce(d.position_ms,0),'completed',coalesce(d.completed_plays,0)>0,
 'interrupted',d.failed_at is not null,'canEndUnscored',d.failed_at is not null);
end;
$function$;

ALTER FUNCTION "private"."assessed_audio_state"(p_session uuid, p_audio uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.assessment_result_v2(p_policy jsonb, p_skills jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare g jsonb; groups jsonb:='[]'; result jsonb; correct_n integer; answered_n integer;
 scored_correct integer; scored_total integer; passed boolean; percent numeric;
begin
 if p_policy->>'schemaVersion' in ('haiedu-assessment-policy-v3','haiedu-assessment-policy-v4') then return private.assessment_result_v3(p_policy,p_skills); end if;
 if p_policy->>'schemaVersion' is distinct from 'haiedu-assessment-policy-v2' then return null; end if;
 for g in select value from jsonb_array_elements(p_policy->'reportingGroups') loop
   select coalesce(sum((s->>'correct')::integer),0),coalesce(sum((s->>'total')::integer),0) into correct_n,answered_n
   from jsonb_array_elements(p_skills) s where g->'skillIds' ? (s->>'skillId');
   groups:=groups||jsonb_build_array(jsonb_build_object('key',g->'key','label',g->'label','skillIds',g->'skillIds',
     'determinesPass',p_policy->>'mode'='mastery_check' and coalesce(p_policy->'scoredSkillIds' @> (g->'skillIds'),false),
     'correct',correct_n,'answered',answered_n,'percent',round(100.0*correct_n/nullif(answered_n,0))));
 end loop;
 select coalesce(sum((s->>'correct')::integer),0),coalesce(sum((s->>'total')::integer),0) into correct_n,answered_n from jsonb_array_elements(p_skills) s;
 result:=jsonb_build_object('schemaVersion','haiedu-assessment-result-v2','groups',groups,
   'overallScore',jsonb_build_object('correct',correct_n,'answered',answered_n,'percent',round(100.0*correct_n/nullif(answered_n,0))),
   'readinessSkillIds',p_policy->'readinessSkillIds','scoredSkillIds',p_policy->'scoredSkillIds');
 if p_policy->>'mode'='mastery_check' then
   select coalesce(sum((s->>'correct')::integer),0),coalesce(sum((s->>'total')::integer),0) into scored_correct,scored_total
   from jsonb_array_elements(p_skills) s where p_policy->'scoredSkillIds' ? (s->>'skillId');
   if scored_total=0 then raise exception 'assessment_result_scope_invalid'; end if;
   percent:=round(100.0*scored_correct/scored_total);
   passed:=100.0*scored_correct/scored_total>=(p_policy->>'minimumPercent')::numeric
   and not exists(select 1 from jsonb_each_text(p_policy->'minimumCorrectBySkill') minimum where
     coalesce((select (s->>'correct')::integer from jsonb_array_elements(p_skills) s where s->>'skillId'=minimum.key),0)<minimum.value::integer);
   result:=result||jsonb_build_object('passed',passed,'score',jsonb_build_object('correct',scored_correct,'answered',scored_total,'percent',percent),
     'passCriteria',jsonb_build_object('minimumPercent',p_policy->'minimumPercent','minimumCorrectBySkill',p_policy->'minimumCorrectBySkill','scoredSkillIds',p_policy->'scoredSkillIds'));
 end if;
 return result;
end;
$function$;

ALTER FUNCTION "private"."assessment_result_v2"(p_policy jsonb, p_skills jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.assessment_result_v3(p_policy jsonb, p_skills jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare g jsonb; groups jsonb:='[]'; result jsonb; earned numeric; total integer; correct_n integer; score jsonb; passed boolean;
begin
 for g in select value from jsonb_array_elements(p_policy->'reportingGroups') loop
  select coalesce(sum((s->>'earned')::numeric),0),coalesce(sum((s->>'total')::integer),0),coalesce(sum((s->>'correct')::integer),0)
  into earned,total,correct_n from jsonb_array_elements(p_skills) s where g->'skillIds' ? (s->>'skillId');
  groups:=groups||jsonb_build_array(g||jsonb_build_object('earned',earned,'possible',total,'correct',correct_n,'answered',total,'percent',round(100*earned/nullif(total,0)),
   'determinesPass',p_policy->>'mode'='mastery_check' and coalesce(p_policy->'scoredSkillIds' @> (g->'skillIds'),false)));
 end loop;
 select coalesce(sum((s->>'earned')::numeric),0),coalesce(sum((s->>'total')::integer),0),coalesce(sum((s->>'correct')::integer),0)
 into earned,total,correct_n from jsonb_array_elements(p_skills) s;
 result:=jsonb_build_object('schemaVersion','haiedu-assessment-result-v3','scoringStrategy','normalized-item-score-v1','itemWeight',1,'groups',groups,
  'overallScore',jsonb_build_object('earned',earned,'possible',total,'correct',correct_n,'answered',total,'percent',round(100*earned/nullif(total,0))),
  'readinessSkillIds',p_policy->'readinessSkillIds','scoredSkillIds',p_policy->'scoredSkillIds');
 if p_policy->>'mode'='mastery_check' then
  select coalesce(sum((s->>'earned')::numeric),0),coalesce(sum((s->>'total')::integer),0),coalesce(sum((s->>'correct')::integer),0)
  into earned,total,correct_n from jsonb_array_elements(p_skills) s where p_policy->'scoredSkillIds' ? (s->>'skillId');
  if total=0 then raise exception 'assessment_result_scope_invalid'; end if;
  passed:=100*earned/total>=(p_policy->>'minimumPercent')::numeric and not exists(select 1 from jsonb_each_text(p_policy->'minimumCorrectBySkill') minimum
   where coalesce((select (s->>'correct')::integer from jsonb_array_elements(p_skills) s where s->>'skillId'=minimum.key),0)<minimum.value::integer);
  result:=result||jsonb_build_object('passed',passed,'score',jsonb_build_object('earned',earned,'possible',total,'correct',correct_n,'answered',total,'percent',round(100*earned/total)),
   'passCriteria',jsonb_build_object('minimumPercent',p_policy->'minimumPercent','minimumCorrectBySkill',p_policy->'minimumCorrectBySkill','scoredSkillIds',p_policy->'scoredSkillIds'));
 end if;
 return result;
end;
$function$;

ALTER FUNCTION "private"."assessment_result_v3"(p_policy jsonb, p_skills jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.assessment_skill_set_valid(p_value jsonb, p_scope jsonb DEFAULT NULL::jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 select case when jsonb_typeof(p_value) is distinct from 'array' then false else
 jsonb_array_length(p_value)>0
 and (select count(distinct x) from jsonb_array_elements(p_value) x)=jsonb_array_length(p_value)
 and not exists(select 1 from jsonb_array_elements(p_value) x where jsonb_typeof(x)<>'string'
 or trim(both '"' from x::text) !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
 or (p_scope is not null and not (p_scope @> jsonb_build_array(x)))) end;
$function$;

ALTER FUNCTION "private"."assessment_skill_set_valid"(p_value jsonb, p_scope jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.attach_governed_lifecycle(p_session uuid, p_details jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.learning_sessions%rowtype; review public.chapter_review_sessions%rowtype;
begin
 select * into strict s from public.learning_sessions where id=p_session;
 if s.mode='mastery_check' then
   insert into public.mastery_check_attempts(chapter_mastery_state_id,learning_session_id,attempt_number,academic_mastery_policy_id,preceding_required_review_id,status,started_at)
   values((p_details->>'stateId')::uuid,s.id,(p_details->>'attemptNumber')::smallint,s.academic_mastery_policy_id,(p_details->>'precedingReviewId')::uuid,'active',s.started_at);
 elsif s.mode='chapter_review' then
   insert into public.chapter_review_sessions(learning_session_id,chapter_mastery_state_id,review_requirement_id,academic_mastery_policy_id,review_context,target_question_count,
   review_cycle_id,review_cycle_number,review_session_number,preceding_mastery_attempt_number,eligible_pool_size)
   values(s.id,(p_details->>'stateId')::uuid,(p_details->>'reviewRequirementId')::uuid,s.academic_mastery_policy_id,p_details->>'reviewContext',s.planned_item_count,
   (p_details->>'reviewCycleId')::uuid,(p_details->>'reviewCycleNumber')::integer,(p_details->>'reviewSessionNumber')::integer,
   (p_details->>'precedingMasteryAttemptNumber')::smallint,(p_details->>'eligiblePoolSize')::integer) returning * into review;
   insert into public.chapter_review_item_exposures(chapter_review_session_id,review_cycle_id,learning_session_item_id,item_id,item_code,item_version,item_template_id,template_code,item_family_id,family_code,
   variant_key,skill_id,selection_reason,prior_exposure_count,seen_in_current_cycle,exact_repeat,pool_exhausted)
   select review.id,review.review_cycle_id,li.id,i.id,i.code,i.version_no,i.item_template_id,t.code,t.item_family_id,f.code,i.variant_key,i.skill_id,li.selection_reason,
   (select count(*) from public.chapter_review_item_exposures old join public.chapter_review_sessions cr on cr.id=old.chapter_review_session_id where cr.chapter_mastery_state_id=review.chapter_mastery_state_id and old.item_id=i.id),
   exists(select 1 from public.chapter_review_item_exposures old where old.review_cycle_id=review.review_cycle_id and old.item_id=i.id),
   exists(select 1 from public.chapter_review_item_exposures old where old.review_cycle_id=review.review_cycle_id and old.item_id=i.id),
   exists(select 1 from public.chapter_review_item_exposures old where old.review_cycle_id=review.review_cycle_id and old.item_id=i.id)
   from public.learning_session_items li join public.items i on i.id=li.item_id join public.item_templates t on t.id=i.item_template_id join public.item_families f on f.id=t.item_family_id where li.session_id=s.id;
 end if;
end;
$function$;

ALTER FUNCTION "private"."attach_governed_lifecycle"(p_session uuid, p_details jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.audit_profile_security_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is not null and (old.role is distinct from new.role or old.account_status is distinct from new.account_status) then
    insert into public.security_audit_log(actor_user_id, actor_role, action, target_user_id, target_type, details)
    values (
      auth.uid(),
      private.current_user_role()::text,
      'profile.security_changed',
      new.id,
      'user',
      jsonb_build_object('old_role', old.role::text, 'new_role', new.role::text, 'old_status', old.account_status, 'new_status', new.account_status)
    );
  end if;
  return new;
end;
$function$;

ALTER FUNCTION "private"."audit_profile_security_change"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.authorized_governed_result(p_student uuid, p_auth uuid, p_enrollment uuid, p_release uuid, p_unit uuid, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 -- Row locks protect revocations; the final clock check also protects expiry
 -- while waiting for content, presentation, guide or mastery-evidence locks.
 perform private.lock_student_learning_context(p_student,p_auth,p_enrollment,p_release,p_unit);
 return p_result;
end;
$function$;

ALTER FUNCTION "private"."authorized_governed_result"(p_student uuid, p_auth uuid, p_enrollment uuid, p_release uuid, p_unit uuid, p_result jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.authorized_legacy_answer_result(p_student_id uuid, p_auth_session_id uuid, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare profile_status text; deleted_at timestamptz; banned_until timestamptz;
  not_after timestamptz; checked_at timestamptz;
begin
  select p.account_status into profile_status from public.profiles p
    where p.id=p_student_id for share;
  if not found or profile_status is distinct from 'active' then raise exception 'learning_context_unavailable'; end if;
  select u.deleted_at,u.banned_until into deleted_at,banned_until from auth.users u
    where u.id=p_student_id for share;
  if not found then raise exception 'learning_context_unavailable'; end if;
  select a.not_after into not_after from auth.sessions a
    where a.id=p_auth_session_id and a.user_id=p_student_id for share;
  if not found then raise exception 'learning_context_unavailable'; end if;
  checked_at:=clock_timestamp();
  if deleted_at is not null or (banned_until is not null and banned_until>checked_at)
    or (not_after is not null and not_after<=checked_at) then raise exception 'learning_context_unavailable'; end if;
  return p_result;
end;
$function$;

ALTER FUNCTION "private"."authorized_legacy_answer_result"(p_student_id uuid, p_auth_session_id uuid, p_result jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.bind_attempt_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_release_id uuid;
  v_blueprint_id uuid;
begin
  if tg_op = 'UPDATE' then
    if old.curriculum_release_id is distinct from new.curriculum_release_id
       or old.assessment_blueprint_id is distinct from new.assessment_blueprint_id
       or old.provenance_status is distinct from new.provenance_status then
      raise exception 'attempt_provenance_is_immutable';
    end if;
    return new;
  end if;

  if new.learning_session_id is not null then
    select curriculum_release_id, assessment_blueprint_id
      into v_release_id, v_blueprint_id
    from public.learning_sessions where id = new.learning_session_id;
  else
    select cr.id, ab.id into v_release_id, v_blueprint_id
    from public.item_curriculum_scopes ics
    join public.units u on u.id = ics.unit_id
    join public.curriculum_release_units cru on cru.unit_id = u.id
    join public.curriculum_releases cr on cr.id = cru.curriculum_release_id
      and cr.status in ('production', 'pilot')
    join public.assessment_blueprints ab on ab.curriculum_release_id = cr.id
      and ab.unit_id = u.id and ab.purpose = 'practice' and ab.status = cr.status
    where ics.item_id = new.item_id and ics.is_primary
    order by case cr.status when 'production' then 1 else 2 end, cr.release_number desc
    limit 1;
  end if;
  if v_release_id is null or v_blueprint_id is null then
    raise exception 'attempt_curriculum_provenance_unresolvable';
  end if;
  if new.curriculum_release_id is not null and new.curriculum_release_id <> v_release_id then
    raise exception 'attempt_curriculum_release_mismatch';
  end if;
  if new.assessment_blueprint_id is not null and new.assessment_blueprint_id <> v_blueprint_id then
    raise exception 'attempt_blueprint_mismatch';
  end if;
  new.curriculum_release_id := v_release_id;
  new.assessment_blueprint_id := v_blueprint_id;
  new.provenance_status := 'exact';
  return new;
end;
$function$;

ALTER FUNCTION "private"."bind_attempt_provenance"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.bind_exposure_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_release_id uuid;
  v_blueprint_id uuid;
begin
  if tg_op = 'UPDATE' then
    if old.curriculum_release_id is distinct from new.curriculum_release_id
       or old.assessment_blueprint_id is distinct from new.assessment_blueprint_id
       or old.provenance_status is distinct from new.provenance_status then
      raise exception 'exposure_provenance_is_immutable';
    end if;
    return new;
  end if;
  if new.session_id is not null then
    select curriculum_release_id, assessment_blueprint_id
      into v_release_id, v_blueprint_id
    from public.learning_sessions where id = new.session_id;
  end if;
  if v_release_id is null then
    select cr.id, ab.id into v_release_id, v_blueprint_id
    from public.item_curriculum_scopes ics
    join public.units u on u.id = ics.unit_id
    join public.curriculum_release_units cru on cru.unit_id = u.id
    join public.curriculum_releases cr on cr.id = cru.curriculum_release_id
      and cr.status in ('production', 'pilot')
    join public.assessment_blueprints ab on ab.curriculum_release_id = cr.id
      and ab.unit_id = u.id and ab.purpose = new.purpose and ab.status = cr.status
    where ics.item_id = new.item_id and ics.is_primary
    order by case cr.status when 'production' then 1 else 2 end, cr.release_number desc
    limit 1;
  end if;
  if v_release_id is null or v_blueprint_id is null then
    raise exception 'exposure_curriculum_provenance_unresolvable';
  end if;
  new.curriculum_release_id := v_release_id;
  new.assessment_blueprint_id := v_blueprint_id;
  new.provenance_status := 'exact';
  return new;
end;
$function$;

ALTER FUNCTION "private"."bind_exposure_provenance"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.bind_learning_session_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_release_id uuid;
  v_blueprint_id uuid;
begin
  if tg_op = 'UPDATE' then
    if old.curriculum_release_id is distinct from new.curriculum_release_id
       or old.assessment_blueprint_id is distinct from new.assessment_blueprint_id
       or old.provenance_status is distinct from new.provenance_status then
      raise exception 'learning_session_provenance_is_immutable';
    end if;
    return new;
  end if;

  if new.curriculum_release_id is null or new.assessment_blueprint_id is null then
    select cr.id, ab.id into v_release_id, v_blueprint_id
    from public.curriculum_releases cr
    join public.curriculum_release_units cru on cru.curriculum_release_id = cr.id
      and cru.unit_code_snapshot = new.unit_code
    join public.assessment_blueprints ab on ab.curriculum_release_id = cr.id
      and ab.unit_id = cru.unit_id and ab.purpose = new.mode
      and ab.status = cr.status
    where cr.status in ('production', 'pilot')
    order by case cr.status when 'production' then 1 else 2 end, cr.release_number desc
    limit 1;
    if v_release_id is null or v_blueprint_id is null then
      raise exception 'no_active_curriculum_release_blueprint_for:%:%', new.unit_code, new.mode;
    end if;
    new.curriculum_release_id := v_release_id;
    new.assessment_blueprint_id := v_blueprint_id;
    new.provenance_status := 'exact';
  end if;

  if not exists (
    select 1
    from public.assessment_blueprints ab
    join public.curriculum_release_units cru
      on cru.curriculum_release_id = ab.curriculum_release_id and cru.unit_id = ab.unit_id
    where ab.id = new.assessment_blueprint_id
      and ab.curriculum_release_id = new.curriculum_release_id
      and ab.purpose = new.mode
      and cru.unit_code_snapshot = new.unit_code
  ) then
    raise exception 'learning_session_release_blueprint_mismatch';
  end if;
  new.provenance_status := coalesce(new.provenance_status, 'exact');
  return new;
end;
$function$;

ALTER FUNCTION "private"."bind_learning_session_provenance"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.bind_mastery_form_selection(p_binding_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare b public.assessment_policy_bindings%rowtype; manifest jsonb; previous jsonb; protected_id uuid;
begin
 select * into strict b from public.assessment_policy_bindings where id=p_binding_id;
 -- Validation is read-only; only actual binding advances durable mutation fences.
 for protected_id in select f.id from public.assessment_forms f join public.assessment_blueprints bp on bp.assessment_pool_id=f.pool_id
   where bp.id=b.assessment_blueprint_id and bp.configuration_snapshot ? 'masteryFormSelection' order by f.id loop
   perform private.advance_mastery_form_fence('form',protected_id);
 end loop;
 for protected_id in select distinct fi.item_id from public.assessment_form_items fi join public.assessment_forms f on f.id=fi.form_id
   join public.assessment_blueprints bp on bp.assessment_pool_id=f.pool_id
   where bp.id=b.assessment_blueprint_id and bp.configuration_snapshot ? 'masteryFormSelection' order by fi.item_id loop
   perform private.advance_mastery_form_fence('item',protected_id);
 end loop;
 manifest:=private.validate_mastery_form_selection(b.assessment_blueprint_id,b.policy_snapshot);
 if manifest is null then return; end if;
 if not exists(select 1 from private.mastery_form_selection_bindings where assessment_policy_binding_id=b.id)
   and exists(select 1 from public.learning_sessions where assessment_policy_binding_id=b.id)
 then raise exception 'mastery_form_selection_requires_new_blueprint'; end if;
 insert into private.mastery_form_selection_bindings(assessment_policy_binding_id,selection_snapshot)
 values(b.id,manifest) on conflict(assessment_policy_binding_id) do nothing;
 select selection_snapshot into strict previous from private.mastery_form_selection_bindings where assessment_policy_binding_id=b.id;
 if previous is distinct from manifest then raise exception 'mastery_form_selection_snapshot_conflict'; end if;
end;
$function$;

ALTER FUNCTION "private"."bind_mastery_form_selection"(p_binding_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.capture_learning_session_item_option_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_student_id uuid;
  v_item_type text;
  v_item_version integer;
  v_order text[];
  v_algorithm text;
begin
  select ls.student_id into v_student_id
  from public.learning_sessions ls
  where ls.id=new.session_id;

  select i.item_type::text,i.version_no
    into v_item_type,v_item_version
  from public.items i
  where i.id=new.item_id;

  if v_student_id is null or v_item_type is null then
    raise exception 'session_item_option_context_missing';
  end if;

  if v_item_type <> 'single_choice' then
    return new;
  end if;

  select g.option_order,g.algorithm_version
    into v_order,v_algorithm
  from private.generate_mcq_option_order(v_student_id,new.item_id) g;

  insert into private.learning_session_item_option_orders(
    session_item_id,session_id,student_id,item_id,item_version_no,
    canonical_option_order,algorithm_version,created_at
  ) values (
    new.id,new.session_id,v_student_id,new.item_id,v_item_version,
    v_order,v_algorithm,clock_timestamp()
  )
  on conflict (session_item_id) do nothing;

  return new;
end;
$function$;

ALTER FUNCTION "private"."capture_learning_session_item_option_order"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.capture_published_item_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare k uuid; i public.items%rowtype; current_snapshot jsonb; old_snapshot jsonb;
begin
 if tg_table_name='items' then k:=coalesce(new.id,old.id);else k:=coalesce(new.item_id,old.item_id);end if;
 select * into i from public.items where id=k for update;
 if not found or i.status::text<>'published' then return null;end if;
 current_snapshot:=private.current_item_version_snapshot(k);
 select snapshot into old_snapshot from public.item_versions where item_id=k and version_no=i.version_no;
 if old_snapshot is null then
  -- Never convert an already-exposed version into invented historical evidence.
  if exists(select 1 from public.assessment_blueprint_items bi join public.assessment_blueprints b on b.id=bi.assessment_blueprint_id
    where bi.item_id=k and bi.item_version_snapshot=i.version_no and b.status<>'draft')
   or exists(select 1 from public.attempts a where a.item_id=k)
  then raise exception 'historical_item_snapshot_recovery_required:%:%',k,i.version_no using errcode='23514';end if;
  insert into public.item_versions(item_id,version_no,snapshot,change_summary)
  values(k,i.version_no,current_snapshot,'Atomic publication snapshot; not a historical recovery') on conflict(item_id,version_no) do nothing;
  select snapshot into old_snapshot from public.item_versions where item_id=k and version_no=i.version_no;
 end if;
 perform private.assert_item_version_snapshot(k,i.version_no);
 if private.item_snapshot_assessment_content(old_snapshot) is distinct from private.item_snapshot_assessment_content(current_snapshot)
 then raise exception 'published_item_snapshot_content_mismatch:%:%',k,i.version_no using errcode='23514';end if;
 return null;
end;$function$;

ALTER FUNCTION "private"."capture_published_item_snapshot"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.classify_prospective_pilot_session()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_run public.pilot_runs%rowtype;
begin
  select * into v_run
  from public.pilot_runs
  where run_key = 'sprint_11l_physics7_chapter1_pilot';

  if v_run.id is null
     or new.curriculum_release_id <> v_run.target_curriculum_release_id
     or not private.pilot_participant_session_is_eligible(
       v_run.id, new.student_id, new.started_at
     ) then
    return new;
  end if;

  insert into public.pilot_evidence_classifications (
    pilot_run_id, learning_session_id, classification, reason_code,
    rationale, evidence_snapshot
  ) values (
    v_run.id,
    new.id,
    case when new.status = 'completed' then 'compatible' else 'incompatible' end,
    case when new.status = 'completed'
      then 'exact_release_completed' else 'exact_release_noncompleted' end,
    case when new.status = 'completed'
      then 'Prospective authorized adult feasibility-pilot session completed on the exact target release.'
      else 'Prospective authorized adult feasibility-pilot trajectory remains incomplete and is retained for metric-specific eligibility.' end,
    jsonb_build_object(
      'prospective', true,
      'mode', new.mode,
      'status', new.status,
      'provenanceStatus', new.provenance_status,
      'modelProvenanceStatus', new.model_provenance_status,
      'runtimeProvenanceStatus', new.runtime_provenance_status,
      'curriculumReleaseId', new.curriculum_release_id,
      'assessmentBlueprintId', new.assessment_blueprint_id,
      'startedAt', new.started_at,
      'completedAt', new.completed_at
    )
  )
  on conflict (pilot_run_id, learning_session_id) do update set
    classification = excluded.classification,
    reason_code = excluded.reason_code,
    rationale = excluded.rationale,
    evidence_snapshot = excluded.evidence_snapshot,
    classified_at = now(),
    updated_at = now();

  return new;
end;
$function$;

