CREATE OR REPLACE FUNCTION private.guard_registered_mastery_form_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare form_id uuid;
begin
 for form_id in select distinct x from unnest(case when tg_op='INSERT' then array[new.form_id]
   when tg_op='DELETE' then array[old.form_id] else array[old.form_id,new.form_id] end) x order by x loop
   perform private.advance_mastery_form_fence('form',form_id);
   perform 1 from public.assessment_forms where id=form_id for update;
   if exists(select 1 from private.mastery_form_selection_bindings
     where selection_snapshot->'forms' @> jsonb_build_array(jsonb_build_object('formId',form_id)))
   then raise exception 'mastery_form_membership_immutable'; end if;
 end loop;
 return case when tg_op='DELETE' then old else new end;
end;
$function$;

ALTER FUNCTION "private"."guard_registered_mastery_form_membership"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.guard_registered_mastery_pool_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare protected_item uuid; protected_pool uuid;
begin
 -- Lock the parent before its fence, matching a pool row update. This also
 -- covers an empty pool whose first membership is still uncommitted.
 for protected_pool in select distinct x from unnest(case when tg_op='INSERT' then array[new.pool_id] else array[old.pool_id,new.pool_id] end) x order by x loop
   perform 1 from public.assessment_pools where id=protected_pool for share;
   perform private.advance_mastery_form_fence('pool',protected_pool);
 end loop;
 for protected_item in select distinct x from unnest(case when tg_op='INSERT' then array[new.item_id] else array[old.item_id,new.item_id] end) x order by x loop
   perform private.advance_mastery_form_fence('item',protected_item);
 end loop;
 if new.enabled and exists(select 1 from private.mastery_form_selection_bindings
   where selection_snapshot->'forms' @> jsonb_build_array(jsonb_build_object('items',jsonb_build_array(jsonb_build_object('itemId',new.item_id)))))
   and exists(select 1 from public.assessment_pools where id=new.pool_id and (purpose<>'mastery_check' or not is_protected))
 then raise exception 'mastery_form_pool_overlap'; end if;
 return new;
end;
$function$;

ALTER FUNCTION "private"."guard_registered_mastery_pool_membership"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.guard_registered_mastery_pool_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare protected_item uuid;
begin
 if (new.purpose,new.is_protected,new.status) is not distinct from (old.purpose,old.is_protected,old.status) then return new; end if;
 perform private.advance_mastery_form_fence('pool',new.id);
 for protected_item in select item_id from public.assessment_pool_items where pool_id=new.id and enabled order by item_id loop
   perform private.advance_mastery_form_fence('item',protected_item);
   if (new.purpose<>'mastery_check' or not new.is_protected) and exists(select 1 from private.mastery_form_selection_bindings
     where selection_snapshot->'forms' @> jsonb_build_array(jsonb_build_object('items',jsonb_build_array(jsonb_build_object('itemId',protected_item)))))
   then raise exception 'mastery_form_pool_overlap'; end if;
 end loop;
 return new;
end;
$function$;

ALTER FUNCTION "private"."guard_registered_mastery_pool_scope"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.guard_release_snapshot_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record; ids uuid[];
begin
  perform private.require_curriculum_governance_transaction();
  ids:=array_remove(array[
    case when tg_op<>'INSERT' then old.curriculum_release_id end,
    case when tg_op<>'DELETE' then new.curriculum_release_id end
  ],null);
  for r in select id,status from public.curriculum_releases
    where id=any(ids) order by id for update
  loop
    if r.status<>'draft' then
      raise exception 'activated_curriculum_release_snapshot_is_immutable:%',r.id;
    end if;
  end loop;
  if tg_op='DELETE' then return old; end if;
  return new;
end;
$function$;

ALTER FUNCTION "private"."guard_release_snapshot_immutability"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.guard_release_unit_programme()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare programme uuid; unit_programme uuid;
begin
  perform private.require_curriculum_governance_transaction();
  -- Existing snapshot trigger obtains the same lock; this also ensures a
  -- concurrent programme change cannot race an INSERT into the draft snapshot.
  select subject_program_id into programme from public.curriculum_releases
    where id=new.curriculum_release_id for update;
  select subject_program_id into unit_programme from public.units where id=new.unit_id for share;
  if not found or unit_programme is distinct from programme
  then raise exception 'curriculum_release_unit_programme_mismatch'; end if;
  return new;
end;
$function$;

ALTER FUNCTION "private"."guard_release_unit_programme"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.guard_school_admin_membership_14b()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if old.role='school_admin' and old.status='active' and old.valid_from<=now()
     and (old.valid_to is null or old.valid_to>now())
     and exists(select 1 from public.profiles p where p.id=old.person_id
       and p.role::text='school_admin' and p.account_status='active') then
    if tg_op='UPDATE' and new.school_id=old.school_id and new.person_id=old.person_id
       and new.role='school_admin' and new.status='active' and new.valid_from<=now()
       and (new.valid_to is null or new.valid_to>now()) then return new; end if;
    perform private.assert_school_admin_successor_14b(old.school_id,old.id,null);
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end $function$;

ALTER FUNCTION "private"."guard_school_admin_membership_14b"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.guard_school_admin_profile_14b()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_school uuid;
begin
  if old.role::text='school_admin' and old.account_status='active' then
    if tg_op='UPDATE' and new.role::text='school_admin' and new.account_status='active' then return new; end if;
    -- Same lock used by membership removal; UUID order is stable for multi-school administrators.
    for v_school in select distinct m.school_id from public.institutional_memberships m
      where m.person_id=old.id and m.role='school_admin' and m.status='active'
        and m.valid_from<=now() and (m.valid_to is null or m.valid_to>now()) order by m.school_id loop
      perform private.assert_school_admin_successor_14b(v_school,null,old.id);
    end loop;
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end $function$;

ALTER FUNCTION "private"."guard_school_admin_profile_14b"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.guard_source_family_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.learning_sessions%rowtype; i public.items%rowtype; t public.learning_task_set_versions%rowtype;
begin
 if tg_op='UPDATE' then
  if (new.source_family_id_snapshot,new.task_set_version_id,new.task_set_member_ordinal) is distinct from (old.source_family_id_snapshot,old.task_set_version_id,old.task_set_member_ordinal) then raise exception 'source_assignment_immutable'; end if;
  if old.source_family_id_snapshot is not null and (new.item_id,new.session_id) is distinct from (old.item_id,old.session_id) then raise exception 'source_assignment_immutable'; end if;
  return new;
 end if;
 select * into strict i from public.items where id=new.item_id;
 new.source_family_id_snapshot:=private.item_source_family(i.id);new.task_set_version_id:=null;new.task_set_member_ordinal:=null;
 if coalesce(i.stimulus->>'kind','') not in ('task_set','audio') then return new; end if;
 select * into strict s from public.learning_sessions where id=new.session_id;
 perform pg_advisory_xact_lock(hashtextextended('governed-mastery-form:'||s.student_id::text,0));
 perform private.advance_mastery_form_fence('learner',s.student_id);
 if s.assessment_policy_binding_id is null then raise exception 'shared_source_requires_governed_session'; end if;
 if i.stimulus->>'kind'='task_set' then
  t:=private.validate_task_set_reference(i.stimulus,i.id,s.curriculum_release_id,s.governed_unit_id);
  new.task_set_version_id:=t.id;
  select ord::integer into new.task_set_member_ordinal from jsonb_array_elements(t.members) with ordinality m(value,ord) where value->>'itemId'=i.id::text;
 end if;
 if new.source_family_id_snapshot is null then raise exception 'shared_source_unavailable'; end if;
 if (s.mode in ('diagnostic','mastery_check') and private.source_family_seen(s.student_id,new.source_family_id_snapshot,s.id))
  or (s.mode in ('practice','chapter_review') and private.source_family_reserved(s.student_id,new.source_family_id_snapshot,s.id))
 then raise exception 'source_family_exposed_or_reserved'; end if;
 return new;
end;
$function$;

ALTER FUNCTION "private"."guard_source_family_assignment"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.guard_task_set_attempt()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i public.items%rowtype; li public.learning_session_items%rowtype; s public.learning_sessions%rowtype; t public.learning_task_set_versions%rowtype;
begin
 select * into strict i from public.items where id=new.item_id;
 if coalesce(i.stimulus->>'kind','')<>'task_set' then return new; end if;
 select * into li from public.learning_session_items where id=new.learning_session_item_id and session_id=new.learning_session_id and item_id=i.id;
 select * into s from public.learning_sessions where id=li.session_id and student_id=new.student_id;
 if li.id is null or li.answered_at is not null or s.assessment_policy_binding_id is null or s.status<>'active'
  or not exists(select 1 from public.learning_source_family_exposures where session_item_id=li.id and student_id=new.student_id)
 then raise exception 'shared_source_requires_governed_session'; end if;
 t:=private.validate_task_set_reference(i.stimulus,i.id,s.curriculum_release_id,s.governed_unit_id);
 if t.id is distinct from li.task_set_version_id or t.source_family_id is distinct from li.source_family_id_snapshot then raise exception 'shared_source_unavailable'; end if;
 new.normalized_response:=coalesce(new.normalized_response,'{}')||jsonb_build_object('taskSetEvidence',jsonb_build_object(
  'schemaVersion','haiedu-task-set-evidence-v1','taskSetVersionId',t.id,'sourceFamilyId',t.source_family_id,
  'memberPosition',li.task_set_member_ordinal,'modality',t.stimulus->>'kind','transcriptUsed',false));
 return new;
end;
$function$;

ALTER FUNCTION "private"."guard_task_set_attempt"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.guard_task_set_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m jsonb; a public.learning_audio_versions%rowtype;
begin
 if tg_op='UPDATE' then
  if (to_jsonb(new)-array['revoked_at','revocation_reason','reviewed_by']) is distinct from (to_jsonb(old)-array['revoked_at','revocation_reason','reviewed_by'])
   or (new.reviewed_by is distinct from old.reviewed_by and new.reviewed_by is not null)
   or (old.revoked_at is not null and (new.revoked_at is distinct from old.revoked_at or new.revocation_reason is distinct from old.revocation_reason))
  then raise exception 'task_set_version_immutable'; end if;
  return new;
 end if;
 if new.reviewed_by is null or not exists(select 1 from public.profiles where id=new.reviewed_by and role::text in ('admin','content_admin') and account_status='active') then raise exception 'task_set_review_required'; end if;
 if not exists(select 1 from public.curriculum_release_units where curriculum_release_id=new.curriculum_release_id and unit_id=new.unit_id) then raise exception 'task_set_scope_invalid'; end if;
 if jsonb_typeof(new.members) is distinct from 'array' or jsonb_array_length(new.members) not between 2 and 20 then raise exception 'task_set_members_invalid'; end if;
 for m in select value from jsonb_array_elements(new.members) loop
  if jsonb_typeof(m) is distinct from 'object' or not (m ?& array['itemId','version','skillId']) or (select count(*) from jsonb_object_keys(m))<>3
   or coalesce(m->>'version','') !~ '^[1-9][0-9]{0,8}$'
   or not exists(select 1 from public.items i join public.item_curriculum_scopes sc on sc.item_id=i.id and sc.is_primary
    join public.curriculum_releases r on r.subject_program_id=sc.subject_program_id
    join public.curriculum_release_skills rs on rs.curriculum_release_id=r.id and rs.skill_id=i.skill_id
    where i.id::text=m->>'itemId' and i.skill_id::text=m->>'skillId' and r.id=new.curriculum_release_id and sc.unit_id=new.unit_id)
  then raise exception 'task_set_members_invalid'; end if;
 end loop;
 if (select count(distinct value->>'itemId') from jsonb_array_elements(new.members))<>jsonb_array_length(new.members) then raise exception 'task_set_members_invalid'; end if;
 if new.stimulus->>'kind'='text' then
  if jsonb_typeof(new.stimulus) is distinct from 'object' or (select count(*) from jsonb_object_keys(new.stimulus))<>4
   or new.stimulus->>'schemaVersion' is distinct from 'haiedu-text-v1' or new.stimulus->>'locale' is distinct from new.locale
   or jsonb_typeof(new.stimulus->'content') is distinct from 'string' or length(btrim(new.stimulus->>'content')) not between 1 and 50000
  then raise exception 'task_set_stimulus_invalid'; end if;
 elsif new.stimulus->>'kind'='audio' then
  a:=private.validate_audio_reference(new.stimulus,(new.members->0->>'itemId')::uuid,new.curriculum_release_id,new.unit_id);
  if a.source_family_id<>new.source_family_id or a.locale<>new.locale then raise exception 'task_set_source_mismatch'; end if;
 else raise exception 'task_set_stimulus_invalid'; end if;
 return new;
end;
$function$;

ALTER FUNCTION "private"."guard_task_set_version"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.guard_unit_material()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if TG_OP='DELETE' then raise exception 'material_immutable';end if;
 if TG_OP='UPDATE' then
  -- Preserve historical evidence when a profile is actually deleted.
  if (to_jsonb(new)-array['created_by','reviewed_by'])=(to_jsonb(old)-array['created_by','reviewed_by']) and
   (new.created_by is not distinct from old.created_by or (new.created_by is null and not exists(select 1 from public.profiles where id=old.created_by))) and
   (new.reviewed_by is not distinct from old.reviewed_by or (new.reviewed_by is null and not exists(select 1 from public.profiles where id=old.reviewed_by))) then return new;end if;
  if (to_jsonb(new)-array['qa','status','reviewed_by','reviewed_at']) is distinct from (to_jsonb(old)-array['qa','status','reviewed_by','reviewed_at'])
   or (old.status<>'draft' and (new.qa is distinct from old.qa or new.reviewed_by is distinct from old.reviewed_by or new.reviewed_at is distinct from old.reviewed_at))
   or (old.status='retired' and new.status<>'retired') or (old.status='approved' and new.status not in ('approved','retired'))
   then raise exception 'material_immutable';end if;
 end if;
 if not exists(select 1 from public.curriculum_releases r join public.units u on u.subject_program_id=r.subject_program_id where r.id=new.curriculum_release_id and u.id=new.unit_id and r.subject_program_id=new.subject_program_id) then raise exception 'material_scope_invalid';end if;
 new.fingerprint:=private.unit_material_fingerprint(new);
 if new.status='approved' and (TG_OP='INSERT' or old.status='draft') and
  (not exists(select 1 from public.profiles where id=new.reviewed_by and role::text in ('admin','content_admin') and account_status='active') or
   new.qa->'passed' is distinct from 'true'::jsonb or new.qa->>'fingerprint' is distinct from new.fingerprint)
 then raise exception 'material_qa_required';end if;
 return new;
end;
$function$;

ALTER FUNCTION "private"."guard_unit_material"() OWNER TO postgres;

