CREATE OR REPLACE FUNCTION private.learner_shared_stimulus(p_item uuid, p_session_item uuid DEFAULT NULL::uuid, p_release uuid DEFAULT NULL::uuid, p_unit uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare stimulus jsonb; a public.learning_audio_versions%rowtype; s public.learning_sessions%rowtype;
begin
 select private.task_set_stimulus(i.stimulus,i.id,p_release,p_unit) into stimulus from public.items i where i.id=p_item;
 if stimulus->>'kind'='audio' then
  a:=private.validate_audio_reference(stimulus,p_item,p_release,p_unit);
  select ls.* into s from public.learning_session_items li join public.learning_sessions ls on ls.id=li.session_id where li.id=p_session_item;
  if s.mode in ('diagnostic','mastery_check') then
   return jsonb_build_object('kind','audio','schemaVersion','haiedu-audio-v1','audioVersionId',a.id,'title',a.title,'locale',a.locale,'durationMs',a.duration_ms,
    'playbackPolicy','assessed-recording-v1','transcriptAvailable',false,'playback',private.assessed_audio_state(s.id,a.id),'questions',private.assessed_audio_questions(s.id,a.id));
  end if;
  return jsonb_build_object('kind','audio','schemaVersion','haiedu-audio-v1','audioVersionId',a.id,'title',a.title,'locale',a.locale,
   'durationMs',a.duration_ms,'playbackPolicy','replayable-practice-v1','transcriptAvailable',false,
   'completed',exists(select 1 from public.learning_audio_deliveries d where d.session_item_id=p_session_item and d.audio_version_id=a.id and d.completed_at is not null and d.failed_at is null));
 end if;
 return stimulus;
end;
$function$;

