CREATE OR REPLACE FUNCTION private.lock_feedback_actor(p_actor uuid, p_auth uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x record;t timestamptz;
begin
 select p.role,p.account_status,u.deleted_at,u.banned_until,s.not_after into x
 from public.profiles p join auth.users u on u.id=p.id join auth.sessions s on s.user_id=p.id and s.id=p_auth
 where p.id=p_actor for share of p,u,s;
 t:=clock_timestamp();
 if not found or x.role<>'teacher' or x.account_status<>'active' or x.deleted_at is not null or x.banned_until>t or x.not_after<=t then
 raise exception 'feedback_context_unavailable';end if;
end;$function$;

ALTER FUNCTION "private"."lock_feedback_actor"(p_actor uuid, p_auth uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.lock_governed_learning_session(p_student uuid, p_auth uuid, p_session uuid)
 RETURNS public.learning_sessions
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.learning_sessions%rowtype; b public.assessment_policy_bindings%rowtype;
begin
 select * into s from public.learning_sessions where id=p_session and student_id=p_student;
 if not found or s.assessment_policy_binding_id is null then raise exception 'learning_context_unavailable'; end if;
 -- Exposure serialization starts before a session row lock, including an older
 -- governed session resumed while a prospective form blueprint is selected.
 perform pg_advisory_xact_lock(hashtextextended('governed-mastery-form:'||p_student::text,0));
 perform private.lock_student_learning_context(p_student,p_auth,s.institutional_class_enrollment_id,s.curriculum_release_id,s.governed_unit_id);
 select * into strict s from public.learning_sessions where id=p_session and student_id=p_student for update;
 select * into strict b from public.assessment_policy_bindings where id=s.assessment_policy_binding_id;
 if (s.curriculum_release_id,s.governed_unit_id,s.subject_program_id,s.learning_model_configuration_id,s.academic_mastery_policy_id)
 is distinct from (b.curriculum_release_id,b.unit_id,b.subject_program_id,b.learning_model_configuration_id,b.academic_mastery_policy_id)
 or s.metadata->>'assessmentPolicyFingerprint' is distinct from b.snapshot_fingerprint
 then raise exception 'learning_context_unavailable'; end if;
 return s;
end;
$function$;

ALTER FUNCTION "private"."lock_governed_learning_session"(p_student uuid, p_auth uuid, p_session uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.lock_misconception_review_mapping()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old uuid; v_new uuid;
begin
  if tg_op <> 'INSERT' then v_old := old.misconception_id; end if;
  if tg_op <> 'DELETE' then v_new := new.misconception_id; end if;
  perform 1 from public.misconceptions where id in (v_old, v_new) order by id for key share;
  if tg_op = 'DELETE' then return old; else return new; end if;
end;
$function$;

ALTER FUNCTION "private"."lock_misconception_review_mapping"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.lock_student_learning_context(p_student uuid, p_auth_session uuid, p_enrollment uuid, p_release uuid, p_unit uuid)
 RETURNS public.institutional_class_enrollments
 LANGUAGE plpgsql
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare e public.institutional_class_enrollments%rowtype; ctx record; v_now timestamptz;
  teacher_member uuid; teacher_person uuid;
begin
  select * into e from public.institutional_class_enrollments
    where id=p_enrollment and student_id=p_student;
  if not found then raise exception 'learning_context_unavailable'; end if;
  select tm.id,tm.person_id into teacher_member,teacher_person from public.teacher_assignments a
    join public.institutional_memberships tm on tm.id=a.teacher_membership_id
    where a.id=e.teacher_assignment_id;
  if not found then raise exception 'learning_context_unavailable'; end if;
  -- Match existing profile/membership termination order. Shared offboarding locks
  -- let students start concurrently while the existing teacher cutover is exclusive.
  perform 1 from public.profiles where id in (p_student,teacher_person) order by id for share;
  perform pg_advisory_xact_lock_shared(hashtextextended('teacher-offboarding:'||teacher_member::text,0));
  perform 1 from public.institutional_memberships where id in (e.student_membership_id,teacher_member) order by id for share;
  select * into e from public.institutional_class_enrollments
    where id=p_enrollment and student_id=p_student for share;
  if not found then raise exception 'learning_context_unavailable'; end if;
  -- Use a single exact join, not a convenient enrollment for the same programme.
  select e.id, sm.status sm_status,sm.valid_from sm_from,sm.valid_to sm_to,
    a.status a_status,a.valid_from a_from,a.valid_to a_to,
    tm.status tm_status,tm.valid_from tm_from,tm.valid_to tm_to,
    ta.status ta_status,ta.valid_from ta_from,ta.valid_to ta_to,
    c.is_active, y.status y_status,y.starts_on,y.ends_on,
    sp.status sp_status,sp.effective_from sp_from,sp.effective_to sp_to,
    r.status r_status,r.effective_from r_from,r.effective_to r_to,
    s.status s_status, p.account_status p_status,t.account_status t_status,
    au.deleted_at,au.banned_until,aus.not_after
  into ctx from public.institutional_memberships sm
  join public.teacher_assignments a on a.id=e.teacher_assignment_id
    and a.school_id=e.school_id and a.academic_year_id=e.academic_year_id
    and a.class_id=e.class_id and a.subject_program_id=e.subject_program_id
  join public.institutional_memberships tm on tm.id=a.teacher_membership_id
    and tm.school_id=e.school_id and tm.role='teacher'
  join public.classes c on c.id=e.class_id and c.school_id=e.school_id and c.academic_year_id=e.academic_year_id
  join public.academic_years y on y.id=e.academic_year_id and y.school_id=e.school_id
  join public.subject_programs sp on sp.id=e.subject_program_id and sp.subject_id=c.subject_id and sp.grade_id=c.grade_id
  join public.subjects s on s.id=sp.subject_id
  join public.units u on u.id=p_unit and u.subject_program_id=sp.id
  join public.curriculum_releases r on r.id=p_release and r.subject_program_id=sp.id
  join public.curriculum_release_units ru on ru.curriculum_release_id=r.id and ru.unit_id=u.id
  join public.teacher_subject_authorizations ta on ta.school_id=e.school_id
    and ta.teacher_membership_id=tm.id and ta.subject_id=sp.subject_id and ta.status='active'
  join public.profiles p on p.id=e.student_id and p.role='student'
  join public.profiles t on t.id=tm.person_id and t.role='teacher'
  join auth.users au on au.id=p.id
  join auth.sessions aus on aus.user_id=p.id and aus.id=p_auth_session
  where sm.id=e.student_membership_id and sm.person_id=e.student_id
    and sm.school_id=e.school_id and sm.role='student'
  for share of sm,a,tm,c,y,sp,s,u,r,ru,ta,p,t,au,aus;
  if not found then raise exception 'learning_context_unavailable'; end if;
  -- Reject ambiguous authorizations rather than selecting an arbitrary match.
  if (select count(*) from public.teacher_subject_authorizations ta join public.teacher_assignments a
    on a.id=e.teacher_assignment_id where ta.school_id=e.school_id
    and ta.teacher_membership_id=a.teacher_membership_id and ta.subject_id=(select subject_id from public.subject_programs where id=e.subject_program_id)
    and ta.status='active')<>1 then raise exception 'learning_context_unavailable'; end if;
  -- Re-read time after any waits; transaction-start now() can be stale.
  v_now:=clock_timestamp();
  if e.status<>'active' or e.valid_from>v_now or (e.valid_to is not null and e.valid_to<=v_now)
    or ctx.sm_status<>'active' or ctx.sm_from>v_now or (ctx.sm_to is not null and ctx.sm_to<=v_now)
    or ctx.a_status<>'active' or ctx.a_from>v_now or (ctx.a_to is not null and ctx.a_to<=v_now)
    or ctx.tm_status<>'active' or ctx.tm_from>v_now or (ctx.tm_to is not null and ctx.tm_to<=v_now)
    or ctx.ta_status<>'active' or ctx.ta_from>v_now or (ctx.ta_to is not null and ctx.ta_to<=v_now)
    or not ctx.is_active or ctx.y_status<>'active' or v_now::date not between ctx.starts_on and ctx.ends_on
    or ctx.sp_status<>'published' or (ctx.sp_from is not null and ctx.sp_from>v_now::date) or (ctx.sp_to is not null and ctx.sp_to<v_now::date)
    or ctx.r_status not in ('pilot','production') or (ctx.r_from is not null and ctx.r_from>v_now::date) or (ctx.r_to is not null and ctx.r_to<v_now::date)
    or ctx.s_status<>'published' or ctx.p_status<>'active' or ctx.t_status<>'active'
    or ctx.deleted_at is not null or (ctx.banned_until is not null and ctx.banned_until>v_now)
    or (ctx.not_after is not null and ctx.not_after<=v_now)
  then raise exception 'learning_context_unavailable'; end if;
  return e;
end;
$function$;

ALTER FUNCTION "private"."lock_student_learning_context"(p_student uuid, p_auth_session uuid, p_enrollment uuid, p_release uuid, p_unit uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.lock_teacher_offboarding_14b(p_membership uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if p_membership is not null then
    perform pg_advisory_xact_lock(hashtextextended('teacher-offboarding:'||p_membership::text,0));
  end if;
end $function$;

ALTER FUNCTION "private"."lock_teacher_offboarding_14b"(p_membership uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.lock_written_teacher_context(p_actor uuid, p_auth uuid, p_assignment uuid, p_release uuid, p_unit uuid, p_write boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
#variable_conflict use_column
declare a public.teacher_assignments%rowtype; m public.institutional_memberships%rowtype; x record; t timestamptz; ro boolean;
begin
 select * into a from public.teacher_assignments where id=p_assignment;
 select * into m from public.institutional_memberships where id=a.teacher_membership_id and person_id=p_actor and role='teacher';
 if not found then raise exception 'written_context_unavailable';end if;
 perform 1 from public.profiles where id=p_actor for share;
 perform pg_advisory_xact_lock_shared(hashtextextended('teacher-offboarding:'||m.id::text,0));
 select * into a from public.teacher_assignments where id=p_assignment for share;
 if not found or a.teacher_membership_id<>m.id then raise exception 'written_context_unavailable';end if;
 select p.account_status,au.deleted_at,au.banned_until,ss.not_after,
  m.status m_status,m.valid_from m_from,m.valid_to m_to,a.status a_status,a.valid_from a_from,a.valid_to a_to,
  g.status g_status,g.valid_from g_from,g.valid_to g_to,c.is_active,y.status y_status,y.starts_on,y.ends_on,
  sp.status sp_status,sp.effective_from sp_from,sp.effective_to sp_to,s.status s_status,
  r.status r_status,r.effective_from r_from,r.effective_to r_to
 into x from public.teacher_assignments a
 join public.institutional_memberships m on m.id=a.teacher_membership_id and m.school_id=a.school_id and m.person_id=p_actor and m.role='teacher'
 join public.profiles p on p.id=p_actor and p.role='teacher'
 join auth.users au on au.id=p.id join auth.sessions ss on ss.user_id=p.id and ss.id=p_auth
 join public.classes c on c.id=a.class_id and c.school_id=a.school_id and c.academic_year_id=a.academic_year_id
 join public.academic_years y on y.id=a.academic_year_id and y.school_id=a.school_id
 join public.subject_programs sp on sp.id=a.subject_program_id and sp.subject_id=c.subject_id and sp.grade_id=c.grade_id
 join public.subjects s on s.id=sp.subject_id
 join public.teacher_subject_authorizations g on g.teacher_membership_id=m.id and g.school_id=m.school_id and g.subject_id=sp.subject_id and g.status='active'
 join public.curriculum_releases r on r.id=p_release and r.subject_program_id=sp.id
 join public.units u on u.id=p_unit and u.subject_program_id=sp.id
 join public.curriculum_release_units ru on ru.curriculum_release_id=r.id and ru.unit_id=u.id
 where a.id=p_assignment for share of a,m,p,au,ss,c,y,sp,s,g,r,u,ru;
 if not found then raise exception 'written_context_unavailable';end if;
 t:=clock_timestamp();
 if x.account_status<>'active' or x.deleted_at is not null or x.banned_until>t or x.not_after<=t
 or x.m_status<>'active' or x.m_from>t or x.m_to<=t or x.g_status<>'active' or x.g_from>t or x.g_to<=t
 or x.a_status not in ('active','ended') or x.a_from>t or x.a_from::date>x.ends_on or x.a_to::date<x.starts_on
 or x.sp_status<>'published' or x.s_status<>'published' or x.sp_from>t::date or x.sp_to<t::date
 or x.r_status not in ('pilot','production','retired')
 or (select count(*) from public.teacher_subject_authorizations g join public.subject_programs sp on sp.id=a.subject_program_id where g.teacher_membership_id=m.id and g.school_id=m.school_id and g.subject_id=sp.subject_id and g.status='active')<>1
 then raise exception 'written_context_unavailable';end if;
 ro:=x.a_status<>'active' or coalesce(x.a_to<=t,false) or not x.is_active or x.y_status<>'active' or t::date not between x.starts_on and x.ends_on or x.r_status='retired' or coalesce(x.r_from>t::date,false) or coalesce(x.r_to<t::date,false);
 if p_write and ro then raise exception 'written_read_only';end if;
 return jsonb_build_object('schoolId',a.school_id,'academicYearId',a.academic_year_id,'classId',a.class_id,'subjectProgramId',a.subject_program_id,'readOnly',ro);
end;
$function$;

ALTER FUNCTION "private"."lock_written_teacher_context"(p_actor uuid, p_auth uuid, p_assignment uuid, p_release uuid, p_unit uuid, p_write boolean) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.mark_item_revision_required()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
begin
  if old.skill_id is distinct from new.skill_id
     or old.item_type is distinct from new.item_type
     or old.prompt_hy is distinct from new.prompt_hy
     or old.prompt_en is distinct from new.prompt_en
     or old.stimulus is distinct from new.stimulus
     or old.difficulty is distinct from new.difficulty
     or old.difficulty_band is distinct from new.difficulty_band
     or old.item_family is distinct from new.item_family
     or old.item_template_id is distinct from new.item_template_id
     or old.variant_key is distinct from new.variant_key
     or old.variant_seed is distinct from new.variant_seed
     or old.variant_parameters is distinct from new.variant_parameters
     or old.config is distinct from new.config
     or old.source_reference is distinct from new.source_reference then
    new.review_status := 'needs_review';
    if old.status = 'published' then new.status := 'review'; end if;
    new.updated_at := now();
  end if;
  return new;
end;
$function$;

ALTER FUNCTION "private"."mark_item_revision_required"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.mark_parent_item_revision_required()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare v_item_id uuid;
begin
  if tg_op = 'DELETE' then
    v_item_id := old.item_id;
  else
    v_item_id := new.item_id;
  end if;

  update public.items
  set review_status='needs_review',
      status=case when status='published' then 'review'::content_status else status end,
      updated_at=now()
  where id=v_item_id;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$;

ALTER FUNCTION "private"."mark_parent_item_revision_required"() OWNER TO postgres;

