CREATE OR REPLACE FUNCTION private.normalize_typed_text(p_text text, p_rules jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
 if (p_rules->>'apostrophes')::boolean then p_text:=translate(p_text,'‘’',chr(39)||chr(39)); end if;
 if (p_rules->>'collapseWhitespace')::boolean then p_text:=regexp_replace(p_text,E'[ \\t\\r\\n]+',' ','g'); end if;
 if (p_rules->>'trim')::boolean then p_text:=btrim(p_text,E' \t\r\n'); end if;
 if p_rules->>'caseMode'='ascii-insensitive' then p_text:=translate(p_text,'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz'); end if;
 return p_text;
end;
$function$;

ALTER FUNCTION "private"."normalize_typed_text"(p_text text, p_rules jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.order_task_set_items(p_items uuid[], p_seed text)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare picked uuid; block uuid[]; result uuid[]:='{}';
begin
 for picked in select id from unnest(p_items) x(id) order by md5(p_seed||':'||coalesce((select stimulus->>'taskSetVersionId' from public.items where id=x.id),x.id::text)),x.id loop
  if picked=any(result) then continue; end if;
  block:=private.task_set_item_block(picked);
  if not (block<@p_items) then raise exception 'task_set_partial_selection'; end if;
  result:=result||block;
 end loop;
 return result;
end;
$function$;

ALTER FUNCTION "private"."order_task_set_items"(p_items uuid[], p_seed text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.pack_task_set_items(p_ranked uuid[], p_count integer)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare picked uuid; block uuid[]; visited uuid[]:='{}'; states jsonb:='{"0":[]}'::jsonb; n integer;
begin
 -- Bounded subset packing preserves rank preference without rejecting a feasible
 -- budget merely because the first source block was too large in combination.
 if p_count not between 1 and 1000 then raise exception 'task_set_capacity_unavailable'; end if;
 foreach picked in array p_ranked loop
  if picked=any(visited) then continue; end if;
  block:=private.task_set_item_block(picked);visited:=visited||block;
  if block<@p_ranked and cardinality(block)<=p_count then
   for n in reverse p_count..cardinality(block) loop
    if not (states ? n::text) and states ? (n-cardinality(block))::text then
     states:=states||jsonb_build_object(n::text,(states->(n-cardinality(block))::text)||to_jsonb(block));
    end if;
   end loop;
  end if;
  if states ? p_count::text then return array(select value::uuid from jsonb_array_elements_text(states->p_count::text)); end if;
 end loop;
 raise exception 'task_set_capacity_unavailable';
end;
$function$;

ALTER FUNCTION "private"."pack_task_set_items"(p_ranked uuid[], p_count integer) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.pilot_participant_session_is_eligible(p_pilot_run_id uuid, p_student_id uuid, p_started_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from public.pilot_participants pp
    where pp.pilot_run_id = p_pilot_run_id
      and pp.student_id = p_student_id
      and p_started_at >= pp.evidence_start_at
      and (pp.planned_end_date is null or p_started_at < pp.planned_end_date + 1)
      and not exists (
        select 1
        from public.pilot_participant_events ppe
        where ppe.pilot_participant_id = pp.id
          and ppe.event_type in ('withdrawn','suspended')
          and ppe.effective_at <= p_started_at
          and not exists (
            select 1
            from public.pilot_participant_events later
            where later.pilot_participant_id = pp.id
              and later.event_type = 'resumed'
              and later.effective_at > ppe.effective_at
              and later.effective_at <= p_started_at
          )
      )
  );
$function$;

ALTER FUNCTION "private"."pilot_participant_session_is_eligible"(p_pilot_run_id uuid, p_student_id uuid, p_started_at timestamp with time zone) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.prepare_governed_lifecycle(p_student uuid, p_binding uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare b public.assessment_policy_bindings%rowtype; st public.chapter_mastery_states%rowtype;
 policy public.academic_mastery_policy_versions%rowtype; requirement public.chapter_review_requirements%rowtype;
 cycle public.chapter_review_cycles%rowtype; code text; mode text; attempt_no integer; review_id uuid; context text; pool_count integer; cycle_no integer; session_no integer;
begin
 select * into strict b from public.assessment_policy_bindings where id=p_binding;
 mode:=b.policy_snapshot->>'mode';
 if mode not in ('mastery_check','chapter_review') then return '{}'; end if;
 select unit_code_snapshot into strict code from public.curriculum_release_units where curriculum_release_id=b.curriculum_release_id and unit_id=b.unit_id;
 perform pg_advisory_xact_lock(hashtextextended(p_student::text||'|'||b.curriculum_release_id::text||'|'||code,0));
 select * into strict policy from public.academic_mastery_policy_versions where id=b.academic_mastery_policy_id;
 -- The existing lifecycle schema defines the approved three-attempt extension.
 if policy.maximum_mastery_attempts<>3 or policy.review_required_after_failed_attempts<>array[1,2]::smallint[]
 or not policy.review_optional_after_pass or not policy.review_available_after_final_failure or policy.additional_attempt_after_final_failure
 then raise exception 'unsupported_mastery_lifecycle_contract'; end if;
 select * into st from public.chapter_mastery_states where student_id=p_student and curriculum_release_id=b.curriculum_release_id and unit_code=code for update;
 if not found then
   if mode='chapter_review' then raise exception 'chapter_review_not_available'; end if;
   insert into public.chapter_mastery_states(student_id,curriculum_release_id,unit_code,academic_mastery_policy_id,lifecycle_state)
   values(p_student,b.curriculum_release_id,code,policy.id,'mastery_ready') returning * into st;
 end if;
 if st.academic_mastery_policy_id<>policy.id then raise exception 'mastery_policy_history_incompatible'; end if;
 if mode='mastery_check' then
   attempt_no:=case st.lifecycle_state when 'mastery_ready' then 1 when 'mastery_retry_2_ready' then 2 when 'mastery_retry_3_ready' then 3 else null end;
   if attempt_no is null or attempt_no<>st.attempts_used+1 then raise exception 'mastery_check_not_allowed'; end if;
   if attempt_no=1 and exists(select 1 from jsonb_array_elements_text(case when b.policy_snapshot->>'schemaVersion' in ('haiedu-assessment-policy-v2','haiedu-assessment-policy-v3','haiedu-assessment-policy-v4') then b.policy_snapshot->'readinessSkillIds' else b.skill_scope_snapshot end) skill
      where not private.governed_skill_ready(p_student,b.curriculum_release_id,skill::uuid,b.learning_model_configuration_id)) then raise exception 'skills_not_ready'; end if;
   if attempt_no>1 then
     select r.qualifying_review_session_id into review_id from public.chapter_review_requirements r
     join public.chapter_review_sessions cr on cr.id=r.qualifying_review_session_id
     where r.chapter_mastery_state_id=st.id and r.required_after_attempt=attempt_no-1 and r.status='satisfied' and cr.qualifying and cr.status='completed';
     if review_id is null then raise exception 'mastery_check_not_allowed'; end if;
   end if;
   return jsonb_build_object('stateId',st.id,'attemptNumber',attempt_no,'precedingReviewId',review_id);
 end if;
 context:=case st.lifecycle_state when 'review_required_attempt_2' then 'required_after_attempt_1_failure'
 when 'review_required_attempt_3' then 'required_after_attempt_2_failure' when 'mastery_passed' then 'voluntary_after_mastery_pass'
 when 'mastery_failed_final' then 'voluntary_after_final_failure' else null end;
 if context is null then raise exception 'chapter_review_not_available'; end if;
 if context like 'required_%' then
   select * into requirement from public.chapter_review_requirements where chapter_mastery_state_id=st.id and status='required' for update;
   if not found then raise exception 'chapter_review_not_available'; end if;
 end if;
 select count(*) into pool_count from public.assessment_blueprint_items where assessment_blueprint_id=b.assessment_blueprint_id;
 select * into cycle from public.chapter_review_cycles where chapter_mastery_state_id=st.id and status='active' for update;
 if found and ((select count(distinct item_id) from public.chapter_review_item_exposures where review_cycle_id=cycle.id)>=cycle.eligible_pool_size or cycle.eligible_pool_size<>pool_count) then
   update public.chapter_review_cycles set status='completed',completed_at=now() where id=cycle.id; cycle.id:=null;
 end if;
 if cycle.id is null then
   select coalesce(max(cycle_number),0)+1 into cycle_no from public.chapter_review_cycles where chapter_mastery_state_id=st.id;
   insert into public.chapter_review_cycles(chapter_mastery_state_id,curriculum_release_id,unit_code,cycle_number,eligible_pool_size)
   values(st.id,b.curriculum_release_id,code,cycle_no,pool_count) returning * into cycle;
 end if;
 select coalesce(max(review_session_number),0)+1 into session_no from public.chapter_review_sessions where review_cycle_id=cycle.id;
 return jsonb_build_object('stateId',st.id,'reviewRequirementId',requirement.id,'reviewContext',context,'reviewCycleId',cycle.id,
 'reviewCycleNumber',cycle.cycle_number,'reviewSessionNumber',session_no,'eligiblePoolSize',pool_count,
 'precedingMasteryAttemptNumber',coalesce(st.passed_on_attempt,st.attempts_used));
end;
$function$;

ALTER FUNCTION "private"."prepare_governed_lifecycle"(p_student uuid, p_binding uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.present_arrangement_definition(p_type text, p_definition jsonb, p_seed text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare part text; shuffled jsonb;
begin
 perform private.validate_arrangement_definition(p_type,p_definition);
 if p_seed is null or p_seed='' then raise exception 'arrangement_contract_invalid'; end if;
 part:=case when p_type='matching' then 'targets' else 'segments' end;
 select jsonb_agg(value order by md5(p_seed||'|haiedu-stable-arrangement-v1|'||(value->>'id')),value->>'id') into shuffled from jsonb_array_elements(p_definition->part);
 return jsonb_set(p_definition,array[part],shuffled);
end;
$function$;

ALTER FUNCTION "private"."present_arrangement_definition"(p_type text, p_definition jsonb, p_seed text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.preserve_item_version_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='INSERT' then
  if jsonb_typeof(new.snapshot->'item') is distinct from 'object'
    or new.snapshot#>>'{item,id}' is distinct from new.item_id::text
    or new.snapshot#>>'{item,version_no}' is distinct from new.version_no::text
  then raise exception 'item_version_snapshot_identity_mismatch' using errcode='23514';end if;
  return new;
 end if;
 if tg_op='UPDATE' and new is not distinct from old then return new;end if;
 raise exception 'item_version_snapshot_is_immutable' using errcode='23514';
end;$function$;

ALTER FUNCTION "private"."preserve_item_version_snapshot"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.protect_learning_answer_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if (to_jsonb(new)-'response') is distinct from (to_jsonb(old)-'response')
     or old.response is not null or new.response is null then
    raise exception 'answer_receipt_immutable';
  end if;
  return new;
end;
$function$;

ALTER FUNCTION "private"."protect_learning_answer_receipt"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.purge_idle_actor_rate_buckets(p_limit integer DEFAULT 200)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_now timestamptz := clock_timestamp();
  v_now_us bigint := (extract(epoch from v_now) * 1000000)::bigint;
  v_deleted integer;
begin
  if p_limit is null or p_limit not between 1 and 500 then
    raise exception 'invalid_rate_budget_cleanup_limit' using errcode = '22023';
  end if;
  with expired as (
    select actor_id, policy_key from private.actor_rate_buckets
      where expires_at <= v_now and debt_until_us <= v_now_us
      order by expires_at, actor_id, policy_key
      for update skip locked limit p_limit
  )
  delete from private.actor_rate_buckets b using expired e
    where b.actor_id = e.actor_id and b.policy_key = e.policy_key;
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$function$;

ALTER FUNCTION "private"."purge_idle_actor_rate_buckets"(p_limit integer) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.record_session_answer_before_recovery(p_student_id uuid, p_session_id uuid, p_session_item_id uuid, p_item_id uuid, p_skill_id uuid, p_response jsonb, p_normalized_response jsonb, p_score numeric, p_correct boolean, p_error_code text, p_hint_used boolean, p_response_time_ms integer, p_attempted_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  s public.learning_sessions%rowtype; i public.learning_session_items%rowtype;
  policy jsonb; reporting jsonb; audio public.learning_audio_versions%rowtype; audio_stimulus jsonb; audio_delivery public.learning_audio_deliveries%rowtype;
  v_attempt_id uuid; v_result jsonb; v_answered integer; v_planned integer;
begin
  select * into s from public.learning_sessions where id=p_session_id
    and student_id=p_student_id for update;
  if not found then raise exception 'invalid_or_inactive_session_item'; end if;
  select * into i from public.learning_session_items where id=p_session_item_id
    and session_id=p_session_id and item_id=p_item_id and skill_id=p_skill_id for update;
  if not found then raise exception 'invalid_or_inactive_session_item'; end if;
  if i.attempt_id is not null then
    return jsonb_build_object('attemptId',i.attempt_id,'replayed',true);
  end if;
  if s.status <> 'active' or i.answered_at is not null then
    raise exception 'invalid_or_inactive_session_item'; end if;
  select private.task_set_stimulus(stimulus,id,s.curriculum_release_id,s.governed_unit_id) into audio_stimulus from public.items where id=p_item_id;
  if audio_stimulus->>'kind'='audio' then
    if s.assessment_policy_binding_id is null then raise exception 'audio_mode_unavailable'; end if;
    audio:=private.validate_audio_reference(audio_stimulus,p_item_id,s.curriculum_release_id,s.governed_unit_id);
    if s.mode in ('diagnostic','mastery_check') then
      p_normalized_response:=p_normalized_response||jsonb_build_object('audioEvidence',private.assessed_audio_evidence(s.id,audio.id));
    else
      select * into audio_delivery from public.learning_audio_deliveries where session_item_id=i.id and student_id=p_student_id and audio_version_id=audio.id for update;
      if not found or audio_delivery.completed_at is null or audio_delivery.failed_at is not null then raise exception 'audio_playback_incomplete'; end if;
      p_normalized_response:=p_normalized_response||jsonb_build_object('audioEvidence',jsonb_build_object('schemaVersion','haiedu-audio-evidence-v1','audioVersionId',audio.id,'sourceFamilyId',audio.source_family_id,'playbackPolicy','replayable-practice-v1','transcriptUsed',false,'completionObservedAt',audio_delivery.completed_at));
    end if;
  end if;
  -- Help is server-owned, read again after acquiring the assignment lock.
  p_hint_used := coalesce(i.hint_level_used,0)>0;
  insert into public.attempts(student_id,item_id,skill_id,response,normalized_response,
    score,correct,error_code,hint_used,response_time_ms,created_at,
    learning_session_id,learning_session_item_id)
  values(p_student_id,p_item_id,p_skill_id,p_response,p_normalized_response,p_score,
    p_correct,p_error_code,p_hint_used,p_response_time_ms,p_attempted_at,
    p_session_id,p_session_item_id) returning id into v_attempt_id;
  v_result := private.apply_configured_mastery_attempt(v_attempt_id);
  update public.learning_session_items set attempt_id=v_attempt_id,correct=p_correct,
    answered_at=p_attempted_at where id=p_session_item_id;
  perform public.service_finalize_item_exposure(p_student_id,p_session_id,
    p_session_item_id,p_item_id,v_attempt_id,p_correct,p_hint_used,p_response_time_ms,p_attempted_at);
  update public.learning_sessions set answered_count=answered_count+1,
    correct_count=correct_count+case when p_correct then 1 else 0 end,updated_at=p_attempted_at
    where id=p_session_id returning planned_item_count,answered_count into v_planned,v_answered;
  if v_answered>=v_planned then
    select policy_snapshot into policy from public.assessment_policy_bindings where id=s.assessment_policy_binding_id;
    if policy->>'schemaVersion' in ('haiedu-assessment-policy-v2','haiedu-assessment-policy-v3','haiedu-assessment-policy-v4') then
      select private.assessment_result_v2(policy,jsonb_agg(jsonb_build_object('skillId',skill_id,'correct',correct,'total',total,'earned',earned))) into reporting from
      (select lsi.skill_id,count(*) total,count(*) filter(where lsi.correct) correct,sum(a.score) earned from public.learning_session_items lsi join public.attempts a on a.id=lsi.attempt_id where lsi.session_id=s.id and lsi.answered_at is not null group by lsi.skill_id) q;
    end if;
    update public.learning_sessions set status='completed',completed_at=p_attempted_at,
      updated_at=p_attempted_at,metadata=case when reporting is null then metadata else coalesce(metadata,'{}')||jsonb_build_object('assessmentResultReporting',reporting) end where id=p_session_id;
  end if;
  return v_result || jsonb_build_object('attemptId',v_attempt_id,'replayed',false);
end;
$function$;

ALTER FUNCTION "private"."record_session_answer_before_recovery"(p_student_id uuid, p_session_id uuid, p_session_item_id uuid, p_item_id uuid, p_skill_id uuid, p_response jsonb, p_normalized_response jsonb, p_score numeric, p_correct boolean, p_error_code text, p_hint_used boolean, p_response_time_ms integer, p_attempted_at timestamp with time zone) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.record_source_family_exposure()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare li public.learning_session_items%rowtype; s public.learning_sessions%rowtype; i public.items%rowtype; stimulus jsonb;
begin
 select * into strict i from public.items where id=new.item_id;
 if coalesce(i.stimulus->>'kind','') not in ('task_set','audio') then return new; end if;
 select * into li from public.learning_session_items where id=new.session_item_id and item_id=new.item_id;
 select * into s from public.learning_sessions where id=li.session_id and student_id=new.student_id;
 if li.id is null or s.assessment_policy_binding_id is null or li.source_family_id_snapshot is null then raise exception 'shared_source_requires_governed_session'; end if;
 if (s.mode in ('diagnostic','mastery_check') and private.source_family_seen(s.student_id,li.source_family_id_snapshot,s.id))
  or (s.mode in ('practice','chapter_review') and private.source_family_reserved(s.student_id,li.source_family_id_snapshot,s.id)) then raise exception 'source_family_exposed_or_reserved'; end if;
 stimulus:=private.task_set_stimulus(i.stimulus,i.id,s.curriculum_release_id,s.governed_unit_id);
 insert into public.learning_source_family_exposures(session_item_id,student_id,source_family_id,task_set_version_id,modality,exposed_at)
 values(li.id,s.student_id,li.source_family_id_snapshot,li.task_set_version_id,stimulus->>'kind',new.served_at) on conflict do nothing;
 return new;
end;
$function$;

ALTER FUNCTION "private"."record_source_family_exposure"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.reject_assessment_policy_binding_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin raise exception 'assessment_policy_binding_immutable'; end;
$function$;

ALTER FUNCTION "private"."reject_assessment_policy_binding_mutation"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.render_governed_hint(p_text text, p_keys jsonb, p_parameters jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare key text;
begin
 for key in select jsonb_array_elements_text(coalesce(p_keys,'[]')) loop
   if key ~ '^[A-Za-z0-9_]+$' and jsonb_typeof(p_parameters->key) in ('string','number','boolean') then
     p_text:=replace(p_text,'{{'||key||'}}',p_parameters->>key);
   end if;
 end loop;
 return coalesce(p_text,'');
end;
$function$;

ALTER FUNCTION "private"."render_governed_hint"(p_text text, p_keys jsonb, p_parameters jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.render_item_variant(p_template_code text, p_seed text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_template public.item_templates%rowtype;
  v_family public.item_families%rowtype;
  v_generator text;
  v_difficulty integer;
  v_prompt text;
  v_item_type text;
  v_answer jsonb;
  v_tolerance numeric;
  v_canonical_unit text;
  v_accepted_units jsonb := '[]'::jsonb;
  v_options jsonb := '[]'::jsonb;
  v_parameters jsonb := '{}'::jsonb;
  v_fingerprint text;
  v_i1 integer;
  v_i2 integer;
  v_i3 integer;
  v_num1 numeric;
  v_num2 numeric;
  v_num3 numeric;
  v_text1 text;
  v_text2 text;
  v_correct text;
begin
  if nullif(btrim(p_seed), '') is null then
    raise exception 'variant_seed_required';
  end if;

  select * into v_template
  from public.item_templates
  where code = p_template_code
    and status = 'active';
  if not found then
    raise exception 'active_template_not_found';
  end if;

  select * into v_family
  from public.item_families
  where id = v_template.item_family_id;
  if not found then
    raise exception 'item_family_not_found';
  end if;

  v_generator := v_template.generation_config ->> 'generator';
  v_difficulty := coalesce((v_template.generation_config ->> 'difficulty')::integer, 2);
  if v_difficulty < 1 or v_difficulty > 5 then
    raise exception 'generator_invalid_difficulty';
  end if;

  if v_generator = 's07_length_to_m_v1' then
    v_item_type := 'numeric';
    v_i1 := private.seed_index(p_seed, 'unit', 3);
    v_i2 := private.seed_index(p_seed, 'value', 6);
    if v_i1 = 1 then
      v_text1 := 'կմ';
      v_num1 := case v_i2 when 1 then 1.2 when 2 then 2 when 3 then 3.5 when 4 then 4 when 5 then 7.5 else 12 end;
      v_num2 := v_num1 * 1000;
    elsif v_i1 = 2 then
      v_text1 := 'սմ';
      v_num1 := case v_i2 when 1 then 15 when 2 then 35 when 3 then 80 when 4 then 125 when 5 then 250 else 420 end;
      v_num2 := v_num1 / 100;
    else
      v_text1 := 'մմ';
      v_num1 := case v_i2 when 1 then 250 when 2 then 750 when 3 then 1200 when 4 then 2500 when 5 then 4500 else 8200 end;
      v_num2 := v_num1 / 1000;
    end if;
    v_prompt := v_num1::text || ' ' || v_text1 || '-ը արտահայտեք մետրերով: Գրեք միայն թիվը:';
    v_answer := to_jsonb(v_num2);
    v_tolerance := 0.000001;
    v_parameters := jsonb_build_object('sourceValue', v_num1, 'sourceUnit', v_text1, 'targetUnit', 'մ');

  elsif v_generator = 's07_time_to_s_v1' then
    v_item_type := 'numeric';
    v_i1 := private.seed_index(p_seed, 'unit', 2);
    v_i2 := private.seed_index(p_seed, 'value', 6);
    if v_i1 = 1 then
      v_text1 := 'րոպե';
      v_num1 := case v_i2 when 1 then 2 when 2 then 3 when 3 then 4.5 when 4 then 7 when 5 then 12 else 15 end;
      v_num2 := v_num1 * 60;
    else
      v_text1 := 'ժամ';
      v_num1 := case v_i2 when 1 then 0.5 when 2 then 1 when 3 then 1.5 when 4 then 2 when 5 then 2.5 else 3 end;
      v_num2 := v_num1 * 3600;
    end if;
    v_prompt := v_num1::text || ' ' || v_text1 || '-ը արտահայտեք վայրկյաններով: Գրեք միայն թիվը:';
    v_answer := to_jsonb(v_num2);
    v_tolerance := 0.000001;
    v_parameters := jsonb_build_object('sourceValue', v_num1, 'sourceUnit', v_text1, 'targetUnit', 'վ');

  elsif v_generator = 's07_volume_to_l_v1' then
    v_item_type := 'quantity';
    v_i1 := private.seed_index(p_seed, 'value', 6);
    v_num1 := case v_i1 when 1 then 250 when 2 then 500 when 3 then 1250 when 4 then 1800 when 5 then 2500 else 3750 end;
    v_num2 := v_num1 / 1000;
    v_prompt := v_num1::text || ' մլ-ը արտահայտեք լիտրերով: Մուտքագրեք թվային արժեքը և միավորը:';
    v_answer := to_jsonb(v_num2);
    v_tolerance := 0.000001;
    v_canonical_unit := 'L';
    v_accepted_units := jsonb_build_array('L', 'l', 'լ');
    v_parameters := jsonb_build_object('sourceValue', v_num1, 'sourceUnit', 'մլ', 'targetUnit', 'L');

  elsif v_generator = 's08_scale_division_v1' then
    v_item_type := 'numeric';
    v_i1 := private.seed_index(p_seed, 'lower', 6);
    v_i2 := private.seed_index(p_seed, 'divisions', 3);
    v_i3 := private.seed_index(p_seed, 'step', 4);
    v_num1 := case v_i1 when 1 then 0 when 2 then 10 when 3 then 20 when 4 then 50 when 5 then 100 else 200 end;
    v_num2 := case v_i2 when 1 then 5 when 2 then 10 else 20 end;
    v_num3 := case v_i3 when 1 then 0.5 when 2 then 1 when 3 then 2 else 5 end;
    v_prompt := 'Սանդղակի ' || v_num1::text || ' և ' || (v_num1 + v_num2 * v_num3)::text || ' նշումների միջև կա ' || v_num2::text || ' հավասար բաժանում: Որքա՞ն է մեկ բաժանման արժեքը: Գրեք միայն թիվը:';
    v_answer := to_jsonb(v_num3);
    v_tolerance := 0.000001;
    v_parameters := jsonb_build_object('lowerMark', v_num1, 'upperMark', v_num1 + v_num2 * v_num3, 'divisionCount', v_num2);

  elsif v_generator = 's08_scale_reading_v1' then
    v_item_type := 'numeric';
    v_i1 := private.seed_index(p_seed, 'base', 5);
    v_i2 := private.seed_index(p_seed, 'step', 4);
    v_i3 := private.seed_index(p_seed, 'tick', 8);
    v_num1 := case v_i1 when 1 then 0 when 2 then 10 when 3 then 20 when 4 then 50 else 100 end;
    v_num2 := case v_i2 when 1 then 0.5 when 2 then 1 when 3 then 2 else 5 end;
    v_num3 := v_i3 + 1;
    v_prompt := 'Սանդղակի հիմքային նշումը ' || v_num1::text || ' է, մեկ բաժանումը՝ ' || v_num2::text || ' միավոր, և ցուցիչը գտնվում է հիմքից ' || v_num3::text || ' բաժանում վեր: Ի՞նչ արժեք է ցույց տալիս սարքը:';
    v_answer := to_jsonb(v_num1 + v_num2 * v_num3);
    v_tolerance := 0.000001;
    v_parameters := jsonb_build_object('baseMark', v_num1, 'divisionValue', v_num2, 'ticksAboveBase', v_num3);

  elsif v_generator = 's09_measurement_error_v1' then
    v_item_type := 'numeric';
    v_i1 := private.seed_index(p_seed, 'division', 6);
    v_i2 := private.seed_index(p_seed, 'device', 2);
    v_num1 := case v_i1 when 1 then 0.2 when 2 then 0.4 when 3 then 0.5 when 4 then 1 when 5 then 2 else 5 end;
    if v_i2 = 1 then
      v_text1 := 'քանոնի';
      v_text2 := 'սմ';
    else
      v_text1 := 'ջերմաչափի';
      v_text2 := '°C';
    end if;
    v_prompt := 'Չափիչ ' || v_text1 || ' մեկ բաժանման արժեքը ' || v_num1::text || ' ' || v_text2 || ' է: Ըստ ընդունված կանոնի՝ որքա՞ն է չափման սխալը ' || v_text2 || '-ով: Գրեք միայն թիվը:';
    v_answer := to_jsonb(v_num1 / 2);
    v_tolerance := 0.000001;
    v_parameters := jsonb_build_object('device', v_text1, 'divisionValue', v_num1, 'unit', v_text2, 'rule', 'half_division');

  elsif v_generator = 's10_displacement_volume_v1' then
    v_item_type := 'numeric';
    v_i1 := private.seed_index(p_seed, 'initial', 5);
    v_i2 := private.seed_index(p_seed, 'volume', 5);
    v_num1 := case v_i1 when 1 then 20 when 2 then 35 when 3 then 40 when 4 then 50 else 60 end;
    v_num2 := case v_i2 when 1 then 7 when 2 then 12 when 3 then 15 when 4 then 18 else 24 end;
    v_num3 := v_num1 + v_num2;
    v_prompt := 'Չափագլանում սկզբում կա ' || v_num1::text || ' սմ³ ջուր: Մարմինը լրիվ խորասուզելուց հետո ցուցմունքը դառնում է ' || v_num3::text || ' սմ³: Որքա՞ն է մարմնի ծավալը սմ³-ով: Գրեք միայն թիվը:';
    v_answer := to_jsonb(v_num2);
    v_tolerance := 0.000001;
    v_parameters := jsonb_build_object('initialVolumeCm3', v_num1, 'finalVolumeCm3', v_num3);

  elsif v_generator = 's10_sheet_thickness_v1' then
    v_item_type := 'numeric';
    v_i1 := private.seed_index(p_seed, 'count', 5);
    v_i2 := private.seed_index(p_seed, 'thickness', 4);
    v_num1 := case v_i1 when 1 then 20 when 2 then 25 when 3 then 40 when 4 then 50 else 80 end;
    v_num2 := case v_i2 when 1 then 0.1 when 2 then 0.2 when 3 then 0.25 else 0.5 end;
    v_num3 := v_num1 * v_num2;
    v_prompt := v_num1::text || ' նույնական թերթերի ընդհանուր հաստությունը ' || v_num3::text || ' մմ է: Որքա՞ն է մեկ թերթի հաստությունը մմ-ով:';
    v_answer := to_jsonb(v_num2);
    v_tolerance := 0.000001;
    v_parameters := jsonb_build_object('sheetCount', v_num1, 'totalThicknessMm', v_num3);

  elsif v_generator = 's04_observation_experiment_parallel_v1' then
    v_item_type := 'single_choice';
    v_i1 := private.seed_index(p_seed, 'scenario', 6);
    v_options := jsonb_build_array(
      jsonb_build_object('optionKey','A','contentHy','Դիտում'),
      jsonb_build_object('optionKey','B','contentHy','Փորձ')
    );
    if v_i1 = 1 then
      v_text1 := 'Աշակերտը երեք երեկո անընդմեջ գրանցում է Լուսնի տեսանելի ձևը՝ առանց պայմանները փոխելու:';
      v_correct := 'A';
    elsif v_i1 = 2 then
      v_text1 := 'Աշակերտը փոխում է ճոճանակի թելի երկարությունը և յուրաքանչյուր դեպքում չափում տատանման ժամանակը:';
      v_correct := 'B';
    elsif v_i1 = 3 then
      v_text1 := 'Աշակերտը լուսամուտի մոտ ամեն ժամ գրանցում է ստվերի երկարությունը՝ առանց պայմանները փոխելու:';
      v_correct := 'A';
    elsif v_i1 = 4 then
      v_text1 := 'Աշակերտը նույն քանակի ջուրը տաքացնում է երկու տարբեր հզորության ջեռուցիչներով և համեմատում տաքացման ժամանակը:';
      v_correct := 'B';
    elsif v_i1 = 5 then
      v_text1 := 'Աստղագետը մի քանի գիշեր շարունակ գրանցում է մոլորակի դիրքը՝ չփոխելով դիտման պայմանները:';
      v_correct := 'A';
    else
      v_text1 := 'Աշակերտը տարբեր մակերևույթների վրա նույն խաղալիք մեքենան բաց է թողնում նույն թեքությունից և համեմատում անցած ճանապարհը:';
      v_correct := 'B';
    end if;
    v_prompt := v_text1 || ' Սա հիմնականում ո՞ր մեթոդն է:';
    v_answer := to_jsonb(v_correct);
    v_parameters := jsonb_build_object('scenarioId', v_i1, 'construct', 'observation_vs_experiment');

  elsif v_generator = 's05_hypothesis_test_parallel_v1' then
    v_item_type := 'single_choice';
    v_i1 := private.seed_index(p_seed, 'scenario', 4);
    if v_i1 = 1 then
      v_prompt := 'Աշակերտը ենթադրում է, որ շաքարը տաք ջրում ավելի արագ է լուծվում: Ո՞ր փորձն է ամենահարմարն այս վարկածը ստուգելու համար:';
      v_options := jsonb_build_array(
        jsonb_build_object('optionKey','A','contentHy','Օգտագործել տարբեր քանակի շաքար և տարբեր քանակի ջուր'),
        jsonb_build_object('optionKey','B','contentHy','Վերցնել նույն քանակի ջուր և շաքար, փոխել միայն ջրի ջերմաստիճանը և համեմատել լուծման ժամանակը'),
        jsonb_build_object('optionKey','C','contentHy','Մի բաժակ ջուր դիտել առանց որևէ չափման'),
        jsonb_build_object('optionKey','D','contentHy','Հարցնել ընկերներին՝ ինչ են կարծում')
      );
      v_correct := 'B';
    elsif v_i1 = 2 then
      v_prompt := 'Աշակերտը ենթադրում է, որ ճոճանակի թելի երկարությունը ազդում է տատանման ժամանակի վրա: Ո՞ր գործողությունն է լավագույնս ստուգում վարկածը:';
      v_options := jsonb_build_array(
        jsonb_build_object('optionKey','A','contentHy','Միայն մեկ անգամ չափել մեկ ճոճանակի ժամանակը'),
        jsonb_build_object('optionKey','B','contentHy','Միաժամանակ փոխել թելի երկարությունը և ծանրոցի զանգվածը'),
        jsonb_build_object('optionKey','C','contentHy','Դիտել ուրիշի փորձի տեսանյութը և չկատարել չափումներ'),
        jsonb_build_object('optionKey','D','contentHy','Փոխել միայն թելի երկարությունը, մյուս պայմանները պահել նույնը և չափել տատանման ժամանակը')
      );
      v_correct := 'D';
    elsif v_i1 = 3 then
      v_prompt := 'Աշակերտը ենթադրում է, որ մուգ մակերևույթը նույն լամպի տակ ավելի արագ է տաքանում, քան բաց մակերևույթը: Ո՞ր փորձն է առավել ճիշտ:';
      v_options := jsonb_build_array(
        jsonb_build_object('optionKey','A','contentHy','Օգտագործել նույն նյութից երկու մակերևույթ, փոխել միայն գույնը, պահել լամպի հեռավորությունը նույնը և չափել ջերմաստիճանը'),
        jsonb_build_object('optionKey','B','contentHy','Օգտագործել տարբեր նյութեր, տարբեր լամպեր և տարբեր հեռավորություններ'),
        jsonb_build_object('optionKey','C','contentHy','Միայն նկարագրել մակերևույթների գույները'),
        jsonb_build_object('optionKey','D','contentHy','Մեկ մակերևույթը դնել արևի տակ, մյուսը՝ սենյակում')
      );
      v_correct := 'A';
    else
      v_prompt := 'Աշակերտը ենթադրում է, որ մագնիսը ձգում է միայն երկաթ պարունակող առարկաները: Ո՞ր գործողությունն է ամենահարմարն այս վարկածը ստուգելու համար:';
      v_options := jsonb_build_array(
        jsonb_build_object('optionKey','A','contentHy','Փորձարկել միայն մեկ երկաթե մեխ'),
        jsonb_build_object('optionKey','B','contentHy','Մագնիսը պահել սեղանին և ոչինչ չչափել'),
        jsonb_build_object('optionKey','C','contentHy','Փորձարկել հայտնի կազմով մի քանի երկաթ պարունակող և չպարունակող առարկաներ նույն պայմաններում և գրանցել արդյունքները'),
        jsonb_build_object('optionKey','D','contentHy','Միաժամանակ փոխել մագնիսը, հեռավորությունը և առարկաների նյութը՝ առանց գրանցման')
      );
      v_correct := 'C';
    end if;
    v_answer := to_jsonb(v_correct);
    v_parameters := jsonb_build_object('scenarioId', v_i1, 'construct', 'hypothesis_test_design');
  else
    raise exception 'unsupported_variant_generator:%', coalesce(v_generator, '<null>');
  end if;

  if v_prompt is null or v_answer is null or v_item_type is null then
    raise exception 'generator_incomplete_render';
  end if;

  v_fingerprint := md5(
    v_family.skill_id::text || '|' ||
    regexp_replace(lower(v_prompt), '\s+', ' ', 'g') || '|' ||
    v_answer::text || '|' ||
    coalesce(v_options::text, '[]')
  );

  return jsonb_build_object(
    'templateId', v_template.id,
    'templateCode', v_template.code,
    'templateKind', v_template.template_kind,
    'templateVersion', v_template.template_version,
    'familyId', v_family.id,
    'familyCode', v_family.code,
    'skillId', v_family.skill_id,
    'generator', v_generator,
    'seed', p_seed,
    'itemType', v_item_type,
    'difficulty', v_difficulty,
    'promptHy', v_prompt,
    'parameters', v_parameters,
    'answer', v_answer,
    'tolerance', v_tolerance,
    'canonicalUnit', v_canonical_unit,
    'acceptedUnits', v_accepted_units,
    'options', v_options,
    'semanticFingerprint', v_fingerprint
  );
end;
$function$;

ALTER FUNCTION "private"."render_item_variant"(p_template_code text, p_seed text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.require_curriculum_governance_transaction()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception 'curriculum_release_governance_requires_read_committed';
  end if;
end;
$function$;

ALTER FUNCTION "private"."require_curriculum_governance_transaction"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.reserve_actor_rate_budgets(p_actor uuid, p_costs jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_key text;
  v_value jsonb;
  v_cost integer;
  v_policy private.actor_rate_policies%rowtype;
  v_requested jsonb := '{}'::jsonb;
  v_changes jsonb := '{}'::jsonb;
  v_remaining jsonb := '{}'::jsonb;
  v_now timestamptz;
  v_now_us bigint;
  v_old bigint;
  v_base bigint;
  v_next bigint;
  v_ceiling bigint;
  v_before integer;
  v_retry integer := 0;
begin
  if p_actor is null or p_actor = '00000000-0000-0000-0000-000000000000'::uuid
     or p_costs is null or jsonb_typeof(p_costs) <> 'object' then
    raise exception 'invalid_rate_budget_request' using errcode = '22023';
  end if;
  if (select count(*) from jsonb_object_keys(p_costs)) not between 1 and 4 then
    raise exception 'invalid_rate_budget_request' using errcode = '22023';
  end if;

  -- Keep account deletion/cascade and this reservation mutually consistent.
  perform 1 from auth.users where id = p_actor for key share;
  if not found then
    raise exception 'rate_budget_actor_unavailable' using errcode = '22023';
  end if;

  -- Lock the fixed registry in canonical order. The service role cannot alter
  -- policies; these locks also prevent a maintenance edit mixing two versions.
  for v_key, v_value in select key, value from jsonb_each(p_costs) order by key loop
    if jsonb_typeof(v_value) <> 'number' or v_value::text !~ '^[1-9][0-9]{0,4}$' then
      raise exception 'invalid_rate_budget_cost' using errcode = '22023';
    end if;
    v_cost := (v_value::text)::integer;
    select * into v_policy from private.actor_rate_policies
      where policy_key = v_key for share;
    if not found or v_cost > v_policy.capacity then
      raise exception 'invalid_rate_budget_policy_or_cost' using errcode = '22023';
    end if;
    v_requested := v_requested || jsonb_build_object(v_key,
      jsonb_build_object('cost', v_cost, 'capacity', v_policy.capacity,
        'interval', v_policy.token_interval_us, 'retention', v_policy.retention_seconds));
  end loop;

  -- Serialize this person's requests across workers, sessions and missing rows.
  -- A hash collision can briefly share a lock, never an allowance/state key.
  perform pg_advisory_xact_lock(hashtextextended('haiedu:actor-rate:v1:' || p_actor::text, 0));
  perform 1 from private.actor_rate_buckets
    where actor_id = p_actor and policy_key in (select jsonb_object_keys(v_requested))
    order by policy_key for update;

  -- Capture real server time AFTER waiting for locks. No caller clock argument.
  v_now := clock_timestamp();
  v_now_us := (extract(epoch from v_now) * 1000000)::bigint;
  for v_key, v_value in select key, value from jsonb_each(v_requested) order by key loop
    select debt_until_us into v_old from private.actor_rate_buckets
      where actor_id = p_actor and policy_key = v_key;
    v_base := greatest(coalesce(v_old, v_now_us), v_now_us);
    v_next := v_base + (v_value->>'cost')::bigint * (v_value->>'interval')::bigint;
    v_ceiling := v_now_us + (v_value->>'capacity')::bigint * (v_value->>'interval')::bigint;
    v_before := greatest(0, least((v_value->>'capacity')::integer,
      ((v_ceiling - v_base) / (v_value->>'interval')::bigint)::integer));
    v_remaining := v_remaining || jsonb_build_object(v_key, v_before);
    v_changes := v_changes || jsonb_build_object(v_key,
      jsonb_build_object('debt', v_next, 'retention', (v_value->>'retention')::integer));
    if v_next > v_ceiling then
      v_retry := greatest(v_retry, ((v_next - v_ceiling + 999999) / 1000000)::integer);
    end if;
  end loop;

  if v_retry > 0 then
    -- No partial spend, new bucket, expiry extension or denial-event write.
    return jsonb_build_object('allowed', false, 'retryAfterSeconds', v_retry,
      'remaining', v_remaining);
  end if;

  for v_key, v_value in select key, value from jsonb_each(v_changes) order by key loop
    insert into private.actor_rate_buckets(actor_id, policy_key, debt_until_us, expires_at)
      values (p_actor, v_key, (v_value->>'debt')::bigint,
        v_now + (v_value->>'retention')::integer * interval '1 second')
      on conflict (actor_id, policy_key) do update set
        debt_until_us = excluded.debt_until_us, expires_at = excluded.expires_at;
    v_remaining := jsonb_set(v_remaining, array[v_key], to_jsonb(
      (v_remaining->>v_key)::integer - (v_requested->v_key->>'cost')::integer));
  end loop;
  return jsonb_build_object('allowed', true, 'retryAfterSeconds', 0,
    'remaining', v_remaining);
end;
$function$;

ALTER FUNCTION "private"."reserve_actor_rate_budgets"(p_actor uuid, p_costs jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.reserve_session_rate_budgets(p_actor uuid, p_session uuid, p_costs jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_result jsonb;
begin
  if p_actor is null or p_session is null or not exists (
    select 1 from auth.sessions s join auth.users u on u.id=s.user_id
    where s.id=p_session and s.user_id=p_actor and u.deleted_at is null
      and (u.banned_until is null or u.banned_until<=clock_timestamp())
      and (s.not_after is null or s.not_after>clock_timestamp())
  ) then
    raise exception 'rate_budget_session_inactive' using errcode='42501';
  end if;
  v_result:=private.reserve_actor_rate_budgets(p_actor,p_costs);
  -- The actor lock can have waited. Re-read after admission, using wall-clock
  -- time, so expiry/revocation during that wait rolls this reservation back.
  if not exists (
    select 1 from auth.sessions s join auth.users u on u.id=s.user_id
    where s.id=p_session and s.user_id=p_actor and u.deleted_at is null
      and (u.banned_until is null or u.banned_until<=clock_timestamp())
      and (s.not_after is null or s.not_after>clock_timestamp())
  ) then
    raise exception 'rate_budget_session_inactive' using errcode='42501';
  end if;
  return v_result;
end;
$function$;

ALTER FUNCTION "private"."reserve_session_rate_budgets"(p_actor uuid, p_session uuid, p_costs jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.resource_assignment_available(a public.resource_assignments, m public.supplementary_resource_versions)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select a.status='assigned' and m.status in ('published','superseded') and m.qa->>'passed'='true' and m.qa->>'fingerprint'=m.fingerprint
 and not exists(select 1 from public.supplementary_resource_events ev join public.supplementary_resource_versions v on v.id=ev.version_id
  where v.resource_id=m.resource_id and ev.event='withdrawn' and ev.created_at>=a.created_at);
$function$;

ALTER FUNCTION "private"."resource_assignment_available"(a public.resource_assignments, m public.supplementary_resource_versions) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.resource_assignment_event_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' and new.actor_id is null and old.actor_id is not null and not exists(select 1 from public.profiles where id=old.actor_id)
 and (to_jsonb(new)-'actor_id')=(to_jsonb(old)-'actor_id') then return new;end if;
 raise exception 'assignment_event_immutable';
end;$function$;

ALTER FUNCTION "private"."resource_assignment_event_guard"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.resource_assignment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='DELETE' then raise exception 'assignment_immutable';end if;
 if (to_jsonb(new)-array['status','revision','canceled_at','cancel_reason','created_by']) is distinct from
    (to_jsonb(old)-array['status','revision','canceled_at','cancel_reason','created_by']) then raise exception 'assignment_immutable';end if;
 if new.created_by is distinct from old.created_by and not(new.created_by is null and not exists(select 1 from public.profiles where id=old.created_by)) then raise exception 'assignment_immutable';end if;
 if new.status is distinct from old.status and not(old.status='assigned' and new.status='canceled' and new.revision=old.revision+1) then raise exception 'assignment_immutable';end if;
 if old.status='canceled' and (to_jsonb(new)-'created_by') is distinct from (to_jsonb(old)-'created_by') then raise exception 'assignment_immutable';end if;
 return new;
end;$function$;

ALTER FUNCTION "private"."resource_assignment_guard"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.resource_assignment_privacy_counts(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select jsonb_build_object('materialAssignmentsReceived',(select count(*) from public.resource_assignment_recipients where student_id=p_user_id),'materialAssignmentsSent',(select count(*) from public.resource_assignments where created_by=p_user_id),
 'writingAssignmentsReceived',(select count(*) from public.writing_assignment_recipients where student_id=p_user_id),'writingAssignmentsSent',(select count(*) from public.writing_assignments where created_by=p_user_id));
$function$;

