CREATE OR REPLACE FUNCTION private.resource_assignment_public(a public.resource_assignments, m public.supplementary_resource_versions)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select jsonb_build_object('id',a.id,'material',private.supplementary_public(m),'context',jsonb_build_object('assignmentId',a.teacher_assignment_id,'curriculumReleaseId',a.curriculum_release_id,'unitId',a.unit_id),
 'recipientMode',a.recipient_mode,'recipientCount',a.recipient_count,'instructions',a.instructions,'status',a.status,'revision',a.revision,
 'assignedAt',a.created_at,'canceledAt',a.canceled_at,'cancelReason',a.cancel_reason,'available',coalesce(private.resource_assignment_available(a,m),false),
 'className',(select name from public.classes where id=a.class_id),
 'schoolName',(select name from public.schools where id=a.school_id),
 'subjectName',(select s.name_hy from public.subject_programs sp join public.subjects s on s.id=sp.subject_id where sp.id=a.subject_program_id),
 'unitTitle',(select title_hy_snapshot from public.curriculum_release_units where curriculum_release_id=a.curriculum_release_id and unit_id=a.unit_id),
 'teacherName',(select display_name from public.profiles where id=a.created_by));
$function$;

ALTER FUNCTION "private"."resource_assignment_public"(a public.resource_assignments, m public.supplementary_resource_versions) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.resource_assignment_roster(p_assignment uuid, p_ctx jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare result jsonb:='[]';r record;t timestamptz;
begin
 for r in select e.id enrollment_id,e.student_id,e.status,e.valid_from,e.valid_to,
   m.status membership_status,m.valid_from membership_from,m.valid_to membership_to,
   p.role,p.account_status,p.display_name,u.deleted_at,u.banned_until
  from public.institutional_class_enrollments e
  join public.institutional_memberships m on m.id=e.student_membership_id and m.person_id=e.student_id and m.school_id=e.school_id and m.role='student'
  join public.profiles p on p.id=e.student_id join auth.users u on u.id=p.id
  where e.teacher_assignment_id=p_assignment and e.school_id=(p_ctx->>'schoolId')::uuid
   and e.academic_year_id=(p_ctx->>'academicYearId')::uuid and e.class_id=(p_ctx->>'classId')::uuid
   and e.subject_program_id=(p_ctx->>'subjectProgramId')::uuid
   and e.status='active' and m.status='active' and p.role='student' and p.account_status='active'
  order by e.id for share of e,m,p,u
 loop
  t:=clock_timestamp();
  if r.valid_from>t or r.valid_to<=t or r.membership_from>t or r.membership_to<=t or r.deleted_at is not null or r.banned_until>t then continue;end if;
  result:=result||jsonb_build_array(jsonb_build_object('enrollmentId',r.enrollment_id,'studentId',r.student_id,'studentName',coalesce(nullif(btrim(r.display_name),''),'Աշակերտ')));
  if jsonb_array_length(result)>500 then raise exception 'assignment_recipient_limit';end if;
 end loop;
 return result;
end;$function$;

ALTER FUNCTION "private"."resource_assignment_roster"(p_assignment uuid, p_ctx jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.resource_recipient_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' then raise exception 'assignment_recipients_immutable';end if;
 if not exists(select 1 from public.resource_assignments a join public.institutional_class_enrollments e
 on e.id=new.enrollment_id and e.student_id=new.student_id and e.school_id=a.school_id and e.academic_year_id=a.academic_year_id
 and e.class_id=a.class_id and e.subject_program_id=a.subject_program_id and e.teacher_assignment_id=a.teacher_assignment_id
 where a.id=new.assignment_id) then raise exception 'assignment_recipients_invalid';end if;
 return new;
end;$function$;

ALTER FUNCTION "private"."resource_recipient_guard"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.run_actor_rate_maintenance()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_deleted integer;
  v_history_deleted integer;
  v_job_id bigint;
begin
  -- A duplicate/manual invocation never queues behind the running cleaner.
  if not pg_try_advisory_xact_lock(hashtextextended('haiedu:actor-rate:maintenance:v1', 0)) then
    return jsonb_build_object('skipped', true);
  end if;

  select jobid into v_job_id from cron.job
    where jobname = 'haiedu-bf16-counter-maintenance'
      and username = current_user and database = current_database();
  if v_job_id is null then
    raise exception 'bf16_maintenance_job_missing';
  end if;

  -- The existing primitive checks both idle expiry and fully repaid debt,
  -- skips locked rows and deletes at most500 actor/policy counter rows.
  v_deleted := private.purge_idle_actor_rate_buckets(500);

  -- pg_cron does not prune run history. Touch only this job's completed runs,
  -- retain seven days, and bound each pruning pass independently to500 rows.
  with stale as (
    select runid from cron.job_run_details
    where jobid = v_job_id and end_time < clock_timestamp() - interval '7 days'
    order by end_time, runid limit 500
  )
  delete from cron.job_run_details h using stale s where h.runid = s.runid;
  get diagnostics v_history_deleted = row_count;
  return jsonb_build_object('skipped', false, 'counterRowsRemoved', v_deleted,
    'ownHistoryRowsRemoved', v_history_deleted);
end;
$function$;

ALTER FUNCTION "private"."run_actor_rate_maintenance"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.scoped_chapter_baseline(p_student uuid, p_release uuid, p_unit uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select s.id from public.learning_sessions s
 left join public.legacy_learning_blueprint_mappings m on m.assessment_blueprint_id=s.assessment_blueprint_id
 join public.curriculum_releases target on target.id=p_release
 where s.student_id=p_student and s.mode='diagnostic' and s.status='completed'
 and ((s.assessment_policy_binding_id is not null and s.curriculum_release_id=p_release and s.governed_unit_id=p_unit)
 or (s.assessment_policy_binding_id is null and m.unit_id=p_unit and m.subject_program_id=target.subject_program_id
   and m.curriculum_release_id=s.curriculum_release_id and m.unit_code_snapshot=s.unit_code))
 order by s.completed_at,s.id limit 1;
$function$;

ALTER FUNCTION "private"."scoped_chapter_baseline"(p_student uuid, p_release uuid, p_unit uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.seed_index(p_seed text, p_salt text, p_size integer)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'private'
AS $function$ declare v_hash bigint; begin if p_size < 1 then raise exception 'seed_index_invalid_size'; end if; v_hash := (('x' || substr(md5(p_seed || ':' || p_salt),1,8))::bit(32)::bigint); return ((v_hash % p_size) + 1)::integer; end; $function$;

ALTER FUNCTION "private"."seed_index"(p_seed text, p_salt text, p_size integer) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.service_resource_assignments(p_actor_id uuid, p_auth_session_id uuid, p_action text, p_context jsonb DEFAULT '{}'::jsonb, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
#variable_conflict use_column
declare role_name text;ctx jsonb;roster jsonb;stamp text;entries jsonb:='[]';result jsonb;entry jsonb;r record;
 a public.resource_assignments%rowtype;m public.supplementary_resource_versions%rowtype;e public.institutional_class_enrollments%rowtype;
 rel uuid;unt uuid;ta uuid;enr uuid;off integer;state_filter text;search_text text;rows_n integer;selected_ids uuid[];request_hash text;reason text;material_id uuid;
begin
 if jsonb_typeof(p_context) is distinct from 'object' or jsonb_typeof(p_payload) is distinct from 'object'
 or exists(select 1 from jsonb_object_keys(p_context) k where k not in ('assignmentId','enrollmentId','curriculumReleaseId','unitId'))
 or p_action not in ('catalog','preview','assign','list','inbox','get','cancel','open') then raise exception 'assignment_request_invalid';end if;
 role_name:=private.supplementary_session(p_actor_id,p_auth_session_id);
 if role_name not in ('teacher','student') then raise exception 'assignment_forbidden';end if;
 off:=coalesce((p_payload->>'offset')::integer,0);state_filter:=coalesce(p_payload->>'state','current');
 if off not between 0 and 100000 or state_filter not in ('current','history') then raise exception 'assignment_request_invalid';end if;
 if p_action='inbox' then
  if role_name<>'student' or p_context<>'{}' or exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('offset','state')) then raise exception 'assignment_forbidden';end if;
  rows_n:=0;
  for r in select a.id,rp.enrollment_id from public.resource_assignment_recipients rp join public.resource_assignments a on a.id=rp.assignment_id
   join public.institutional_class_enrollments ie on ie.id=rp.enrollment_id and ie.student_id=p_actor_id
   where rp.student_id=p_actor_id and (case when state_filter='current' then a.status='assigned' else a.status='canceled' end)
   order by a.created_at desc,a.id,rp.enrollment_id offset off limit 51
  loop
   rows_n:=rows_n+1;if rows_n=51 then exit;end if;
   select * into strict a from public.resource_assignments where id=r.id;
   begin
    e:=private.lock_student_learning_context(p_actor_id,p_auth_session_id,r.enrollment_id,a.curriculum_release_id,a.unit_id);
   exception when raise_exception then if sqlerrm<>'learning_context_unavailable' then raise;end if;continue;end;
   if e.teacher_assignment_id<>a.teacher_assignment_id or e.school_id<>a.school_id or e.academic_year_id<>a.academic_year_id or e.class_id<>a.class_id or e.subject_program_id<>a.subject_program_id then continue;end if;
   select * into strict m from public.supplementary_resource_versions where id=a.material_version_id;
   entry:=private.resource_assignment_public(a,m);
   entry:=entry-'recipientCount'||jsonb_build_object('context',jsonb_build_object('enrollmentId',r.enrollment_id,'curriculumReleaseId',a.curriculum_release_id,'unitId',a.unit_id));
   entries:=entries||jsonb_build_array(entry);
  end loop;
  -- Recheck clocks/session/context after the bounded list, not only its first row.
  for entry in select value from jsonb_array_elements(entries) loop
   perform private.lock_student_learning_context(p_actor_id,p_auth_session_id,(entry->'context'->>'enrollmentId')::uuid,(entry->'context'->>'curriculumReleaseId')::uuid,(entry->'context'->>'unitId')::uuid);
  end loop;
  perform private.supplementary_session(p_actor_id,p_auth_session_id);
  return jsonb_build_object('assignments',entries,'hasMore',rows_n>50,'nextOffset',off+50);
 end if;
 rel:=(p_context->>'curriculumReleaseId')::uuid;unt:=(p_context->>'unitId')::uuid;ta:=(p_context->>'assignmentId')::uuid;enr:=(p_context->>'enrollmentId')::uuid;
 if rel is null or unt is null then raise exception 'assignment_request_invalid';end if;
 if role_name='teacher' then
  if ta is null or enr is not null then raise exception 'assignment_forbidden';end if;
  ctx:=private.lock_written_teacher_context(p_actor_id,p_auth_session_id,ta,rel,unt,p_action in ('preview','assign','cancel'));
 else
  if enr is null or ta is not null or p_action not in ('get','open') then raise exception 'assignment_forbidden';end if;
  e:=private.lock_student_learning_context(p_actor_id,p_auth_session_id,enr,rel,unt);ta:=e.teacher_assignment_id;
  ctx:=jsonb_build_object('schoolId',e.school_id,'academicYearId',e.academic_year_id,'classId',e.class_id,'subjectProgramId',e.subject_program_id,'readOnly',false);
 end if;
 if p_action='catalog' then
  if role_name<>'teacher' or exists(select 1 from jsonb_object_keys(p_payload) k where k<>'offset') then raise exception 'assignment_request_invalid';end if;
  rows_n:=0;
  for m in select * from public.supplementary_resource_versions where provider='platform' and status='published'
   and subject_program_id=(ctx->>'subjectProgramId')::uuid and curriculum_release_id=rel and unit_id=unt
   and qa->>'passed'='true' and qa->>'fingerprint'=fingerprint order by published_at desc,id offset off limit 51
  loop
   rows_n:=rows_n+1;if rows_n>50 then exit;end if;entries:=entries||jsonb_build_array(private.supplementary_public(m));
  end loop;
  result:=jsonb_build_object('materials',entries,'hasMore',rows_n>50,'nextOffset',off+50);
 elsif p_action in ('preview','assign') then
  if role_name<>'teacher' then raise exception 'assignment_forbidden';end if;
  if p_action='assign' then
   if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('materialId','fingerprint','requestId','rosterFingerprint','mode','enrollmentIds','instructions'))
    or p_payload->>'mode' not in ('class','selected') or p_payload->>'mode' is null
    or jsonb_typeof(coalesce(p_payload->'enrollmentIds','[]'))<>'array' or jsonb_array_length(coalesce(p_payload->'enrollmentIds','[]'))>500
    or (p_payload ? 'instructions' and jsonb_typeof(p_payload->'instructions')<>'string')
    or length(coalesce(p_payload->>'instructions',''))>2000 or p_payload->>'requestId' is null then raise exception 'assignment_request_invalid';end if;
   select coalesce(array_agg(v::uuid order by v::uuid),array[]::uuid[]) into selected_ids from jsonb_array_elements_text(coalesce(p_payload->'enrollmentIds','[]')) v;
   if cardinality(selected_ids)<>(select count(distinct v) from unnest(selected_ids) v) or
    (p_payload->>'mode'='selected' and cardinality(selected_ids)=0) or (p_payload->>'mode'='class' and cardinality(selected_ids)>0) then raise exception 'assignment_recipients_invalid';end if;
   request_hash:=encode(sha256(convert_to(jsonb_build_array(p_context,p_payload-'enrollmentIds',to_jsonb(selected_ids))::text,'UTF8')),'hex');
   perform pg_advisory_xact_lock(hashtextextended('resource-assignment-request:'||p_actor_id::text||':'||(p_payload->>'requestId')::uuid::text,0));
   select * into a from public.resource_assignments where created_by=p_actor_id and request_id=(p_payload->>'requestId')::uuid;
   if found then
    if a.request_hash<>request_hash then raise exception 'assignment_conflict';end if;
    select * into strict m from public.supplementary_resource_versions where id=a.material_version_id;
    result:=jsonb_build_object('assignment',private.resource_assignment_public(a,m),'replayed',true);
   end if;
  else
   if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('materialId','offset','search')) then raise exception 'assignment_request_invalid';end if;
  end if;
  if result is null then
   select * into m from public.supplementary_resource_versions where id=(p_payload->>'materialId')::uuid and curriculum_release_id=rel and unit_id=unt
    and subject_program_id=(ctx->>'subjectProgramId')::uuid and (provider='platform' or (assignment_id=ta and created_by=p_actor_id));
   if not found then raise exception 'assignment_unavailable';end if;
   perform pg_advisory_xact_lock(hashtextextended('supplementary:'||m.resource_id::text,0));
   select * into strict m from public.supplementary_resource_versions where id=m.id for share;
   if m.status<>'published' or m.qa->>'passed' is distinct from 'true' or m.qa->>'fingerprint' is distinct from m.fingerprint then raise exception 'assignment_unavailable';end if;
   roster:=private.resource_assignment_roster(ta,ctx);
   stamp:=encode(sha256(convert_to(roster::text,'UTF8')),'hex');
   if p_action='preview' then
    search_text:=btrim(coalesce(p_payload->>'search',''));if length(search_text)>120 then raise exception 'assignment_request_invalid';end if;
    select count(*) into rows_n from jsonb_array_elements(roster) v where position(lower(search_text) in lower(v->>'studentName'))>0;
    select coalesce(jsonb_agg(v order by v->>'enrollmentId'),'[]') into entries from
     (select v from jsonb_array_elements(roster) v where position(lower(search_text) in lower(v->>'studentName'))>0 order by v->>'enrollmentId' offset off limit 50) q;
    result:=jsonb_build_object('material',private.supplementary_public(m),'roster',entries,'rosterFingerprint',stamp,'total',jsonb_array_length(roster),'matched',rows_n,'hasMore',rows_n>off+50,'nextOffset',off+50);
   else
    if p_payload->>'fingerprint' is distinct from m.fingerprint or p_payload->>'rosterFingerprint' is distinct from stamp then raise exception 'assignment_preview_stale';end if;
    if p_payload->>'mode'='class' then select coalesce(array_agg((v->>'enrollmentId')::uuid order by v->>'enrollmentId'),array[]::uuid[]) into selected_ids from jsonb_array_elements(roster) v;end if;
    if cardinality(selected_ids)=0 or exists(select 1 from unnest(selected_ids) id where not exists(select 1 from jsonb_array_elements(roster) v where (v->>'enrollmentId')::uuid=id)) then raise exception 'assignment_recipients_invalid';end if;
    insert into public.resource_assignments(material_version_id,teacher_assignment_id,school_id,academic_year_id,class_id,subject_program_id,curriculum_release_id,unit_id,created_by,request_id,request_hash,recipient_mode,recipient_count,instructions)
     values(m.id,ta,(ctx->>'schoolId')::uuid,(ctx->>'academicYearId')::uuid,(ctx->>'classId')::uuid,(ctx->>'subjectProgramId')::uuid,rel,unt,p_actor_id,(p_payload->>'requestId')::uuid,request_hash,p_payload->>'mode',cardinality(selected_ids),btrim(coalesce(p_payload->>'instructions',''))) returning * into a;
    insert into public.resource_assignment_recipients(assignment_id,enrollment_id,student_id)
     select a.id,(v->>'enrollmentId')::uuid,(v->>'studentId')::uuid from jsonb_array_elements(roster) v where (v->>'enrollmentId')::uuid=any(selected_ids);
    insert into public.resource_assignment_events(assignment_id,actor_id,event,detail)
     values(a.id,p_actor_id,'assigned',jsonb_build_object('mode',a.recipient_mode,'recipientCount',a.recipient_count,'materialVersionId',m.id,'fingerprint',m.fingerprint));
    if stamp<>encode(sha256(convert_to(private.resource_assignment_roster(ta,ctx)::text,'UTF8')),'hex') then raise exception 'assignment_preview_stale';end if;
    result:=jsonb_build_object('assignment',private.resource_assignment_public(a,m),'replayed',false);
   end if;
  end if;
 elsif p_action='list' then
  if role_name<>'teacher' or exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('offset','state')) then raise exception 'assignment_request_invalid';end if;
  select coalesce(jsonb_agg(entry order by created_at desc,id),'[]') into entries from (
   select a.created_at,a.id,private.resource_assignment_public(a,m) entry from public.resource_assignments a
   join public.supplementary_resource_versions m on m.id=a.material_version_id
   where a.teacher_assignment_id=ta and a.curriculum_release_id=rel and a.unit_id=unt and a.created_by=p_actor_id
   and (case when state_filter='current' then a.status='assigned' else a.status='canceled' end)
   order by a.created_at desc,a.id offset off limit 51) q;
  result:=jsonb_build_object('assignments',case when jsonb_array_length(entries)>50 then entries-50 else entries end,'hasMore',jsonb_array_length(entries)>50,'nextOffset',off+50,'readOnly',ctx->'readOnly');
 else
  if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('id','revision','reason')) or p_payload->>'id' is null then raise exception 'assignment_request_invalid';end if;
  select * into a from public.resource_assignments where id=(p_payload->>'id')::uuid and teacher_assignment_id=ta and curriculum_release_id=rel and unit_id=unt
   and school_id=(ctx->>'schoolId')::uuid and class_id=(ctx->>'classId')::uuid
   and (case when role_name='teacher' then created_by=p_actor_id else exists(select 1 from public.resource_assignment_recipients rp where rp.assignment_id=resource_assignments.id and rp.enrollment_id=enr and rp.student_id=p_actor_id) end);
  if not found then raise exception 'assignment_unavailable';end if;
  select * into strict m from public.supplementary_resource_versions where id=a.material_version_id;
  -- Same order as resource publication and withdrawal; re-read state after lock waits.
  perform pg_advisory_xact_lock(hashtextextended('supplementary:'||m.resource_id::text,0));
  select * into strict m from public.supplementary_resource_versions where id=m.id for share;
  select * into strict a from public.resource_assignments where id=a.id for update;
  if p_action='cancel' then
   if role_name<>'teacher' then raise exception 'assignment_forbidden';end if;
   reason:=btrim(coalesce(p_payload->>'reason',''));
   if length(reason) not between 1 and 1000 then raise exception 'assignment_reason_required';end if;
   if (p_payload->>'revision')::integer is null then raise exception 'assignment_request_invalid';end if;
   if a.status='canceled' then
    if a.cancel_reason<>reason or (p_payload->>'revision')::integer not in (a.revision,a.revision-1) then raise exception 'assignment_conflict';end if;
   else
    if (p_payload->>'revision')::integer is distinct from a.revision then raise exception 'assignment_conflict';end if;
    update public.resource_assignments set status='canceled',revision=revision+1,canceled_at=clock_timestamp(),cancel_reason=reason where id=a.id returning * into a;
    insert into public.resource_assignment_events(assignment_id,actor_id,event,detail) values(a.id,p_actor_id,'canceled',jsonb_build_object('reason',reason));
   end if;
  end if;
  entry:=private.resource_assignment_public(a,m);
  if role_name='student' then entry:=entry-'recipientCount'||jsonb_build_object('context',p_context);end if;
  result:=jsonb_build_object('assignment',entry,'readOnly',ctx->'readOnly');
  if p_action in ('get','cancel') and role_name='teacher' then
   result:=result||jsonb_build_object('recipients',(select coalesce(jsonb_agg(jsonb_build_object('enrollmentId',rp.enrollment_id,'studentName',coalesce(nullif(btrim(p.display_name),''),'Աշակերտ')) order by rp.enrollment_id),'[]')
    from public.resource_assignment_recipients rp join public.profiles p on p.id=rp.student_id where rp.assignment_id=a.id),
    'events',(select coalesce(jsonb_agg(jsonb_build_object('event',event,'at',created_at,'detail',detail) order by created_at,id),'[]') from public.resource_assignment_events where assignment_id=a.id));
  end if;
  if p_action='open' then
   if not coalesce(private.resource_assignment_available(a,m),false) or (m.definition->>'format'='pdf' and m.object_path is null) then raise exception 'assignment_unavailable';end if;
   result:=result||jsonb_build_object('delivery',jsonb_build_object('path',m.object_path,'sha256',m.file_sha256,'bytes',m.file_bytes,'url',m.definition->>'url'));
  end if;
 end if;
 if role_name='teacher' then
  perform private.lock_written_teacher_context(p_actor_id,p_auth_session_id,ta,rel,unt,p_action in ('preview','assign','cancel'));
 else perform private.lock_student_learning_context(p_actor_id,p_auth_session_id,enr,rel,unt);end if;
 perform private.supplementary_session(p_actor_id,p_auth_session_id);
 return result;
end;$function$;

ALTER FUNCTION "private"."service_resource_assignments"(p_actor_id uuid, p_auth_session_id uuid, p_action text, p_context jsonb, p_payload jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.service_supplementary_resources(p_actor_id uuid, p_auth_session_id uuid, p_aal text, p_action text, p_context jsonb DEFAULT '{}'::jsonb, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
#variable_conflict use_column
declare role_name text;ctx jsonb;result jsonb;entries jsonb:='[]';r record;m public.supplementary_resource_versions%rowtype;n public.supplementary_resource_versions%rowtype;
 rel uuid:=(p_context->>'curriculumReleaseId')::uuid;unt uuid:=(p_context->>'unitId')::uuid;teacher boolean;is_student boolean;off integer;reason text;issues jsonb;
begin
 if p_aal not in ('aal1','aal2') or p_aal is null or jsonb_typeof(p_context) is distinct from 'object' or jsonb_typeof(p_payload) is distinct from 'object'
 or exists(select 1 from jsonb_object_keys(p_context) k where k not in ('curriculumReleaseId','unitId','assignmentId','enrollmentId'))
 or p_action not in ('contexts','list','get','create','revise','qa','publish','withdraw','upload_check','attach','open') then raise exception 'resource_request_invalid';end if;
 role_name:=private.supplementary_session(p_actor_id,p_auth_session_id);teacher:=role_name='teacher';is_student:=role_name='student';
 if role_name not in ('teacher','student','admin','content_admin') then raise exception 'resource_forbidden';end if;
 if p_action='contexts' then
  if p_context<>'{}' or p_payload<>'{}' then raise exception 'resource_request_invalid';end if;
  if is_student then return public.service_student_learning_navigation(p_actor_id,p_auth_session_id)||jsonb_build_object('role',role_name);end if;
  for r in select distinct cr.id release_id,ru.unit_id,a.id assignment_id,sp.id programme_id,s.name_hy subject_name,g.label_hy grade_label,
    ru.title_hy_snapshot unit_title,ru.sequence_order_snapshot seq,cl.name class_name,sch.name school_name,y.label year_label
   from public.curriculum_releases cr join public.curriculum_release_units ru on ru.curriculum_release_id=cr.id
   join public.subject_programs sp on sp.id=cr.subject_program_id join public.subjects s on s.id=sp.subject_id join public.grades g on g.id=sp.grade_id
   left join public.teacher_assignments a on teacher and a.subject_program_id=sp.id
   left join public.institutional_memberships im on im.id=a.teacher_membership_id
   left join public.classes cl on cl.id=a.class_id left join public.schools sch on sch.id=a.school_id left join public.academic_years y on y.id=a.academic_year_id
   where cr.status in ('pilot','production') and (not teacher or im.person_id=p_actor_id)
   order by subject_name,grade_label,programme_id,school_name,class_name,year_label,assignment_id,seq,unit_id,release_id
  loop
   ctx:=jsonb_build_object('curriculumReleaseId',r.release_id,'unitId',r.unit_id)||case when teacher then jsonb_build_object('assignmentId',r.assignment_id) else '{}'::jsonb end;
   begin perform private.supplementary_context(p_actor_id,p_auth_session_id,role_name,ctx);
   exception when raise_exception then if sqlerrm not in ('resource_forbidden','written_context_unavailable','written_read_only') then raise;end if;continue;end;
   entries:=entries||jsonb_build_array(ctx||jsonb_build_object('subjectProgramId',r.programme_id,'subjectNameHy',r.subject_name,'gradeLabelHy',r.grade_label,'unitTitleHy',r.unit_title,'className',r.class_name,'schoolName',r.school_name,'academicYearLabel',r.year_label));
  end loop;
  for ctx in select value from jsonb_array_elements(entries) loop
   perform private.supplementary_context(p_actor_id,p_auth_session_id,role_name,ctx);
  end loop;
  perform private.supplementary_session(p_actor_id,p_auth_session_id);
  return jsonb_build_object('role',role_name,'contexts',entries);
 end if;
 ctx:=private.supplementary_context(p_actor_id,p_auth_session_id,role_name,p_context);
 if is_student and p_action not in ('list','get','open') then raise exception 'resource_forbidden';end if;
 if p_action='list' then
  if exists(select 1 from jsonb_object_keys(p_payload) k where k<>'offset') then raise exception 'resource_request_invalid';end if;
  off:=coalesce((p_payload->>'offset')::integer,0);if off not between 0 and 100000 then raise exception 'resource_request_invalid';end if;
  select coalesce(jsonb_agg(entry order by created_at desc,id),'[]') into entries from (
   select m.id,m.created_at,private.supplementary_public(m)||case when is_student then '{}'::jsonb else jsonb_build_object('qa',m.qa) end entry
   from public.supplementary_resource_versions m where m.curriculum_release_id=rel and m.unit_id=unt
   and m.subject_program_id=(ctx->>'subjectProgramId')::uuid
   and ((is_student and m.status='published' and (m.provider='platform' or (m.assignment_id=(ctx->>'assignmentId')::uuid and m.created_by=(select im.person_id from public.teacher_assignments ta join public.institutional_memberships im on im.id=ta.teacher_membership_id where ta.id=m.assignment_id))))
     or (not is_student and ((teacher and m.provider='teacher' and m.assignment_id=(ctx->>'assignmentId')::uuid and m.created_by=p_actor_id) or (not teacher and m.provider='platform'))
       and not exists(select 1 from public.supplementary_resource_versions newer where newer.resource_id=m.resource_id and newer.version_no>m.version_no)))
   order by m.created_at desc,m.id offset off limit 51
  ) q;
  result:=jsonb_build_object('materials',entries,'hasMore',jsonb_array_length(entries)>50);
  if jsonb_array_length(entries)>50 then result:=jsonb_set(result,'{materials}',entries-50);end if;
 elsif p_action='create' then
  if exists(select 1 from jsonb_object_keys(p_payload) k where k<>'definition') then raise exception 'resource_request_invalid';end if;
  perform private.supplementary_definition(p_payload->'definition',teacher);
  insert into public.supplementary_resource_versions(version_no,subject_program_id,curriculum_release_id,unit_id,assignment_id,provider,created_by,definition,fingerprint)
   values(1,(ctx->>'subjectProgramId')::uuid,rel,unt,(ctx->>'assignmentId')::uuid,case when teacher then 'teacher' else 'platform' end,p_actor_id,p_payload->'definition','') returning * into m;
  insert into public.supplementary_resource_events(version_id,actor_id,event,actor_aal) values(m.id,p_actor_id,'created',p_aal);
  result:=jsonb_build_object('material',private.supplementary_public(m)||jsonb_build_object('definition',m.definition,'qa',m.qa));
 else
  if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('id','fingerprint','definition','reason','objectPath','fileBytes','fileSha256')) then raise exception 'resource_request_invalid';end if;
  select * into m from public.supplementary_resource_versions where id=(p_payload->>'id')::uuid and curriculum_release_id=rel and unit_id=unt and subject_program_id=(ctx->>'subjectProgramId')::uuid
   and ((is_student and (provider='platform' or (assignment_id=(ctx->>'assignmentId')::uuid and created_by=(select im.person_id from public.teacher_assignments ta join public.institutional_memberships im on im.id=ta.teacher_membership_id where ta.id=assignment_id)))) or
       (not is_student and ((teacher and provider='teacher' and assignment_id=(ctx->>'assignmentId')::uuid and created_by=p_actor_id) or (not teacher and provider='platform'))));
  if not found then raise exception 'resource_unavailable';end if;
  perform pg_advisory_xact_lock(hashtextextended('supplementary:'||m.resource_id::text,0));
  select * into strict m from public.supplementary_resource_versions where id=m.id for update;
  if is_student and m.status<>'published' then raise exception 'resource_unavailable';end if;
  if p_action not in ('get','open') then
   if p_payload->>'fingerprint' is distinct from m.fingerprint or exists(select 1 from public.supplementary_resource_versions where resource_id=m.resource_id and version_no>m.version_no) then raise exception 'resource_conflict';end if;
   if p_action in ('publish','withdraw') and not teacher and p_aal<>'aal2' then raise exception 'resource_mfa_required';end if;
  end if;
  reason:=btrim(coalesce(p_payload->>'reason',''));
  if p_action='revise' then
   if length(reason) not between 1 and 2000 then raise exception 'resource_reason_required';end if;
   perform private.supplementary_definition(p_payload->'definition',teacher);
   insert into public.supplementary_resource_versions(resource_id,version_no,subject_program_id,curriculum_release_id,unit_id,assignment_id,provider,created_by,definition,fingerprint)
    values(m.resource_id,m.version_no+1,m.subject_program_id,rel,unt,m.assignment_id,m.provider,p_actor_id,p_payload->'definition','') returning * into n;
   insert into public.supplementary_resource_events(version_id,actor_id,event,actor_aal,detail) values(n.id,p_actor_id,'revised',p_aal,jsonb_build_object('from',m.id,'reason',reason));m:=n;
  elsif p_action in ('upload_check','attach','qa') then
   if m.status<>'draft' then raise exception 'resource_read_only';end if;
   if p_action in ('upload_check','attach') then
    if m.definition->>'format'<>'pdf' or m.object_path is not null then raise exception 'resource_conflict';end if;
    if p_action='attach' then
     if p_payload->>'objectPath' !~ ('^'||m.id::text||'/[0-9a-f-]{36}\.pdf$') or p_payload->>'objectPath' is null
      or (p_payload->>'fileBytes')::integer not between 1 and 5242880 or p_payload->>'fileBytes' is null
      or p_payload->>'fileSha256' !~ '^[a-f0-9]{64}$' or p_payload->>'fileSha256' is null then raise exception 'resource_file_invalid';end if;
     update public.supplementary_resource_versions set object_path=p_payload->>'objectPath',file_bytes=(p_payload->>'fileBytes')::integer,file_sha256=p_payload->>'fileSha256',qa=null where id=m.id returning * into m;
     insert into public.supplementary_resource_events(version_id,actor_id,event,actor_aal) values(m.id,p_actor_id,'file_attached',p_aal);
    end if;
   else
    perform private.supplementary_definition(m.definition,teacher);issues:=case when m.definition->>'format'='pdf' and m.object_path is null then '["file_required"]'::jsonb else '[]'::jsonb end;
    update public.supplementary_resource_versions set qa=jsonb_build_object('passed',issues='[]'::jsonb,'issues',issues,'fingerprint',m.fingerprint,'checkedAt',clock_timestamp()) where id=m.id returning * into m;
    insert into public.supplementary_resource_events(version_id,actor_id,event,actor_aal,detail) values(m.id,p_actor_id,'qa',p_aal,m.qa);
   end if;
  elsif p_action='publish' and m.status<>'published' then
   if m.status<>'draft' then raise exception 'resource_read_only';end if;
   if m.qa->>'passed' is distinct from 'true' or m.qa->>'fingerprint' is distinct from m.fingerprint then raise exception 'resource_qa_required';end if;
   with old as (update public.supplementary_resource_versions set status='superseded' where resource_id=m.resource_id and status='published' returning id)
    insert into public.supplementary_resource_events(version_id,actor_id,event,actor_aal,detail) select id,p_actor_id,'superseded',p_aal,jsonb_build_object('replacement',m.id) from old;
   update public.supplementary_resource_versions set status='published',published_at=clock_timestamp() where id=m.id returning * into m;
   insert into public.supplementary_resource_events(version_id,actor_id,event,actor_aal) values(m.id,p_actor_id,'published',p_aal);
  elsif p_action='withdraw' then
   if length(reason) not between 1 and 2000 then raise exception 'resource_reason_required';end if;
   -- Withdraw the logical resource, including its published predecessor while a revision is pending.
   with old as (update public.supplementary_resource_versions set status='withdrawn' where resource_id=m.resource_id and status in ('draft','published') returning id)
    insert into public.supplementary_resource_events(version_id,actor_id,event,actor_aal,detail) select id,p_actor_id,'withdrawn',p_aal,jsonb_build_object('reason',reason) from old;
   select * into m from public.supplementary_resource_versions where id=m.id;
  end if;
  result:=jsonb_build_object('material',private.supplementary_public(m)||case when is_student then '{}'::jsonb else jsonb_build_object('definition',m.definition,'qa',m.qa) end);
  if p_action='get' and not is_student then
   result:=result||jsonb_build_object('history',(select coalesce(jsonb_agg(private.supplementary_public(v) order by v.version_no desc),'[]') from public.supplementary_resource_versions v where v.resource_id=m.resource_id),
    'events',(select coalesce(jsonb_agg(jsonb_build_object('event',ev.event,'version',v.version_no,'at',ev.created_at,'detail',ev.detail) order by ev.created_at desc),'[]') from public.supplementary_resource_events ev join public.supplementary_resource_versions v on v.id=ev.version_id where v.resource_id=m.resource_id));
  end if;
  if p_action='open' then
   if m.definition->>'format'='pdf' and m.object_path is null then raise exception 'resource_unavailable';end if;
   result:=result||jsonb_build_object('delivery',jsonb_build_object('path',m.object_path,'sha256',m.file_sha256,'bytes',m.file_bytes,'url',m.definition->>'url'));
  end if;
 end if;
 perform private.supplementary_context(p_actor_id,p_auth_session_id,role_name,p_context);
 perform private.supplementary_session(p_actor_id,p_auth_session_id);
 return result;
end;$function$;

ALTER FUNCTION "private"."service_supplementary_resources"(p_actor_id uuid, p_auth_session_id uuid, p_aal text, p_action text, p_context jsonb, p_payload jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.service_teacher_feedback(p_actor uuid, p_auth uuid, p_action text, p_context jsonb DEFAULT '{}'::jsonb, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_column
declare ctx jsonb; result jsonb; written jsonb; w public.written_work%rowtype; d private.teacher_feedback_drafts%rowtype;
 sn private.teacher_feedback_snippets%rowtype; receipt private.teacher_feedback_receipts%rowtype;
 assignment uuid:=(p_context->>'assignmentId')::uuid; rel uuid:=(p_context->>'curriculumReleaseId')::uuid; unt uuid:=(p_context->>'unitId')::uuid;
 work uuid:=(p_payload->>'workId')::uuid; req uuid; expected integer; version_n integer; info jsonb; definition jsonb; c jsonb;
 is_archived boolean; skip_n integer; request_data jsonb; review uuid;
begin
 if p_actor is null or p_auth is null or jsonb_typeof(p_context) is distinct from 'object' or jsonb_typeof(p_payload) is distinct from 'object'
 or p_action not in ('open','save_draft','publish','snippets','save_snippet') then raise exception 'feedback_request_invalid';end if;
 if p_action in ('snippets','save_snippet') then
  if p_context<>'{}' then raise exception 'feedback_request_invalid';end if;
  perform private.lock_feedback_actor(p_actor,p_auth);
  if p_action='snippets' then
   if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('archived','offset')) then raise exception 'feedback_request_invalid';end if;
   is_archived:=coalesce((p_payload->>'archived')::boolean,false);skip_n:=coalesce((p_payload->>'offset')::integer,0);
   if skip_n not between 0 and 100000 then raise exception 'feedback_request_invalid';end if;
   select jsonb_build_object('snippets',coalesce(jsonb_agg(to_jsonb(q)-'teacher_id' order by updated_at desc,id),'[]'),'hasMore',count(*)>20)
   into result from(select * from private.teacher_feedback_snippets where teacher_id=p_actor and archived=is_archived order by updated_at desc,id offset skip_n limit 21) q;
   result:=jsonb_set(result,'{snippets}',coalesce((select jsonb_agg(v) from(select v from jsonb_array_elements(result->'snippets') v limit 20) z),'[]'));
  else
   if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('id','expectedRevision','title','body','archived'))
   or jsonb_typeof(p_payload->'expectedRevision') is distinct from 'number' or (p_payload->>'expectedRevision')!~'^[0-9]+$'
   or (p_payload->>'expectedRevision')::numeric>2147483646 or jsonb_typeof(p_payload->'title') is distinct from 'string'
   or length(btrim(p_payload->>'title')) not between 1 and 80 or jsonb_typeof(p_payload->'body') is distinct from 'string'
   or length(btrim(p_payload->>'body')) not between 1 and 2000 or jsonb_typeof(p_payload->'archived') is distinct from 'boolean' then raise exception 'feedback_request_invalid';end if;
   req:=(p_payload->>'id')::uuid;expected:=(p_payload->>'expectedRevision')::integer;if req is null then raise exception 'feedback_request_invalid';end if;
   perform pg_advisory_xact_lock(hashtextextended('feedback-snippets:'||p_actor::text,0));
   select * into sn from private.teacher_feedback_snippets where id=req for update;
   if found and sn.teacher_id<>p_actor then raise exception 'feedback_context_unavailable';end if;
   if sn.id is not null and sn.revision=expected+1 and sn.title=btrim(p_payload->>'title') and sn.body=btrim(p_payload->>'body') and sn.archived=(p_payload->>'archived')::boolean then
    result:=jsonb_build_object('snippet',to_jsonb(sn)-'teacher_id');
   else
    if coalesce(sn.revision,0)<>expected then raise exception 'feedback_conflict';end if;
    if not (p_payload->>'archived')::boolean and (sn.id is null or sn.archived)
    and (select count(*) from private.teacher_feedback_snippets where teacher_id=p_actor and not archived)>=50 then raise exception 'feedback_snippet_limit';end if;
    insert into private.teacher_feedback_snippets(id,teacher_id,title,body,archived,revision) values(req,p_actor,btrim(p_payload->>'title'),btrim(p_payload->>'body'),(p_payload->>'archived')::boolean,1)
    on conflict(id) do update set title=excluded.title,body=excluded.body,archived=excluded.archived,revision=private.teacher_feedback_snippets.revision+1,updated_at=clock_timestamp() returning * into sn;
    result:=jsonb_build_object('snippet',to_jsonb(sn)-'teacher_id');
   end if;
  end if;
  perform private.lock_feedback_actor(p_actor,p_auth);
 else
  if assignment is null or rel is null or unt is null or work is null or exists(select 1 from jsonb_object_keys(p_context) k where k not in ('assignmentId','curriculumReleaseId','unitId')) then raise exception 'feedback_request_invalid';end if;
  ctx:=private.lock_written_teacher_context(p_actor,p_auth,assignment,rel,unt,p_action<>'open');
  select * into w from public.written_work where id=work and school_id=(ctx->>'schoolId')::uuid and academic_year_id=(ctx->>'academicYearId')::uuid
   and class_id=(ctx->>'classId')::uuid and subject_program_id=(ctx->>'subjectProgramId')::uuid and curriculum_release_id=rel and unit_id=unt for update;
  if not found or w.current_submission_id is null then raise exception 'feedback_context_unavailable';end if;
  select * into d from private.teacher_feedback_drafts where teacher_id=p_actor and work_id=w.id for update;
  if p_action='open' then
   if exists(select 1 from jsonb_object_keys(p_payload) k where k<>'workId') then raise exception 'feedback_request_invalid';end if;
   written:=private.service_written_work(p_actor,p_auth,'inspect',p_context,p_payload);
   select coalesce(jsonb_agg(to_jsonb(q)-'teacher_id' order by updated_at desc,id),'[]') into info from(select * from private.teacher_feedback_snippets where teacher_id=p_actor and not archived order by updated_at desc,id limit 20) q;
   result:=jsonb_build_object('writtenWork',written,'draft',case when d.work_id is null then null else to_jsonb(d)-array['teacher_id','work_id'] end,'snippets',info,'snippetsHasMore',(select count(*)>20 from private.teacher_feedback_snippets where teacher_id=p_actor and not archived));
  else
   if jsonb_typeof(p_payload->'expectedRevision') is distinct from 'number' or (p_payload->>'expectedRevision')!~'^[0-9]+$'
   or jsonb_typeof(p_payload->'draftRevision') is distinct from 'number' or (p_payload->>'draftRevision')!~'^[0-9]+$'
   or (p_payload->>'expectedRevision')::numeric>2147483646 or (p_payload->>'draftRevision')::numeric>2147483646 then raise exception 'feedback_request_invalid';end if;
   expected:=(p_payload->>'expectedRevision')::integer;version_n:=(p_payload->>'draftRevision')::integer;
   if p_action='publish' then
    if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('workId','expectedRevision','draftRevision','decision','requestId'))
    or coalesce(p_payload->>'decision','') not in ('assessed','return') then raise exception 'feedback_request_invalid';end if;
    req:=(p_payload->>'requestId')::uuid;if req is null then raise exception 'feedback_request_invalid';end if;
    perform pg_advisory_xact_lock(hashtextextended('feedback-publish:'||p_actor::text||':'||req::text,0));
    request_data:=jsonb_build_object('context',p_context,'payload',p_payload-'requestId');
    select * into receipt from private.teacher_feedback_receipts where teacher_id=p_actor and request_id=req;
    if found then
     if receipt.work_id<>w.id or receipt.request_data<>request_data then raise exception 'feedback_conflict';end if;
     written:=private.service_written_work(p_actor,p_auth,'inspect',p_context,jsonb_build_object('workId',work));
     result:=jsonb_build_object('writtenWork',written,'receipt',jsonb_build_object('requestId',req,'reviewId',receipt.review_id,'replayed',true));
    end if;
   end if;
   if p_action='save_draft' and result is null and w.revision=expected and d.work_revision=w.revision and d.submission_id=w.current_submission_id and d.revision=version_n+1 and d.data=p_payload->'data' and not exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('workId','expectedRevision','draftRevision','data')) then result:=jsonb_build_object('draft',to_jsonb(d)-array['teacher_id','work_id']);end if;
   if result is null then
    if w.revision<>expected or w.state not in ('submitted','reviewed') or coalesce(d.revision,0)<>version_n or (d.work_id is not null and (d.work_revision<>w.revision or d.submission_id<>w.current_submission_id)) then raise exception 'feedback_conflict';end if;
    if p_action='save_draft' then
     if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('workId','expectedRevision','draftRevision','data')) then raise exception 'feedback_request_invalid';end if;
     info:=p_payload->'data';
     if jsonb_typeof(info) is distinct from 'object' or exists(select 1 from jsonb_object_keys(info) k where k not in ('scores','feedback','changeReason'))
     or jsonb_typeof(info->'scores') is distinct from 'object' or jsonb_typeof(info->'feedback') is distinct from 'string' or length(info->>'feedback')>4000
     or jsonb_typeof(info->'changeReason') is distinct from 'string' or length(info->>'changeReason')>1000 then raise exception 'feedback_request_invalid';end if;
     select definition into definition from public.written_task_versions where id=w.task_version_id;
     if exists(select 1 from jsonb_object_keys(info->'scores') k where not exists(select 1 from jsonb_array_elements(definition->'criteria') c where c->>'key'=k)) then raise exception 'feedback_request_invalid';end if;
     for c in select value from jsonb_array_elements(definition->'criteria') loop
      if info->'scores' ? (c->>'key') and info->'scores'->(c->>'key')<>'null'::jsonb and
       (jsonb_typeof(info->'scores'->(c->>'key'))<>'number' or coalesce(info->'scores'->>(c->>'key'),'')!~'^[0-9]+$' or (info->'scores'->>(c->>'key'))::numeric>=jsonb_array_length(c->'descriptors')) then raise exception 'feedback_request_invalid';end if;
     end loop;
     insert into private.teacher_feedback_drafts(teacher_id,work_id,submission_id,work_revision,revision,data) values(p_actor,w.id,w.current_submission_id,w.revision,1,info)
     on conflict(teacher_id,work_id) do update set revision=private.teacher_feedback_drafts.revision+1,data=excluded.data,updated_at=clock_timestamp() returning * into d;
     result:=jsonb_build_object('draft',to_jsonb(d)-array['teacher_id','work_id']);
    else
     if d.work_id is null then raise exception 'feedback_conflict';end if;
     written:=private.service_written_work(p_actor,p_auth,'review',p_context,jsonb_build_object('workId',work,'expectedRevision',expected,'decision',p_payload->>'decision',
      'scores',case when p_payload->>'decision'='assessed' then d.data->'scores' else 'null'::jsonb end,'feedback',d.data->>'feedback','changeReason',d.data->>'changeReason'));
     review:=((written->'submissions'->-1)->'reviews'->-1->>'id')::uuid;
     insert into private.teacher_feedback_receipts(teacher_id,request_id,work_id,review_id,request_data) values(p_actor,req,work,review,request_data);
     result:=jsonb_build_object('writtenWork',written,'receipt',jsonb_build_object('requestId',req,'reviewId',review,'replayed',false));
    end if;
   end if;
  end if;
  perform private.lock_written_teacher_context(p_actor,p_auth,assignment,rel,unt,p_action<>'open');
 end if;
 return result||jsonb_build_object('version','teacher-feedback-v1');
exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'feedback_request_invalid';
end;$function$;

ALTER FUNCTION "private"."service_teacher_feedback"(p_actor uuid, p_auth uuid, p_action text, p_context jsonb, p_payload jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.service_teacher_task_delivery(p_actor uuid, p_auth uuid, p_action text, p_context jsonb, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
#variable_conflict use_column
declare ctx jsonb; d public.teacher_task_drafts%rowtype; a public.teacher_task_deliveries%rowtype; v public.teacher_task_versions%rowtype;
 roster jsonb; stamp text; selected_ids uuid[]; request_hash text; result jsonb; entries jsonb; off integer; needle text; n integer;
 ta uuid:=(p_context->>'assignmentId')::uuid; rel uuid:=(p_context->>'curriculumReleaseId')::uuid; unt uuid:=(p_context->>'unitId')::uuid;
begin
 if jsonb_typeof(p_context) is distinct from 'object' or jsonb_typeof(p_payload) is distinct from 'object' or ta is null or rel is null or unt is null
 or exists(select 1 from jsonb_object_keys(p_context) k where k not in ('assignmentId','curriculumReleaseId','unitId')) or p_action not in ('preview','assign','get','list') then raise exception 'assignment_request_invalid';end if;
 ctx:=private.lock_written_teacher_context(p_actor,p_auth,ta,rel,unt,p_action in ('preview','assign'));
 if p_action='assign' then
  if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('id','expectedRevision','definition','requestId','rosterFingerprint','mode','enrollmentIds'))
  or p_payload->>'requestId' is null or p_payload->>'mode' is null or p_payload->>'mode' not in ('class','selected') or jsonb_typeof(p_payload->'definition') is distinct from 'object'
  or jsonb_typeof(p_payload->'enrollmentIds') is distinct from 'array' or jsonb_array_length(p_payload->'enrollmentIds')>500
  then raise exception 'assignment_request_invalid';end if;
  select coalesce(array_agg(x::uuid order by x::uuid),array[]::uuid[]) into selected_ids from jsonb_array_elements_text(p_payload->'enrollmentIds') x;
  if cardinality(selected_ids)<>(select count(distinct x) from unnest(selected_ids) x) or (p_payload->>'mode'='class' and cardinality(selected_ids)>0) or (p_payload->>'mode'='selected' and cardinality(selected_ids)=0) then raise exception 'assignment_recipients_invalid';end if;
  request_hash:=encode(sha256(convert_to(jsonb_build_array(p_context,p_payload-'enrollmentIds',to_jsonb(selected_ids))::text,'UTF8')),'hex');
  perform pg_advisory_xact_lock(hashtextextended('teacher-task-send:'||p_actor::text||':'||(p_payload->>'requestId')::uuid::text,0));
  select * into a from public.teacher_task_deliveries where created_by=p_actor and request_id=(p_payload->>'requestId')::uuid;
  if found then
   if a.request_hash<>request_hash then raise exception 'assignment_conflict';end if;
   result:=jsonb_build_object('delivery',private.teacher_task_delivery_public(a),'replayed',true);
  end if;
 end if;
 if p_action in ('preview','assign') and result is null then
  select * into d from public.teacher_task_drafts where id=(p_payload->>'id')::uuid and created_by=p_actor and teacher_assignment_id=ta and curriculum_release_id=rel and unit_id=unt for update;
  if not found then raise exception 'task_draft_unavailable';end if;
  roster:=private.resource_assignment_roster(ta,ctx);stamp:=encode(sha256(convert_to(roster::text,'UTF8')),'hex');
  if p_action='preview' then
   if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('id','offset','search')) then raise exception 'assignment_request_invalid';end if;
   off:=coalesce((p_payload->>'offset')::integer,0);needle:=btrim(coalesce(p_payload->>'search',''));
   if off not between 0 and 100000 or length(needle)>120 then raise exception 'assignment_request_invalid';end if;
   select count(*) into n from jsonb_array_elements(roster) x where position(lower(needle) in lower(x->>'studentName'))>0;
   select coalesce(jsonb_agg(x order by x->>'enrollmentId'),'[]') into entries from (select x from jsonb_array_elements(roster) x where position(lower(needle) in lower(x->>'studentName'))>0 order by x->>'enrollmentId' offset off limit 50) q;
   result:=jsonb_build_object('draft',jsonb_build_object('id',d.id,'revision',d.revision,'definition',d.definition),'roster',entries,'total',jsonb_array_length(roster),'hasMore',n>off+50,'nextOffset',off+50,'rosterFingerprint',stamp,'alreadyAssigned',(select coalesce(jsonb_agg(rp.enrollment_id order by rp.enrollment_id),'[]') from public.teacher_task_delivery_recipients rp join public.teacher_task_deliveries old on old.id=rp.delivery_id join public.teacher_task_versions frozen on frozen.id=old.task_version_id where frozen.draft_id=d.id and frozen.draft_revision=d.revision and exists(select 1 from jsonb_array_elements(roster) member where (member->>'enrollmentId')::uuid=rp.enrollment_id)));
  else
   if (p_payload->>'expectedRevision')::integer is distinct from d.revision or p_payload->'definition' is distinct from d.definition or p_payload->>'rosterFingerprint' is distinct from stamp then raise exception 'assignment_preview_stale';end if;
   if p_payload->>'mode'='class' then select coalesce(array_agg((x->>'enrollmentId')::uuid order by x->>'enrollmentId'),array[]::uuid[]) into selected_ids from jsonb_array_elements(roster) x;end if;
   if cardinality(selected_ids)=0 or exists(select 1 from unnest(selected_ids) member where not exists(select 1 from jsonb_array_elements(roster) x where (x->>'enrollmentId')::uuid=member)) then raise exception 'assignment_recipients_invalid';end if;
   select * into v from public.teacher_task_versions where draft_id=d.id and draft_revision=d.revision;
   if not found then
    insert into public.teacher_task_versions(draft_id,draft_revision,definition,source_file_id) values(d.id,d.revision,d.definition,case when d.definition->'source'->>'kind'='pdf' then (d.definition->'source'->>'attachmentId')::uuid end) returning * into v;
   end if;
   if exists(select 1 from public.teacher_task_deliveries old join public.teacher_task_delivery_recipients rp on rp.delivery_id=old.id where old.task_version_id=v.id and rp.enrollment_id=any(selected_ids)) then raise exception 'assignment_already_assigned';end if;
   insert into public.teacher_task_deliveries(task_version_id,teacher_assignment_id,created_by,curriculum_release_id,unit_id,request_id,request_hash,recipient_mode,recipient_count)
   values(v.id,ta,p_actor,rel,unt,(p_payload->>'requestId')::uuid,request_hash,p_payload->>'mode',cardinality(selected_ids)) returning * into a;
   insert into public.teacher_task_delivery_recipients(delivery_id,enrollment_id,student_id) select a.id,(x->>'enrollmentId')::uuid,(x->>'studentId')::uuid from jsonb_array_elements(roster) x where (x->>'enrollmentId')::uuid=any(selected_ids);
   insert into public.teacher_task_delivery_events(delivery_id,actor_id,event) values(a.id,p_actor,'sent');
   if stamp<>encode(sha256(convert_to(private.resource_assignment_roster(ta,ctx)::text,'UTF8')),'hex') then raise exception 'assignment_preview_stale';end if;
   result:=jsonb_build_object('delivery',private.teacher_task_delivery_public(a),'replayed',false);
  end if;
 elsif p_action='get' then
  if p_payload<>jsonb_build_object('id',p_payload->'id') then raise exception 'assignment_request_invalid';end if;
  select * into a from public.teacher_task_deliveries where id=(p_payload->>'id')::uuid and created_by=p_actor and teacher_assignment_id=ta and curriculum_release_id=rel and unit_id=unt;
  if not found then raise exception 'assignment_unavailable';end if;
  result:=jsonb_build_object('delivery',private.teacher_task_delivery_public(a));
 elsif p_action='list' then
  if exists(select 1 from jsonb_object_keys(p_payload) k where k<>'offset') then raise exception 'assignment_request_invalid';end if;
  off:=coalesce((p_payload->>'offset')::integer,0);if off not between 0 and 100000 then raise exception 'assignment_request_invalid';end if;
  select coalesce(jsonb_agg(entry order by created_at desc,id),'[]') into entries from (select id,created_at,jsonb_build_object('id',id,'taskVersionId',task_version_id,'recipientCount',recipient_count,'sentAt',created_at) entry from public.teacher_task_deliveries where created_by=p_actor and teacher_assignment_id=ta and curriculum_release_id=rel and unit_id=unt order by created_at desc,id offset off limit 51) q;
  result:=jsonb_build_object('deliveries',case when jsonb_array_length(entries)>50 then entries-50 else entries end,'hasMore',jsonb_array_length(entries)>50,'nextOffset',off+50);
 end if;
 perform private.lock_written_teacher_context(p_actor,p_auth,ta,rel,unt,p_action in ('preview','assign'));
 return jsonb_build_object('version','teacher-task-delivery-v1','readOnly',ctx->'readOnly')||result;
exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'assignment_request_invalid';
end;$function$;

ALTER FUNCTION "private"."service_teacher_task_delivery"(p_actor uuid, p_auth uuid, p_action text, p_context jsonb, p_payload jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.service_teacher_task_drafts(p_actor uuid, p_auth uuid, p_action text, p_context jsonb, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
#variable_conflict use_column
declare ctx jsonb; d public.teacher_task_drafts%rowtype; original public.teacher_task_drafts%rowtype; result jsonb; entries jsonb; off integer;
 ta uuid:=(p_context->>'assignmentId')::uuid; rel uuid:=(p_context->>'curriculumReleaseId')::uuid; unt uuid:=(p_context->>'unitId')::uuid;
begin
 if jsonb_typeof(p_context) is distinct from 'object' or jsonb_typeof(p_payload) is distinct from 'object'
 or ta is null or rel is null or unt is null or exists(select 1 from jsonb_object_keys(p_context) k where k not in ('assignmentId','curriculumReleaseId','unitId'))
 or p_action not in ('create','copy','save','get','list') then raise exception 'task_draft_invalid';end if;
 ctx:=private.lock_written_teacher_context(p_actor,p_auth,ta,rel,unt,p_action in ('create','copy','save'));
 if p_action='copy' then
  if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('requestId','id','expectedRevision')) or p_payload->>'requestId' is null or p_payload->>'id' is null
   or jsonb_typeof(p_payload->'expectedRevision') is distinct from 'number' or coalesce(p_payload->>'expectedRevision','')!~'^[0-9]+$' or (p_payload->>'expectedRevision')::numeric not between 1 and 2147483646 then raise exception 'task_draft_invalid';end if;
  perform pg_advisory_xact_lock(hashtextextended('teacher-task-draft:'||p_actor::text||':'||(p_payload->>'requestId')::uuid::text,0));
  -- Reconcile the original copy before checking a source that may now be newer.
  select * into d from public.teacher_task_drafts where created_by=p_actor and request_id=(p_payload->>'requestId')::uuid;
  if found then
   if d.teacher_assignment_id<>ta or d.curriculum_release_id<>rel or d.unit_id<>unt or d.copied_from_id is distinct from (p_payload->>'id')::uuid or d.copied_from_revision is distinct from (p_payload->>'expectedRevision')::integer then raise exception 'task_draft_conflict';end if;
  else
   select * into original from public.teacher_task_drafts where id=(p_payload->>'id')::uuid and created_by=p_actor and teacher_assignment_id=ta and curriculum_release_id=rel and unit_id=unt for share;
   if not found then raise exception 'task_draft_unavailable';end if;
   if original.revision<>(p_payload->>'expectedRevision')::integer then raise exception 'task_draft_conflict';end if;
   insert into public.teacher_task_drafts(created_by,teacher_assignment_id,school_id,academic_year_id,class_id,subject_program_id,curriculum_release_id,unit_id,request_id,initial_definition,definition,copied_from_id,copied_from_revision)
   values(p_actor,ta,(ctx->>'schoolId')::uuid,(ctx->>'academicYearId')::uuid,(ctx->>'classId')::uuid,(ctx->>'subjectProgramId')::uuid,rel,unt,(p_payload->>'requestId')::uuid,original.definition,original.definition,original.id,original.revision) returning * into d;
  end if;
 elsif p_action='create' then
  if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('requestId','definition')) or p_payload->>'requestId' is null
   or jsonb_typeof(p_payload->'definition') is distinct from 'object' then raise exception 'task_draft_invalid';end if;
  perform pg_advisory_xact_lock(hashtextextended('teacher-task-draft:'||p_actor::text||':'||(p_payload->>'requestId')::uuid::text,0));
  select * into d from public.teacher_task_drafts where created_by=p_actor and request_id=(p_payload->>'requestId')::uuid;
  if found then
   if d.copied_from_id is not null or d.teacher_assignment_id<>ta or d.curriculum_release_id<>rel or d.unit_id<>unt or d.initial_definition is distinct from p_payload->'definition' then raise exception 'task_draft_conflict';end if;
  else
   insert into public.teacher_task_drafts(created_by,teacher_assignment_id,school_id,academic_year_id,class_id,subject_program_id,curriculum_release_id,unit_id,request_id,initial_definition,definition)
   values(p_actor,ta,(ctx->>'schoolId')::uuid,(ctx->>'academicYearId')::uuid,(ctx->>'classId')::uuid,(ctx->>'subjectProgramId')::uuid,rel,unt,(p_payload->>'requestId')::uuid,p_payload->'definition',p_payload->'definition') returning * into d;
  end if;
 elsif p_action='list' then
  if exists(select 1 from jsonb_object_keys(p_payload) k where k<>'offset') then raise exception 'task_draft_invalid';end if;
  off:=coalesce((p_payload->>'offset')::integer,0);if off not between 0 and 100000 then raise exception 'task_draft_invalid';end if;
  select coalesce(jsonb_agg(entry order by updated_at desc,id),'[]') into entries from (
   select id,updated_at,jsonb_build_object('id',id,'title',definition->>'title','revision',revision,'updatedAt',updated_at) entry
   from public.teacher_task_drafts where created_by=p_actor and teacher_assignment_id=ta and curriculum_release_id=rel and unit_id=unt order by updated_at desc,id offset off limit 51) q;
  result:=jsonb_build_object('drafts',case when jsonb_array_length(entries)>50 then entries-50 else entries end,'hasMore',jsonb_array_length(entries)>50,'nextOffset',off+50);
 else
  if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('id','expectedRevision','definition')) then raise exception 'task_draft_invalid';end if;
  select * into d from public.teacher_task_drafts where id=(p_payload->>'id')::uuid and created_by=p_actor and teacher_assignment_id=ta and curriculum_release_id=rel and unit_id=unt for update;
  if not found then raise exception 'task_draft_unavailable';end if;
  if p_action='get' and p_payload<>jsonb_build_object('id',p_payload->'id') then raise exception 'task_draft_invalid';end if;
  if p_action='save' then
   if jsonb_typeof(p_payload->'expectedRevision') is distinct from 'number' or coalesce(p_payload->>'expectedRevision','')!~'^[0-9]+$' or jsonb_typeof(p_payload->'definition') is distinct from 'object' then raise exception 'task_draft_invalid';end if;
   -- An exact replay reconciles a lost acknowledgement, including a later revision.
   if d.definition is distinct from p_payload->'definition' then
    if d.revision<>(p_payload->>'expectedRevision')::integer then raise exception 'task_draft_conflict';end if;
    update public.teacher_task_drafts set definition=p_payload->'definition',revision=revision+1,updated_at=clock_timestamp() where id=d.id returning * into d;
   end if;
  end if;
 end if;
 perform private.lock_written_teacher_context(p_actor,p_auth,ta,rel,unt,p_action in ('create','copy','save'));
 return jsonb_build_object('version','teacher-task-drafts-v1','readOnly',ctx->'readOnly')||coalesce(result,jsonb_build_object('draft',jsonb_build_object('id',d.id,'revision',d.revision,'definition',d.definition,'updatedAt',d.updated_at)));
exception when invalid_text_representation or numeric_value_out_of_range or check_violation then raise exception 'task_draft_invalid';
end;$function$;

ALTER FUNCTION "private"."service_teacher_task_drafts"(p_actor uuid, p_auth uuid, p_action text, p_context jsonb, p_payload jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.service_teacher_task_privacy(p_actor uuid, p_auth uuid, p_action text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
#variable_conflict use_column
declare req public.account_deletion_requests%rowtype; job public.teacher_task_erasure_jobs%rowtype; person public.profiles%rowtype;
 f record; target_request uuid; result jsonb; ids uuid[]; n integer;
begin
 if private.supplementary_session(p_actor,p_auth)<>'admin' then raise exception 'task_privacy_forbidden';end if;
 if jsonb_typeof(p_payload) is distinct from 'object' or p_action is null or p_action not in ('prepare','purge','status','files','ack','finish')
 or exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('requestId','ids','cleanupId')) then raise exception 'task_privacy_invalid';end if;
 if p_action not in ('files','ack','status') and p_payload<>jsonb_build_object('requestId',p_payload->'requestId') or p_action<>'ack' and p_payload ? 'ids' then raise exception 'task_privacy_invalid';end if;
 if p_action in ('files','ack','status') and p_payload ? 'cleanupId' then
  if p_payload ? 'requestId' or not exists(select 1 from public.teacher_task_cleanup_runs where id=(p_payload->>'cleanupId')::uuid) then raise exception 'task_privacy_invalid';end if;
 else
  target_request:=(p_payload->>'requestId')::uuid;if target_request is null then raise exception 'task_privacy_invalid';end if;
  select * into req from public.account_deletion_requests where id=target_request for update;
  if not found or req.status not in ('processing','completed') then raise exception 'approved_request_required';end if;
  select * into job from public.teacher_task_erasure_jobs where teacher_task_erasure_jobs.request_id=req.id for update;
  if p_action='prepare' and job.request_id is null then
   select * into person from public.profiles where id=req.user_id for update;
   if not found or person.role::text<>'student' or person.account_status<>'deletion_pending' or req.auth_user_id is distinct from person.id or person.id=p_actor then raise exception 'task_privacy_target';end if;
   -- A role change never authorizes removing teacher-owned resources or others' work.
   if exists(select 1 from public.teacher_task_drafts where created_by=person.id)
    or exists(select 1 from public.teacher_task_deliveries where created_by=person.id)
    or exists(select 1 from public.teacher_task_reviews where teacher_id=person.id)
    or exists(select 1 from public.teacher_task_review_drafts where teacher_id=person.id)
    or exists(select 1 from public.teacher_task_delivery_cancellations where actor_id=person.id)
    then raise exception 'staff_offboarding_required';end if;
   update public.account_deletion_requests set execution_started_at=clock_timestamp() where id=req.id;
   insert into public.teacher_task_erasure_jobs(request_id,target_id,phase,inventory)
    values(req.id,person.id,'prepared',jsonb_build_object('teacherTasks',private.teacher_task_privacy_counts(person.id))) returning * into job;
  end if;
  if job.request_id is null then raise exception 'task_privacy_prepare_required';end if;
 end if;
 if p_action='purge' and job.phase='prepared' then
  -- Ban is acknowledged before erasure. Revoke live sessions in the same transaction.
  if not exists(select 1 from auth.users where id=job.target_id and banned_until>clock_timestamp()) then raise exception 'task_privacy_ban_required';end if;
  perform 1 from public.profiles where id=job.target_id and account_status='deletion_pending' for update;
  if not found then raise exception 'task_privacy_target';end if;
  delete from auth.sessions where user_id=job.target_id;
  -- Existing student RPCs lock the profile before work; review RPCs lock each work.
  perform 1 from public.teacher_task_student_work where student_id=job.target_id order by delivery_id,enrollment_id for update;
  update public.teacher_task_erasure_jobs set inventory=jsonb_build_object('teacherTasks',private.teacher_task_privacy_counts(job.target_id)) where teacher_task_erasure_jobs.request_id=req.id;
  for f in select * from public.teacher_task_response_files where student_id=job.target_id order by id for update loop
   insert into public.teacher_task_storage_deletions(owner_id,request_id,asset_id,asset_kind,object_path,file_bytes,not_before)
    values(job.target_id,req.id,f.id,'response',f.object_path,f.file_bytes,f.upload_lease_until) on conflict(object_path) do nothing;
  end loop;
  -- Include previously queued orphan files owned by this same account.
  update public.teacher_task_storage_deletions set request_id=req.id where owner_id=job.target_id and deleted_at is null;
  insert into private.teacher_task_privacy_scopes(transaction_id,backend_pid,student_id) values(txid_current(),pg_backend_pid(),job.target_id);
  delete from public.teacher_task_review_drafts where submission_id in (select id from public.teacher_task_submissions where student_id=job.target_id);
  delete from public.teacher_task_reviews where submission_id in (select id from public.teacher_task_submissions where student_id=job.target_id);
  delete from public.teacher_task_work_events where submission_id in (select id from public.teacher_task_submissions where student_id=job.target_id);
  delete from public.teacher_task_submissions where student_id=job.target_id;
  delete from public.teacher_task_student_work where student_id=job.target_id;
  delete from public.teacher_task_response_files where student_id=job.target_id;
  delete from public.teacher_task_delivery_recipients where student_id=job.target_id;
  delete from private.teacher_task_privacy_scopes where transaction_id=txid_current() and backend_pid=pg_backend_pid();
  update public.teacher_task_erasure_jobs set phase='data_erased' where teacher_task_erasure_jobs.request_id=req.id;
 elsif p_action='files' then
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'path',object_path)),'[]') into result from (
   select id,object_path from public.teacher_task_storage_deletions where deleted_at is null and not_before<=clock_timestamp()
   and (case when target_request is not null then teacher_task_storage_deletions.request_id=target_request else cleanup_id=(p_payload->>'cleanupId')::uuid end)
   order by id limit 100) q;
  return jsonb_build_object('version','teacher-task-privacy-v1','files',result);
 elsif p_action='ack' then
  if jsonb_typeof(p_payload->'ids') is distinct from 'array' or jsonb_array_length(p_payload->'ids') not between 1 and 100 then raise exception 'task_privacy_invalid';end if;
  select array_agg(x::uuid) into ids from jsonb_array_elements_text(p_payload->'ids') x;
  if cardinality(ids)<>(select count(distinct x) from unnest(ids) x) or exists(select 1 from unnest(ids) x where not exists(
   select 1 from public.teacher_task_storage_deletions d where d.id=x and d.not_before<=clock_timestamp()
   and (case when target_request is not null then d.request_id=target_request else d.cleanup_id=(p_payload->>'cleanupId')::uuid end))) then raise exception 'task_privacy_invalid';end if;
  update public.teacher_task_storage_deletions set owner_id=null,asset_id=null,object_path=null,deleted_at=clock_timestamp() where id=any(ids) and deleted_at is null;
 elsif p_action='finish' and job.phase<>'completed' then
  if job.phase<>'profile_erased' or exists(select 1 from public.teacher_task_storage_deletions where teacher_task_storage_deletions.request_id=req.id and deleted_at is null)
   or exists(select 1 from auth.users where id=job.target_id) or exists(select 1 from public.profiles where id=job.target_id) then raise exception 'task_privacy_not_finished';end if;
  update public.account_deletion_requests set status='completed',resolved_at=clock_timestamp(),resolved_by=p_actor,resolution_code='student_erased',auth_user_id=null where id=req.id;
  update public.teacher_task_erasure_jobs set phase='completed',target_id=null,completed_at=clock_timestamp() where teacher_task_erasure_jobs.request_id=req.id;
  insert into public.security_audit_log(actor_user_id,actor_role,action,outcome,target_type,target_key,details)
   values(p_actor,'admin','admin.student_account_erased','success','deletion_request',req.id::text,jsonb_build_object('erasedInventory',job.inventory||coalesce(job.legacy_inventory,'{}'),'authDeleted',true));
 end if;
 perform private.supplementary_session(p_actor,p_auth);
 if target_request is not null then return private.teacher_task_erasure_state(target_request);end if;
 return jsonb_build_object('version','teacher-task-privacy-v1','pendingFiles',(select count(*) from public.teacher_task_storage_deletions where cleanup_id=(p_payload->>'cleanupId')::uuid and deleted_at is null));
exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'task_privacy_invalid';
end;$function$;

ALTER FUNCTION "private"."service_teacher_task_privacy"(p_actor uuid, p_auth uuid, p_action text, p_payload jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.service_teacher_task_retention(p_actor uuid, p_auth uuid, p_action text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
#variable_conflict use_column
declare cutoff timestamptz; entries jsonb; manifest jsonb; stamp text; run public.teacher_task_cleanup_runs%rowtype;
 f jsonb; actual record; nonce uuid; n integer;
begin
 if private.supplementary_session(p_actor,p_auth)<>'admin' then raise exception 'task_privacy_forbidden';end if;
 if p_action is null or p_action not in ('preview','enqueue') or jsonb_typeof(p_payload) is distinct from 'object'
  or exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('before','fingerprint','requestId')) then raise exception 'task_privacy_invalid';end if;
 cutoff:=(p_payload->>'before')::timestamptz;
 if cutoff is null or not isfinite(cutoff) or cutoff>clock_timestamp()-interval '1 day' then raise exception 'task_retention_cutoff';end if;
 if p_action='enqueue' then
  nonce:=(p_payload->>'requestId')::uuid;
  if nonce is null or coalesce(p_payload->>'fingerprint','')!~'^[a-f0-9]{64}$' then raise exception 'task_privacy_invalid';end if;
  perform pg_advisory_xact_lock(hashtextextended('task-retention:'||p_actor::text||':'||nonce::text,0));
  select * into run from public.teacher_task_cleanup_runs where actor_id=p_actor and request_id=nonce;
  if found then
   if run.before_at<>cutoff or run.fingerprint<>p_payload->>'fingerprint' then raise exception 'task_retention_conflict';end if;
   return jsonb_build_object('version','teacher-task-retention-v1','cleanupId',run.id,'files',run.file_count,'replayed',true);
  end if;
 end if;
 entries:=private.teacher_task_retention_candidates(cutoff);
 manifest:=case when jsonb_array_length(entries)>50 then entries-50 else entries end;
 if p_action='enqueue' then
  -- Same profile -> asset lock order as erasure; do not lock drafts or work here.
  perform 1 from public.profiles where id in(select (x->>'owner_id')::uuid from jsonb_array_elements(manifest) x) order by id for share;
  for f in select x from jsonb_array_elements(manifest) x order by x->>'kind',x->>'id' loop
   if f->>'kind'='source' then
    select * into actual from public.teacher_task_source_files where id=(f->>'id')::uuid for update;
   else select * into actual from public.teacher_task_response_files where id=(f->>'id')::uuid for update;end if;
   if not found or actual.object_path<>f->>'object_path' or actual.upload_lease_until>clock_timestamp()
    or private.teacher_task_file_referenced(f->>'kind',(f->>'id')::uuid) then raise exception 'task_retention_stale';end if;
  end loop;
  -- A changed candidate set must be previewed again, never silently expanded.
  entries:=private.teacher_task_retention_candidates(cutoff);
  if manifest is distinct from (case when jsonb_array_length(entries)>50 then entries-50 else entries end) then raise exception 'task_retention_stale';end if;
 end if;
 stamp:=encode(sha256(convert_to(jsonb_build_array(cutoff,manifest)::text,'UTF8')),'hex');
 if p_action='preview' then
  return jsonb_build_object('version','teacher-task-retention-v1','fingerprint',stamp,'files',jsonb_array_length(manifest),
   'bytes',(select coalesce(sum((x->>'file_bytes')::integer),0) from jsonb_array_elements(manifest) x),'hasMore',jsonb_array_length(entries)>50);
 end if;
 if stamp<>p_payload->>'fingerprint' then raise exception 'task_retention_stale';end if;
 insert into public.teacher_task_cleanup_runs(actor_id,request_id,fingerprint,before_at,file_count)
  values(p_actor,nonce,stamp,cutoff,jsonb_array_length(manifest)) returning * into run;
 insert into public.security_audit_log(actor_user_id,actor_role,action,outcome,target_type,target_key,details) values(p_actor,'admin','admin.teacher_task_orphans_queued','success','task_cleanup',run.id::text,jsonb_build_object('files',run.file_count,'before',cutoff));
 for f in select x from jsonb_array_elements(manifest) x loop
  insert into private.teacher_task_privacy_scopes(transaction_id,backend_pid,asset_id,asset_kind)
   values(txid_current(),pg_backend_pid(),(f->>'id')::uuid,f->>'kind');
  insert into public.teacher_task_storage_deletions(owner_id,cleanup_id,asset_id,asset_kind,object_path,file_bytes,not_before)
   values((f->>'owner_id')::uuid,run.id,(f->>'id')::uuid,f->>'kind',f->>'object_path',(f->>'file_bytes')::integer,(f->>'upload_lease_until')::timestamptz);
  if f->>'kind'='source' then delete from public.teacher_task_source_files where id=(f->>'id')::uuid;
  else delete from public.teacher_task_response_files where id=(f->>'id')::uuid;end if;
 end loop;
 delete from private.teacher_task_privacy_scopes where transaction_id=txid_current() and backend_pid=pg_backend_pid();
 perform private.supplementary_session(p_actor,p_auth);
 return jsonb_build_object('version','teacher-task-retention-v1','cleanupId',run.id,'files',run.file_count,'replayed',false);
exception when invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow or invalid_datetime_format then raise exception 'task_privacy_invalid';
end;$function$;

ALTER FUNCTION "private"."service_teacher_task_retention"(p_actor uuid, p_auth uuid, p_action text, p_payload jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.service_teacher_task_review(p_actor uuid, p_auth uuid, p_action text, p_context jsonb, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
#variable_conflict use_column
declare ctx jsonb; result jsonb; entries jsonb; off integer; state_filter text; definition jsonb;
 a public.teacher_task_deliveries%rowtype; s public.teacher_task_submissions%rowtype; w public.teacher_task_student_work%rowtype;
 d public.teacher_task_review_drafts%rowtype; published public.teacher_task_reviews%rowtype; cancellation public.teacher_task_delivery_cancellations%rowtype;
 file jsonb; fingerprint text; can_edit boolean; latest uuid; prior integer;
 ta uuid:=(p_context->>'assignmentId')::uuid; rel uuid:=(p_context->>'curriculumReleaseId')::uuid; unt uuid:=(p_context->>'unitId')::uuid;
begin
 if jsonb_typeof(p_context) is distinct from 'object' or (select count(*) from jsonb_object_keys(p_context))<>3
 or exists(select 1 from jsonb_object_keys(p_context) k where k not in ('assignmentId','curriculumReleaseId','unitId'))
 or ta is null or rel is null or unt is null or jsonb_typeof(p_payload) is distinct from 'object'
 or p_action not in ('queue','deliveries','open','save','publish','cancel','file','source') then raise exception 'task_review_invalid';end if;
 ctx:=private.lock_written_teacher_context(p_actor,p_auth,ta,rel,unt,false);
 if p_action in ('queue','deliveries') then
  if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('offset','state')) or p_action='deliveries' and p_payload ? 'state' then raise exception 'task_review_invalid';end if;
  off:=coalesce((p_payload->>'offset')::integer,0);state_filter:=coalesce(p_payload->>'state','submitted');
  if off not between 0 and 100000 or state_filter not in ('submitted','returned','reviewed','all') then raise exception 'task_review_invalid';end if;
  if p_action='queue' then
   select coalesce(jsonb_agg(entry order by submitted_at,id),'[]') into entries from (
    select s.id,s.submitted_at,jsonb_build_object('id',s.id,'deliveryId',a.id,'title',v.definition->>'title','studentName',coalesce(nullif(btrim(p.display_name),''),'Աշակերտ'),
     'state',w.state,'submittedAt',s.submitted_at,'cancelled',exists(select 1 from public.teacher_task_delivery_cancellations c where c.delivery_id=a.id)) entry
    from public.teacher_task_submissions s join public.teacher_task_deliveries a on a.id=s.delivery_id
    join public.teacher_task_versions v on v.id=a.task_version_id join public.profiles p on p.id=s.student_id
    join public.teacher_task_student_work w on w.delivery_id=s.delivery_id and w.enrollment_id=s.enrollment_id
    where a.created_by=p_actor and a.teacher_assignment_id=ta and a.curriculum_release_id=rel and a.unit_id=unt
    and s.id=(select s2.id from public.teacher_task_submissions s2 where s2.delivery_id=s.delivery_id and s2.enrollment_id=s.enrollment_id order by s2.submitted_at desc,s2.id desc limit 1)
    and (state_filter='all' or w.state=state_filter)
    order by s.submitted_at,s.id offset off limit 51
   ) q;
  else
   select coalesce(jsonb_agg(entry order by created_at desc,id),'[]') into entries from (
    select a.id,a.created_at,jsonb_build_object('id',a.id,'title',v.definition->>'title','recipientCount',a.recipient_count,'sentAt',a.created_at,
     'cancelled',exists(select 1 from public.teacher_task_delivery_cancellations c where c.delivery_id=a.id),
     'submissionCount',(select count(distinct s.enrollment_id) from public.teacher_task_submissions s where s.delivery_id=a.id)) entry
    from public.teacher_task_deliveries a join public.teacher_task_versions v on v.id=a.task_version_id
    where a.created_by=p_actor and a.teacher_assignment_id=ta and a.curriculum_release_id=rel and a.unit_id=unt
    order by a.created_at desc,a.id offset off limit 51
   ) q;
  end if;
  result:=jsonb_build_object('entries',case when jsonb_array_length(entries)>50 then entries-50 else entries end,'hasMore',jsonb_array_length(entries)>50,'nextOffset',off+50);
 else
  if p_action='cancel' then
   if p_payload<>jsonb_build_object('deliveryId',p_payload->'deliveryId','requestId',p_payload->'requestId','reason',p_payload->'reason') or jsonb_typeof(p_payload->'reason') is distinct from 'string' or length(btrim(p_payload->>'reason')) not between 1 and 1000 then raise exception 'task_review_invalid';end if;
   select * into a from public.teacher_task_deliveries where id=(p_payload->>'deliveryId')::uuid;
  else
   if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('submissionId','expectedRevision','review','requestId')) or p_payload->>'submissionId' is null then raise exception 'task_review_invalid';end if;
   select * into s from public.teacher_task_submissions where id=(p_payload->>'submissionId')::uuid;
   select * into a from public.teacher_task_deliveries where id=s.delivery_id;
  end if;
  if a.id is null or a.created_by<>p_actor or a.teacher_assignment_id<>ta or a.curriculum_release_id<>rel or a.unit_id<>unt then raise exception 'task_review_unavailable';end if;
  -- Same order as the student service: delivery cancellation fence, then work.
  if p_action='cancel' then perform pg_advisory_xact_lock(hashtextextended('teacher-task-delivery:'||a.id::text,0));else perform pg_advisory_xact_lock_shared(hashtextextended('teacher-task-delivery:'||a.id::text,0));end if;
  if p_action='cancel' then
   fingerprint:=encode(sha256(convert_to(jsonb_build_array(p_context,p_payload)::text,'UTF8')),'hex');
   perform pg_advisory_xact_lock(hashtextextended('task-cancel:'||p_actor::text||':'||(p_payload->>'requestId')::uuid::text,0));
   select * into cancellation from public.teacher_task_delivery_cancellations where actor_id=p_actor and request_id=(p_payload->>'requestId')::uuid;
   if found then if cancellation.request_hash<>fingerprint then raise exception 'task_review_conflict';end if;
   else
    perform private.lock_written_teacher_context(p_actor,p_auth,ta,rel,unt,true);
    if exists(select 1 from public.teacher_task_delivery_cancellations where delivery_id=a.id) then raise exception 'task_review_locked';end if;
    insert into public.teacher_task_delivery_cancellations(delivery_id,actor_id,request_id,request_hash,reason) values(a.id,p_actor,(p_payload->>'requestId')::uuid,fingerprint,p_payload->>'reason') returning * into cancellation;
   end if;
   result:=jsonb_build_object('cancellation',jsonb_build_object('deliveryId',a.id,'cancelledAt',cancellation.cancelled_at,'reason',cancellation.reason));
  else
   perform pg_advisory_xact_lock(hashtextextended('teacher-task-work:'||a.id::text||':'||s.enrollment_id::text,0));
   select * into w from public.teacher_task_student_work where delivery_id=a.id and enrollment_id=s.enrollment_id for update;
   select s2.id into latest from public.teacher_task_submissions s2 where s2.delivery_id=a.id and s2.enrollment_id=s.enrollment_id order by s2.submitted_at desc,s2.id desc limit 1;
   select v.definition into definition from public.teacher_task_versions v where v.id=a.task_version_id;
   select * into d from public.teacher_task_review_drafts where submission_id=s.id and teacher_id=p_actor;
   can_edit:=not (ctx->>'readOnly')::boolean and latest=s.id and w.state in ('submitted','reviewed') and not exists(select 1 from public.teacher_task_delivery_cancellations where delivery_id=a.id);
   if p_action in ('save','publish') then
    if jsonb_typeof(p_payload->'expectedRevision') is distinct from 'number' or coalesce(p_payload->>'expectedRevision','')!~'^[0-9]+$' or not coalesce(private.teacher_task_review_valid(definition,p_payload->'review',p_action='publish'),false) then raise exception 'task_review_invalid';end if;
    if p_action='publish' then
     if p_payload->>'requestId' is null then raise exception 'task_review_invalid';end if;
     fingerprint:=encode(sha256(convert_to(jsonb_build_array(p_context,p_payload)::text,'UTF8')),'hex');
     perform pg_advisory_xact_lock(hashtextextended('task-review-publish:'||p_actor::text||':'||(p_payload->>'requestId')::uuid::text,0));
     select * into published from public.teacher_task_reviews where teacher_id=p_actor and request_id=(p_payload->>'requestId')::uuid;
     if found then
      if published.request_hash<>fingerprint then raise exception 'task_review_conflict';end if;
      result:=jsonb_build_object('receipt',jsonb_build_object('id',published.id,'version',published.version,'publishedAt',published.published_at),'replayed',true);
     end if;
    elsif p_payload ? 'requestId' then raise exception 'task_review_invalid';end if;
    if result is null then
     if p_action='save' and d.review is not distinct from p_payload->'review' then null;
     else
      if not can_edit then raise exception 'task_review_locked';end if;
      perform private.lock_written_teacher_context(p_actor,p_auth,ta,rel,unt,true);
      if coalesce(d.revision,0)<>(p_payload->>'expectedRevision')::integer then raise exception 'task_review_conflict';end if;
      if p_action='save' then
       if d.submission_id is null then insert into public.teacher_task_review_drafts(submission_id,teacher_id,revision,review) values(s.id,p_actor,1,p_payload->'review') returning * into d;
       else update public.teacher_task_review_drafts set review=p_payload->'review',revision=revision+1,updated_at=clock_timestamp() where submission_id=s.id returning * into d;end if;
      else
       if d.review is distinct from p_payload->'review' then raise exception 'task_review_conflict';end if;
       if exists(select 1 from public.teacher_task_reviews where submission_id=s.id and draft_revision=d.revision) then raise exception 'task_review_conflict';end if;
       select count(*) into prior from public.teacher_task_reviews where submission_id=s.id;
       if prior>0 and length(btrim(p_payload->'review'->>'reason'))=0 then raise exception 'task_review_reason_required';end if;
       insert into public.teacher_task_reviews(submission_id,teacher_id,version,draft_revision,request_id,request_hash,review) values(s.id,p_actor,prior+1,d.revision,(p_payload->>'requestId')::uuid,fingerprint,d.review) returning * into published;
       update public.teacher_task_student_work set state=d.review->>'decision',revision=revision+1,updated_at=clock_timestamp() where delivery_id=a.id and enrollment_id=s.enrollment_id;
       insert into public.teacher_task_work_events(submission_id,actor_id,event) values(s.id,p_actor,d.review->>'decision');
       result:=jsonb_build_object('receipt',jsonb_build_object('id',published.id,'version',published.version,'publishedAt',published.published_at),'replayed',false);
       can_edit:=can_edit and d.review->>'decision'='reviewed';
      end if;
     end if;
    end if;
   elsif p_payload<>jsonb_build_object('submissionId',p_payload->'submissionId') then raise exception 'task_review_invalid';end if;
   if p_action in ('file','source') then
    if p_action='file' then select jsonb_build_object('path',f.object_path,'sha256',f.file_sha256,'bytes',f.file_bytes,'format',f.format) into file from public.teacher_task_response_files f where f.id=s.file_id and f.delivery_id=s.delivery_id and f.enrollment_id=s.enrollment_id and f.student_id=s.student_id and f.status='ready';
    else select jsonb_build_object('path',f.object_path,'sha256',f.file_sha256,'bytes',f.file_bytes,'format','pdf') into file from public.teacher_task_source_files f join public.teacher_task_versions v on v.source_file_id=f.id where v.id=a.task_version_id and f.status='ready';end if;
    if file is null then raise exception 'task_file_unavailable';end if;result:=jsonb_build_object('file',file);
   else
    result:=coalesce(result,'{}')||jsonb_build_object('submission',jsonb_build_object('id',s.id,'deliveryId',a.id,'content',s.content,'submittedAt',s.submitted_at,'studentName',(select coalesce(nullif(btrim(display_name),''),'Աշակերտ') from public.profiles where id=s.student_id),'definition',definition,
     'state',(select state from public.teacher_task_student_work where delivery_id=a.id and enrollment_id=s.enrollment_id),'editable',can_edit,
     'cancelled',exists(select 1 from public.teacher_task_delivery_cancellations where delivery_id=a.id),
     'history',(select coalesce(jsonb_agg(jsonb_build_object('id',s2.id,'submittedAt',s2.submitted_at) order by s2.submitted_at,s2.id),'[]') from public.teacher_task_submissions s2 where s2.delivery_id=a.id and s2.enrollment_id=s.enrollment_id),
     'reviews',private.teacher_task_reviews_public(s.id)),
     'draft',jsonb_build_object('revision',coalesce(d.revision,0),'review',d.review));
   end if;
  end if;
 end if;
 perform private.lock_written_teacher_context(p_actor,p_auth,ta,rel,unt,false);
 return jsonb_build_object('version','teacher-task-review-v1','readOnly',ctx->'readOnly')||result;
exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'task_review_invalid';
end;$function$;

ALTER FUNCTION "private"."service_teacher_task_review"(p_actor uuid, p_auth uuid, p_action text, p_context jsonb, p_payload jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.service_teacher_task_sources(p_actor uuid, p_auth uuid, p_action text, p_context jsonb, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
#variable_conflict use_column
declare ctx jsonb; d public.teacher_task_drafts%rowtype; a public.teacher_task_source_files%rowtype; asset_id uuid;
 ta uuid:=(p_context->>'assignmentId')::uuid; rel uuid:=(p_context->>'curriculumReleaseId')::uuid; unt uuid:=(p_context->>'unitId')::uuid;
begin
 if jsonb_typeof(p_context) is distinct from 'object' or jsonb_typeof(p_payload) is distinct from 'object' or ta is null or rel is null or unt is null
 or exists(select 1 from jsonb_object_keys(p_context) k where k not in ('assignmentId','curriculumReleaseId','unitId')) or p_action not in ('reserve','ready','open') then raise exception 'task_source_invalid';end if;
 ctx:=private.lock_written_teacher_context(p_actor,p_auth,ta,rel,unt,p_action<>'open');
 if p_action='reserve' then
  if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('draftId','requestId','sha256','bytes')) or p_payload->>'requestId' is null
   or coalesce(p_payload->>'sha256','')!~'^[a-f0-9]{64}$' or jsonb_typeof(p_payload->'bytes') is distinct from 'number' or coalesce(p_payload->>'bytes','')!~'^[0-9]+$' or (p_payload->>'bytes')::numeric not between 1 and 10485760 then raise exception 'task_source_invalid';end if;
  select * into d from public.teacher_task_drafts where id=(p_payload->>'draftId')::uuid and created_by=p_actor and teacher_assignment_id=ta and curriculum_release_id=rel and unit_id=unt for update;
  if not found then raise exception 'task_source_unavailable';end if;
  if d.definition->'source'->>'kind' is distinct from 'pdf' then raise exception 'task_source_invalid';end if;
  perform pg_advisory_xact_lock(hashtextextended('task-source:'||p_actor::text||':'||(p_payload->>'requestId')::uuid::text,0));
  select * into a from public.teacher_task_source_files where created_by=p_actor and request_id=(p_payload->>'requestId')::uuid;
  if found then
   if a.draft_id<>d.id or a.file_sha256<>p_payload->>'sha256' or a.file_bytes<>(p_payload->>'bytes')::integer then raise exception 'task_source_conflict';end if;
  else
   asset_id:=gen_random_uuid();insert into public.teacher_task_source_files(id,draft_id,created_by,request_id,file_sha256,file_bytes,object_path)
    values(asset_id,d.id,p_actor,(p_payload->>'requestId')::uuid,p_payload->>'sha256',(p_payload->>'bytes')::integer,d.id::text||'/'||asset_id::text||'.pdf') returning * into a;
  end if;
  if a.status='pending' then update public.teacher_task_source_files set upload_lease_until=greatest(upload_lease_until,clock_timestamp()+interval '15 minutes') where id=a.id returning * into a;end if;
 else
  if p_payload<>jsonb_build_object('id',p_payload->'id') then raise exception 'task_source_invalid';end if;
  select * into a from public.teacher_task_source_files where id=(p_payload->>'id')::uuid and created_by=p_actor for update;
  if not found then raise exception 'task_source_unavailable';end if;
  select * into d from public.teacher_task_drafts where id=a.draft_id and created_by=p_actor and teacher_assignment_id=ta and curriculum_release_id=rel and unit_id=unt for share;
  if not found then raise exception 'task_source_unavailable';end if;
  if p_action='ready' then
   if d.definition->'source'->>'kind' is distinct from 'pdf' then raise exception 'task_source_invalid';end if;
   update public.teacher_task_source_files set status='ready' where id=a.id returning * into a;
  elsif a.status<>'ready' then raise exception 'task_source_unavailable';end if;
 end if;
 perform private.lock_written_teacher_context(p_actor,p_auth,ta,rel,unt,p_action<>'open');
 return jsonb_build_object('id',a.id,'draftId',a.draft_id,'path',a.object_path,'sha256',a.file_sha256,'bytes',a.file_bytes,'status',a.status);
exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'task_source_invalid';end;$function$;

ALTER FUNCTION "private"."service_teacher_task_sources"(p_actor uuid, p_auth uuid, p_action text, p_context jsonb, p_payload jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.service_teacher_task_student_work(p_actor uuid, p_auth uuid, p_action text, p_context jsonb, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
#variable_conflict use_column
declare ctx jsonb; definition jsonb; result jsonb; item jsonb; entries jsonb:='[]'; r record; off integer; n integer:=0;
 task_id uuid:=(p_payload->>'id')::uuid; enr uuid; w public.teacher_task_student_work%rowtype; s public.teacher_task_submissions%rowtype;
 f public.teacher_task_response_files%rowtype; source public.teacher_task_source_files%rowtype; file_id uuid; request_hash text;
begin
 if private.supplementary_session(p_actor,p_auth)<>'student' or jsonb_typeof(p_payload) is distinct from 'object' or jsonb_typeof(p_context) is distinct from 'object' or p_action not in ('inbox','open','save','submit','reserve_file','ready_file','open_file','source') then raise exception 'task_work_forbidden';end if;
 if p_action='inbox' then
  if p_context<>'{}' or exists(select 1 from jsonb_object_keys(p_payload) k where k<>'offset') then raise exception 'task_work_invalid';end if;
  off:=coalesce((p_payload->>'offset')::integer,0);if off not between 0 and 100000 then raise exception 'task_work_invalid';end if;
  for r in select a.id,a.task_version_id,a.curriculum_release_id,a.unit_id,rp.enrollment_id from public.teacher_task_delivery_recipients rp join public.teacher_task_deliveries a on a.id=rp.delivery_id where rp.student_id=p_actor order by a.created_at desc,a.id,rp.enrollment_id offset off limit 51 loop
   n:=n+1;if n=51 then exit;end if;
   begin
    item:=private.teacher_task_student_context(p_actor,p_auth,r.id,jsonb_build_object('enrollmentId',r.enrollment_id,'curriculumReleaseId',r.curriculum_release_id,'unitId',r.unit_id));
   exception when raise_exception then if sqlerrm not in ('task_work_unavailable','learning_context_unavailable') then raise;end if;continue;end;
   select v.definition into definition from public.teacher_task_versions v where v.id=r.task_version_id;
   entries:=entries||jsonb_build_array(item||jsonb_build_object('title',definition->>'title','response',definition->'response','state',coalesce((select state from public.teacher_task_student_work where delivery_id=r.id and enrollment_id=r.enrollment_id),'not_started')));
  end loop;
  for item in select value from jsonb_array_elements(entries) loop perform private.teacher_task_student_context(p_actor,p_auth,(item->>'id')::uuid,item->'context');end loop;
  return jsonb_build_object('version','teacher-task-student-work-v1','assignments',entries,'hasMore',n>50,'nextOffset',off+50);
 end if;
 ctx:=private.teacher_task_student_context(p_actor,p_auth,task_id,p_context);enr:=(p_context->>'enrollmentId')::uuid;
 select v.definition into strict definition from public.teacher_task_versions v where v.id=(ctx->>'taskVersionId')::uuid;
 -- One lock covers draft creation/save, submit and upload state transitions.
 perform pg_advisory_xact_lock_shared(hashtextextended('teacher-task-delivery:'||task_id::text,0));
 ctx:=private.teacher_task_student_context(p_actor,p_auth,task_id,p_context);
 perform pg_advisory_xact_lock(hashtextextended('teacher-task-work:'||task_id::text||':'||enr::text,0));
 select * into w from public.teacher_task_student_work where delivery_id=task_id and enrollment_id=enr for update;
 if p_action='source' then
  if p_payload<>jsonb_build_object('id',p_payload->'id') then raise exception 'task_work_invalid';end if;
  select f.* into source from public.teacher_task_source_files f join public.teacher_task_versions v on v.source_file_id=f.id where v.id=(ctx->>'taskVersionId')::uuid and f.status='ready';
  if not found then raise exception 'task_file_unavailable';end if;
  result:=jsonb_build_object('file',jsonb_build_object('path',source.object_path,'sha256',source.file_sha256,'bytes',source.file_bytes,'format','pdf'));
 elsif p_action in ('reserve_file','ready_file','open_file') then
  if p_action='reserve_file' then
   if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('id','requestId','sha256','bytes','format')) or p_payload->>'requestId' is null or coalesce(p_payload->>'sha256','')!~'^[a-f0-9]{64}$' or jsonb_typeof(p_payload->'bytes') is distinct from 'number' or coalesce(p_payload->>'bytes','')!~'^[0-9]+$' or (p_payload->>'bytes')::numeric not between 1 and 10485760 then raise exception 'task_work_invalid';end if;
   if definition->'response'->>'kind'<>'document' or not(definition->'response'->'allowedFormats' ? (p_payload->>'format')) then raise exception 'task_work_format';end if;
   if w.state in ('submitted','reviewed') or coalesce((ctx->>'cancelled')::boolean,false) then raise exception 'task_work_locked';end if;
   perform pg_advisory_xact_lock(hashtextextended('task-response-file:'||p_actor::text||':'||(p_payload->>'requestId')::uuid::text,0));
   select * into f from public.teacher_task_response_files where student_id=p_actor and request_id=(p_payload->>'requestId')::uuid;
   if found then
    if f.delivery_id<>task_id or f.enrollment_id<>enr or f.file_sha256<>p_payload->>'sha256' or f.file_bytes<>(p_payload->>'bytes')::integer or f.format<>p_payload->>'format' then raise exception 'task_work_conflict';end if;
   else
    file_id:=gen_random_uuid();insert into public.teacher_task_response_files(id,delivery_id,enrollment_id,student_id,request_id,format,file_sha256,file_bytes,object_path)
     values(file_id,task_id,enr,p_actor,(p_payload->>'requestId')::uuid,p_payload->>'format',p_payload->>'sha256',(p_payload->>'bytes')::integer,'responses/'||task_id::text||'/'||file_id::text||'.'||(p_payload->>'format')) returning * into f;
   end if;
   if f.status='pending' then update public.teacher_task_response_files set upload_lease_until=greatest(upload_lease_until,clock_timestamp()+interval '15 minutes') where id=f.id returning * into f;end if;
  else
   if p_payload<>jsonb_build_object('id',p_payload->'id','fileId',p_payload->'fileId') then raise exception 'task_work_invalid';end if;
   select * into f from public.teacher_task_response_files where id=(p_payload->>'fileId')::uuid and delivery_id=task_id and enrollment_id=enr and student_id=p_actor for update;
   if not found then raise exception 'task_file_unavailable';end if;
   if p_action='ready_file' then
    if w.state in ('submitted','reviewed') or coalesce((ctx->>'cancelled')::boolean,false) then raise exception 'task_work_locked';end if;
    update public.teacher_task_response_files set status='ready' where teacher_task_response_files.id=f.id returning * into f;
   elsif f.status<>'ready' then raise exception 'task_file_unavailable';end if;
  end if;
  result:=jsonb_build_object('file',jsonb_build_object('id',f.id,'path',f.object_path,'sha256',f.file_sha256,'bytes',f.file_bytes,'format',f.format,'status',f.status));
 elsif p_action in ('save','submit') then
  if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('id','expectedRevision','content','requestId')) or jsonb_typeof(p_payload->'expectedRevision') is distinct from 'number' or coalesce(p_payload->>'expectedRevision','')!~'^[0-9]+$' then raise exception 'task_work_invalid';end if;
  if not coalesce(private.teacher_task_content_valid(p_actor,task_id,enr,definition,p_payload->'content',p_action='submit'),false) then raise exception 'task_work_format';end if;
  if p_action='submit' then
   if p_payload->>'requestId' is null then raise exception 'task_work_invalid';end if;
   request_hash:=encode(sha256(convert_to(jsonb_build_array(p_context,p_payload)::text,'UTF8')),'hex');
   perform pg_advisory_xact_lock(hashtextextended('task-submit:'||p_actor::text||':'||(p_payload->>'requestId')::uuid::text,0));
   select * into s from public.teacher_task_submissions where student_id=p_actor and request_id=(p_payload->>'requestId')::uuid;
   if found then
    if s.request_hash<>request_hash then raise exception 'task_work_conflict';end if;
    result:=jsonb_build_object('receipt',jsonb_build_object('id',s.id,'submittedAt',s.submitted_at),'replayed',true);
   end if;
  elsif p_payload ? 'requestId' then raise exception 'task_work_invalid';end if;
  if result is null then
   if w.state in ('submitted','reviewed') or coalesce((ctx->>'cancelled')::boolean,false) then raise exception 'task_work_locked';end if;
   if p_action='save' and w.content is not distinct from p_payload->'content' then null;
   else
    if coalesce(w.revision,0)<>(p_payload->>'expectedRevision')::integer then raise exception 'task_work_conflict';end if;
    if p_action='submit' then
     if w.content is distinct from p_payload->'content' then raise exception 'task_work_conflict';end if;
     insert into public.teacher_task_submissions(delivery_id,enrollment_id,student_id,request_id,request_hash,content,file_id)
      values(task_id,enr,p_actor,(p_payload->>'requestId')::uuid,request_hash,w.content,case when w.content->>'kind'='document' then (w.content->>'fileId')::uuid end) returning * into s;
     update public.teacher_task_student_work set state='submitted',revision=revision+1,updated_at=clock_timestamp() where delivery_id=task_id and enrollment_id=enr;
     insert into public.teacher_task_work_events(submission_id,actor_id,event) values(s.id,p_actor,'submitted');
     result:=jsonb_build_object('receipt',jsonb_build_object('id',s.id,'submittedAt',s.submitted_at),'replayed',false);
    elsif w.delivery_id is null then
     insert into public.teacher_task_student_work(delivery_id,enrollment_id,student_id,revision,state,content) values(task_id,enr,p_actor,1,'draft',p_payload->'content');
    else
     update public.teacher_task_student_work set content=p_payload->'content',revision=revision+1,updated_at=clock_timestamp() where delivery_id=task_id and enrollment_id=enr;
    end if;
   end if;
  end if;
 elsif p_action='open' then
  if p_payload<>jsonb_build_object('id',p_payload->'id') then raise exception 'task_work_invalid';end if;
 else raise exception 'task_work_invalid';end if;
 perform private.teacher_task_student_context(p_actor,p_auth,task_id,p_context);
 if p_action in ('open','save','submit') then result:=coalesce(result,'{}')||jsonb_build_object('assignment',ctx||jsonb_build_object('definition',definition),'work',private.teacher_task_work_public(task_id,enr));end if;
 return jsonb_build_object('version','teacher-task-student-work-v1')||result;
exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'task_work_invalid';
end;$function$;

ALTER FUNCTION "private"."service_teacher_task_student_work"(p_actor uuid, p_auth uuid, p_action text, p_context jsonb, p_payload jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.service_teacher_workspace(p_actor uuid, p_auth uuid, p_assignment uuid DEFAULT NULL::uuid, p_cursor jsonb DEFAULT NULL::jsonb, p_work uuid DEFAULT NULL::uuid, p_recent jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare result jsonb; cursor_time timestamptz; cursor_id uuid;
begin
 if p_actor is null or p_auth is null or jsonb_typeof(p_recent) is distinct from 'array'
 or jsonb_array_length(p_recent)>4 or exists(select 1 from jsonb_array_elements(p_recent) v where jsonb_typeof(v)<>'string')
 or (p_cursor is not null and (jsonb_typeof(p_cursor)<>'object' or not p_cursor ? 'submittedAt' or not p_cursor ? 'id'
 or (select count(*) from jsonb_object_keys(p_cursor))<>2)) then
  raise exception 'workspace_request_invalid' using errcode='22023';end if;
 perform v#>>'{}' from jsonb_array_elements(p_recent) v where (v#>>'{}')::uuid is not null;
 if p_cursor is not null then
  cursor_time:=(p_cursor->>'submittedAt')::timestamptz;cursor_id:=(p_cursor->>'id')::uuid;
  if cursor_time is null or cursor_id is null then raise exception 'workspace_request_invalid' using errcode='22023';end if;
 end if;
 if not exists(select 1 from public.profiles p join auth.users u on u.id=p.id
  join auth.sessions ss on ss.user_id=p.id and ss.id=p_auth
  where p.id=p_actor and p.role='teacher' and p.account_status='active' and u.deleted_at is null
  and (u.banned_until is null or u.banned_until<=now()) and (ss.not_after is null or ss.not_after>now()))
 then raise exception 'workspace_context_unavailable' using errcode='42501';end if;

 with assignments as materialized (
  select a.id assignment_id,c.id class_id,a.school_id,a.academic_year_id,a.subject_program_id,
   c.name class_name,y.label academic_year,s.name school_name,sub.code subject_code,sub.name_hy subject_name,gr.grade_number
  from public.teacher_assignments a
  join public.institutional_memberships m on m.id=a.teacher_membership_id and m.person_id=p_actor
   and m.school_id=a.school_id and m.role='teacher' and m.status='active' and m.valid_from<=now() and (m.valid_to is null or m.valid_to>now())
  join public.classes c on c.id=a.class_id and c.school_id=a.school_id and c.academic_year_id=a.academic_year_id and c.is_active
  join public.academic_years y on y.id=a.academic_year_id and y.school_id=a.school_id and y.status='active' and current_date between y.starts_on and y.ends_on
  join public.schools s on s.id=a.school_id
  join public.subject_programs sp on sp.id=a.subject_program_id and sp.subject_id=c.subject_id and sp.grade_id=c.grade_id
   and sp.status='published' and (sp.effective_from is null or sp.effective_from<=current_date) and (sp.effective_to is null or sp.effective_to>=current_date)
  join public.subjects sub on sub.id=sp.subject_id and sub.status='published'
  join public.grades gr on gr.id=sp.grade_id
  where a.status='active' and a.valid_from<=now() and (a.valid_to is null or a.valid_to>now())
   and a.valid_from::date<=y.ends_on and (a.valid_to is null or a.valid_to::date>=y.starts_on)
   and (select count(*) from public.teacher_subject_authorizations g where g.teacher_membership_id=m.id and g.school_id=m.school_id
    and g.subject_id=sp.subject_id and g.status='active')=1
   and exists(select 1 from public.teacher_subject_authorizations g where g.teacher_membership_id=m.id and g.school_id=m.school_id
    and g.subject_id=sp.subject_id and g.status='active' and g.valid_from<=now() and (g.valid_to is null or g.valid_to>now()))
 ), works as materialized (
  select w.id,w.state,w.revision,su.submitted_at,a.*,
   w.curriculum_release_id,w.unit_id,ru.title_hy_snapshot unit_title,t.definition->>'title' task_title,
   coalesce(nullif(btrim(p.display_name),''),'Աշակերտ') student_name
  from assignments a join public.written_work w on w.class_id=a.class_id and w.school_id=a.school_id
   and w.academic_year_id=a.academic_year_id and w.subject_program_id=a.subject_program_id
  join public.curriculum_releases r on r.id=w.curriculum_release_id and r.subject_program_id=a.subject_program_id
   and r.status in ('pilot','production') and (r.effective_from is null or r.effective_from<=current_date) and (r.effective_to is null or r.effective_to>=current_date)
  join public.units u on u.id=w.unit_id and u.subject_program_id=a.subject_program_id
  join public.curriculum_release_units ru on ru.curriculum_release_id=r.id and ru.unit_id=u.id
  join public.written_task_versions t on t.id=w.task_version_id and t.curriculum_release_id=r.id and t.unit_id=u.id and t.subject_program_id=a.subject_program_id
  join public.written_submissions su on su.id=w.current_submission_id and su.work_id=w.id
  join public.profiles p on p.id=w.student_id
  where w.state in ('submitted','reviewed','changes_requested') and (w.state='submitted' or w.id=p_work)
 ), entries as materialized (
  select distinct on(id) id,state,submitted_at,assignment_id,class_id,jsonb_build_object('id',id,'state',state,'revision',revision,
   'submittedAt',submitted_at,'studentName',student_name,'taskTitle',task_title,'classId',class_id,'className',class_name,
   'schoolName',school_name,'academicYear',academic_year,'subjectName',subject_name,'subjectCode',subject_code,'gradeNumber',grade_number,
   'assignmentId',assignment_id,'curriculumReleaseId',curriculum_release_id,'unitId',unit_id,'unitTitle',unit_title) entry from works
   where p_assignment is null or assignment_id=p_assignment order by id,assignment_id
 ), page as materialized (
  select * from entries where state='submitted' and (p_cursor is null or (submitted_at,id)>(cursor_time,cursor_id))
   order by submitted_at,id limit 13
 ), cards as (
  select a.class_id,a.assignment_id,a.class_name,jsonb_build_object('id',a.class_id,'assignmentId',a.assignment_id,
   'name',a.class_name,'isActive',true,'schoolName',a.school_name,'academicYear',a.academic_year,'subjectName',a.subject_name,
   'subjectCode',a.subject_code,'gradeNumber',a.grade_number,'recent',p_recent ? a.class_id::text,
   'pendingCount',(select count(*) from works w where w.assignment_id=a.assignment_id and w.state='submitted')) card
  from assignments a
  union all
  select c.id,null,c.name,jsonb_build_object('id',c.id,'assignmentId',null,'name',c.name,'isActive',true,'academicYear',c.academic_year,
   'subjectName',s.name_hy,'subjectCode',s.code,'gradeNumber',g.grade_number,'recent',p_recent ? c.id::text,'pendingCount',null)
  from public.classes c left join public.subjects s on s.id=c.subject_id left join public.grades g on g.id=c.grade_id
  where c.teacher_id=p_actor and c.school_id is null and c.is_active
   and not exists(select 1 from public.institutional_memberships m where m.person_id=p_actor and m.role='teacher')
 ), card_page as (
  select * from cards order by coalesce((select min(ordinal) from jsonb_array_elements_text(p_recent) with ordinality x(v,ordinal) where v=class_id::text),100),class_name,class_id,assignment_id limit 6
 )
 select jsonb_build_object('version','teacher-workspace-v1','snapshotAt',now(),
  'authorizedFilter',p_assignment is null or exists(select 1 from assignments where assignment_id=p_assignment),
  'authorizedWork',p_work is null or exists(select 1 from entries where id=p_work),
  'coverage',case when exists(select 1 from cards where assignment_id is null) then 'schoolless_unavailable' else 'active_writable_school_contexts' end,
  'pendingCount',case when exists(select 1 from cards where assignment_id is null) then null else (select count(*) from entries where state='submitted') end,
  'assignmentId',p_assignment,'filterClass',(select jsonb_build_object('className',class_name,'subjectName',subject_name,'schoolName',school_name) from assignments where assignment_id=p_assignment),'queue',coalesce((select jsonb_agg(entry order by submitted_at,id) from (select * from page order by submitted_at,id limit 12) q),'[]'),
  'hasMore',(select count(*)>12 from page),
  'nextCursor',(select jsonb_build_object('submittedAt',submitted_at,'id',id) from page order by submitted_at,id offset 11 limit 1),
  'selectedWork',(select entry from entries where id=p_work),
  'cards',coalesce((select jsonb_agg(card order by coalesce((select min(ordinal) from jsonb_array_elements_text(p_recent) with ordinality x(v,ordinal) where v=class_id::text),100),class_name,class_id,assignment_id) from card_page),'[]'),
  'classCount',(select count(*) from cards),'cardsPartial',(select count(*)>6 from cards)) into result;
 if result->'authorizedFilter' <> 'true' or result->'authorizedWork' <> 'true' then
  raise exception 'workspace_context_unavailable' using errcode='42501';end if;
 return result - 'authorizedFilter' - 'authorizedWork';
end; $function$;

ALTER FUNCTION "private"."service_teacher_workspace"(p_actor uuid, p_auth uuid, p_assignment uuid, p_cursor jsonb, p_work uuid, p_recent jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.service_unit_materials(p_actor_id uuid, p_auth_session_id uuid, p_aal text, p_action text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_column
declare m public.unit_material_versions%rowtype; prior public.unit_material_versions%rowtype; result jsonb; issues jsonb; new_id uuid; off_n integer;
begin
 if p_action is null or p_action not in ('list','get','revise','qa','approve','retire') or jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>100000 then raise exception 'material_request_invalid';end if;
 -- Lock identities before content locks, and evaluate wall-clock expiry after waits.
 perform 1 from public.profiles p join auth.users u on u.id=p.id join auth.sessions s on s.user_id=p.id
  where p.id=p_actor_id and s.id=p_auth_session_id for share of p,u,s;
 if not exists(select 1 from public.profiles p join auth.users u on u.id=p.id join auth.sessions s on s.user_id=p.id
  where p.id=p_actor_id and p.role::text in ('admin','content_admin') and p.account_status='active' and s.id=p_auth_session_id
  and (s.not_after is null or s.not_after>clock_timestamp()) and u.deleted_at is null and (u.banned_until is null or u.banned_until<=clock_timestamp()))
 then raise exception 'material_forbidden';end if;
 if p_aal is null or p_aal not in ('aal1','aal2') then raise exception 'material_forbidden';end if;
 if p_action in ('approve','retire') and p_aal<>'aal2' then raise exception 'material_mfa_required';end if;
 if p_action='list' then
  if coalesce(p_payload->>'offset','0')!~ '^[0-9]{1,6}$' then raise exception 'material_request_invalid';end if;
  off_n:=coalesce((p_payload->>'offset')::integer,0);
  with latest as (
   select distinct on (curriculum_release_id,unit_id,material_key) * from public.unit_material_versions order by curriculum_release_id,unit_id,material_key,version_no desc
  ), page as (
   select m.id,m.material_key,m.kind,m.version_no,m.sequence_order,m.status,m.qa,m.definition->>'title' title,
    m.subject_program_id,m.curriculum_release_id,m.unit_id,s.name_hy subject_name,g.label_hy grade_label,ru.title_hy_snapshot unit_title
   from latest m join public.subject_programs sp on sp.id=m.subject_program_id join public.subjects s on s.id=sp.subject_id
   join public.grades g on g.id=sp.grade_id join public.curriculum_release_units ru on ru.curriculum_release_id=m.curriculum_release_id and ru.unit_id=m.unit_id
   order by s.name_hy,g.grade_number,m.curriculum_release_id,ru.sequence_order_snapshot,m.sequence_order,m.material_key offset off_n limit 201
  ) select jsonb_build_object('materials',coalesce((select jsonb_agg(to_jsonb(q)) from (select * from page limit 200) q),'[]'::jsonb),'hasMore',(select count(*)>200 from page)) into result;
 else
  select * into m from public.unit_material_versions where id=(p_payload->>'id')::uuid;
  if not found then raise exception 'material_unavailable';end if;
  perform pg_advisory_xact_lock(hashtextextended('unit-material:'||m.curriculum_release_id::text||':'||m.unit_id::text||':'||m.material_key,0));
  select * into m from public.unit_material_versions where id=m.id for update;
  if p_action<>'get' then
   if p_payload->>'fingerprint' is distinct from m.fingerprint or exists(select 1 from public.unit_material_versions v where v.curriculum_release_id=m.curriculum_release_id and v.unit_id=m.unit_id and v.material_key=m.material_key and v.version_no>m.version_no) then raise exception 'material_conflict';end if;
  end if;
  if p_action='revise' then
   if jsonb_typeof(p_payload->'definition') is distinct from 'object' or jsonb_typeof(p_payload->'reviewPackage') is distinct from 'object' or coalesce(length(btrim(p_payload->>'reason')),0) not between 1 and 2000 then raise exception 'material_request_invalid';end if;
   -- A material's outcomes/source/assessment policy are governed onboarding data, not silently moved by text editing.
   if ((p_payload->'definition')-array['title','text','workedExample','prompt','minWords','maxWords','criteria']) is distinct from (m.definition-array['title','text','workedExample','prompt','minWords','maxWords','criteria']) or p_payload->'reviewPackage' is distinct from m.review_package then raise exception 'material_scope_invalid';end if;
   insert into public.unit_material_versions(subject_program_id,curriculum_release_id,unit_id,material_key,kind,version_no,sequence_order,definition,review_package,fingerprint,created_by)
    values(m.subject_program_id,m.curriculum_release_id,m.unit_id,m.material_key,m.kind,m.version_no+1,m.sequence_order,p_payload->'definition',m.review_package,'',p_actor_id) returning id into new_id;
   insert into public.unit_material_events(material_version_id,event,actor_id,aal,detail) values(new_id,'revised',p_actor_id,p_aal,jsonb_build_object('fromVersion',m.id,'reason',p_payload->>'reason'));
   select * into m from public.unit_material_versions where id=new_id;
  elsif p_action='qa' then
   if m.status<>'draft' then raise exception 'material_read_only';end if;
   issues:=private.unit_material_issues(m);
   update public.unit_material_versions set qa=jsonb_build_object('passed',jsonb_array_length(issues)=0,'issues',issues,'fingerprint',m.fingerprint,'checkedAt',clock_timestamp(),'checkVersion','unit-material-qa-v1') where id=m.id returning * into m;
   insert into public.unit_material_events(material_version_id,event,actor_id,aal,detail) values(m.id,'qa',p_actor_id,p_aal,m.qa);
  elsif p_action='approve' and m.status<>'approved' then
   if m.status<>'draft' then raise exception 'material_read_only';end if;
   if m.qa->'passed' is distinct from 'true'::jsonb or m.qa->>'fingerprint' is distinct from m.fingerprint or private.unit_material_issues(m)<>'[]'::jsonb then raise exception 'material_qa_required';end if;
   for prior in select * from public.unit_material_versions v where v.curriculum_release_id=m.curriculum_release_id and v.unit_id=m.unit_id and v.material_key=m.material_key and v.status='approved' for update loop
    update public.unit_material_versions set status='retired' where id=prior.id;
    insert into public.unit_material_events(material_version_id,event,actor_id,aal,detail) values(prior.id,'retired',p_actor_id,p_aal,jsonb_build_object('supersededBy',m.id));
   end loop;
   if m.kind='writing' then
    -- Never overwrite an independently registered task, even if its textual key matches.
    if exists(select 1 from public.written_task_versions w where w.curriculum_release_id=m.curriculum_release_id and w.unit_id=m.unit_id and w.task_key=m.material_key and not exists(select 1 from public.unit_material_versions v where v.id=w.id)) then raise exception 'material_conflict';end if;
    update public.written_task_versions set status='retired' where curriculum_release_id=m.curriculum_release_id and unit_id=m.unit_id and task_key=m.material_key and status='approved';
    insert into public.written_task_versions(id,task_key,version_no,subject_program_id,curriculum_release_id,unit_id,definition,status,reviewed_by,reviewed_at,review_evidence)
     values(m.id,m.material_key,m.version_no,m.subject_program_id,m.curriculum_release_id,m.unit_id,m.definition,'approved',p_actor_id,clock_timestamp(),jsonb_build_object('qaPassed',true,'reviewReference','unit-material:'||m.id::text,'sourceComparisonReference',m.review_package->>'comparisonReference','fingerprint',m.fingerprint));
   end if;
   update public.unit_material_versions set status='approved',reviewed_by=p_actor_id,reviewed_at=clock_timestamp() where id=m.id returning * into m;
   insert into public.unit_material_events(material_version_id,event,actor_id,aal,detail) values(m.id,'approved',p_actor_id,p_aal,jsonb_build_object('fingerprint',m.fingerprint,'scope','content-rubric-and-review-package; no curriculum activation'));
  elsif p_action='retire' and m.status<>'retired' then
   if coalesce(length(btrim(p_payload->>'reason')),0) not between 1 and 2000 then raise exception 'material_request_invalid';end if;
   update public.unit_material_versions set status='retired' where id=m.id returning * into m;
   if m.kind='writing' then update public.written_task_versions set status='retired' where id=m.id and status='approved';end if;
   insert into public.unit_material_events(material_version_id,event,actor_id,aal,detail) values(m.id,'retired',p_actor_id,p_aal,jsonb_build_object('reason',p_payload->>'reason'));
  end if;
  select jsonb_build_object('material',to_jsonb(m),'history',coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'version_no',v.version_no,'status',v.status,'created_at',v.created_at) order by v.version_no desc) from public.unit_material_versions v where v.curriculum_release_id=m.curriculum_release_id and v.unit_id=m.unit_id and v.material_key=m.material_key),'[]'::jsonb),'events',coalesce((select jsonb_agg(to_jsonb(e) order by e.created_at,e.id) from public.unit_material_events e where e.material_version_id=m.id),'[]'::jsonb)) into result;
 end if;
 if not exists(select 1 from auth.sessions s join auth.users u on u.id=s.user_id where s.id=p_auth_session_id and s.user_id=p_actor_id and (s.not_after is null or s.not_after>clock_timestamp()) and u.deleted_at is null and (u.banned_until is null or u.banned_until<=clock_timestamp())) then raise exception 'material_forbidden';end if;
 return result;
exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'material_request_invalid';
end;
$function$;

ALTER FUNCTION "private"."service_unit_materials"(p_actor_id uuid, p_auth_session_id uuid, p_aal text, p_action text, p_payload jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.service_writing_assignments(p_actor_id uuid, p_auth_session_id uuid, p_action text, p_context jsonb DEFAULT '{}'::jsonb, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
#variable_conflict use_column
declare role_name text;ctx jsonb;roster jsonb;stamp text;entries jsonb:='[]';result jsonb;entry jsonb;r record;
 a public.writing_assignments%rowtype;m public.written_task_versions%rowtype;e public.institutional_class_enrollments%rowtype;
 rel uuid;unt uuid;ta uuid;enr uuid;off integer;state_filter text;search_text text;rows_n integer;selected_ids uuid[];request_hash text;reason text;task_id uuid;
begin
 if jsonb_typeof(p_context) is distinct from 'object' or jsonb_typeof(p_payload) is distinct from 'object'
 or exists(select 1 from jsonb_object_keys(p_context) k where k not in ('assignmentId','enrollmentId','curriculumReleaseId','unitId'))
 or p_action not in ('catalog','preview','assign','list','inbox','get','cancel','open') then raise exception 'assignment_request_invalid';end if;
 role_name:=private.supplementary_session(p_actor_id,p_auth_session_id);
 if role_name not in ('teacher','student') then raise exception 'assignment_forbidden';end if;
 off:=coalesce((p_payload->>'offset')::integer,0);state_filter:=coalesce(p_payload->>'state','current');
 if off not between 0 and 100000 or state_filter not in ('current','history') then raise exception 'assignment_request_invalid';end if;
 if p_action='inbox' then
  if role_name<>'student' or p_context<>'{}' or exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('offset','state')) then raise exception 'assignment_forbidden';end if;
  rows_n:=0;
  for r in select a.id,rp.enrollment_id from public.writing_assignment_recipients rp join public.writing_assignments a on a.id=rp.assignment_id
   join public.institutional_class_enrollments ie on ie.id=rp.enrollment_id and ie.student_id=p_actor_id
   where rp.student_id=p_actor_id and (case when state_filter='current' then a.status='assigned' else a.status='canceled' end)
   order by a.created_at desc,a.id,rp.enrollment_id offset off limit 51
  loop
   rows_n:=rows_n+1;if rows_n=51 then exit;end if;
   select * into strict a from public.writing_assignments where id=r.id;
   begin
    e:=private.lock_student_learning_context(p_actor_id,p_auth_session_id,r.enrollment_id,a.curriculum_release_id,a.unit_id);
   exception when raise_exception then if sqlerrm<>'learning_context_unavailable' then raise;end if;continue;end;
   if e.teacher_assignment_id<>a.teacher_assignment_id or e.school_id<>a.school_id or e.academic_year_id<>a.academic_year_id or e.class_id<>a.class_id or e.subject_program_id<>a.subject_program_id then continue;end if;
   select * into strict m from public.written_task_versions where id=a.task_version_id;
   entry:=private.writing_assignment_public(a,m);
   entry:=entry-'recipientCount'||jsonb_build_object('context',jsonb_build_object('enrollmentId',r.enrollment_id,'curriculumReleaseId',a.curriculum_release_id,'unitId',a.unit_id),'workState',coalesce((select w.state from public.written_work w where w.task_version_id=a.task_version_id and w.student_id=p_actor_id and w.class_id=a.class_id and w.school_id=a.school_id and w.academic_year_id=a.academic_year_id),'not_started'));
   entries:=entries||jsonb_build_array(entry);
  end loop;
  -- Recheck clocks/session/context after the bounded list, not only its first row.
  for entry in select value from jsonb_array_elements(entries) loop
   perform private.lock_student_learning_context(p_actor_id,p_auth_session_id,(entry->'context'->>'enrollmentId')::uuid,(entry->'context'->>'curriculumReleaseId')::uuid,(entry->'context'->>'unitId')::uuid);
  end loop;
  perform private.supplementary_session(p_actor_id,p_auth_session_id);
  return jsonb_build_object('version','writing-assignments-v1','assignments',entries,'hasMore',rows_n>50,'nextOffset',off+50);
 end if;
 rel:=(p_context->>'curriculumReleaseId')::uuid;unt:=(p_context->>'unitId')::uuid;ta:=(p_context->>'assignmentId')::uuid;enr:=(p_context->>'enrollmentId')::uuid;
 if rel is null or unt is null then raise exception 'assignment_request_invalid';end if;
 if role_name='teacher' then
  if ta is null or enr is not null then raise exception 'assignment_forbidden';end if;
  ctx:=private.lock_written_teacher_context(p_actor_id,p_auth_session_id,ta,rel,unt,p_action in ('preview','assign','cancel'));
 else
  if enr is null or ta is not null or p_action not in ('get','open') then raise exception 'assignment_forbidden';end if;
  e:=private.lock_student_learning_context(p_actor_id,p_auth_session_id,enr,rel,unt);ta:=e.teacher_assignment_id;
  ctx:=jsonb_build_object('schoolId',e.school_id,'academicYearId',e.academic_year_id,'classId',e.class_id,'subjectProgramId',e.subject_program_id,'readOnly',false);
 end if;
 if p_action='catalog' then
  if role_name<>'teacher' or exists(select 1 from jsonb_object_keys(p_payload) k where k<>'offset') then raise exception 'assignment_request_invalid';end if;
  rows_n:=0;
  for m in select * from public.written_task_versions where status='approved'
   and subject_program_id=(ctx->>'subjectProgramId')::uuid and curriculum_release_id=rel and unit_id=unt
   order by task_key,version_no,id offset off limit 51
  loop
   rows_n:=rows_n+1;if rows_n>50 then exit;end if;entries:=entries||jsonb_build_array(private.writing_task_public(m));
  end loop;
  result:=jsonb_build_object('tasks',entries,'hasMore',rows_n>50,'nextOffset',off+50,'readOnly',ctx->'readOnly');
 elsif p_action in ('preview','assign') then
  if role_name<>'teacher' then raise exception 'assignment_forbidden';end if;
  if p_action='assign' then
   if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('taskId','fingerprint','requestId','rosterFingerprint','mode','enrollmentIds','instructions'))
    or p_payload->>'mode' not in ('class','selected') or p_payload->>'mode' is null
    or jsonb_typeof(coalesce(p_payload->'enrollmentIds','[]'))<>'array' or jsonb_array_length(coalesce(p_payload->'enrollmentIds','[]'))>500
    or (p_payload ? 'instructions' and jsonb_typeof(p_payload->'instructions')<>'string')
    or length(coalesce(p_payload->>'instructions',''))>2000 or p_payload->>'requestId' is null then raise exception 'assignment_request_invalid';end if;
   select coalesce(array_agg(v::uuid order by v::uuid),array[]::uuid[]) into selected_ids from jsonb_array_elements_text(coalesce(p_payload->'enrollmentIds','[]')) v;
   if cardinality(selected_ids)<>(select count(distinct v) from unnest(selected_ids) v) or
    (p_payload->>'mode'='selected' and cardinality(selected_ids)=0) or (p_payload->>'mode'='class' and cardinality(selected_ids)>0) then raise exception 'assignment_recipients_invalid';end if;
   request_hash:=encode(sha256(convert_to(jsonb_build_array(p_context,p_payload-'enrollmentIds',to_jsonb(selected_ids))::text,'UTF8')),'hex');
   perform pg_advisory_xact_lock(hashtextextended('resource-assignment-request:'||p_actor_id::text||':'||(p_payload->>'requestId')::uuid::text,0));
   select * into a from public.writing_assignments where created_by=p_actor_id and request_id=(p_payload->>'requestId')::uuid;
   if found then
    if a.request_hash<>request_hash then raise exception 'assignment_conflict';end if;
    select * into strict m from public.written_task_versions where id=a.task_version_id;
    result:=jsonb_build_object('assignment',private.writing_assignment_public(a,m),'replayed',true);
   end if;
  else
   if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('taskId','offset','search')) then raise exception 'assignment_request_invalid';end if;
  end if;
  if result is null then
   select * into m from public.written_task_versions where id=(p_payload->>'taskId')::uuid and curriculum_release_id=rel and unit_id=unt
    and subject_program_id=(ctx->>'subjectProgramId')::uuid;
   if not found then raise exception 'assignment_unavailable';end if;
   perform pg_advisory_xact_lock(hashtextextended('writing-task-delivery:'||m.id::text,0));
   select * into strict m from public.written_task_versions where id=m.id for share;
   if m.status<>'approved' then raise exception 'assignment_unavailable';end if;
   roster:=private.resource_assignment_roster(ta,ctx);
   stamp:=encode(sha256(convert_to(roster::text,'UTF8')),'hex');
   if p_action='preview' then
    search_text:=btrim(coalesce(p_payload->>'search',''));if length(search_text)>120 then raise exception 'assignment_request_invalid';end if;
    select count(*) into rows_n from jsonb_array_elements(roster) v where position(lower(search_text) in lower(v->>'studentName'))>0;
    select coalesce(jsonb_agg(v order by v->>'enrollmentId'),'[]') into entries from
     (select v from jsonb_array_elements(roster) v where position(lower(search_text) in lower(v->>'studentName'))>0 order by v->>'enrollmentId' offset off limit 50) q;
    result:=jsonb_build_object('task',private.writing_task_public(m)||jsonb_build_object('definition',m.definition),'roster',entries,'rosterFingerprint',stamp,'total',jsonb_array_length(roster),'matched',rows_n,'hasMore',rows_n>off+50,'nextOffset',off+50,'alreadyAssigned',(select coalesce(jsonb_agg(rp.enrollment_id order by rp.enrollment_id),'[]') from public.writing_assignment_recipients rp join public.writing_assignments old on old.id=rp.assignment_id where old.teacher_assignment_id=ta and old.task_version_id=m.id and old.status='assigned' and exists(select 1 from jsonb_array_elements(roster) member where (member->>'enrollmentId')::uuid=rp.enrollment_id)));
   else
    if p_payload->>'fingerprint' is distinct from private.writing_task_fingerprint(m) or p_payload->>'rosterFingerprint' is distinct from stamp then raise exception 'assignment_preview_stale';end if;
    if p_payload->>'mode'='class' then select coalesce(array_agg((v->>'enrollmentId')::uuid order by v->>'enrollmentId'),array[]::uuid[]) into selected_ids from jsonb_array_elements(roster) v;end if;
    if cardinality(selected_ids)=0 or exists(select 1 from unnest(selected_ids) id where not exists(select 1 from jsonb_array_elements(roster) v where (v->>'enrollmentId')::uuid=id)) then raise exception 'assignment_recipients_invalid';end if;
    if exists(select 1 from public.writing_assignment_recipients rp join public.writing_assignments old on old.id=rp.assignment_id
      where old.teacher_assignment_id=ta and old.task_version_id=m.id and old.status='assigned' and rp.enrollment_id=any(selected_ids))
     then raise exception 'assignment_already_assigned';end if;
    insert into public.writing_assignments(task_version_id,teacher_assignment_id,school_id,academic_year_id,class_id,subject_program_id,curriculum_release_id,unit_id,created_by,request_id,request_hash,recipient_mode,recipient_count,instructions)
     values(m.id,ta,(ctx->>'schoolId')::uuid,(ctx->>'academicYearId')::uuid,(ctx->>'classId')::uuid,(ctx->>'subjectProgramId')::uuid,rel,unt,p_actor_id,(p_payload->>'requestId')::uuid,request_hash,p_payload->>'mode',cardinality(selected_ids),btrim(coalesce(p_payload->>'instructions',''))) returning * into a;
    insert into public.writing_assignment_recipients(assignment_id,enrollment_id,student_id)
     select a.id,(v->>'enrollmentId')::uuid,(v->>'studentId')::uuid from jsonb_array_elements(roster) v where (v->>'enrollmentId')::uuid=any(selected_ids);
    insert into public.writing_assignment_events(assignment_id,actor_id,event,detail)
     values(a.id,p_actor_id,'assigned',jsonb_build_object('mode',a.recipient_mode,'recipientCount',a.recipient_count,'taskVersionId',m.id,'fingerprint',private.writing_task_fingerprint(m)));
    if stamp<>encode(sha256(convert_to(private.resource_assignment_roster(ta,ctx)::text,'UTF8')),'hex') then raise exception 'assignment_preview_stale';end if;
    result:=jsonb_build_object('assignment',private.writing_assignment_public(a,m),'replayed',false);
   end if;
  end if;
 elsif p_action='list' then
  if role_name<>'teacher' or exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('offset','state')) then raise exception 'assignment_request_invalid';end if;
  select coalesce(jsonb_agg(entry order by created_at desc,id),'[]') into entries from (
   select a.created_at,a.id,private.writing_assignment_public(a,m) entry from public.writing_assignments a
   join public.written_task_versions m on m.id=a.task_version_id
   where a.teacher_assignment_id=ta and a.curriculum_release_id=rel and a.unit_id=unt and a.created_by=p_actor_id
   and (case when state_filter='current' then a.status='assigned' else a.status='canceled' end)
   order by a.created_at desc,a.id offset off limit 51) q;
  result:=jsonb_build_object('assignments',case when jsonb_array_length(entries)>50 then entries-50 else entries end,'hasMore',jsonb_array_length(entries)>50,'nextOffset',off+50,'readOnly',ctx->'readOnly');
 else
  if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('id','revision','reason')) or p_payload->>'id' is null then raise exception 'assignment_request_invalid';end if;
  select * into a from public.writing_assignments where id=(p_payload->>'id')::uuid and teacher_assignment_id=ta and curriculum_release_id=rel and unit_id=unt
   and school_id=(ctx->>'schoolId')::uuid and class_id=(ctx->>'classId')::uuid
   and (case when role_name='teacher' then created_by=p_actor_id else exists(select 1 from public.writing_assignment_recipients rp where rp.assignment_id=writing_assignments.id and rp.enrollment_id=enr and rp.student_id=p_actor_id) end);
  if not found then raise exception 'assignment_unavailable';end if;
  select * into strict m from public.written_task_versions where id=a.task_version_id;
  -- Serialize delivery/cancellation for a pinned task; re-read after lock waits.
  perform pg_advisory_xact_lock(hashtextextended('writing-task-delivery:'||m.id::text,0));
  select * into strict m from public.written_task_versions where id=m.id for share;
  select * into strict a from public.writing_assignments where id=a.id for update;
  if p_action='cancel' then
   if role_name<>'teacher' then raise exception 'assignment_forbidden';end if;
   reason:=btrim(coalesce(p_payload->>'reason',''));
   if length(reason) not between 1 and 1000 then raise exception 'assignment_reason_required';end if;
   if (p_payload->>'revision')::integer is null then raise exception 'assignment_request_invalid';end if;
   if a.status='canceled' then
    if a.cancel_reason<>reason or (p_payload->>'revision')::integer not in (a.revision,a.revision-1) then raise exception 'assignment_conflict';end if;
   else
    if (p_payload->>'revision')::integer is distinct from a.revision then raise exception 'assignment_conflict';end if;
    update public.writing_assignments set status='canceled',revision=revision+1,canceled_at=clock_timestamp(),cancel_reason=reason where id=a.id returning * into a;
    insert into public.writing_assignment_events(assignment_id,actor_id,event,detail) values(a.id,p_actor_id,'canceled',jsonb_build_object('reason',reason));
   end if;
  end if;
  entry:=private.writing_assignment_public(a,m);
  if role_name='student' then entry:=entry-'recipientCount'||jsonb_build_object('context',p_context);end if;
  result:=jsonb_build_object('assignment',entry,'readOnly',ctx->'readOnly');
  if p_action in ('get','cancel') and role_name='teacher' then
   result:=result||jsonb_build_object('recipients',(select coalesce(jsonb_agg(jsonb_build_object('enrollmentId',rp.enrollment_id,'studentName',coalesce(nullif(btrim(p.display_name),''),'Աշակերտ')) order by rp.enrollment_id),'[]')
    from public.writing_assignment_recipients rp join public.profiles p on p.id=rp.student_id where rp.assignment_id=a.id),
    'events',(select coalesce(jsonb_agg(jsonb_build_object('event',event,'at',created_at,'detail',detail) order by created_at,id),'[]') from public.writing_assignment_events where assignment_id=a.id));
  end if;
  if p_action='open' and not coalesce(private.writing_assignment_available(a,m),false) then raise exception 'assignment_unavailable';end if;
 end if;
 if role_name='teacher' then
  perform private.lock_written_teacher_context(p_actor_id,p_auth_session_id,ta,rel,unt,p_action in ('preview','assign','cancel'));
 else perform private.lock_student_learning_context(p_actor_id,p_auth_session_id,enr,rel,unt);end if;
 perform private.supplementary_session(p_actor_id,p_auth_session_id);
 return jsonb_build_object('version','writing-assignments-v1')||result;
end;$function$;

ALTER FUNCTION "private"."service_writing_assignments"(p_actor_id uuid, p_auth_session_id uuid, p_action text, p_context jsonb, p_payload jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.service_written_work(p_actor_id uuid, p_auth_session_id uuid, p_action text, p_context jsonb, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
#variable_conflict use_column
declare teacher boolean; ctx jsonb; e public.institutional_class_enrollments%rowtype;
 task public.written_task_versions%rowtype; w public.written_work%rowtype; sub public.written_submissions%rowtype;
 old_review public.written_reviews%rowtype; cr public.written_reviews%rowtype;
 rel uuid:=(p_context->>'curriculumReleaseId')::uuid; unt uuid:=(p_context->>'unitId')::uuid;
 assignment uuid:=(p_context->>'assignmentId')::uuid; enrollment uuid:=(p_context->>'enrollmentId')::uuid;
 mutating boolean:=p_action in ('save','submit','review'); result jsonb; entries jsonb; histories jsonb;
 c jsonb; scores jsonb; decision text; txt text; state_filter text; offset_n integer; revision_n integer;
begin
 if jsonb_typeof(p_context) is distinct from 'object' or jsonb_typeof(p_payload) is distinct from 'object'
 or rel is null or unt is null or (assignment is null)=(enrollment is null)
 or p_action not in ('tasks','open','save','submit','queue','inspect','review') then raise exception 'written_request_invalid';end if;
 teacher:=assignment is not null;
 if teacher then
  if p_action not in ('queue','inspect','review') then raise exception 'written_context_unavailable';end if;
  ctx:=private.lock_written_teacher_context(p_actor_id,p_auth_session_id,assignment,rel,unt,mutating);
 else
  if p_action not in ('tasks','open','save','submit') then raise exception 'written_context_unavailable';end if;
  e:=private.lock_student_learning_context(p_actor_id,p_auth_session_id,enrollment,rel,unt);
  ctx:=jsonb_build_object('schoolId',e.school_id,'academicYearId',e.academic_year_id,'classId',e.class_id,'subjectProgramId',e.subject_program_id,'readOnly',false);
 end if;
 if p_action='tasks' then
  if p_payload<>'{}'::jsonb then raise exception 'written_request_invalid';end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',t.id,'title',t.definition->>'title','locale',t.definition->>'locale','version',t.version_no,
   'state',coalesce(w.state,'not_started'),'workId',w.id,'available',t.status='approved',
   'baselineRequired',(t.definition->>'baselineRequired')::boolean,'baselineCompleted',private.scoped_chapter_baseline(p_actor_id,rel,unt) is not null)
   order by t.task_key,t.version_no),'[]') into entries
  from public.written_task_versions t left join public.written_work w on w.task_version_id=t.id and w.student_id=p_actor_id and w.school_id=e.school_id and w.academic_year_id=e.academic_year_id and w.class_id=e.class_id
  where t.curriculum_release_id=rel and t.unit_id=unt and t.subject_program_id=e.subject_program_id and (t.status='approved' or w.id is not null);
  result:=jsonb_build_object('version','written-work-v1','tasks',entries);
 elsif p_action='queue' then
  if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('state','offset')) then raise exception 'written_request_invalid';end if;
  state_filter:=coalesce(p_payload->>'state','submitted');offset_n:=coalesce((p_payload->>'offset')::integer,0);
  if state_filter not in ('all','submitted','changes_requested','reviewed') or offset_n not between 0 and 100000 then raise exception 'written_request_invalid';end if;
  select coalesce(jsonb_agg(entry order by updated_at desc,id),'[]') into entries from (
   select w.id,w.updated_at,jsonb_build_object('id',w.id,'studentName',coalesce(p.display_name,'Աշակերտ'),'taskTitle',t.definition->>'title',
    'state',w.state,'updatedAt',w.updated_at,'revision',w.revision,'taskVersion',t.version_no) entry
   from public.written_work w join public.written_task_versions t on t.id=w.task_version_id join public.profiles p on p.id=w.student_id
   where w.school_id=(ctx->>'schoolId')::uuid and w.academic_year_id=(ctx->>'academicYearId')::uuid and w.class_id=(ctx->>'classId')::uuid
   and w.subject_program_id=(ctx->>'subjectProgramId')::uuid and w.curriculum_release_id=rel and w.unit_id=unt and w.current_submission_id is not null
   and (state_filter='all' or w.state=state_filter)
   order by w.updated_at desc,w.id offset offset_n limit 51
  ) q;
  result:=jsonb_build_object('version','written-work-v1','queue',entries,'readOnly',ctx->'readOnly');
 else
  if p_action='open' then
   if exists(select 1 from jsonb_object_keys(p_payload) k where k<>'taskId') then raise exception 'written_request_invalid';end if;
   select * into task from public.written_task_versions where id=(p_payload->>'taskId')::uuid and curriculum_release_id=rel and unit_id=unt and subject_program_id=e.subject_program_id for share;
   if not found then raise exception 'written_task_unavailable';end if;
   select * into w from public.written_work where task_version_id=task.id and student_id=p_actor_id and school_id=e.school_id and academic_year_id=e.academic_year_id and class_id=e.class_id;
   if w.id is null and task.status<>'approved' then raise exception 'written_task_unavailable';end if;
   -- Opening is read-only. First save or submission creates the work record.
  else
   if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('taskId','workId','expectedRevision','text','decision','scores','feedback','changeReason')) then raise exception 'written_request_invalid';end if;
   if teacher then
    select * into w from public.written_work where id=(p_payload->>'workId')::uuid and school_id=(ctx->>'schoolId')::uuid and academic_year_id=(ctx->>'academicYearId')::uuid and class_id=(ctx->>'classId')::uuid and subject_program_id=(ctx->>'subjectProgramId')::uuid and curriculum_release_id=rel and unit_id=unt for update;
    if not found or w.current_submission_id is null then raise exception 'written_work_unavailable';end if;
    select * into task from public.written_task_versions where id=w.task_version_id for share;
   else
    select * into task from public.written_task_versions where id=(p_payload->>'taskId')::uuid and curriculum_release_id=rel and unit_id=unt and subject_program_id=e.subject_program_id for share;
    if not found or task.status<>'approved' then raise exception 'written_task_unavailable';end if;
    if (task.definition->>'baselineRequired')::boolean and private.scoped_chapter_baseline(p_actor_id,rel,unt) is null then raise exception 'chapter_diagnostic_required';end if;
    -- Unique key serializes concurrent first saves; no draft is visible to teachers.
    insert into public.written_work(task_version_id,student_id,enrollment_id,school_id,academic_year_id,class_id,subject_program_id,curriculum_release_id,unit_id)
     values(task.id,p_actor_id,e.id,e.school_id,e.academic_year_id,e.class_id,e.subject_program_id,rel,unt) on conflict do nothing;
    select * into strict w from public.written_work where task_version_id=task.id and student_id=p_actor_id and school_id=e.school_id and academic_year_id=e.academic_year_id and class_id=e.class_id for update;
   end if;
   if mutating then
    if jsonb_typeof(p_payload->'expectedRevision') is distinct from 'number' or coalesce(p_payload->>'expectedRevision','')!~ '^[0-9]+$' or (p_payload->>'expectedRevision')::numeric>2147483646 then raise exception 'written_request_invalid';end if;
    revision_n:=(p_payload->>'expectedRevision')::integer;
    if w.revision<>revision_n then raise exception 'written_conflict';end if;
   end if;
   if p_action in ('save','submit') then
    txt:=p_payload->>'text';
    if jsonb_typeof(p_payload->'text') is distinct from 'string' or length(txt)>20000 or (p_action='submit' and private.written_word_count(txt)=0) then raise exception 'written_text_invalid';end if;
    if w.state not in ('draft','changes_requested') then raise exception 'written_conflict';end if;
    if p_action='submit' then
     insert into public.written_submissions(work_id,version_no,response_text,word_count,assistance_snapshot)
      values(w.id,(select coalesce(max(version_no),0)+1 from public.written_submissions where work_id=w.id),txt,private.written_word_count(txt),task.definition->'assistance') returning * into sub;
    end if;
    update public.written_work set draft_text=txt,enrollment_id=e.id,revision=revision+1,updated_at=clock_timestamp(),
     state=case when p_action='submit' then 'submitted' else state end,current_submission_id=case when p_action='submit' then sub.id else current_submission_id end where id=w.id returning * into w;
   elsif p_action='review' then
    if w.state not in ('submitted','reviewed') then raise exception 'written_conflict';end if;
    decision:=p_payload->>'decision';scores:=p_payload->'scores';
    if decision not in ('assessed','return') or decision is null or jsonb_typeof(p_payload->'feedback') is distinct from 'string' or length(btrim(p_payload->>'feedback')) not between 1 and 4000 then raise exception 'written_review_invalid';end if;
    if decision='assessed' then
     if jsonb_typeof(scores) is distinct from 'object' or (select count(*) from jsonb_object_keys(scores))<>jsonb_array_length(task.definition->'criteria') then raise exception 'written_review_invalid';end if;
     for c in select value from jsonb_array_elements(task.definition->'criteria') loop
      if jsonb_typeof(scores->(c->>'key')) is distinct from 'number' or coalesce(scores->>(c->>'key'),'')!~ '^[0-9]+$' or (scores->>(c->>'key'))::numeric>=jsonb_array_length(c->'descriptors') then raise exception 'written_review_invalid';end if;
     end loop;
    elsif scores is not null and scores<>'null'::jsonb then raise exception 'written_review_invalid';end if;
    select * into old_review from public.written_reviews where submission_id=w.current_submission_id order by version_no desc limit 1;
    if old_review.id is not null and coalesce(length(btrim(p_payload->>'changeReason')),0) not between 3 and 1000 then raise exception 'written_review_invalid';end if;
    insert into public.written_reviews(submission_id,version_no,decision,criterion_scores,feedback,assessor_id,teacher_assignment_id,supersedes_review_id,change_reason)
     values(w.current_submission_id,coalesce(old_review.version_no,0)+1,decision,case when decision='assessed' then scores else null end,btrim(p_payload->>'feedback'),p_actor_id,assignment,old_review.id,case when old_review.id is not null then btrim(p_payload->>'changeReason') end) returning * into cr;
    update public.written_work set state=case when decision='assessed' then 'reviewed' else 'changes_requested' end,revision=revision+1,updated_at=clock_timestamp() where id=w.id returning * into w;
   end if;
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'version',s.version_no,'text',s.response_text,'wordCount',s.word_count,'submittedAt',s.submitted_at,
   'reviews',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'version',r.version_no,'decision',r.decision,'scores',r.criterion_scores,'feedback',r.feedback,'createdAt',r.created_at,'changeReason',r.change_reason,'supersedesReviewId',r.supersedes_review_id) order by r.version_no) from public.written_reviews r where r.submission_id=s.id),'[]')) order by s.version_no),'[]') into histories
   from public.written_submissions s where s.work_id=w.id;
  result:=jsonb_build_object('version','written-work-v1','task',jsonb_build_object('id',task.id,'version',task.version_no,'definition',task.definition,'available',task.status='approved'),
   'work',case when w.id is null then null else jsonb_build_object('id',w.id,'state',w.state,'revision',w.revision,'currentSubmissionId',w.current_submission_id,'updatedAt',w.updated_at) end,
   'submissions',histories,'readOnly',case when teacher then (ctx->>'readOnly')::boolean else task.status<>'approved' end);
  if teacher then result:=result||jsonb_build_object('studentName',(select coalesce(display_name,'Աշակերտ') from public.profiles where id=w.student_id));end if;
  if not teacher then result:=result||jsonb_build_object('draftText',coalesce(w.draft_text,''),'baselineCompleted',private.scoped_chapter_baseline(p_actor_id,rel,unt) is not null);end if;
 end if;
 -- Lock waits cannot extend expired authority. Revalidate before returning any evidence.
 if teacher then perform private.lock_written_teacher_context(p_actor_id,p_auth_session_id,assignment,rel,unt,mutating);
 else perform private.lock_student_learning_context(p_actor_id,p_auth_session_id,enrollment,rel,unt);end if;
 return result;
exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'written_request_invalid';
end;
$function$;

ALTER FUNCTION "private"."service_written_work"(p_actor_id uuid, p_auth_session_id uuid, p_action text, p_context jsonb, p_payload jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.set_row_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$;

ALTER FUNCTION "private"."set_row_updated_at"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.source_family_reserved(p_student uuid, p_family uuid, p_session uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select exists(select 1 from public.learning_session_items li join public.learning_sessions s on s.id=li.session_id
  where s.student_id=p_student and li.source_family_id_snapshot=p_family and s.id is distinct from p_session
   and s.status='active' and s.mode in ('diagnostic','mastery_check'));
$function$;

ALTER FUNCTION "private"."source_family_reserved"(p_student uuid, p_family uuid, p_session uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.source_family_seen(p_student uuid, p_family uuid, p_session uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select p_family is not null and (
 exists(select 1 from public.learning_source_family_exposures e join public.learning_session_items li on li.id=e.session_item_id
  where e.student_id=p_student and e.source_family_id=p_family and li.session_id is distinct from p_session)
 or exists(select 1 from public.learning_session_items li join public.learning_sessions s on s.id=li.session_id
  where s.student_id=p_student and li.source_family_id_snapshot=p_family and s.id is distinct from p_session)
 or exists(select 1 from public.attempts a where a.student_id=p_student and a.normalized_response#>>'{audioEvidence,sourceFamilyId}'=p_family::text and a.learning_session_id is distinct from p_session));
$function$;

ALTER FUNCTION "private"."source_family_seen"(p_student uuid, p_family uuid, p_session uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.student_unit_guides(p_student_id uuid, p_auth_session_id uuid, p_enrollment_id uuid, p_release_id uuid, p_unit_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.institutional_class_enrollments%rowtype; m public.unit_material_versions%rowtype;
 code text; programme uuid; availability text:='available'; guides jsonb:='[]';
begin
 select ru.unit_code_snapshot,r.subject_program_id into code,programme
 from public.curriculum_release_units ru join public.curriculum_releases r on r.id=ru.curriculum_release_id
 where ru.curriculum_release_id=p_release_id and ru.unit_id=p_unit_id;
 if not found then raise exception 'learning_context_unavailable';end if;
 -- Same order as assessment starts, including the registered legacy adapter.
 -- This serializes a guide read with a concurrent start, across enrollments.
 perform pg_advisory_xact_lock(hashtextextended('initial-diagnostic:'||p_student_id::text||':'||code,0));
 perform pg_advisory_xact_lock(hashtextextended('governed-diagnostic:'||p_student_id::text||':'||programme::text||':'||p_unit_id::text,0));
 e:=private.lock_student_learning_context(p_student_id,p_auth_session_id,p_enrollment_id,p_release_id,p_unit_id);
 if exists(select 1 from public.learning_sessions s where s.student_id=p_student_id
  and s.status='active' and s.mode in ('diagnostic','mastery_check')
  and ((s.assessment_policy_binding_id is not null and s.subject_program_id=e.subject_program_id and s.governed_unit_id=p_unit_id)
   or (s.assessment_policy_binding_id is null and exists(select 1 from public.legacy_learning_blueprint_mappings lm
    where lm.assessment_blueprint_id=s.assessment_blueprint_id and lm.curriculum_release_id=s.curriculum_release_id
    and lm.subject_program_id=e.subject_program_id and lm.unit_id=p_unit_id and lm.unit_code_snapshot=s.unit_code))))
 then availability:='assessment_active';
 elsif private.scoped_chapter_baseline(p_student_id,p_release_id,p_unit_id) is null
 then availability:='diagnostic_required';
 else
  for m in select * from public.unit_material_versions v
   where v.subject_program_id=e.subject_program_id and v.curriculum_release_id=p_release_id and v.unit_id=p_unit_id
    and v.kind='guide' and v.status='approved' and v.reviewed_at is not null
    and v.definition->>'schemaVersion'='teaching-guide-v1'
    and v.qa->'passed'='true'::jsonb and v.qa->>'fingerprint'=v.fingerprint
   order by v.sequence_order,v.material_key,v.id for share
  loop
   -- Explicit public projection: never send review packages, source references,
   -- comparison notes, staff identities, writing models or arbitrary JSON keys.
   guides:=guides||jsonb_build_array(jsonb_build_object('id',m.id,'version',m.version_no,
    'sequenceOrder',m.sequence_order,'schemaVersion','teaching-guide-v1',
    'title',m.definition->>'title','text',m.definition->>'text',
    'workedExample',m.definition->>'workedExample','locale',m.definition->>'locale'));
  end loop;
 end if;
 -- Recheck wall-clock validity after material locks, including empty/blocked reads.
 perform private.lock_student_learning_context(p_student_id,p_auth_session_id,p_enrollment_id,p_release_id,p_unit_id);
 return jsonb_build_object('guidesVersion','unit-guides-v1','availability',availability,'guides',guides,'readOnly',true);
end;
$function$;

ALTER FUNCTION "private"."student_unit_guides"(p_student_id uuid, p_auth_session_id uuid, p_enrollment_id uuid, p_release_id uuid, p_unit_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.supplementary_context(p_actor uuid, p_auth uuid, p_role text, p_context jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare e public.institutional_class_enrollments%rowtype;ctx jsonb;x record;t timestamptz;
 rel uuid:=(p_context->>'curriculumReleaseId')::uuid; unt uuid:=(p_context->>'unitId')::uuid;
begin
 if rel is null or unt is null then raise exception 'resource_request_invalid';end if;
 if p_role='student' then
  if p_context ? 'assignmentId' or not(p_context ? 'enrollmentId') then raise exception 'resource_forbidden';end if;
  e:=private.lock_student_learning_context(p_actor,p_auth,(p_context->>'enrollmentId')::uuid,rel,unt);
  return jsonb_build_object('subjectProgramId',e.subject_program_id,'assignmentId',e.teacher_assignment_id);
 elsif p_role='teacher' then
  if p_context ? 'enrollmentId' or not(p_context ? 'assignmentId') then raise exception 'resource_forbidden';end if;
  ctx:=private.lock_written_teacher_context(p_actor,p_auth,(p_context->>'assignmentId')::uuid,rel,unt,true);
  return ctx||jsonb_build_object('assignmentId',p_context->>'assignmentId');
 elsif p_role in ('admin','content_admin') then
  if p_context ?| array['assignmentId','enrollmentId'] then raise exception 'resource_forbidden';end if;
  select r.subject_program_id,r.status,r.effective_from,r.effective_to,sp.status sp_status,s.status s_status into x
   from public.curriculum_releases r join public.subject_programs sp on sp.id=r.subject_program_id
   join public.subjects s on s.id=sp.subject_id join public.units u on u.subject_program_id=sp.id and u.id=unt
   join public.curriculum_release_units ru on ru.curriculum_release_id=r.id and ru.unit_id=u.id
   where r.id=rel for share of r,sp,s,u,ru;
  t:=clock_timestamp();
  if not found or x.status not in ('pilot','production') or x.effective_from>t::date or x.effective_to<t::date or x.sp_status<>'published' or x.s_status<>'published' then raise exception 'resource_forbidden';end if;
  return jsonb_build_object('subjectProgramId',x.subject_program_id);
 end if;
 raise exception 'resource_forbidden';
end;$function$;

ALTER FUNCTION "private"."supplementary_context"(p_actor uuid, p_auth uuid, p_role text, p_context jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.supplementary_definition(p_d jsonb, p_teacher boolean)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if jsonb_typeof(p_d) is distinct from 'object' or octet_length(p_d::text)>16000
 or exists(select 1 from jsonb_each(p_d) v where v.key in ('title','description','goal','topic','purpose','format','url','locale','sourceReference') and jsonb_typeof(v.value)<>'string')
 or exists(select 1 from jsonb_object_keys(p_d) k where k not in ('title','description','goal','topic','purpose','format','url','locale','estimatedMinutes','recommended','sourceReference','rightsConfirmed','assessmentSafe'))
 or p_d->>'purpose' not in ('practice','reading') or p_d->>'purpose' is null
 or p_d->>'format' not in ('pdf','link') or p_d->>'format' is null
 or coalesce(length(btrim(p_d->>'title')),0) not between 1 and 200
 or coalesce(length(btrim(p_d->>'description')),0) not between 1 and 2000
 or coalesce(length(p_d->>'goal'),0)>500 or coalesce(length(p_d->>'topic'),0)>200
 or p_d->>'locale' not in ('hy','en','ru') or p_d->>'locale' is null
 or coalesce(length(btrim(p_d->>'sourceReference')),0) not between 1 and 2000
 or p_d->'rightsConfirmed' is distinct from 'true'::jsonb or p_d->'assessmentSafe' is distinct from 'true'::jsonb
 or (p_d ? 'recommended' and jsonb_typeof(p_d->'recommended')<>'boolean')
 or (not p_teacher and p_d->'recommended'='true'::jsonb)
 or (p_d ? 'estimatedMinutes' and (jsonb_typeof(p_d->'estimatedMinutes')<>'number' or (p_d->>'estimatedMinutes') !~ '^[0-9]{1,3}$' or (p_d->>'estimatedMinutes')::integer not between 1 and 240))
 or (p_d->>'format'='link' and (coalesce(p_d->>'url','') !~ '^https://[^/@[:space:]]+([/?#].*)?$' or length(p_d->>'url')>2048))
 or (p_d->>'format'='pdf' and p_d ? 'url') then raise exception 'resource_definition_invalid';end if;
end;$function$;

ALTER FUNCTION "private"."supplementary_definition"(p_d jsonb, p_teacher boolean) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.supplementary_fingerprint(p_definition jsonb, p_path text, p_bytes integer, p_sha text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 select encode(sha256(convert_to(jsonb_build_array(p_definition,p_path,p_bytes,p_sha)::text,'UTF8')),'hex');
$function$;

ALTER FUNCTION "private"."supplementary_fingerprint"(p_definition jsonb, p_path text, p_bytes integer, p_sha text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.supplementary_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' and (to_jsonb(new)-array['status','qa','published_at','fingerprint','object_path','file_bytes','file_sha256','created_by'])
   is distinct from (to_jsonb(old)-array['status','qa','published_at','fingerprint','object_path','file_bytes','file_sha256','created_by']) then raise exception 'resource_immutable';end if;
 if tg_op='UPDATE' and new.created_by is distinct from old.created_by and not(new.created_by is null and not exists(select 1 from public.profiles where id=old.created_by)) then raise exception 'resource_immutable';end if;
 if tg_op='UPDATE' and (new.object_path,new.file_bytes,new.file_sha256) is distinct from (old.object_path,old.file_bytes,old.file_sha256)
 and (old.status<>'draft' or old.object_path is not null) then raise exception 'resource_immutable';end if;
 if not exists(select 1 from public.curriculum_releases where id=new.curriculum_release_id and subject_program_id=new.subject_program_id) then raise exception 'resource_scope_invalid';end if;
 new.fingerprint:=private.supplementary_fingerprint(new.definition,new.object_path,new.file_bytes,new.file_sha256);
 if new.status='published' and (new.qa->>'fingerprint' is distinct from new.fingerprint or new.qa->>'passed' is distinct from 'true') then raise exception 'resource_qa_required';end if;
 return new;
end;$function$;

ALTER FUNCTION "private"."supplementary_guard"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.supplementary_public(p public.supplementary_resource_versions)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select jsonb_build_object('id',p.id,'resourceId',p.resource_id,'version',p.version_no,'provider',p.provider,
 'providerName',case when p.provider='teacher' then (select display_name from public.profiles where id=p.created_by) else null end,
 'definition',p.definition-array['sourceReference','rightsConfirmed','assessmentSafe','url'],
 'status',p.status,'publishedAt',p.published_at,'fileBytes',p.file_bytes,'fingerprint',p.fingerprint);
$function$;

