CREATE OR REPLACE FUNCTION private.supplementary_session(p_actor uuid, p_auth uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare x record;t timestamptz;
begin
 select p.role,p.account_status,u.deleted_at,u.banned_until,s.not_after into x from public.profiles p
 join auth.users u on u.id=p.id join auth.sessions s on s.user_id=p.id and s.id=p_auth where p.id=p_actor for share of p,u,s;
 t:=clock_timestamp();
 if not found or x.account_status<>'active' or x.deleted_at is not null or x.banned_until>t or x.not_after<=t then raise exception 'resource_forbidden';end if;
 return x.role;
end;$function$;

ALTER FUNCTION "private"."supplementary_session"(p_actor uuid, p_auth uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.sync_active_curriculum_release_units()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  delete from private.active_curriculum_release_units where curriculum_release_id=new.id;
  if new.status in ('pilot','production') then
    insert into private.active_curriculum_release_units(unit_id,curriculum_release_id)
    select unit_id,new.id from public.curriculum_release_units
    where curriculum_release_id=new.id order by unit_id;
  end if;
  return new;
end;
$function$;

