 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 if tg_op='DELETE' or new.submission_id<>old.submission_id or new.teacher_id<>old.teacher_id or new.revision<>old.revision+1 then raise exception 'task_review_immutable';end if;return new;end;$function$;

