CREATE OR REPLACE FUNCTION private.teacher_task_work_public(p_id uuid, p_enrollment uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select jsonb_build_object('revision',coalesce(w.revision,0),'state',coalesce(w.state,'not_started'),'content',w.content,'document',(select jsonb_build_object('id',f.id,'format',f.format,'bytes',f.file_bytes) from public.teacher_task_response_files f where f.id=case when w.content->>'kind'='document' then (w.content->>'fileId')::uuid end and f.delivery_id=p_id and f.enrollment_id=p_enrollment),
 'submissions',(select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'content',s.content,'submittedAt',s.submitted_at,'reviews',private.teacher_task_submission_reviews(s.id)) order by s.submitted_at,s.id),'[]') from public.teacher_task_submissions s where s.delivery_id=p_id and s.enrollment_id=p_enrollment))
 from (values(1)) seed(n) left join public.teacher_task_student_work w on w.delivery_id=p_id and w.enrollment_id=p_enrollment;
$function$;

ALTER FUNCTION "private"."teacher_task_work_public"(p_id uuid, p_enrollment uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.unit_material_fingerprint(m public.unit_material_versions)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 select encode(sha256(convert_to(jsonb_build_array(m.subject_program_id,m.curriculum_release_id,m.unit_id,m.material_key,m.kind,m.version_no,m.sequence_order,m.definition,m.review_package)::text,'UTF8')),'hex');
$function$;

ALTER FUNCTION "private"."unit_material_fingerprint"(m public.unit_material_versions) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.unit_material_issues(m public.unit_material_versions)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare d jsonb:=m.definition; p jsonb:=m.review_package; issues jsonb:='[]'; c jsonb;
begin
 if jsonb_typeof(d->'title') is distinct from 'string' or coalesce(length(btrim(d->>'title')),0) not between 1 and 200
 or coalesce(d->>'locale','')!~ '^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$' then issues:=issues||'"title_or_locale"'::jsonb;end if;
 if jsonb_typeof(d->'source') is distinct from 'object' or coalesce(d->'source','{}')='{}'::jsonb
 or coalesce(length(btrim(p->>'sourceReference')),0)=0 or coalesce(length(btrim(p->>'comparisonReference')),0)=0
 then issues:=issues||'"source_or_comparison"'::jsonb;end if;
 if jsonb_typeof(d->'outcomes') is distinct from 'array' then issues:=issues||'"outcomes"'::jsonb;
 elsif jsonb_array_length(d->'outcomes')=0 or exists(select 1 from jsonb_array_elements(d->'outcomes') x where jsonb_typeof(x)<>'string' or not exists(select 1 from public.curriculum_release_skills s where s.curriculum_release_id=m.curriculum_release_id and s.skill_code_snapshot=x#>>'{}')) then issues:=issues||'"outcomes"'::jsonb;end if;
 if m.kind='guide' then
  if d->>'schemaVersion' is distinct from 'teaching-guide-v1' or jsonb_typeof(d->'text') is distinct from 'string'
   or coalesce(length(btrim(d->>'text')),0) not between 1 and 12000 or jsonb_typeof(d->'workedExample') is distinct from 'string'
   or coalesce(length(btrim(d->>'workedExample')),0) not between 1 and 4000 then issues:=issues||'"guide_definition"'::jsonb;end if;
 else
  if d->>'schemaVersion' is distinct from 'extended-text-v1' or jsonb_typeof(d->'prompt') is distinct from 'string'
   or coalesce(length(btrim(d->>'prompt')),0) not between 1 and 8000 or d->>'wordCountConvention' is distinct from 'unicode-whitespace-v1'
   or jsonb_typeof(d->'baselineRequired') is distinct from 'boolean' or jsonb_typeof(d->'assistance') is distinct from 'object'
   or exists(select 1 from jsonb_object_keys(d) k where k not in ('schemaVersion','title','prompt','locale','minWords','maxWords','wordCountConvention','baselineRequired','assistance','source','outcomes','criteria'))
   then issues:=issues||'"writing_definition"'::jsonb;end if;
  if coalesce(d->>'minWords','')!~ '^[0-9]{1,4}$' or coalesce(d->>'maxWords','')!~ '^[1-9][0-9]{0,3}$' then issues:=issues||'"word_range"'::jsonb;
  elsif (d->>'minWords')::integer>(d->>'maxWords')::integer or (d->>'maxWords')::integer>4000 then issues:=issues||'"word_range"'::jsonb;end if;
  if jsonb_typeof(d->'criteria') is distinct from 'array' then issues:=issues||'"rubric"'::jsonb;
  else
   if jsonb_array_length(d->'criteria') not between 1 and 12 or (select count(distinct v->>'key') from jsonb_array_elements(d->'criteria') v)<>jsonb_array_length(d->'criteria') then issues:=issues||'"rubric"'::jsonb;end if;
   for c in select value from jsonb_array_elements(d->'criteria') loop
    if coalesce(c->>'key','')!~ '^[a-z][a-z0-9_]{0,39}$' or jsonb_typeof(c->'label') is distinct from 'string' or coalesce(length(btrim(c->>'label')),0) not between 1 and 160 or jsonb_typeof(c->'descriptors') is distinct from 'array' then issues:=issues||'"rubric"'::jsonb;
    elsif jsonb_array_length(c->'descriptors') not between 2 and 11 or exists(select 1 from jsonb_array_elements(c->'descriptors') v where jsonb_typeof(v)<>'string' or length(btrim(v#>>'{}')) not between 1 and 1000) then issues:=issues||'"rubric"'::jsonb;end if;
   end loop;
  end if;
 end if;
 return issues;
end;
$function$;

ALTER FUNCTION "private"."unit_material_issues"(m public.unit_material_versions) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.unit_material_privacy_counts(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select jsonb_build_object('materialVersions',(select count(*) from public.unit_material_versions where created_by=p_user_id),'materialReviews',(select count(*) from public.unit_material_versions where reviewed_by=p_user_id),'materialEvents',(select count(*) from public.unit_material_events where actor_id=p_user_id));
$function$;

ALTER FUNCTION "private"."unit_material_privacy_counts"(p_user_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_arrangement_definition(p_type text, p_definition jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare names text[]; name text; rows jsonb; row jsonb;
begin
 if p_type not in ('matching','ordering') or p_type is null or jsonb_typeof(p_definition) is distinct from 'object' then raise exception 'arrangement_contract_invalid'; end if;
 names:=case when p_type='matching' then array['schemaVersion','locale','cardinality','sources','targets'] else array['schemaVersion','locale','segments'] end;
 if (select count(*) from jsonb_object_keys(p_definition))<>cardinality(names) or not (p_definition ?& names)
 or p_definition->>'schemaVersion' is distinct from ('haiedu-'||p_type||'-v1')
 or jsonb_typeof(p_definition->'locale') is distinct from 'string' or length(p_definition->>'locale')>35
 or (p_definition->>'locale') !~ '^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$' then raise exception 'arrangement_contract_invalid'; end if;
 foreach name in array (case when p_type='matching' then array['sources','targets'] else array['segments'] end) loop
  rows:=p_definition->name;
  if jsonb_typeof(rows) is distinct from 'array' then raise exception 'arrangement_contract_invalid'; end if;
  if jsonb_array_length(rows) not between 2 and 12 then raise exception 'arrangement_contract_invalid'; end if;
  for row in select value from jsonb_array_elements(rows) loop
   if jsonb_typeof(row) is distinct from 'object' then raise exception 'arrangement_contract_invalid'; end if;
   if (select count(*) from jsonb_object_keys(row))<>2 or not (row ?& array['id','label'])
   or jsonb_typeof(row->'id') is distinct from 'string' or (row->>'id') !~ '^[a-z][a-z0-9_]{0,39}$'
   or jsonb_typeof(row->'label') is distinct from 'string' or length(btrim(row->>'label',E' \t\r\n'))=0 or length(row->>'label')>2000
   then raise exception 'arrangement_contract_invalid'; end if;
  end loop;
  if (select count(distinct value->>'id') from jsonb_array_elements(rows))<>jsonb_array_length(rows) then raise exception 'arrangement_contract_invalid'; end if;
 end loop;
 if p_type='matching' and (coalesce(p_definition->>'cardinality','') not in ('one_to_one','many_to_one')
 or (p_definition->>'cardinality'='one_to_one' and jsonb_array_length(p_definition->'targets')<jsonb_array_length(p_definition->'sources')))
 then raise exception 'arrangement_contract_invalid'; end if;
end;
$function$;

ALTER FUNCTION "private"."validate_arrangement_definition"(p_type text, p_definition jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_arrangement_key(p_type text, p_definition jsonb, p_key jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare sequence jsonb; part text;
begin
 perform private.validate_arrangement_definition(p_type,p_definition);
 part:=case when p_type='matching' then 'pairs' else 'acceptedSequences' end;
 if jsonb_typeof(p_key) is distinct from 'object' then raise exception 'arrangement_contract_invalid'; end if;
 if (select count(*) from jsonb_object_keys(p_key))<>2 or not (p_key ?& array['schemaVersion',part])
 or p_key->>'schemaVersion' is distinct from p_definition->>'schemaVersion' then raise exception 'arrangement_contract_invalid'; end if;
 if p_type='matching' then
  perform private.validate_arrangement_response(p_type,p_definition,p_key);
  if exists(select 1 from jsonb_each(p_key->'pairs') where value='""'::jsonb) then raise exception 'arrangement_contract_invalid'; end if;
 else
  if jsonb_typeof(p_key->'acceptedSequences') is distinct from 'array' then raise exception 'arrangement_contract_invalid'; end if;
  if jsonb_array_length(p_key->'acceptedSequences') not between 1 and 20 then raise exception 'arrangement_contract_invalid'; end if;
  for sequence in select value from jsonb_array_elements(p_key->'acceptedSequences') loop
   perform private.validate_arrangement_response(p_type,p_definition,jsonb_build_object('schemaVersion',p_key->'schemaVersion','sequence',sequence));
   if sequence ? '' then raise exception 'arrangement_contract_invalid'; end if;
  end loop;
  if (select count(distinct value) from jsonb_array_elements(p_key->'acceptedSequences'))<>jsonb_array_length(p_key->'acceptedSequences') then raise exception 'arrangement_contract_invalid'; end if;
 end if;
exception when raise_exception then raise exception 'arrangement_contract_invalid';
end;
$function$;

ALTER FUNCTION "private"."validate_arrangement_key"(p_type text, p_definition jsonb, p_key jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_arrangement_response(p_type text, p_definition jsonb, p_response jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare part text; ids jsonb; vals jsonb; source jsonb; val jsonb; n integer;
begin
 perform private.validate_arrangement_definition(p_type,p_definition);
 part:=case when p_type='matching' then 'pairs' else 'sequence' end;
 if jsonb_typeof(p_response) is distinct from 'object' then raise exception 'arrangement_response_invalid'; end if;
 if (select count(*) from jsonb_object_keys(p_response))<>2 or not (p_response ?& array['schemaVersion',part])
 or p_response->>'schemaVersion' is distinct from p_definition->>'schemaVersion' then raise exception 'arrangement_response_invalid'; end if;
 if p_type='matching' then
  if jsonb_typeof(p_response->'pairs') is distinct from 'object' then raise exception 'arrangement_response_invalid'; end if;
  if (select count(*) from jsonb_object_keys(p_response->'pairs'))<>jsonb_array_length(p_definition->'sources') then raise exception 'arrangement_response_invalid'; end if;
  for source in select value from jsonb_array_elements(p_definition->'sources') loop
   if not (p_response->'pairs' ? (source->>'id')) then raise exception 'arrangement_response_invalid'; end if;
  end loop;
  select jsonb_agg(value) into vals from jsonb_each(p_response->'pairs');
  select jsonb_agg(value->'id') into ids from jsonb_array_elements(p_definition->'targets');
 else
  if jsonb_typeof(p_response->'sequence') is distinct from 'array' then raise exception 'arrangement_response_invalid'; end if;
  if jsonb_array_length(p_response->'sequence')<>jsonb_array_length(p_definition->'segments') then raise exception 'arrangement_response_invalid'; end if;
  vals:=p_response->'sequence';
  select jsonb_agg(value->'id') into ids from jsonb_array_elements(p_definition->'segments');
 end if;
 for val in select value from jsonb_array_elements(vals) loop
  if jsonb_typeof(val)<>'string' or (val<>'""'::jsonb and not (ids ? (val#>>'{}'))) then raise exception 'arrangement_response_invalid'; end if;
 end loop;
 if p_type='ordering' or p_definition->>'cardinality'='one_to_one' then
  select count(*)-count(distinct value) into n from jsonb_array_elements(vals) where value<>'""'::jsonb;
  if n<>0 then raise exception 'arrangement_response_invalid'; end if;
 end if;
end;
$function$;

ALTER FUNCTION "private"."validate_arrangement_response"(p_type text, p_definition jsonb, p_response jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_assessed_audio_policy(p_policy jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a jsonb:=p_policy->'audioPlayback';
begin
 if p_policy->>'schemaVersion' is distinct from 'haiedu-assessment-policy-v4'
 or p_policy->>'mode' not in ('diagnostic','mastery_check')
 or jsonb_typeof(a) is distinct from 'object' then raise exception 'audio_policy_unavailable'; end if;
 if (select count(*) from jsonb_object_keys(a))<>7
 or a->>'schemaVersion' is distinct from 'haiedu-assessed-audio-v1'
 or jsonb_typeof(a->'maximumPlays') is distinct from 'number'
 or coalesce(a->>'maximumPlays','') !~ '^([1-9]|10)$'
 or a->'playbackRate' is distinct from '1'::jsonb
 or a->'transcriptAvailable' is distinct from 'false'::jsonb
 or a->>'scope' is distinct from 'session-recording'
 or a->>'questionVisibility' is distinct from 'whole-recording'
 or a->>'interruption' is distinct from 'resume-or-unscored-v1'
 then raise exception 'audio_policy_invalid'; end if;
 return a;
end;
$function$;

ALTER FUNCTION "private"."validate_assessed_audio_policy"(p_policy jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_assessment_form_item_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$ declare v_pool_id uuid; v_form_status text; begin select pool_id,status into v_pool_id,v_form_status from public.assessment_forms where id=new.form_id; if v_pool_id is null then raise exception 'assessment_form_not_found'; end if; if v_form_status='draft' then if not exists(select 1 from public.assessment_pool_items api where api.pool_id=v_pool_id and api.item_id=new.item_id and (api.enabled=true or (api.enabled=false and api.metadata->>'phase'='11D' and coalesce((api.metadata->>'candidate')::boolean,false)=true))) then raise exception 'draft_assessment_form_item_not_staged_in_parent_pool'; end if; else if not exists(select 1 from public.assessment_pool_items api where api.pool_id=v_pool_id and api.item_id=new.item_id and api.enabled=true) then raise exception 'assessment_form_item_not_in_parent_pool'; end if; end if; return new; end; $function$;

ALTER FUNCTION "private"."validate_assessment_form_item_membership"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_assessment_policy_v1(p_blueprint_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  b public.assessment_blueprints%rowtype; r public.curriculum_releases%rowtype;
  pool public.assessment_pools%rowtype; model public.learning_model_configurations%rowtype;
  lifecycle public.academic_mastery_policy_versions%rowtype;
  policy jsonb; entry record; form record; total numeric; n integer; code text;
begin
  select * into b from public.assessment_blueprints where id=p_blueprint_id for share;
  if not found or b.status not in ('pilot','production') then
    raise exception 'assessment_policy_unavailable'; end if;
  select * into r from public.curriculum_releases where id=b.curriculum_release_id for share;
  if not found or r.status<>b.status then raise exception 'assessment_policy_unavailable'; end if;
  select unit_code_snapshot into code from public.curriculum_release_units
    where curriculum_release_id=r.id and unit_id=b.unit_id for share;
  if not found then raise exception 'assessment_policy_invalid'; end if;
  policy:=b.configuration_snapshot->'assessmentPolicy';
  if jsonb_typeof(policy) is distinct from 'object' then raise exception 'assessment_policy_unconfigured'; end if;
  if coalesce(policy->>'schemaVersion','') not in ('haiedu-assessment-policy-v1','haiedu-assessment-policy-v2','haiedu-assessment-policy-v3','haiedu-assessment-policy-v4')
    or b.purpose not in ('diagnostic','practice','mastery_check','chapter_review')
    or coalesce(length(trim(policy->>'policyKey')),0)=0
    or jsonb_typeof(policy->'policyKey') is distinct from 'string'
    or jsonb_typeof(policy->'version') is distinct from 'number'
    or coalesce(policy->>'version','') !~ '^[1-9][0-9]*$'
    or (policy->>'version')::numeric>9007199254740991
    or policy->>'mode' is distinct from b.purpose
    or policy->>'subjectProgramId' is distinct from r.subject_program_id::text
    or policy->>'curriculumReleaseId' is distinct from r.id::text
    or policy->>'unitId' is distinct from b.unit_id::text
    or jsonb_typeof(policy->'plannedQuestionCount') is distinct from 'number'
    or coalesce(policy->>'plannedQuestionCount','') !~ '^[1-9][0-9]*$'
    or (policy->>'plannedQuestionCount')::numeric>100
    or policy->>'scoringStrategy' is distinct from (case when policy->>'schemaVersion' in ('haiedu-assessment-policy-v3','haiedu-assessment-policy-v4') then 'normalized-item-score-v1' else 'selected-response-v1' end)
    or jsonb_typeof(policy->'hintsAllowed') is distinct from 'boolean'
    or jsonb_typeof(policy->'baselineRequired') is distinct from 'boolean'
    or jsonb_typeof(policy->'responseTypes') is distinct from 'array'
  then raise exception 'assessment_policy_invalid'; end if;
  if policy->>'schemaVersion'='haiedu-assessment-policy-v4' then perform private.validate_assessed_audio_policy(policy); end if;
  n:=(policy->>'plannedQuestionCount')::integer;
  if jsonb_array_length(policy->'responseTypes')=0 or exists (
    select 1 from jsonb_array_elements(policy->'responseTypes') x
    where x not in ('"single_choice"'::jsonb,'"true_false"'::jsonb) and not (policy->>'schemaVersion' in ('haiedu-assessment-policy-v3','haiedu-assessment-policy-v4') and x in ('"typed_fields"'::jsonb,'"matching"'::jsonb,'"ordering"'::jsonb)))
    or (select count(distinct x) from jsonb_array_elements(policy->'responseTypes') x)
      <>jsonb_array_length(policy->'responseTypes')
    or exists (select 1 from jsonb_object_keys(policy) k where k not in
      ('schemaVersion','policyKey','version','mode','subjectProgramId','curriculumReleaseId','unitId',
       'plannedQuestionCount','learningModelConfigurationId','academicMasteryPolicyId','responseTypes',
       'scoringStrategy','hintsAllowed','baselineRequired','questionCountBySkill',
       'maximumCompletedBaselines','minimumPercent','minimumCorrectBySkill')
      and not (policy->>'schemaVersion' in ('haiedu-assessment-policy-v2','haiedu-assessment-policy-v3','haiedu-assessment-policy-v4') and k in ('deliveredSkillIds','scoredSkillIds','readinessSkillIds','reportingGroups'))
      and not (policy->>'schemaVersion' in ('haiedu-assessment-policy-v3','haiedu-assessment-policy-v4') and k in ('responseCapabilities','itemWeight'))
      and not (policy->>'schemaVersion'='haiedu-assessment-policy-v4' and k='audioPlayback'))
  then raise exception 'assessment_policy_invalid'; end if;
  if policy->>'schemaVersion' in ('haiedu-assessment-policy-v3','haiedu-assessment-policy-v4') then
    if policy->'itemWeight' is distinct from '1'::jsonb or policy->'responseCapabilities' is distinct from (select coalesce(jsonb_object_agg(k,v),'{}'::jsonb) from (values ('typed_fields','haiedu-typed-fields-v1'),('matching','haiedu-matching-v1'),('ordering','haiedu-ordering-v1')) capabilities(k,v) where policy->'responseTypes' ? k) then raise exception 'assessment_policy_invalid'; end if;
  end if;
  if b.purpose in ('diagnostic','mastery_check') then
    if policy->'hintsAllowed'<>'false'::jsonb or jsonb_typeof(policy->'questionCountBySkill') is distinct from 'object'
      or policy->'questionCountBySkill'='{}'::jsonb then raise exception 'assessment_policy_invalid'; end if;
    total:=0;
    for entry in select * from jsonb_each(policy->'questionCountBySkill') loop
      if entry.key !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or jsonb_typeof(entry.value)<>'number' or entry.value::text !~ '^[1-9][0-9]*$'
        or not exists (select 1 from public.curriculum_release_skills rs
          join public.items i on i.skill_id=rs.skill_id
          join public.assessment_blueprint_items bi on bi.item_id=i.id and bi.assessment_blueprint_id=b.id
          join public.item_curriculum_scopes sc on sc.item_id=i.id and sc.is_primary
          where rs.curriculum_release_id=r.id and sc.unit_id=b.unit_id
            and sc.subject_program_id=r.subject_program_id and rs.skill_id=entry.key::uuid)
      then raise exception 'assessment_policy_skill_scope_invalid'; end if;
      total:=total+entry.value::text::numeric;
    end loop;
    if total<>n then raise exception 'assessment_policy_invalid'; end if;
  elsif policy ? 'questionCountBySkill' then raise exception 'assessment_policy_invalid'; end if;
  if b.purpose='diagnostic' then
    if policy->'maximumCompletedBaselines' is distinct from '1'::jsonb
      or policy->'baselineRequired'<>'false'::jsonb then raise exception 'assessment_policy_invalid'; end if;
  elsif policy ? 'maximumCompletedBaselines' then raise exception 'assessment_policy_invalid'; end if;
  -- Retain the accepted diagnostic-before-practice/review product rule.
  if b.purpose in ('practice','chapter_review') and policy->'baselineRequired'<>'true'::jsonb then
    raise exception 'chapter_diagnostic_policy_required'; end if;
  if b.purpose='mastery_check' then
    if jsonb_typeof(policy->'minimumPercent') is distinct from 'number'
      or (policy->>'minimumPercent')::numeric<=0 or (policy->>'minimumPercent')::numeric>100
      or jsonb_typeof(policy->'minimumCorrectBySkill') is distinct from 'object'
      or policy->'minimumCorrectBySkill'='{}'::jsonb then raise exception 'assessment_policy_invalid'; end if;
    for entry in select * from jsonb_each(policy->'minimumCorrectBySkill') loop
      if jsonb_typeof(entry.value)<>'number' or entry.value::text !~ '^(0|[1-9][0-9]*)$'
        or not (policy->'questionCountBySkill' ? entry.key)
        or entry.value::text::numeric>(policy->'questionCountBySkill'->>entry.key)::numeric
      then raise exception 'assessment_policy_invalid'; end if;
    end loop;
  elsif policy ? 'minimumPercent' or policy ? 'minimumCorrectBySkill' then raise exception 'assessment_policy_invalid'; end if;
  if policy->>'schemaVersion' in ('haiedu-assessment-policy-v2','haiedu-assessment-policy-v3','haiedu-assessment-policy-v4') then
    perform private.validate_assessment_scope_v2(policy,(select jsonb_agg(distinct i.skill_id order by i.skill_id) from public.assessment_blueprint_items bi join public.items i on i.id=bi.item_id where bi.assessment_blueprint_id=b.id));
  end if;
  if coalesce(policy->>'learningModelConfigurationId','') !~ '^[0-9a-f-]{36}$'
    or coalesce(policy->>'academicMasteryPolicyId','') !~ '^[0-9a-f-]{36}$' then raise exception 'assessment_policy_invalid'; end if;
  select * into model from public.learning_model_configurations
    where id=(policy->>'learningModelConfigurationId')::uuid for share;
  if not found or model.configuration_kind not in ('baseline','approved')
    or model.reference_curriculum_release_id is distinct from r.id
    or jsonb_typeof(model.configuration->'assessmentPolicyContracts') is distinct from 'array'
    or not (model.configuration->'assessmentPolicyContracts' @> jsonb_build_array(policy))
  then raise exception 'assessment_policy_model_incompatible'; end if;
  select * into lifecycle from public.academic_mastery_policy_versions
    where id=(policy->>'academicMasteryPolicyId')::uuid for share;
  if not found or lifecycle.status<>'active' or lifecycle.effective_from>clock_timestamp()
    or (b.purpose='chapter_review' and lifecycle.target_review_question_count<>n)
  then raise exception 'assessment_policy_lifecycle_incompatible'; end if;
  select * into pool from public.assessment_pools where id=b.assessment_pool_id for update;
  if not found or pool.status<>'active' or pool.unit_code<>code
    or pool.purpose<>(case when b.purpose='chapter_review' then 'practice' else b.purpose end)
  then raise exception 'assessment_policy_pool_invalid'; end if;
  perform 1 from public.assessment_blueprint_items bi join public.items i on i.id=bi.item_id
    where bi.assessment_blueprint_id=b.id order by i.id for share of bi,i;
  perform 1 from public.curriculum_release_skills rs join public.items i on i.skill_id=rs.skill_id
    join public.assessment_blueprint_items bi on bi.item_id=i.id and bi.assessment_blueprint_id=b.id
    join public.item_curriculum_scopes sc on sc.item_id=i.id
    where rs.curriculum_release_id=r.id order by rs.skill_id,i.id,sc.id for share of rs,sc;
  perform 1 from public.assessment_pool_items where pool_id=pool.id order by item_id for share;
  if not exists (select 1 from public.assessment_blueprint_items where assessment_blueprint_id=b.id)
    or exists (select 1 from public.assessment_blueprint_items bi
      join public.items i on i.id=bi.item_id
      where bi.assessment_blueprint_id=b.id and
       (i.status<>'published' or i.version_no<>bi.item_version_snapshot
        or not (policy->'responseTypes' ? i.item_type::text)
        or not exists (select 1 from public.assessment_pool_items pi
          where pi.pool_id=pool.id and pi.item_id=i.id and pi.enabled)
        or not exists (select 1 from public.curriculum_release_skills rs
          join public.item_curriculum_scopes sc on sc.item_id=i.id and sc.is_primary
          where rs.curriculum_release_id=r.id and sc.unit_id=b.unit_id
            and sc.subject_program_id=r.subject_program_id and rs.skill_id=i.skill_id)))
  then raise exception 'assessment_policy_item_scope_invalid'; end if;
  if (select count(*) from public.assessment_blueprint_items where assessment_blueprint_id=b.id)<n then
    raise exception 'assessment_policy_coverage_insufficient'; end if;
  if policy->>'schemaVersion' in ('haiedu-assessment-policy-v3','haiedu-assessment-policy-v4') then
    if policy->'itemWeight' is distinct from '1'::jsonb or policy->'responseCapabilities' is distinct from (select coalesce(jsonb_object_agg(k,v),'{}'::jsonb) from (values ('typed_fields','haiedu-typed-fields-v1'),('matching','haiedu-matching-v1'),('ordering','haiedu-ordering-v1')) capabilities(k,v) where policy->'responseTypes' ? k) then raise exception 'assessment_policy_invalid'; end if;
  end if;
  if b.purpose in ('diagnostic','mastery_check') then
    for entry in select * from jsonb_each_text(policy->'questionCountBySkill') loop
      if (select count(*) from public.assessment_blueprint_items bi join public.items i on i.id=bi.item_id
        where bi.assessment_blueprint_id=b.id and i.skill_id=entry.key::uuid)<entry.value::integer then
        raise exception 'assessment_policy_coverage_insufficient'; end if;
    end loop;
  end if;
  if b.purpose='diagnostic' and not exists (select 1 from public.assessment_forms f
    where f.pool_id=pool.id and f.status='active') then raise exception 'assessment_policy_forms_unavailable'; end if;
  if b.purpose='diagnostic' then
    for form in select f.id from public.assessment_forms f where f.pool_id=pool.id and f.status='active' order by f.id for update loop
      perform 1 from public.assessment_form_items where form_id=form.id order by item_id for share;
      if (select count(*) from public.assessment_form_items where form_id=form.id)<>n
        or exists (select 1 from public.assessment_form_items fi where fi.form_id=form.id
          and not exists (select 1 from public.assessment_blueprint_items bi where bi.assessment_blueprint_id=b.id and bi.item_id=fi.item_id))
      then raise exception 'assessment_policy_form_coverage_invalid'; end if;
      for entry in select * from jsonb_each_text(policy->'questionCountBySkill') loop
        if (select count(*) from public.assessment_form_items fi join public.items i on i.id=fi.item_id
          where fi.form_id=form.id and i.skill_id=entry.key::uuid)<>entry.value::integer then
          raise exception 'assessment_policy_form_coverage_invalid'; end if;
      end loop;
      if exists (select 1 from public.assessment_form_items fi join public.items i on i.id=fi.item_id
        where fi.form_id=form.id and not (policy->'questionCountBySkill' ? i.skill_id::text)) then
        raise exception 'assessment_policy_form_coverage_invalid'; end if;
    end loop;
  end if;
  for entry in select i.item_type::text response_type,i.config,k.answer from public.assessment_blueprint_items bi join public.items i on i.id=bi.item_id left join public.item_answer_keys k on k.item_id=i.id where bi.assessment_blueprint_id=b.id and i.item_type::text in ('typed_fields','matching','ordering') loop
    if entry.response_type='typed_fields' then perform private.validate_typed_key(entry.config->'responseDefinition',entry.answer);
    else perform private.validate_arrangement_key(entry.response_type,entry.config->'responseDefinition',entry.answer); end if;
  end loop;
  for entry in select i.id,i.stimulus from public.assessment_blueprint_items bi join public.items i on i.id=bi.item_id where bi.assessment_blueprint_id=b.id and i.stimulus->>'kind' in ('audio','task_set') loop
    entry.stimulus:=private.task_set_stimulus(entry.stimulus,entry.id,b.curriculum_release_id,b.unit_id);
    if entry.stimulus->>'kind'<>'audio' then continue; end if;
    if b.purpose not in ('practice','chapter_review') then perform private.validate_assessed_audio_policy(policy); end if;
    perform private.validate_audio_reference(entry.stimulus,entry.id,b.curriculum_release_id,b.unit_id);
  end loop;
  perform private.validate_task_set_blueprint(b.id);
  return policy;
end;
$function$;

ALTER FUNCTION "private"."validate_assessment_policy_v1"(p_blueprint_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_assessment_scope_v2(p_policy jsonb, p_scope jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare delivered jsonb:=p_policy->'deliveredSkillIds'; groups jsonb:=p_policy->'reportingGroups';
 g jsonb; members jsonb:='[]'; keys text[]:='{}'; scored jsonb:=p_policy->'scoredSkillIds';
begin
 if not private.assessment_skill_set_valid(delivered,p_scope) or not (delivered @> p_scope)
 or jsonb_typeof(groups) is distinct from 'array' then raise exception 'assessment_policy_skill_scope_invalid'; end if;
 if jsonb_array_length(groups)=0 then raise exception 'assessment_policy_invalid'; end if;
 if p_policy ? 'questionCountBySkill' and
 ((select count(*) from jsonb_object_keys(p_policy->'questionCountBySkill'))<>jsonb_array_length(delivered)
 or exists(select 1 from jsonb_array_elements_text(delivered) skill where not (p_policy->'questionCountBySkill' ? skill)))
 then raise exception 'assessment_policy_skill_scope_invalid'; end if;
 for g in select value from jsonb_array_elements(groups) loop
   if jsonb_typeof(g) is distinct from 'object' then raise exception 'assessment_policy_invalid'; end if;
   if (select count(*) from jsonb_object_keys(g))<>3 or exists(select 1 from jsonb_object_keys(g) k where k not in ('key','label','skillIds'))
   or jsonb_typeof(g->'key') is distinct from 'string' or coalesce(g->>'key','') !~ '^[a-z][a-z0-9_-]{0,63}$'
   or g->>'key'=any(keys) or jsonb_typeof(g->'label') is distinct from 'string'
   or coalesce(length(trim(g->>'label')),0)=0 or length(g->>'label')>200
   or not private.assessment_skill_set_valid(g->'skillIds',delivered)
   then raise exception 'assessment_policy_invalid'; end if;
   members:=members||(g->'skillIds'); keys:=array_append(keys,g->>'key');
 end loop;
 if jsonb_array_length(members)<>jsonb_array_length(delivered)
 or not private.assessment_skill_set_valid(members,delivered) then raise exception 'assessment_policy_invalid'; end if;
 if p_policy->>'mode'='mastery_check' then
   if not private.assessment_skill_set_valid(scored,delivered)
   or not private.assessment_skill_set_valid(p_policy->'readinessSkillIds',delivered)
   or exists(select 1 from jsonb_object_keys(p_policy->'minimumCorrectBySkill') k where not (scored ? k))
   or exists(select 1 from jsonb_array_elements(groups) grp where
     exists(select 1 from jsonb_array_elements_text(grp->'skillIds') s where scored ? s)
     and exists(select 1 from jsonb_array_elements_text(grp->'skillIds') s where not (scored ? s)))
   then raise exception 'assessment_policy_invalid'; end if;
 elsif p_policy ? 'scoredSkillIds' or p_policy ? 'readinessSkillIds' then raise exception 'assessment_policy_invalid'; end if;
end;
$function$;

ALTER FUNCTION "private"."validate_assessment_scope_v2"(p_policy jsonb, p_scope jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_assigned_source(p_assignment uuid, p_item uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare li public.learning_session_items%rowtype; i public.items%rowtype;
begin
 select * into strict li from public.learning_session_items where id=p_assignment and item_id=p_item;
 select * into strict i from public.items where id=p_item;
 if li.source_family_id_snapshot is distinct from private.item_source_family(i.id)
  or li.task_set_version_id::text is distinct from (case when i.stimulus->>'kind'='task_set' then i.stimulus->>'taskSetVersionId' else null end)
 then raise exception 'shared_source_assignment_changed'; end if;
end;
$function$;

ALTER FUNCTION "private"."validate_assigned_source"(p_assignment uuid, p_item uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_audio_reference(p_stimulus jsonb, p_item_id uuid, p_release_id uuid DEFAULT NULL::uuid, p_unit_id uuid DEFAULT NULL::uuid)
 RETURNS public.learning_audio_versions
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a public.learning_audio_versions%rowtype;
begin
 if jsonb_typeof(p_stimulus) is distinct from 'object' or p_stimulus->>'kind' is distinct from 'audio'
 or p_stimulus->>'schemaVersion' is distinct from 'haiedu-audio-v1'
 or (select count(*) from jsonb_object_keys(p_stimulus))<>3
 or coalesce(p_stimulus->>'audioVersionId','') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
 then raise exception 'audio_reference_invalid'; end if;
 select * into a from public.learning_audio_versions where id=(p_stimulus->>'audioVersionId')::uuid for share;
 if not found or a.revoked_at is not null then raise exception 'audio_unavailable'; end if;
 if (p_release_id is not null and a.curriculum_release_id<>p_release_id) or (p_unit_id is not null and a.unit_id<>p_unit_id)
 or not exists(select 1 from public.item_curriculum_scopes sc join public.curriculum_releases r on r.subject_program_id=sc.subject_program_id
   join public.curriculum_release_skills rs on rs.curriculum_release_id=r.id join public.items i on i.id=sc.item_id and i.skill_id=rs.skill_id
   where sc.item_id=p_item_id and sc.is_primary and r.id=a.curriculum_release_id and sc.unit_id=a.unit_id)
 then raise exception 'audio_scope_invalid'; end if;
 return a;
end;
$function$;

ALTER FUNCTION "private"."validate_audio_reference"(p_stimulus jsonb, p_item_id uuid, p_release_id uuid, p_unit_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_governed_learning_model(p_model uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare c jsonb; m jsonb; p jsonb; r jsonb; h jsonb;
begin
 select configuration into strict c from public.learning_model_configurations where id=p_model;
 m:=c->'mastery';p:=c->'practice';r:=c->'recentRecovery';h:=c->'hinting';
 if m is null or p is null or r is null or h is null
 or not (m ?& array['priorAlpha','priorBeta','minimumEvidenceCount','needsSupportBelow','secureAtOrAbove','hintedPositiveMultiplier','incorrectEvidenceHintReduction'])
 or not ((m->'difficultyWeight') ?& array['formula','difficultyMin','difficultyMax'])
 or m->'difficultyWeight' is null
 or exists(select 1 from unnest(array['priorAlpha','priorBeta','minimumEvidenceCount','needsSupportBelow','secureAtOrAbove','hintedPositiveMultiplier']) k where jsonb_typeof(m->k) is distinct from 'number')
 or exists(select 1 from unnest(array['recentWindow','minimumUniqueItems','minimumIndependentCorrect']) k where jsonb_typeof(r->k) is distinct from 'number')
 or exists(select 1 from unnest(array['difficultyMin','difficultyMax']) k where jsonb_typeof(m->'difficultyWeight'->k) is distinct from 'number')
 or m#>>'{difficultyWeight,formula}' !~ '^([0-9]+[.]?[0-9]*) [+] ([0-9]+[.]?[0-9]*)[*]difficulty$'
 or m#>>'{difficultyWeight,formula}' ~ '^0[.]?0* [+] 0[.]?0*[*]difficulty$'
 or (m->>'priorAlpha')::numeric<=0 or (m->>'priorBeta')::numeric<=0 or (m->>'minimumEvidenceCount')::integer<1
 or (m->>'needsSupportBelow')::numeric<0 or (m->>'secureAtOrAbove')::numeric>1 or (m->>'secureAtOrAbove')::numeric<=(m->>'needsSupportBelow')::numeric
 or (m->>'hintedPositiveMultiplier')::numeric<=0 or (m->>'hintedPositiveMultiplier')::numeric>1 or (m->>'incorrectEvidenceHintReduction')::boolean is distinct from false
 or (m#>>'{difficultyWeight,difficultyMin}')::integer<1 or (m#>>'{difficultyWeight,difficultyMax}')::integer<(m#>>'{difficultyWeight,difficultyMin}')::integer
 or not (r ?& array['recentWindow','minimumUniqueItems','minimumIndependentCorrect','hintFreeRequired'])
 or (r->>'recentWindow')::integer<1 or (r->>'minimumUniqueItems')::integer<1 or (r->>'minimumIndependentCorrect')::integer<1
 or (r->>'minimumIndependentCorrect')::integer>(r->>'recentWindow')::integer or (r->>'hintFreeRequired')::boolean is distinct from true
 or not (p ?& array['desiredDifficultyBands','consecutiveWrongAdjustment','exactVariantCooldownRecentDistinctVariants','selectionPolicyVersion'])
 or p->>'selectionPolicyVersion'<>'11B-v1' or jsonb_typeof(p->'desiredDifficultyBands')<>'array' or jsonb_array_length(p->'desiredDifficultyBands')<1
 or not ((p->'consecutiveWrongAdjustment') ?& array['oneWrong','twoOrMoreWrong']) or (p->>'exactVariantCooldownRecentDistinctVariants')::integer<0
 or h->'levels' is distinct from '["orient","strategy","analogous_worked_example"]'::jsonb or h->>'liveAiGeneration' is distinct from 'false'
 or h->>'postErrorHelpAllowed' is distinct from 'true' or h->>'independentConfirmationRequired' is distinct from 'true'
 or not ((c#>'{recommendation,corePolicy}') ?& array['default','insufficientEvidence','weakWithUnmetPrerequisite','secureWithNextSkill'])
 or c#>'{recommendation,corePolicy}' is null
 then raise exception 'unsupported_learning_model_contract'; end if;
 if exists(select 1 from jsonb_array_elements(p->'desiredDifficultyBands') band
   where jsonb_typeof(band) is distinct from 'object' or jsonb_typeof(band->'difficulty') is distinct from 'number'
   or not (band->>'difficulty' ~ '^[0-9]+$')
   or (band->>'difficulty')::integer not between (m#>>'{difficultyWeight,difficultyMin}')::integer and (m#>>'{difficultyWeight,difficultyMax}')::integer
   or (band ? 'masteryBelow')=(band ? 'masteryAtOrAbove')
   or jsonb_typeof(coalesce(band->'masteryBelow',band->'masteryAtOrAbove')) is distinct from 'number'
   or coalesce(band->>'masteryBelow',band->>'masteryAtOrAbove')::numeric not between 0 and 1)
 or exists(select 1 from unnest(array['oneWrong','twoOrMoreWrong']) k
   where jsonb_typeof(p->'consecutiveWrongAdjustment'->k) is distinct from 'number'
   or not (p->'consecutiveWrongAdjustment'->>k ~ '^-[0-9]+$'))
 or (p#>>'{consecutiveWrongAdjustment,twoOrMoreWrong}')::integer>(p#>>'{consecutiveWrongAdjustment,oneWrong}')::integer
 or c#>>'{recommendation,corePolicy,default}' is distinct from 'continue_current_skill'
 or c#>>'{recommendation,corePolicy,insufficientEvidence}' is distinct from 'collect_more_evidence'
 or c#>>'{recommendation,corePolicy,weakWithUnmetPrerequisite}' is distinct from 'review_prerequisite'
 or c#>>'{recommendation,corePolicy,secureWithNextSkill}' is distinct from 'advance_skill'
 then raise exception 'unsupported_learning_model_contract'; end if;
end;
$function$;

ALTER FUNCTION "private"."validate_governed_learning_model"(p_model uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_mastery_form_selection(p_blueprint_id uuid, p_policy jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare bp public.assessment_blueprints%rowtype; config jsonb; manifest jsonb; form record; entry record;
 form_ids uuid[]; form_items jsonb; forms jsonb:='[]'; previous jsonb; n integer;
begin
 select * into strict bp from public.assessment_blueprints where id=p_blueprint_id for share;
 select fb.selection_snapshot into previous from private.mastery_form_selection_bindings fb
 join public.assessment_policy_bindings pb on pb.id=fb.assessment_policy_binding_id
 where pb.assessment_blueprint_id=bp.id;
 if not (bp.configuration_snapshot ? 'masteryFormSelection') then
   if previous is not null then raise exception 'mastery_form_selection_snapshot_conflict'; end if;
   return null;
 end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'mastery_form_selection_requires_read_committed'; end if;
 config:=bp.configuration_snapshot->'masteryFormSelection';
 if bp.purpose<>'mastery_check' or jsonb_typeof(config) is distinct from 'object'
   or config->>'schemaVersion' is distinct from 'haiedu-mastery-form-selection-v1'
   or config->>'selectionStrategy' is distinct from 'ordered-unseen-whole-form-v1'
   or jsonb_typeof(config->'formIds') is distinct from 'array'
 then raise exception 'mastery_form_selection_invalid'; end if;
 if exists(select 1 from jsonb_object_keys(config) k where k not in ('schemaVersion','selectionStrategy','formIds'))
   or jsonb_array_length(config->'formIds') not between 1 and 100
   or exists(select 1 from jsonb_array_elements(config->'formIds') x where jsonb_typeof(x)<>'string'
     or trim(both '"' from x::text) !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
 then raise exception 'mastery_form_selection_invalid'; end if;
 select array_agg(value::uuid order by ord) into form_ids
 from jsonb_array_elements_text(config->'formIds') with ordinality f(value,ord);
 if (select count(distinct x) from unnest(form_ids) x)<>cardinality(form_ids)
   or cardinality(form_ids)<(select maximum_mastery_attempts from public.academic_mastery_policy_versions
      where id=(p_policy->>'academicMasteryPolicyId')::uuid)
   or not exists(select 1 from public.assessment_pools where id=bp.assessment_pool_id and is_protected)
 then raise exception 'mastery_form_selection_invalid'; end if;
 n:=(p_policy->>'plannedQuestionCount')::integer;
 -- Parent/pool locks serialize governed edits; row locks also defend against retirement/removal.
 perform 1 from public.assessment_forms where id=any(form_ids) order by id for share;
 perform 1 from public.assessment_form_items where form_id=any(form_ids) order by form_id,item_id for share;
 if (select count(*) from public.assessment_forms where id=any(form_ids) and pool_id=bp.assessment_pool_id and status='active')<>cardinality(form_ids)
   or exists(select fi.item_id from public.assessment_form_items fi where fi.form_id=any(form_ids) group by fi.item_id having count(*)>1)
 then raise exception 'mastery_form_selection_invalid'; end if;
 for form in select value::uuid id,ord from jsonb_array_elements_text(config->'formIds') with ordinality f(value,ord) order by ord loop
   if (select count(*) from public.assessment_form_items where form_id=form.id)<>n
     or exists(select 1 from public.assessment_form_items fi where fi.form_id=form.id and not exists(
       select 1 from public.assessment_blueprint_items bi join public.items i on i.id=bi.item_id
       join public.assessment_pool_items pi on pi.item_id=i.id and pi.pool_id=bp.assessment_pool_id and pi.enabled
       where bi.assessment_blueprint_id=bp.id and bi.item_id=fi.item_id and i.status='published' and i.version_no=bi.item_version_snapshot))
   then raise exception 'mastery_form_selection_invalid'; end if;
   for entry in select * from jsonb_each_text(p_policy->'questionCountBySkill') loop
     if (select count(*) from public.assessment_form_items fi join public.items i on i.id=fi.item_id
       where fi.form_id=form.id and i.skill_id=entry.key::uuid)<>entry.value::integer
     then raise exception 'mastery_form_selection_invalid'; end if;
   end loop;
   if exists(select 1 from public.assessment_form_items fi join public.items i on i.id=fi.item_id
     where fi.form_id=form.id and not (p_policy->'questionCountBySkill' ? i.skill_id::text))
   then raise exception 'mastery_form_selection_invalid'; end if;
   select jsonb_agg(jsonb_build_object('itemId',i.id,'itemVersion',bi.item_version_snapshot,'skillId',i.skill_id) order by i.id)
   into form_items from public.assessment_form_items fi join public.items i on i.id=fi.item_id
   join public.assessment_blueprint_items bi on bi.item_id=i.id and bi.assessment_blueprint_id=bp.id where fi.form_id=form.id;
   forms:=forms||jsonb_build_array(jsonb_build_object('formId',form.id,
     'formVersion',(select form_version from public.assessment_forms where id=form.id),'items',form_items));
 end loop;
 -- Protected form items cannot also be eligible for a practice/review/diagnostic pool, including staged pools.
 if exists(select 1 from public.assessment_form_items fi join public.assessment_pool_items pi on pi.item_id=fi.item_id and pi.enabled
   join public.assessment_pools p on p.id=pi.pool_id
   where fi.form_id=any(form_ids) and (p.purpose<>'mastery_check' or not p.is_protected))
 then raise exception 'mastery_form_pool_overlap'; end if;
 manifest:=jsonb_build_object('selection',config,'forms',forms);
 if previous is not null and previous is distinct from manifest then raise exception 'mastery_form_selection_snapshot_conflict'; end if;
 return manifest;
end;
$function$;

ALTER FUNCTION "private"."validate_mastery_form_selection"(p_blueprint_id uuid, p_policy jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_pilot_evidence_participant()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_student_id uuid;
  v_started_at timestamptz;
begin
  if new.reason_code in ('exact_release_completed','exact_release_noncompleted') then
    select student_id, started_at into v_student_id, v_started_at
    from public.learning_sessions
    where id = new.learning_session_id;

    if not private.pilot_participant_session_is_eligible(
      new.pilot_run_id, v_student_id, v_started_at
    ) then
      raise exception 'pilot_session_outside_authorized_participant_window';
    end if;
  end if;
  return new;
end;
$function$;

ALTER FUNCTION "private"."validate_pilot_evidence_participant"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_rendered_item_variant(p_render jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_errors text[] := array[]::text[];
  v_warnings text[] := array[]::text[];
  v_prompt text := coalesce(p_render ->> 'promptHy', '');
  v_type text := p_render ->> 'itemType';
  v_params jsonb := coalesce(p_render -> 'parameters', '{}'::jsonb);
  v_options jsonb := coalesce(p_render -> 'options', '[]'::jsonb);
  v_fingerprint text := p_render ->> 'semanticFingerprint';
  v_skill_id uuid := (p_render ->> 'skillId')::uuid;
  v_template_id uuid := (p_render ->> 'templateId')::uuid;
  v_seed text := p_render ->> 'seed';
  v_answer jsonb := p_render -> 'answer';
  v_option_count integer;
  v_unique_option_count integer;
  v_existing_same_id uuid;
begin
  select i.id into v_existing_same_id
  from public.items i
  where i.item_template_id = v_template_id
    and i.variant_key = 'seed:' || v_seed
    and i.retired_at is null
  limit 1;

  if btrim(v_prompt) = '' then v_errors := array_append(v_errors, 'empty_prompt'); end if;
  if v_prompt ~* '(\{\{\s*answer\s*\}\}|\$\{\s*answer\s*\}|\[\s*answer\s*\])' then
    v_errors := array_append(v_errors, 'answer_placeholder_leak');
  end if;
  if v_params ?| array['answer','correctAnswer','correct_answer','correctOption','correct_option'] then
    v_errors := array_append(v_errors, 'answer_present_in_public_parameters');
  end if;
  if coalesce((p_render ->> 'difficulty')::integer, 0) not between 1 and 5 then
    v_errors := array_append(v_errors, 'invalid_difficulty');
  end if;
  if v_type not in ('single_choice','true_false','numeric','quantity') then
    v_errors := array_append(v_errors, 'unsupported_item_type');
  end if;
  if v_answer is null then v_errors := array_append(v_errors, 'missing_answer'); end if;

  if v_type in ('numeric','quantity') then
    if jsonb_typeof(v_answer) <> 'number' then v_errors := array_append(v_errors, 'numeric_answer_not_number'); end if;
    if p_render ->> 'tolerance' is null then v_errors := array_append(v_errors, 'numeric_tolerance_missing'); end if;
  end if;

  if v_type = 'quantity' then
    if nullif(p_render ->> 'canonicalUnit','') is null then v_errors := array_append(v_errors, 'quantity_unit_missing'); end if;
    if jsonb_array_length(coalesce(p_render -> 'acceptedUnits','[]'::jsonb)) = 0 then v_errors := array_append(v_errors, 'accepted_units_missing'); end if;
  end if;

  if v_type = 'single_choice' then
    select count(*), count(distinct lower(btrim(x.elem ->> 'contentHy')))
      into v_option_count, v_unique_option_count
    from jsonb_array_elements(v_options) as x(elem);
    if v_option_count < 2 then v_errors := array_append(v_errors, 'insufficient_options'); end if;
    if v_option_count <> v_unique_option_count then v_errors := array_append(v_errors, 'duplicate_options'); end if;
    if not exists (
      select 1 from jsonb_array_elements(v_options) as x(elem)
      where x.elem ->> 'optionKey' = p_render ->> 'answer'
    ) then
      v_errors := array_append(v_errors, 'answer_not_in_options');
    end if;
    if exists (
      select 1 from jsonb_array_elements(v_options) as x(elem)
      where coalesce(x.elem ->> 'contentHy','') ~* '(\(\s*ճիշտ\s*\)|\bcorrect\b)'
    ) then
      v_errors := array_append(v_errors, 'option_answer_marker_leak');
    end if;
  end if;

  if nullif(v_fingerprint,'') is null then
    v_errors := array_append(v_errors, 'missing_semantic_fingerprint');
  elsif exists (
    select 1 from public.items i
    where i.skill_id = v_skill_id
      and i.variant_fingerprint = v_fingerprint
      and i.retired_at is null
      and (v_existing_same_id is null or i.id <> v_existing_same_id)
  ) then
    v_errors := array_append(v_errors, 'duplicate_effective_variant');
  end if;

  if exists (
    select 1 from public.items i
    where i.skill_id = v_skill_id
      and i.prompt_hy = v_prompt
      and i.retired_at is null
      and (v_existing_same_id is null or i.id <> v_existing_same_id)
  ) then
    v_warnings := array_append(v_warnings, 'duplicate_prompt_existing_item');
  end if;

  return jsonb_build_object(
    'valid', cardinality(v_errors) = 0,
    'errors', to_jsonb(v_errors),
    'warnings', to_jsonb(v_warnings)
  );
end;
$function$;

ALTER FUNCTION "private"."validate_rendered_item_variant"(p_render jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_sprint_11d_candidate_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare v_item record; v_pool record;
begin
  if new.enabled is not true then return new; end if;
  select i.status,i.review_status,i.retired_at,i.config into v_item from public.items i where i.id=new.item_id;
  if v_item.config->>'phase' is distinct from '11D' then return new; end if;
  select p.code,p.purpose,p.is_protected into v_pool from public.assessment_pools p where p.id=new.pool_id;
  if v_pool.code not in ('PHY7-U01-PRACTICE-BASELINE','PHY7-U01-DIAGNOSTIC-BASELINE','PHY7-U01-MASTERY-PROTECTED-A') then raise exception '11D_candidate_wrong_pool'; end if;
  if v_item.config->>'sprint11dBucket' is distinct from v_pool.purpose then raise exception '11D_candidate_purpose_mismatch'; end if;
  if coalesce((v_item.config->>'pilot_ready')::boolean,false) is not true or v_item.config->>'technicalQaStatus' is distinct from 'passed' or v_item.config->>'humanReviewStatus' is distinct from 'approved' or v_item.status<>'published'::public.content_status or v_item.review_status<>'approved' or v_item.retired_at is not null then raise exception '11D_candidate_activation_gate_not_satisfied'; end if;
  if v_pool.purpose='mastery_check' and v_pool.is_protected is not true then raise exception '11D_mastery_candidate_requires_protected_pool'; end if;
  return new;
end; $function$;

ALTER FUNCTION "private"."validate_sprint_11d_candidate_activation"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_task_set_blueprint(p_blueprint uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare bp public.assessment_blueprints%rowtype; t public.learning_task_set_versions%rowtype; m jsonb; ids uuid[]; f record;
begin
 select * into strict bp from public.assessment_blueprints where id=p_blueprint;
 for t in select distinct ts.* from public.assessment_blueprint_items bi join public.items i on i.id=bi.item_id
  join public.learning_task_set_versions ts on ts.id::text=i.stimulus->>'taskSetVersionId' where bi.assessment_blueprint_id=bp.id and i.stimulus->>'kind'='task_set' loop
  if bp.purpose='mastery_check' and not (bp.configuration_snapshot ? 'masteryFormSelection') then raise exception 'task_set_requires_registered_mastery_forms'; end if;
  if jsonb_array_length(t.members)>(bp.configuration_snapshot#>>'{assessmentPolicy,plannedQuestionCount}')::integer then raise exception 'task_set_capacity_unavailable'; end if;
  for m in select value from jsonb_array_elements(t.members) loop
   if not exists(select 1 from public.assessment_blueprint_items bi join public.items i on i.id=bi.item_id
    where bi.assessment_blueprint_id=bp.id and i.id::text=m->>'itemId' and i.skill_id::text=m->>'skillId'
    and i.version_no=(m->>'version')::integer and bi.item_version_snapshot=i.version_no
    and i.stimulus=jsonb_build_object('kind','task_set','schemaVersion','haiedu-task-set-v1','taskSetVersionId',t.id))
   then raise exception 'task_set_blueprint_incomplete'; end if;
   perform private.validate_task_set_reference(jsonb_build_object('kind','task_set','schemaVersion','haiedu-task-set-v1','taskSetVersionId',t.id),(m->>'itemId')::uuid,bp.curriculum_release_id,bp.unit_id);
  end loop;
 end loop;
 -- Validate unknown/malformed references too; a failed join is not a fallback.
 perform private.validate_task_set_reference(i.stimulus,i.id,bp.curriculum_release_id,bp.unit_id)
 from public.assessment_blueprint_items bi join public.items i on i.id=bi.item_id where bi.assessment_blueprint_id=bp.id and i.stimulus->>'kind'='task_set';
 if bp.purpose in ('diagnostic','mastery_check') then
  for f in select id from public.assessment_forms where pool_id=bp.assessment_pool_id and status='active' loop
   select array_agg(item_id) into ids from public.assessment_form_items where form_id=f.id;
   perform private.order_task_set_items(ids,'validation');
   if exists(select private.item_source_family(i.id) from public.items i where i.id=any(ids) and i.stimulus->>'kind'='task_set'
    group by private.item_source_family(i.id) having count(distinct i.stimulus->>'taskSetVersionId')>1) then raise exception 'task_set_form_source_overlap'; end if;
  end loop;
 end if;
end;
$function$;

ALTER FUNCTION "private"."validate_task_set_blueprint"(p_blueprint uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_task_set_reference(p_stimulus jsonb, p_item uuid, p_release uuid DEFAULT NULL::uuid, p_unit uuid DEFAULT NULL::uuid)
 RETURNS public.learning_task_set_versions
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.learning_task_set_versions%rowtype;
begin
 if jsonb_typeof(p_stimulus) is distinct from 'object' or p_stimulus->>'kind' is distinct from 'task_set'
  or p_stimulus->>'schemaVersion' is distinct from 'haiedu-task-set-v1' or (select count(*) from jsonb_object_keys(p_stimulus))<>3
  or coalesce(p_stimulus->>'taskSetVersionId','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
 then raise exception 'task_set_reference_invalid'; end if;
 select * into t from public.learning_task_set_versions where id=(p_stimulus->>'taskSetVersionId')::uuid for share;
 if not found or t.revoked_at is not null then raise exception 'task_set_unavailable'; end if;
 if (p_release is not null and t.curriculum_release_id<>p_release) or (p_unit is not null and t.unit_id<>p_unit)
  or not exists(select 1 from public.items i join public.item_curriculum_scopes sc on sc.item_id=i.id and sc.is_primary
   join public.curriculum_releases r on r.subject_program_id=sc.subject_program_id
   join public.curriculum_release_skills rs on rs.curriculum_release_id=r.id and rs.skill_id=i.skill_id
   where i.id=p_item and r.id=t.curriculum_release_id and sc.unit_id=t.unit_id
   and t.members @> jsonb_build_array(jsonb_build_object('itemId',i.id,'version',i.version_no,'skillId',i.skill_id)))
 then raise exception 'task_set_member_scope_invalid'; end if;
 return t;
end;
$function$;

ALTER FUNCTION "private"."validate_task_set_reference"(p_stimulus jsonb, p_item uuid, p_release uuid, p_unit uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_typed_definition(p_definition jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare f jsonb; ids text[]:='{}';
begin
 if jsonb_typeof(p_definition) is distinct from 'object' then raise exception 'typed_fields_contract_invalid'; end if;
 if (select count(*) from jsonb_object_keys(p_definition))<>4
 or not(p_definition ?& array['schemaVersion','layout','locale','fields'])
 or p_definition->>'schemaVersion' is distinct from 'haiedu-typed-fields-v1'
 or jsonb_typeof(p_definition->'locale') is distinct from 'string' or coalesce(p_definition->>'locale','') !~ '^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$' or length(p_definition->>'locale')>35
 or coalesce(p_definition->>'layout','') not in ('short_answer','gap_fill')
 or jsonb_typeof(p_definition->'fields') is distinct from 'array'
 then raise exception 'typed_fields_contract_invalid'; end if;
 if jsonb_array_length(p_definition->'fields') not between 1 and 10
 or (p_definition->>'layout'='short_answer' and jsonb_array_length(p_definition->'fields')<>1)
 then raise exception 'typed_fields_contract_invalid'; end if;
 for f in select value from jsonb_array_elements(p_definition->'fields') loop
  if jsonb_typeof(f) is distinct from 'object' then raise exception 'typed_fields_contract_invalid'; end if;
  if (select count(*) from jsonb_object_keys(f))<>3 or not(f ?& array['id','label','maxLength'])
  or jsonb_typeof(f->'id') is distinct from 'string' or coalesce(f->>'id','') !~ '^[a-z][a-z0-9_]{0,39}$' or f->>'id'=any(ids)
  or jsonb_typeof(f->'label') is distinct from 'string' or length(btrim(coalesce(f->>'label',''),E' \t\r\n'))=0 or length(f->>'label')>2000
  or jsonb_typeof(f->'maxLength') is distinct from 'number' or coalesce(f->>'maxLength','') !~ '^[1-9][0-9]*$'
  then raise exception 'typed_fields_contract_invalid'; end if;
  if (f->>'maxLength')::numeric>500 then raise exception 'typed_fields_contract_invalid'; end if;
  ids:=array_append(ids,f->>'id');
 end loop;
end;
$function$;

ALTER FUNCTION "private"."validate_typed_definition"(p_definition jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_typed_key(p_definition jsonb, p_key jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare f jsonb; k jsonb; rules jsonb; a jsonb; norm text; seen text[];
begin
 perform private.validate_typed_definition(p_definition);
 if jsonb_typeof(p_key) is distinct from 'object' then raise exception 'typed_fields_contract_invalid'; end if;
 if (select count(*) from jsonb_object_keys(p_key))<>2 or not(p_key ?& array['schemaVersion','fields'])
 or p_key->>'schemaVersion' is distinct from 'haiedu-typed-fields-v1' or jsonb_typeof(p_key->'fields') is distinct from 'object'
 then raise exception 'typed_fields_contract_invalid'; end if;
 if (select count(*) from jsonb_object_keys(p_key->'fields'))<>jsonb_array_length(p_definition->'fields')
 then raise exception 'typed_fields_contract_invalid'; end if;
 for f in select value from jsonb_array_elements(p_definition->'fields') loop
  k:=p_key->'fields'->(f->>'id'); rules:=k->'normalization';seen:='{}';
  if jsonb_typeof(k) is distinct from 'object' or jsonb_typeof(rules) is distinct from 'object' then raise exception 'typed_fields_contract_invalid'; end if;
  if (select count(*) from jsonb_object_keys(k))<>2 or not(k ?& array['accepted','normalization'])
  or (select count(*) from jsonb_object_keys(rules))<>4 or not(rules ?& array['trim','collapseWhitespace','apostrophes','caseMode'])
  or jsonb_typeof(rules->'trim') is distinct from 'boolean' or jsonb_typeof(rules->'collapseWhitespace') is distinct from 'boolean'
  or jsonb_typeof(rules->'apostrophes') is distinct from 'boolean' or coalesce(rules->>'caseMode','') not in ('sensitive','ascii-insensitive')
  or jsonb_typeof(k->'accepted') is distinct from 'array' then raise exception 'typed_fields_contract_invalid'; end if;
  if jsonb_array_length(k->'accepted') not between 1 and 20 then raise exception 'typed_fields_contract_invalid'; end if;
  for a in select value from jsonb_array_elements(k->'accepted') loop
   if jsonb_typeof(a)<>'string' or length(a#>>'{}')>(f->>'maxLength')::integer then raise exception 'typed_fields_contract_invalid'; end if;
   norm:=private.normalize_typed_text(a#>>'{}',rules);
   if length(btrim(norm,E' \t\r\n'))=0 or norm=any(seen) then raise exception 'typed_fields_contract_invalid'; end if;
   seen:=array_append(seen,norm);
  end loop;
 end loop;
end;
$function$;

ALTER FUNCTION "private"."validate_typed_key"(p_definition jsonb, p_key jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_typed_response(p_definition jsonb, p_response jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare f jsonb;
begin
 perform private.validate_typed_definition(p_definition);
 if jsonb_typeof(p_response) is distinct from 'object' then raise exception 'typed_fields_response_invalid'; end if;
 if (select count(*) from jsonb_object_keys(p_response))<>2 or not(p_response ?& array['schemaVersion','fields'])
 or p_response->>'schemaVersion' is distinct from 'haiedu-typed-fields-v1' or jsonb_typeof(p_response->'fields') is distinct from 'object'
 then raise exception 'typed_fields_response_invalid'; end if;
 if (select count(*) from jsonb_object_keys(p_response->'fields'))<>jsonb_array_length(p_definition->'fields') then raise exception 'typed_fields_response_invalid'; end if;
 for f in select value from jsonb_array_elements(p_definition->'fields') loop
  if jsonb_typeof(p_response->'fields'->(f->>'id')) is distinct from 'string'
  or length(p_response->'fields'->>(f->>'id'))>(f->>'maxLength')::integer then raise exception 'typed_fields_response_invalid'; end if;
 end loop;
end;
$function$;

ALTER FUNCTION "private"."validate_typed_response"(p_definition jsonb, p_response jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION private.validate_written_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c jsonb; d jsonb:=new.definition;
begin
 if TG_OP='UPDATE' and old.reviewed_by is not null and new.reviewed_by is null and not exists(select 1 from public.profiles where id=old.reviewed_by) and (to_jsonb(new)-'reviewed_by')=(to_jsonb(old)-'reviewed_by') then return new;end if;
 if TG_OP='UPDATE' and (old.status<>'draft' and (to_jsonb(new)-'status') is distinct from (to_jsonb(old)-'status')) then raise exception 'written_task_immutable';end if;
 if TG_OP='UPDATE' and old.status<>'draft' and new.status not in (old.status,'retired') then raise exception 'written_task_immutable';end if;
 if new.status='approved' and (TG_OP='INSERT' or old.status='draft') and (not exists(select 1 from public.profiles where id=new.reviewed_by and role::text in ('admin','content_admin') and account_status='active') or new.review_evidence->'qaPassed' is distinct from 'true'::jsonb or coalesce(length(btrim(new.review_evidence->>'reviewReference')),0)=0 or coalesce(length(btrim(new.review_evidence->>'sourceComparisonReference')),0)=0) then raise exception 'written_task_review_required';end if;
 if jsonb_typeof(d) is distinct from 'object' or d->>'schemaVersion' is distinct from 'extended-text-v1'
 or coalesce(length(btrim(d->>'title')),0) not between 1 and 200 or coalesce(length(btrim(d->>'prompt')),0) not between 1 and 8000
 or coalesce(d->>'locale','')!~ '^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$'
 or d->>'wordCountConvention' is distinct from 'unicode-whitespace-v1'
 or jsonb_typeof(d->'baselineRequired') is distinct from 'boolean'
 or jsonb_typeof(d->'assistance') is distinct from 'object'
 or jsonb_typeof(d->'source') is distinct from 'object' or d->'source'='{}'::jsonb
 or jsonb_typeof(d->'outcomes') is distinct from 'array' or jsonb_array_length(d->'outcomes')=0
 or jsonb_typeof(d->'criteria') is distinct from 'array' or jsonb_array_length(d->'criteria') not between 1 and 12
 or jsonb_typeof(d->'title') is distinct from 'string' or jsonb_typeof(d->'prompt') is distinct from 'string'
 or coalesce(d->>'minWords','')!~ '^[0-9]+$' or coalesce(d->>'maxWords','')!~ '^[1-9][0-9]*$'
 or (d->>'minWords')::integer>(d->>'maxWords')::integer or (d->>'maxWords')::integer>4000
 then raise exception 'written_task_invalid';end if;
 if (select count(distinct criterion.value->>'key') from jsonb_array_elements(d->'criteria') criterion(value))<>jsonb_array_length(d->'criteria') then raise exception 'written_task_invalid';end if;
 for c in select value from jsonb_array_elements(d->'criteria') loop
  if coalesce(c->>'key','')!~ '^[a-z][a-z0-9_]{0,39}$' or coalesce(length(btrim(c->>'label')),0) not between 1 and 160
   or jsonb_typeof(c->'descriptors') is distinct from 'array' or jsonb_array_length(c->'descriptors') not between 2 and 11
   or exists(select 1 from jsonb_array_elements(c->'descriptors') v where jsonb_typeof(v)<>'string' or length(btrim(v#>>'{}')) not between 1 and 1000)
   then raise exception 'written_task_invalid';end if;
 end loop;
 if not exists(select 1 from public.curriculum_releases r join public.units u on u.subject_program_id=r.subject_program_id where r.id=new.curriculum_release_id and u.id=new.unit_id and r.subject_program_id=new.subject_program_id) then raise exception 'written_task_scope_invalid';end if;
 return new;
end;
$function$;

ALTER FUNCTION "private"."validate_written_task"() OWNER TO postgres;

