CREATE OR REPLACE FUNCTION public.enforce_item_misconception_mapping_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_policy text;
  v_answer_key text;
  v_missing integer;
begin
  if new.item_template_id is null or new.status::text <> 'published' then
    return new;
  end if;

  select template.generation_config->>'misconceptionMappingPolicy'
  into v_policy
  from public.item_templates template
  where template.id = new.item_template_id;

  if v_policy is distinct from 'all_distractors'
     or new.item_type::text <> 'single_choice' then
    return new;
  end if;

  select answer #>> '{}'
  into v_answer_key
  from public.item_answer_keys
  where item_id = new.id;

  select count(*)
  into v_missing
  from public.item_options option_row
  where option_row.item_id = new.id
    and option_row.option_key is distinct from v_answer_key
    and not exists (
      select 1
      from public.item_misconception_mappings mapping
      where mapping.item_id = new.id
        and mapping.response_key in (option_row.option_key, '*')
    );

  if v_missing <> 0 then
    raise exception 'misconception_mapping_incomplete:%', v_missing;
  end if;

  return new;
end;
$function$;

ALTER FUNCTION "public"."enforce_item_misconception_mapping_policy"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.enforce_prospective_item_evidence_purpose()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_template_config jsonb;
  v_evidence_purpose text;
begin
  if new.item_template_id is null then
    return new;
  end if;

  select template.generation_config
  into v_template_config
  from public.item_templates template
  where template.id = new.item_template_id;

  if coalesce(v_template_config->>'authoringProfileVersion', '') <> 'haiedu-evidence-blueprint-v1' then
    return new;
  end if;

  if coalesce(new.config->>'authoringProfileVersion', '') <> 'haiedu-evidence-blueprint-v1' then
    raise exception 'prospective_authoring_profile_missing:%', coalesce(new.code, new.id::text)
      using errcode = '23514';
  end if;

  v_evidence_purpose := coalesce(new.config->>'evidencePurpose', '');
  if v_evidence_purpose not in (
    'core_understanding',
    'application',
    'misconception_diagnosis',
    'transfer_reasoning'
  ) then
    raise exception 'prospective_evidence_purpose_invalid:%:%', coalesce(new.code, new.id::text), v_evidence_purpose
      using errcode = '23514';
  end if;

  return new;
end;
$function$;

ALTER FUNCTION "public"."enforce_prospective_item_evidence_purpose"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.enforce_published_mapping_mutation_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_item_id uuid;
  v_policy text;
  v_item_type text;
  v_item_status text;
  v_answer_key text;
  v_missing integer;
begin
  if tg_op = 'DELETE' then
    v_item_id := old.item_id;
  else
    v_item_id := new.item_id;
  end if;

  select item.item_type::text,
         item.status::text,
         template.generation_config->>'misconceptionMappingPolicy'
  into v_item_type, v_item_status, v_policy
  from public.items item
  left join public.item_templates template on template.id = item.item_template_id
  where item.id = v_item_id;

  if v_item_status is distinct from 'published'
     or v_item_type is distinct from 'single_choice'
     or v_policy is distinct from 'all_distractors' then
    if tg_op = 'DELETE' then return old; else return new; end if;
  end if;

  select answer #>> '{}'
  into v_answer_key
  from public.item_answer_keys
  where item_id = v_item_id;

  select count(*)
  into v_missing
  from public.item_options option_row
  where option_row.item_id = v_item_id
    and option_row.option_key is distinct from v_answer_key
    and not exists (
      select 1
      from public.item_misconception_mappings mapping
      where mapping.item_id = v_item_id
        and mapping.response_key in (option_row.option_key, '*')
    );

  if v_missing <> 0 then
    raise exception 'published_misconception_mapping_incomplete:%', v_missing;
  end if;

  if tg_op = 'DELETE' then return old; else return new; end if;
end;
$function$;

ALTER FUNCTION "public"."enforce_published_mapping_mutation_policy"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.erase_student_data(p_student_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j public.teacher_task_erasure_jobs%rowtype; inv jsonb; rid uuid;
begin
 -- Match progress/finish: request -> job -> profile. The legacy profile FK
 -- cascade also updates the request; reversing these locks can deadlock.
 select request_id into rid from public.teacher_task_erasure_jobs where target_id=p_student_id;
 if rid is null then raise exception 'task_privacy_prepare_required';end if;
 perform 1 from public.account_deletion_requests where id=rid for update;
 select * into j from public.teacher_task_erasure_jobs where request_id=rid and target_id=p_student_id for update;
 if not found then raise exception 'task_privacy_prepare_required';end if;
 if j.phase='profile_erased' then return j.inventory||j.legacy_inventory;end if;
 if j.phase<>'data_erased' or exists(select 1 from public.teacher_task_storage_deletions where request_id=j.request_id and deleted_at is null) then raise exception 'task_privacy_files_pending';end if;
 inv:=private.erase_student_data_legacy(p_student_id);
 update public.teacher_task_erasure_jobs set phase='profile_erased',legacy_inventory=inv where request_id=j.request_id;
 return j.inventory||inv;
end;$function$;

ALTER FUNCTION "public"."erase_student_data"(p_student_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.finalize_chapter_review_atomic(p_student_id uuid, p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_session public.learning_sessions%rowtype;
  v_review public.chapter_review_sessions%rowtype;
  v_state public.chapter_mastery_states%rowtype;
  v_requirement public.chapter_review_requirements%rowtype;
  v_next_state text;
begin
  select * into v_session from public.learning_sessions
  where id=p_session_id and student_id=p_student_id and mode='chapter_review' for update;
  if not found then raise exception 'chapter_review_session_not_found'; end if;
  if v_session.status<>'completed' or v_session.answered_count<v_session.planned_item_count then
    raise exception 'chapter_review_not_complete';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    p_student_id::text || '|' || v_session.curriculum_release_id::text || '|' || v_session.unit_code,0
  ));

  select * into v_review from public.chapter_review_sessions
  where learning_session_id=p_session_id for update;
  if not found then raise exception 'chapter_review_record_not_found'; end if;
  select * into v_state from public.chapter_mastery_states where id=v_review.chapter_mastery_state_id for update;

  if v_review.status='completed' then
    return jsonb_build_object(
      'reviewSessionId',v_review.id,'qualifying',v_review.qualifying,
      'lifecycleState',v_state.lifecycle_state,'idempotent',true
    );
  end if;

  if v_review.review_requirement_id is not null then
    select * into v_requirement from public.chapter_review_requirements
    where id=v_review.review_requirement_id for update;
    if v_requirement.status<>'required' then raise exception 'chapter_review_requirement_not_open'; end if;

    v_next_state:=case
      when v_requirement.required_after_attempt=1 and v_state.lifecycle_state='review_required_attempt_2'
        then 'mastery_retry_2_ready'
      when v_requirement.required_after_attempt=2 and v_state.lifecycle_state='review_required_attempt_3'
        then 'mastery_retry_3_ready'
      else null
    end;
    if v_next_state is null then raise exception 'chapter_review_transition_invalid'; end if;

    update public.chapter_review_sessions
    set status='completed',qualifying=true,completed_at=coalesce(v_session.completed_at,now())
    where id=v_review.id;
    update public.chapter_review_requirements
    set status='satisfied',qualifying_review_session_id=v_review.id,
        satisfied_at=coalesce(v_session.completed_at,now())
    where id=v_requirement.id;
    update public.chapter_mastery_states set lifecycle_state=v_next_state,updated_at=now()
    where id=v_state.id;
  else
    v_next_state:=v_state.lifecycle_state;
    update public.chapter_review_sessions
    set status='completed',qualifying=false,completed_at=coalesce(v_session.completed_at,now())
    where id=v_review.id;
  end if;

  return jsonb_build_object(
    'reviewSessionId',v_review.id,'qualifying',v_review.review_requirement_id is not null,
    'lifecycleState',v_next_state,'idempotent',false
  );
end;
$function$;

ALTER FUNCTION "public"."finalize_chapter_review_atomic"(p_student_id uuid, p_session_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.finalize_mastery_check_atomic(p_student_id uuid, p_session_id uuid, p_passed boolean, p_score_percent numeric, p_result_metadata jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_session public.learning_sessions%rowtype;
  v_attempt public.mastery_check_attempts%rowtype;
  v_state public.chapter_mastery_states%rowtype;
  v_policy public.academic_mastery_policy_versions%rowtype;
  v_result text;
  v_next_state text;
  v_expected_percent numeric;
  v_requirement_id uuid;
  v_assessment_policy jsonb; v_reporting jsonb;
begin
  select * into v_session from public.learning_sessions
  where id=p_session_id and student_id=p_student_id and mode='mastery_check' for update;
  if not found then raise exception 'mastery_session_not_found'; end if;
  if v_session.status<>'completed' then raise exception 'mastery_session_not_completed'; end if;

  perform pg_advisory_xact_lock(hashtextextended(
    p_student_id::text || '|' || v_session.curriculum_release_id::text || '|' || v_session.unit_code,0
  ));

  select * into v_attempt from public.mastery_check_attempts where learning_session_id=p_session_id for update;
  if not found then raise exception 'mastery_attempt_not_found'; end if;
  select * into v_state from public.chapter_mastery_states where id=v_attempt.chapter_mastery_state_id for update;
  select * into v_policy from public.academic_mastery_policy_versions where id=v_attempt.academic_mastery_policy_id;

  if v_attempt.status='completed' then
    return jsonb_build_object(
      'attemptNumber',v_attempt.attempt_number,'result',v_attempt.result,
      'lifecycleState',v_state.lifecycle_state,'idempotent',true
    );
  end if;
  if v_attempt.attempt_number<>v_state.attempts_used+1 then raise exception 'mastery_attempt_sequence_invalid'; end if;

  v_expected_percent:=case when v_session.answered_count=0 then 0
    else round((v_session.correct_count::numeric/v_session.answered_count::numeric)*100) end;
  select policy_snapshot into v_assessment_policy from public.assessment_policy_bindings where id=v_session.assessment_policy_binding_id;
  if v_assessment_policy->>'schemaVersion' in ('haiedu-assessment-policy-v2','haiedu-assessment-policy-v3','haiedu-assessment-policy-v4') then
    if v_session.answered_count<>(v_assessment_policy->>'plannedQuestionCount')::integer then raise exception 'mastery_session_not_completed'; end if;
    select private.assessment_result_v2(v_assessment_policy,jsonb_agg(jsonb_build_object('skillId',skill_id,'correct',correct,'total',total,'earned',earned))) into v_reporting
      from (select lsi.skill_id,count(*) total,count(*) filter(where lsi.correct) correct,sum(a.score) earned from public.learning_session_items lsi join public.attempts a on a.id=lsi.attempt_id where lsi.session_id=p_session_id and lsi.answered_at is not null group by lsi.skill_id) q;
    v_expected_percent:=(v_reporting#>>'{score,percent}')::numeric;
    if p_passed is distinct from (v_reporting->>'passed')::boolean then raise exception 'mastery_result_mismatch'; end if;
    p_result_metadata:=coalesce(p_result_metadata,'{}')||jsonb_build_object('assessmentResultReporting',v_reporting);
  end if;
  if p_score_percent<>v_expected_percent then raise exception 'mastery_score_mismatch'; end if;

  v_result:=case when p_passed then 'passed' else 'failed' end;
  v_next_state:=case
    when p_passed then 'mastery_passed'
    when v_attempt.attempt_number=1 then 'review_required_attempt_2'
    when v_attempt.attempt_number=2 then 'review_required_attempt_3'
    when v_attempt.attempt_number=v_policy.maximum_mastery_attempts then 'mastery_failed_final'
    else null
  end;
  if v_next_state is null then raise exception 'invalid_mastery_transition'; end if;

  update public.learning_sessions
  set assessment_result=v_result,score_percent=p_score_percent,
      metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_result_metadata,'{}'::jsonb),updated_at=now()
  where id=p_session_id;
  update public.mastery_check_attempts
  set result=v_result,score_percent=p_score_percent,status='completed',completed_at=now()
  where id=v_attempt.id;
  update public.chapter_mastery_states
  set lifecycle_state=v_next_state,attempts_used=v_attempt.attempt_number,
      passed_on_attempt=case when p_passed then v_attempt.attempt_number else null end,updated_at=now()
  where id=v_state.id;

  if p_passed then
    update public.chapter_review_requirements
    set status='cancelled',cancelled_at=now()
    where chapter_mastery_state_id=v_state.id and status='required';
  elsif v_attempt.attempt_number in (1,2) then
    insert into public.chapter_review_requirements(
      chapter_mastery_state_id,originating_mastery_attempt_id,required_after_attempt,status
    ) values (v_state.id,v_attempt.id,v_attempt.attempt_number,'required')
    on conflict (chapter_mastery_state_id,required_after_attempt) do update
      set status='required',qualifying_review_session_id=null,satisfied_at=null,cancelled_at=null
    returning id into v_requirement_id;
  end if;

  return jsonb_build_object(
    'attemptNumber',v_attempt.attempt_number,'result',v_result,'lifecycleState',v_next_state,
    'attemptsUsed',v_attempt.attempt_number,
    'attemptsRemaining',v_policy.maximum_mastery_attempts-v_attempt.attempt_number,
    'reviewRequirementId',v_requirement_id,'idempotent',false
  );
end;
$function$;

ALTER FUNCTION "public"."finalize_mastery_check_atomic"(p_student_id uuid, p_session_id uuid, p_passed boolean, p_score_percent numeric, p_result_metadata jsonb) OWNER TO postgres;

