 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(old.id::text, 1508001)
  );

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$;

