CREATE OR REPLACE FUNCTION public.reject_student_account_acceptance_mutation_14c()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  raise exception 'student account acceptances are immutable';
end;
$function$;

ALTER FUNCTION "public"."reject_student_account_acceptance_mutation_14c"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.resolve_active_curriculum_release(p_unit_code text)
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select cr.id
  from public.curriculum_releases cr
  join public.curriculum_release_units cru on cru.curriculum_release_id = cr.id
  where cru.unit_code_snapshot = p_unit_code
    and cr.status in ('production', 'pilot')
  order by case cr.status when 'production' then 1 else 2 end, cr.release_number desc
  limit 1
$function$;

ALTER FUNCTION "public"."resolve_active_curriculum_release"(p_unit_code text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.resolve_remediation_event_guide_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.guide_source_id is null then
    return new;
  end if;

  select v.id
    into new.guide_snapshot_id
  from public.remediation_guide_versions v
  where v.guide_scope = new.guide_scope
    and v.guide_source_id = new.guide_source_id
    and v.guide_version = coalesce(new.guide_version,1)
  limit 1;

  if new.guide_snapshot_id is null then
    raise exception
      'No immutable remediation guide snapshot for scope %, source %, version %',
      new.guide_scope, new.guide_source_id, new.guide_version;
  end if;

  return new;
end;
$function$;

ALTER FUNCTION "public"."resolve_remediation_event_guide_snapshot"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_accept_staff_invite_14b(p_recipient uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_request uuid;
begin
  select id into v_request from public.staff_account_provisioning
    where recipient_id=p_recipient and accepted_at is null and revoked_at is null
      and expires_at>now() for update;
  if v_request is null then
    raise exception 'staff_invite_unavailable' using errcode='P0001'; end if;
  return public.service_accept_staff_invite_14b(p_recipient,v_request);
end $function$;

ALTER FUNCTION "public"."service_accept_staff_invite_14b"(p_recipient uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_accept_staff_invite_14b(p_recipient uuid, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v record; v_result jsonb; v_membership uuid;
begin
  select * into v from public.staff_account_provisioning where id=p_request for update;
  if not found or v.recipient_id is distinct from p_recipient
    or v.accepted_at is not null or v.revoked_at is not null or v.expires_at<=now()
    or not exists(select 1 from public.profiles p join auth.users u on u.id=p.id
      where p.id=p_recipient and p.role='student' and p.account_status='active'
        and u.email_confirmed_at is not null) then
    raise exception 'staff_invite_unavailable' using errcode='P0001'; end if;
  if v.kind='school_admin' then
    v_result:=public.service_bootstrap_school_14b(
      v.issued_by,p_recipient,v.school_name,null);
  else
    if not private.active_school_admin_14b(v.issued_by,v.school_id)
       or not exists(select 1 from public.subjects
         where id=v.subject_id and status::text='published')
       or exists(select 1 from public.learning_sessions where student_id=p_recipient)
       or exists(select 1 from public.attempts where student_id=p_recipient)
       or exists(select 1 from public.chapter_mastery_states where student_id=p_recipient)
       or exists(select 1 from public.student_skill_mastery where student_id=p_recipient)
       or exists(select 1 from public.student_skill_mastery_by_release where student_id=p_recipient)
       or exists(select 1 from public.student_item_exposure_events where student_id=p_recipient)
       or exists(select 1 from public.remediation_events where student_id=p_recipient)
       or exists(select 1 from public.recommendation_events where student_id=p_recipient)
       or exists(select 1 from public.pilot_participants where student_id=p_recipient)
       or exists(select 1 from public.institutional_class_enrollments where student_id=p_recipient)
       or exists(select 1 from private.learning_session_item_option_orders where student_id=p_recipient)
       or exists(select 1 from public.class_memberships where student_id=p_recipient)
       or exists(select 1 from public.institutional_memberships where person_id=p_recipient)
       or exists(select 1 from public.institutional_invitations where recipient_user_id=p_recipient) then
      raise exception 'staff_invite_unavailable' using errcode='P0001'; end if;
    update public.profiles set role='teacher',updated_at=now() where id=p_recipient;
    insert into public.institutional_memberships
      (school_id,person_id,role,valid_from,status,created_by)
    values(v.school_id,p_recipient,'teacher',now(),'active',v.issued_by)
    returning id into v_membership;
    insert into public.teacher_subject_authorizations
      (school_id,teacher_membership_id,subject_id,created_by)
    values(v.school_id,v_membership,v.subject_id,v.issued_by);
    insert into public.academic_identity_events
      (table_name,row_id,operation,old_value,new_value,actor_id)
    values('profiles',p_recipient,'TEACHER_ACCOUNT_ACTIVATION',
      jsonb_build_object('role','student'),
      jsonb_build_object('role','teacher','school_id',v.school_id,'subject_id',v.subject_id),v.issued_by);
    v_result:=jsonb_build_object('schoolId',v.school_id,'membershipId',v_membership);
  end if;
  update public.staff_account_provisioning set accepted_at=now() where id=p_request;
  return v_result;
end $function$;

ALTER FUNCTION "public"."service_accept_staff_invite_14b"(p_recipient uuid, p_request uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_accept_student_invitation_14c(p_recipient uuid, p_token_digest text, p_display_name text, p_acceptance_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_name text:=regexp_replace(btrim(coalesce(p_display_name,'')),'\s+',' ','g');
  v_invitation uuid; v_result jsonb;
begin
  perform private.lock_teacher_offboarding_14b((select a.teacher_membership_id from public.institutional_invitations i join public.teacher_assignments a on a.id=i.teacher_assignment_id where i.token_digest=p_token_digest));
  if p_recipient is null or p_token_digest !~ '^[0-9a-f]{64}$'
     or length(v_name) not between 2 and 80
     or p_acceptance_version<>'student-school-access-v1' then
    raise exception 'student_invitation_unavailable' using errcode='P0001';
  end if;
  select id into v_invitation from public.institutional_invitations
    where token_digest=p_token_digest and recipient_user_id=p_recipient
      and invited_role='student' for update;
  if v_invitation is null then
    raise exception 'student_invitation_unavailable' using errcode='P0001';
  end if;
  v_result:=public.service_redeem_institutional_invitation_14b(p_recipient,p_token_digest);
  update public.profiles set display_name=v_name,updated_at=now()
    where id=p_recipient and role='student' and account_status='active';
  if not found then raise exception 'student_invitation_unavailable' using errcode='P0001'; end if;
  insert into public.student_account_acceptances
    (student_id,invitation_id,acceptance_version,display_name_at_acceptance)
  values(p_recipient,v_invitation,p_acceptance_version,v_name);
  return v_result||jsonb_build_object('displayName',v_name);
end;
$function$;

ALTER FUNCTION "public"."service_accept_student_invitation_14c"(p_recipient uuid, p_token_digest text, p_display_name text, p_acceptance_version text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_account_deletion_blockers(p_user_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_fk record;
  v_has_rows boolean;
  v_blockers text[] := '{}'::text[];
begin
  for v_fk in
    select c.conrelid::regclass as child_table, a.attname as child_column
    from pg_catalog.pg_constraint c
    join pg_catalog.pg_attribute a
      on a.attrelid = c.conrelid and a.attnum = c.conkey[1]
    where c.contype = 'f'
      and c.confrelid = 'public.profiles'::regclass
      and c.confdeltype in ('a', 'r', 'c')
      and array_length(c.conkey, 1) = 1
      and c.conrelid <> 'public.privacy_preferences'::regclass
    order by c.conrelid::regclass::text, a.attname
  loop
    execute format('select exists(select 1 from %s where %I = $1)', v_fk.child_table, v_fk.child_column)
      into v_has_rows using p_user_id;
    if v_has_rows then
      v_blockers := array_append(v_blockers, format('%s.%I', v_fk.child_table, v_fk.child_column));
    end if;
  end loop;
  return v_blockers;
end;
$function$;

ALTER FUNCTION "public"."service_account_deletion_blockers"(p_user_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_append_remediation_guide_authoring_version(p_guide_scope text, p_guide_source_id uuid, p_expected_authoring_version integer, p_lifecycle_status text, p_content_snapshot jsonb, p_reference_metadata jsonb, p_change_rationale text, p_actor_id uuid, p_actor_role text, p_actor_aal text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_profile record;
  v_latest public.remediation_guide_authoring_versions%rowtype;
  v_next integer;
  v_new_id uuid;
  v_runtime_version integer;
  v_allowed_keys text[] := '{}'::text[];
  v_metadata jsonb;
begin
  if p_guide_scope not in ('skill','template') then
    raise exception 'invalid_guide_scope';
  end if;
  if p_lifecycle_status not in ('draft','review','published','archived') then
    raise exception 'invalid_lifecycle_status';
  end if;
  if jsonb_typeof(p_content_snapshot) is distinct from 'object' then
    raise exception 'invalid_content_snapshot';
  end if;
  if jsonb_typeof(coalesce(p_reference_metadata, '{}'::jsonb)) is distinct from 'object' then
    raise exception 'invalid_reference_metadata';
  end if;
  if length(btrim(coalesce(p_change_rationale,''))) < 3 then
    raise exception 'change_rationale_required';
  end if;

  select role, account_status into v_profile
  from public.profiles
  where id = p_actor_id;

  if not found or v_profile.account_status <> 'active'
     or v_profile.role not in ('content_admin','admin')
     or v_profile.role::text <> p_actor_role then
    raise exception 'content_authoring_role_required';
  end if;

  if p_lifecycle_status in ('published','archived') and p_actor_aal <> 'aal2' then
    raise exception 'mfa_required';
  end if;

  if p_guide_scope = 'skill' then
    perform 1 from public.skill_remediation_guides
    where id = p_guide_source_id for update;
  else
    perform 1 from public.item_template_remediation_guides
    where id = p_guide_source_id for update;
  end if;
  if not found then raise exception 'guide_not_found'; end if;

  select * into v_latest
  from public.remediation_guide_authoring_versions
  where guide_scope = p_guide_scope and guide_source_id = p_guide_source_id
  order by authoring_version desc
  limit 1;

  if not found then raise exception 'authoring_history_missing'; end if;
  if v_latest.authoring_version <> p_expected_authoring_version then
    raise exception 'stale_authoring_version';
  end if;
  if p_lifecycle_status = 'review' and v_latest.lifecycle_status <> 'draft' then
    raise exception 'draft_required_before_review';
  end if;
  if p_lifecycle_status = 'published' and v_latest.lifecycle_status <> 'review' then
    raise exception 'review_required_before_publish';
  end if;
  if p_lifecycle_status = 'published'
     and (p_content_snapshot is distinct from v_latest.content_snapshot
       or coalesce(p_reference_metadata,'{}'::jsonb) is distinct from v_latest.reference_metadata) then
    raise exception 'published_content_must_match_review';
  end if;
  if p_lifecycle_status = 'archived' and v_latest.lifecycle_status <> 'published' then
    raise exception 'published_guide_required_before_archive';
  end if;

  v_next := v_latest.authoring_version + 1;
  v_metadata := coalesce(p_content_snapshot->'metadata','{}'::jsonb)
    || jsonb_build_object('referenceMetadata', coalesce(p_reference_metadata,'{}'::jsonb));

  perform set_config('app.remediation_actor_id', p_actor_id::text, true);
  perform set_config('app.remediation_actor_role', p_actor_role, true);
  perform set_config('app.remediation_change_rationale', btrim(p_change_rationale), true);
  perform set_config('app.remediation_lifecycle_action', p_lifecycle_status, true);

  if p_lifecycle_status = 'published' then
    if p_guide_scope = 'skill' then
      update public.skill_remediation_guides set
        misconception_code = btrim(coalesce(p_content_snapshot->>'misconceptionCode','')),
        title_hy = btrim(coalesce(p_content_snapshot->>'titleHy','')),
        strategy_hy = btrim(coalesce(p_content_snapshot->>'strategyHy','')),
        hint_1_hy = btrim(coalesce(p_content_snapshot->>'hint1Hy','')),
        hint_2_hy = btrim(coalesce(p_content_snapshot->>'hint2Hy','')),
        worked_example_hy = btrim(coalesce(p_content_snapshot->>'workedExampleHy','')),
        metadata = v_metadata,
        status = 'published'
      where id = p_guide_source_id
      returning guide_version into v_runtime_version;
    else
      select coalesce(array_agg(value), '{}'::text[]) into v_allowed_keys
      from jsonb_array_elements_text(coalesce(p_content_snapshot->'allowedParameterKeys','[]'::jsonb));

      update public.item_template_remediation_guides set
        trigger_error_code = nullif(btrim(coalesce(p_content_snapshot->>'triggerErrorCode','')), ''),
        title_hy = btrim(coalesce(p_content_snapshot->>'titleHy','')),
        strategy_hy = btrim(coalesce(p_content_snapshot->>'strategyHy','')),
        hint_1_hy = btrim(coalesce(p_content_snapshot->>'hint1Hy','')),
        hint_2_hy = btrim(coalesce(p_content_snapshot->>'hint2Hy','')),
        worked_example_hy = btrim(coalesce(p_content_snapshot->>'workedExampleHy','')),
        allowed_parameter_keys = v_allowed_keys,
        metadata = v_metadata,
        status = 'published'
      where id = p_guide_source_id
      returning guide_version into v_runtime_version;
    end if;
  elsif p_lifecycle_status = 'archived' then
    -- Archive uses the last reviewed/published content; it cannot smuggle a content edit.
    p_content_snapshot := v_latest.content_snapshot;
    p_reference_metadata := v_latest.reference_metadata;
    if p_guide_scope = 'skill' then
      update public.skill_remediation_guides set status = 'archived'
      where id = p_guide_source_id
      returning guide_version into v_runtime_version;
    else
      update public.item_template_remediation_guides set status = 'archived'
      where id = p_guide_source_id
      returning guide_version into v_runtime_version;
    end if;
  end if;

  insert into public.remediation_guide_authoring_versions (
    guide_scope, guide_source_id, authoring_version, lifecycle_status,
    content_snapshot, reference_metadata, change_rationale,
    actor_id, actor_role, actor_aal, parent_version_id,
    published_runtime_version
  ) values (
    p_guide_scope, p_guide_source_id, v_next, p_lifecycle_status,
    p_content_snapshot, coalesce(p_reference_metadata,'{}'::jsonb), btrim(p_change_rationale),
    p_actor_id, p_actor_role, p_actor_aal, v_latest.id,
    case when p_lifecycle_status in ('published','archived') then v_runtime_version else null end
  ) returning id into v_new_id;

  return jsonb_build_object(
    'id', v_new_id,
    'guideScope', p_guide_scope,
    'guideSourceId', p_guide_source_id,
    'authoringVersion', v_next,
    'lifecycleStatus', p_lifecycle_status,
    'runtimeVersion', v_runtime_version
  );
end;
$function$;

ALTER FUNCTION "public"."service_append_remediation_guide_authoring_version"(p_guide_scope text, p_guide_source_id uuid, p_expected_authoring_version integer, p_lifecycle_status text, p_content_snapshot jsonb, p_reference_metadata jsonb, p_change_rationale text, p_actor_id uuid, p_actor_role text, p_actor_aal text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_assessed_audio(p_actor_id uuid, p_auth_session_id uuid, p_action text, p_session_id uuid, p_session_item_id uuid, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.learning_sessions%rowtype; li public.learning_session_items%rowtype; i public.items%rowtype;
 a public.learning_audio_versions%rowtype; d public.learning_assessed_audio%rowtype; policy jsonb;
 stamp timestamptz:=clock_timestamp(); client uuid; play uuid; position integer; max_plays integer;
begin
 if not public.service_validate_active_session(p_actor_id,p_auth_session_id) then raise exception 'audio_access_denied'; end if;
 if p_action not in ('state','load','fetched','begin','progress','complete','pause','failed','unavailable','cancel')
 or jsonb_typeof(p_payload) is distinct from 'object' then raise exception 'audio_request_invalid'; end if;
 s:=private.lock_governed_learning_session(p_actor_id,p_auth_session_id,p_session_id);
 if p_action='cancel' and s.status='abandoned' and s.metadata ? 'technicalInterruption' then return jsonb_build_object('endedUnscored',true,'sourceExposureRetained',true); end if;
 if s.status<>'active' or s.mode not in ('diagnostic','mastery_check') then raise exception 'audio_mode_unavailable'; end if;
 policy:=private.assessed_audio_policy(s.id);max_plays:=(policy->>'maximumPlays')::integer;
 select * into li from public.learning_session_items where id=p_session_item_id and session_id=s.id for update;
 if not found or li.answered_at is not null or li.ordinal<>s.answered_count+1
 or not exists(select 1 from public.student_item_exposure_events where session_item_id=li.id and student_id=p_actor_id)
 then raise exception 'audio_access_denied'; end if;
 select * into strict i from public.items where id=li.item_id for share;
 -- Cancellation retains evidence even if the approved media was withdrawn.
 -- Resolve only the originally assigned source; this branch cannot deliver bytes.
 if p_action in ('failed','cancel') then
  select av.* into a from public.learning_audio_versions av where av.source_family_id=li.source_family_id_snapshot
   and av.id=coalesce((select t.stimulus->>'audioVersionId' from public.learning_task_set_versions t where t.id=li.task_set_version_id),i.stimulus->>'audioVersionId')::uuid;
  if a.id is null then raise exception 'audio_access_denied'; end if;
 else
 perform private.validate_assigned_source(li.id,i.id);
 if i.status<>'published' or not exists(select 1 from public.assessment_blueprint_items bi join public.assessment_blueprints bp on bp.id=bi.assessment_blueprint_id
 join public.assessment_pool_items pi on pi.pool_id=bp.assessment_pool_id and pi.item_id=i.id join public.assessment_pools pool on pool.id=pi.pool_id
 where bi.assessment_blueprint_id=s.assessment_blueprint_id and bi.item_id=i.id and bi.item_version_snapshot=i.version_no and pi.enabled and pool.status='active')
 then raise exception 'audio_access_denied'; end if;
 a:=private.validate_audio_reference(private.task_set_stimulus(i.stimulus,i.id),i.id,s.curriculum_release_id,s.governed_unit_id);
 end if;
 if p_action='state' then
  if p_payload<>'{}'::jsonb then raise exception 'audio_request_invalid'; end if;
  return private.assessed_audio_state(s.id,a.id);
 end if;
 insert into public.learning_assessed_audio(session_id,audio_version_id,student_id) values(s.id,a.id,p_actor_id) on conflict do nothing;
 select * into strict d from public.learning_assessed_audio where session_id=s.id and audio_version_id=a.id and student_id=p_actor_id for update;
 stamp:=clock_timestamp();
 if p_action in ('begin','progress','complete','pause') then
  if (select count(*) from jsonb_object_keys(p_payload))<>3
  or coalesce(p_payload->>'clientId','') !~ '^[0-9a-f-]{36}$' or coalesce(p_payload->>'playId','') !~ '^[0-9a-f-]{36}$'
  or jsonb_typeof(p_payload->'positionMs') is distinct from 'number' or coalesce(p_payload->>'positionMs','') !~ '^(0|[1-9][0-9]{0,5})$'
  then raise exception 'audio_request_invalid'; end if;
  client:=(p_payload->>'clientId')::uuid;play:=(p_payload->>'playId')::uuid;position:=(p_payload->>'positionMs')::integer;
 elsif p_payload<>'{}'::jsonb then raise exception 'audio_request_invalid'; end if;
 if p_action='load' then
  if d.completed_plays>=max_plays then raise exception 'audio_play_limit_reached'; end if;
  return jsonb_build_object('audioVersionId',a.id,'bucketId',a.bucket_id,'objectPath',a.object_path,'sha256',a.sha256,'mimeType',a.mime_type,'byteLength',a.byte_length,'durationMs',a.duration_ms);
 elsif p_action='fetched' then
  update public.learning_assessed_audio set fetched_at=stamp,updated_at=stamp where session_id=s.id and audio_version_id=a.id;
 elsif p_action='begin' then
  if play=d.last_completed_play_id then return private.assessed_audio_state(s.id,a.id); end if;
  if d.completed_plays>=max_plays then raise exception 'audio_play_limit_reached'; end if;
  if d.fetched_at is null then raise exception 'audio_not_loaded'; end if;
  if d.client_id is distinct from client and d.lease_until>stamp then raise exception 'audio_playback_busy'; end if;
  if d.play_id is not null and d.play_id<>play then raise exception 'audio_playback_conflict'; end if;
  if position<>d.position_ms then raise exception 'audio_playback_conflict'; end if;
  update public.learning_assessed_audio set play_id=play,client_id=client,started_at=coalesce(started_at,stamp),playback_anchor_at=stamp,playback_anchor_position_ms=position,last_event_at=stamp,lease_until=stamp+interval '5 seconds',failed_at=null,failure_origin=null,updated_at=stamp where session_id=s.id and audio_version_id=a.id;
 elsif p_action in ('progress','complete','pause') then
  if p_action='complete' and play=d.last_completed_play_id then return private.assessed_audio_state(s.id,a.id); end if;
  if d.play_id is distinct from play or d.client_id is distinct from client or d.lease_until is null or d.lease_until<stamp then raise exception 'audio_playback_conflict'; end if;
  if position<d.position_ms or position>a.duration_ms or position-coalesce(d.playback_anchor_position_ms,d.position_ms)>extract(epoch from(stamp-coalesce(d.playback_anchor_at,d.last_event_at)))*1000+250
  then raise exception 'audio_progress_invalid'; end if;
  if p_action='complete' then
   if position<a.duration_ms-100 or d.completed_plays>=max_plays then raise exception 'audio_playback_incomplete'; end if;
   update public.learning_assessed_audio set completed_plays=completed_plays+1,last_completed_play_id=play,play_id=null,client_id=null,position_ms=0,started_at=null,playback_anchor_at=null,playback_anchor_position_ms=null,last_event_at=stamp,lease_until=null,completed_at=stamp,failed_at=null,failure_origin=null,updated_at=stamp where session_id=s.id and audio_version_id=a.id;
  else
   update public.learning_assessed_audio set position_ms=position,last_event_at=stamp,lease_until=case when p_action='pause' then null else stamp+interval '5 seconds' end,client_id=case when p_action='pause' then null else client_id end,updated_at=stamp where session_id=s.id and audio_version_id=a.id;
  end if;
 elsif p_action in ('failed','unavailable') then
  -- No completion or allowance is reset by a failed load/device report.
  update public.learning_assessed_audio set failed_at=stamp,failure_origin=case when p_action='unavailable' then 'server_media_failure' else 'client_reported' end,updated_at=stamp where session_id=s.id and audio_version_id=a.id;
 elsif p_action='cancel' then
  if d.failed_at is null then raise exception 'audio_interruption_required'; end if;
  update public.mastery_check_attempts set status='abandoned' where learning_session_id=s.id and status='active';
  update public.learning_sessions set status='abandoned',updated_at=stamp,metadata=metadata||jsonb_build_object('technicalInterruption',jsonb_build_object('schemaVersion','haiedu-audio-interruption-v1','audioVersionId',a.id,'origin',d.failure_origin,'at',stamp,'scoredAttemptCharged',false)) where id=s.id;
  return jsonb_build_object('endedUnscored',true,'sourceExposureRetained',true);
 end if;
 return private.assessed_audio_state(s.id,a.id);
end;
$function$;

ALTER FUNCTION "public"."service_assessed_audio"(p_actor_id uuid, p_auth_session_id uuid, p_action text, p_session_id uuid, p_session_item_id uuid, p_payload jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_authorize_staff_invite_14b(p_actor uuid, p_kind text, p_school uuid, p_subject uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if p_kind='school_admin' then
    return p_school is null and p_subject is null and exists(
      select 1 from public.profiles where id=p_actor and role='admin' and account_status='active');
  elsif p_kind='teacher' then
    return p_school is not null and p_subject is not null
      and private.active_school_admin_14b(p_actor,p_school)
      and exists(select 1 from public.subjects where id=p_subject and status::text='published');
  end if;
  return false;
end $function$;

ALTER FUNCTION "public"."service_authorize_staff_invite_14b"(p_actor uuid, p_kind text, p_school uuid, p_subject uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_authorize_student_invite_14c(p_actor uuid, p_school uuid, p_class uuid, p_assignment uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select exists(
    select 1
    from public.classes c
    join public.academic_years y
      on y.id=c.academic_year_id and y.school_id=c.school_id
    join public.teacher_assignments a
      on a.id=p_assignment and a.class_id=c.id and a.school_id=c.school_id
     and a.academic_year_id=c.academic_year_id
    join public.subject_programs sp on sp.id=a.subject_program_id
    join public.subjects s on s.id=sp.subject_id
    join public.institutional_memberships tm
      on tm.id=a.teacher_membership_id and tm.school_id=a.school_id
    join public.profiles p on p.id=tm.person_id
    where p.id=p_actor and p.role='teacher' and p.account_status='active'
      and c.id=p_class and c.school_id=p_school and c.is_active
      and y.status='active' and current_date between y.starts_on and y.ends_on
      and a.status='active' and a.valid_from<=now()
      and (a.valid_to is null or a.valid_to>now())
      and tm.role='teacher' and tm.status='active' and tm.valid_from<=now()
      and (tm.valid_to is null or tm.valid_to>now())
      and sp.subject_id=c.subject_id and sp.grade_id=c.grade_id
      and sp.status::text='published' and s.status::text='published'
  );
$function$;

ALTER FUNCTION "public"."service_authorize_student_invite_14c"(p_actor uuid, p_school uuid, p_class uuid, p_assignment uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_bind_assessment_policy(p_blueprint_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare policy jsonb; result uuid; skill_scope jsonb; existing public.assessment_policy_bindings%rowtype;
begin
  policy:=private.validate_assessment_policy_v1(p_blueprint_id);
  select jsonb_agg(distinct i.skill_id order by i.skill_id) into skill_scope
    from public.assessment_blueprint_items bi join public.items i on i.id=bi.item_id
    where bi.assessment_blueprint_id=p_blueprint_id;
  insert into public.assessment_policy_bindings(assessment_blueprint_id,curriculum_release_id,unit_id,
    subject_program_id,learning_model_configuration_id,academic_mastery_policy_id,policy_snapshot,skill_scope_snapshot)
  values(p_blueprint_id,(policy->>'curriculumReleaseId')::uuid,(policy->>'unitId')::uuid,
    (policy->>'subjectProgramId')::uuid,(policy->>'learningModelConfigurationId')::uuid,
    (policy->>'academicMasteryPolicyId')::uuid,policy,skill_scope)
  on conflict (assessment_blueprint_id) do nothing returning id into result;
  if result is null then
    select * into existing from public.assessment_policy_bindings where assessment_blueprint_id=p_blueprint_id;
    if existing.policy_snapshot is distinct from policy or existing.skill_scope_snapshot is distinct from skill_scope then
      raise exception 'assessment_policy_snapshot_conflict'; end if;
    result:=existing.id;
  end if;
  perform private.bind_mastery_form_selection(result);
  return result;
end;
$function$;

ALTER FUNCTION "public"."service_bind_assessment_policy"(p_blueprint_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_bootstrap_school_14b(p_actor uuid, p_first_admin uuid, p_name text, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_target record; v_school uuid; v_membership uuid; v_code text;
  v_attempt integer; v_constraint text;
begin
  if p_actor is null or p_first_admin is null or p_actor=p_first_admin
     or p_name is null or length(btrim(p_name))<3 or length(btrim(p_name))>160
     or p_code is not null
     or not exists(select 1 from public.profiles where id=p_actor
       and role='admin' and account_status='active') then
    raise exception 'school_bootstrap_unavailable' using errcode='P0001';
  end if;
  select p.id,p.role::text as role,p.account_status,u.email_confirmed_at
    into v_target from public.profiles p join auth.users u on u.id=p.id
    where p.id=p_first_admin for update of p;
  if not found or v_target.account_status is distinct from 'active'
     or v_target.email_confirmed_at is null
     or v_target.role not in ('student','school_admin') then
    raise exception 'school_bootstrap_unavailable' using errcode='P0001';
  end if;
  -- Converting a new account must not relabel a learner's historical identity.
  if v_target.role='student' then
    if exists(select 1 from public.learning_sessions where student_id=p_first_admin)
       or exists(select 1 from public.attempts where student_id=p_first_admin)
       or exists(select 1 from public.chapter_mastery_states where student_id=p_first_admin)
       or exists(select 1 from public.student_skill_mastery where student_id=p_first_admin)
       or exists(select 1 from public.student_skill_mastery_by_release where student_id=p_first_admin)
       or exists(select 1 from public.student_item_exposure_events where student_id=p_first_admin)
       or exists(select 1 from public.remediation_events where student_id=p_first_admin)
       or exists(select 1 from public.recommendation_events where student_id=p_first_admin)
       or exists(select 1 from public.pilot_participants where student_id=p_first_admin)
       or exists(select 1 from public.institutional_class_enrollments where student_id=p_first_admin)
       or exists(select 1 from private.learning_session_item_option_orders where student_id=p_first_admin)
       or exists(select 1 from public.class_memberships where student_id=p_first_admin)
       or exists(select 1 from public.institutional_memberships where person_id=p_first_admin)
       or exists(select 1 from public.institutional_invitations where recipient_user_id=p_first_admin)
    then raise exception 'school_bootstrap_unavailable' using errcode='P0001'; end if;
    update public.profiles set role='school_admin',updated_at=now() where id=p_first_admin;
  end if;
  -- A school code is an identifier, not an access credential.
  for v_attempt in 1..8 loop
    v_code := 'SCH-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,16));
    begin
      insert into public.schools(name,school_code,created_by)
        values(btrim(p_name),v_code,p_actor) returning id into v_school;
      exit;
    exception when unique_violation then
      get stacked diagnostics v_constraint = constraint_name;
      if v_constraint <> 'schools_school_code_unique' then raise; end if;
    end;
  end loop;
  if v_school is null then
    raise exception 'school_code_generation_failed' using errcode='P0001';
  end if;
  if v_target.role='student' then
    insert into public.academic_identity_events
      (table_name,row_id,operation,old_value,new_value,actor_id)
    values('profiles',p_first_admin,'SCHOOL_ADMIN_BOOTSTRAP_ROLE',
      jsonb_build_object('role','student'),
      jsonb_build_object('role','school_admin','school_id',v_school),p_actor);
  end if;
  insert into public.institutional_memberships
    (school_id,person_id,role,valid_from,status,created_by)
    values(v_school,p_first_admin,'school_admin',now(),'active',p_actor)
    returning id into v_membership;
  return jsonb_build_object('schoolId',v_school,'membershipId',v_membership,'schoolCode',v_code);
end $function$;

ALTER FUNCTION "public"."service_bootstrap_school_14b"(p_actor uuid, p_first_admin uuid, p_name text, p_code text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_claim_staff_invite_resend_14b(p_actor uuid, p_invitation uuid)
 RETURNS TABLE(recipient_id uuid, recipient_email text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v record;
begin
  select i.*,u.email::text as contact_email,u.email_confirmed_at,
         p.role::text as profile_role,p.account_status as profile_status
    into v
    from public.staff_account_provisioning i
    join auth.users u on u.id=i.recipient_id
    join public.profiles p on p.id=i.recipient_id
    where i.id=p_invitation for update of i;
  if not found or v.accepted_at is not null or v.revoked_at is not null
     or v.expires_at<=now() or v.email_confirmed_at is not null
     or v.profile_role is distinct from 'student'
     or v.profile_status is distinct from 'active'
     or not public.service_authorize_staff_invite_14b(
       p_actor,v.kind,v.school_id,v.subject_id)
     or not public.service_authorize_staff_invite_14b(
       v.issued_by,v.kind,v.school_id,v.subject_id) then
    return;
  end if;
  if v.resend_attempts>=3
     or now()<v.created_at+interval '2 minutes'
     or (v.last_resend_attempt_at is not null
         and now()<v.last_resend_attempt_at+interval '15 minutes') then
    return;
  end if;
  update public.staff_account_provisioning
    set resend_attempts=resend_attempts+1,last_resend_attempt_at=now()
    where id=p_invitation;
  insert into public.academic_identity_events
    (table_name,row_id,operation,old_value,new_value,actor_id)
  values('staff_account_provisioning',p_invitation,'RESEND_REQUESTED',
    jsonb_build_object('resend_attempts',v.resend_attempts),
    jsonb_build_object('resend_attempts',v.resend_attempts+1),p_actor);
  return query select v.recipient_id,v.contact_email;
end $function$;

ALTER FUNCTION "public"."service_claim_staff_invite_resend_14b"(p_actor uuid, p_invitation uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_create_remediation_guide_draft(p_guide_scope text, p_skill_id uuid, p_item_template_id uuid, p_specialization_code text, p_content_snapshot jsonb, p_reference_metadata jsonb, p_change_rationale text, p_actor_id uuid, p_actor_role text, p_actor_aal text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_profile record;
  v_guide_source_id uuid;
  v_authoring_id uuid;
  v_skill_id uuid;
  v_specialization_code text;
  v_allowed_keys text[] := '{}'::text[];
  v_content jsonb;
  v_metadata jsonb;
begin
  if p_guide_scope not in ('skill', 'template') then
    raise exception 'invalid_guide_scope';
  end if;
  if jsonb_typeof(p_content_snapshot) is distinct from 'object' then
    raise exception 'invalid_content_snapshot';
  end if;
  if jsonb_typeof(coalesce(p_reference_metadata, '{}'::jsonb)) is distinct from 'object' then
    raise exception 'invalid_reference_metadata';
  end if;
  if length(btrim(coalesce(p_change_rationale, ''))) < 3 then
    raise exception 'change_rationale_required';
  end if;
  if p_actor_aal not in ('aal1', 'aal2') then
    raise exception 'invalid_actor_aal';
  end if;

  select role, account_status into v_profile
  from public.profiles
  where id = p_actor_id;

  if not found or v_profile.account_status <> 'active'
     or v_profile.role not in ('content_admin', 'admin')
     or v_profile.role::text <> p_actor_role then
    raise exception 'content_authoring_role_required';
  end if;

  v_specialization_code := nullif(btrim(coalesce(p_specialization_code, '')), '');
  if v_specialization_code is not null and (
    length(v_specialization_code) > 120
    or v_specialization_code !~ '^[a-z0-9][a-z0-9_.-]*$'
  ) then
    raise exception 'invalid_specialization_code';
  end if;

  if p_guide_scope = 'skill' then
    if p_skill_id is null or p_item_template_id is not null then
      raise exception 'skill_guide_target_invalid';
    end if;
    if v_specialization_code is null then
      raise exception 'misconception_code_required';
    end if;

    perform 1 from public.skills where id = p_skill_id;
    if not found then raise exception 'skill_not_found'; end if;

    if exists (
      select 1 from public.skill_remediation_guides
      where skill_id = p_skill_id and misconception_code = v_specialization_code
    ) then
      raise exception 'guide_already_exists';
    end if;

    v_skill_id := p_skill_id;
    v_content := p_content_snapshot || jsonb_build_object(
      'skillId', p_skill_id,
      'itemTemplateId', null,
      'misconceptionCode', v_specialization_code,
      'triggerErrorCode', null,
      'allowedParameterKeys', '[]'::jsonb
    );
  else
    if p_item_template_id is null or p_skill_id is not null then
      raise exception 'template_guide_target_invalid';
    end if;

    select f.skill_id into v_skill_id
    from public.item_templates it
    join public.item_families f on f.id = it.item_family_id
    where it.id = p_item_template_id;
    if not found then raise exception 'item_template_not_found'; end if;

    if exists (
      select 1 from public.item_template_remediation_guides
      where item_template_id = p_item_template_id
        and coalesce(trigger_error_code, '__default__') = coalesce(v_specialization_code, '__default__')
    ) then
      raise exception 'guide_already_exists';
    end if;

    if jsonb_typeof(coalesce(p_content_snapshot->'allowedParameterKeys', '[]'::jsonb)) is distinct from 'array' then
      raise exception 'invalid_allowed_parameter_keys';
    end if;
    select coalesce(array_agg(value), '{}'::text[]) into v_allowed_keys
    from jsonb_array_elements_text(coalesce(p_content_snapshot->'allowedParameterKeys', '[]'::jsonb));

    v_content := p_content_snapshot || jsonb_build_object(
      'skillId', v_skill_id,
      'itemTemplateId', p_item_template_id,
      'misconceptionCode', '',
      'triggerErrorCode', v_specialization_code,
      'allowedParameterKeys', to_jsonb(v_allowed_keys)
    );
  end if;

  v_metadata := coalesce(v_content->'metadata', '{}'::jsonb)
    || jsonb_build_object('referenceMetadata', coalesce(p_reference_metadata, '{}'::jsonb));

  perform set_config('app.remediation_actor_id', p_actor_id::text, true);
  perform set_config('app.remediation_actor_role', p_actor_role, true);
  perform set_config('app.remediation_change_rationale', btrim(p_change_rationale), true);
  perform set_config('app.remediation_lifecycle_action', 'draft_created', true);

  if p_guide_scope = 'skill' then
    insert into public.skill_remediation_guides (
      skill_id, misconception_code, title_hy, strategy_hy,
      hint_1_hy, hint_2_hy, worked_example_hy, status, metadata
    ) values (
      p_skill_id,
      v_specialization_code,
      btrim(coalesce(v_content->>'titleHy', '')),
      btrim(coalesce(v_content->>'strategyHy', '')),
      btrim(coalesce(v_content->>'hint1Hy', '')),
      btrim(coalesce(v_content->>'hint2Hy', '')),
      btrim(coalesce(v_content->>'workedExampleHy', '')),
      'draft',
      v_metadata
    ) returning id into v_guide_source_id;
  else
    insert into public.item_template_remediation_guides (
      item_template_id, trigger_error_code, title_hy, strategy_hy,
      hint_1_hy, hint_2_hy, worked_example_hy, allowed_parameter_keys,
      status, metadata
    ) values (
      p_item_template_id,
      v_specialization_code,
      btrim(coalesce(v_content->>'titleHy', '')),
      btrim(coalesce(v_content->>'strategyHy', '')),
      btrim(coalesce(v_content->>'hint1Hy', '')),
      btrim(coalesce(v_content->>'hint2Hy', '')),
      btrim(coalesce(v_content->>'workedExampleHy', '')),
      v_allowed_keys,
      'draft',
      v_metadata
    ) returning id into v_guide_source_id;
  end if;

  insert into public.remediation_guide_authoring_versions (
    guide_scope, guide_source_id, authoring_version, lifecycle_status,
    content_snapshot, reference_metadata, change_rationale,
    actor_id, actor_role, actor_aal, published_runtime_version
  ) values (
    p_guide_scope, v_guide_source_id, 1, 'draft',
    v_content, coalesce(p_reference_metadata, '{}'::jsonb), btrim(p_change_rationale),
    p_actor_id, p_actor_role, p_actor_aal, null
  ) returning id into v_authoring_id;

  return jsonb_build_object(
    'id', v_authoring_id,
    'guideScope', p_guide_scope,
    'guideSourceId', v_guide_source_id,
    'authoringVersion', 1,
    'lifecycleStatus', 'draft',
    'runtimeVersion', 1
  );
end;
$function$;

ALTER FUNCTION "public"."service_create_remediation_guide_draft"(p_guide_scope text, p_skill_id uuid, p_item_template_id uuid, p_specialization_code text, p_content_snapshot jsonb, p_reference_metadata jsonb, p_change_rationale text, p_actor_id uuid, p_actor_role text, p_actor_aal text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_create_school_year_14b(p_actor uuid, p_school uuid, p_label text, p_starts date, p_ends date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id uuid; v_label text := btrim(coalesce(p_label,''));
begin
  if p_school is null or p_starts is null or p_ends is null
     or length(v_label) < 4 or length(v_label) > 32
     or p_starts > current_date or p_ends < current_date
     or p_ends <= p_starts or p_ends - p_starts > 400
     or not private.active_school_admin_14b(p_actor,p_school) then
    raise exception 'school_year_unavailable' using errcode='P0001';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('school-year:'||p_school::text,0));
  if exists(
    select 1 from public.academic_years
      where school_id=p_school and status='active'
        and daterange(starts_on,ends_on,'[]') && daterange(p_starts,p_ends,'[]')
  ) then raise exception 'school_year_overlap' using errcode='P0001'; end if;
  insert into public.academic_years
    (school_id,label,starts_on,ends_on,status,created_by)
  values (p_school,v_label,p_starts,p_ends,'active',p_actor)
  returning id into v_id;
  return v_id;
end $function$;

ALTER FUNCTION "public"."service_create_school_year_14b"(p_actor uuid, p_school uuid, p_label text, p_starts date, p_ends date) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_create_teacher_class_14b(p_actor uuid, p_membership uuid, p_year uuid, p_program uuid, p_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_member record; v_year record; v_program record; v_grant uuid;
  v_class uuid; v_name text := btrim(coalesce(p_name,''));
begin
  if p_actor is null or p_membership is null or p_year is null or p_program is null
    or length(v_name) < 2 or length(v_name) > 120
    or not exists(select 1 from public.profiles
      where id=p_actor and role='teacher' and account_status='active') then
    raise exception 'teacher_class_unavailable' using errcode='P0001';
  end if;
  select * into v_member from public.institutional_memberships
    where id=p_membership and person_id=p_actor and role='teacher'
      and status='active' and valid_from<=now()
      and (valid_to is null or valid_to>now()) for share;
  if not found then raise exception 'teacher_class_unavailable' using errcode='P0001'; end if;
  select * into v_year from public.academic_years
    where id=p_year and school_id=v_member.school_id and status='active'
      and starts_on<=current_date and ends_on>=current_date for share;
  if not found then raise exception 'school_year_unavailable' using errcode='P0001'; end if;
  select p.* into v_program from public.subject_programs p
    join public.subjects s on s.id=p.subject_id
    where p.id=p_program and p.status::text='published'
      and s.status::text='published' for share of p,s;
  if not found then raise exception 'subject_program_unavailable' using errcode='P0001'; end if;
  select id into v_grant from public.teacher_subject_authorizations
    where teacher_membership_id=v_member.id and school_id=v_member.school_id
      and subject_id=v_program.subject_id and status='active'
      and valid_from<=now() and (valid_to is null or valid_to>now()) for share;
  if v_grant is null then raise exception 'teacher_subject_unavailable' using errcode='P0001'; end if;
  insert into public.classes
    (school_id,academic_year_id,teacher_id,subject_id,grade_id,name,academic_year,join_code,is_active)
  values (v_member.school_id,v_year.id,p_actor,v_program.subject_id,
    v_program.grade_id,v_name,v_year.label,null,true)
  returning id into v_class;
  insert into public.teacher_assignments
    (school_id,academic_year_id,class_id,teacher_membership_id,subject_program_id,
     status,valid_from,valid_to,created_by)
  values (v_member.school_id,v_year.id,v_class,v_member.id,v_program.id,
    'active',now(),v_member.valid_to,p_actor);
  insert into public.academic_identity_events
    (table_name,row_id,operation,new_value,actor_id)
  values ('classes',v_class,'INSERT',
    jsonb_build_object('school_id',v_member.school_id,'academic_year_id',v_year.id,
      'subject_program_id',v_program.id),p_actor);
  return v_class;
end $function$;

ALTER FUNCTION "public"."service_create_teacher_class_14b"(p_actor uuid, p_membership uuid, p_year uuid, p_program uuid, p_name text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_end_institutional_enrollment_14b(p_actor uuid, p_enrollment uuid, p_reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_row record;
begin
  if p_reason is null or p_reason not in ('withdrawn','transfer','year_end','role_change','administrative')
    then return false; end if;
  select * into v_row from public.institutional_class_enrollments where id=p_enrollment for update;
  if not found or v_row.status <> 'active' or
     not exists(select 1 from public.profiles where id=p_actor and account_status='active') then
    return false;
  end if;
  if not exists(select 1 from public.institutional_memberships m
     where m.school_id=v_row.school_id and m.person_id=p_actor and m.role='school_admin'
       and m.status='active' and m.valid_from<=now() and (m.valid_to is null or m.valid_to>now()))
    and not exists(select 1 from public.teacher_assignments a
      join public.institutional_memberships m on m.id=a.teacher_membership_id and m.school_id=a.school_id
      where a.school_id=v_row.school_id and a.class_id=v_row.class_id
        and a.academic_year_id=v_row.academic_year_id and a.status='active'
        and a.valid_from<=now() and (a.valid_to is null or a.valid_to>now())
        and m.person_id=p_actor and m.role='teacher' and m.status='active'
        and m.valid_from<=now() and (m.valid_to is null or m.valid_to>now())) then
    return false;
  end if;
  update public.institutional_class_enrollments
    set status='ended', valid_to=greatest(now(),valid_from+interval '1 microsecond'),
        ended_by=p_actor,end_reason=p_reason where id=p_enrollment;
  return true;
end $function$;

ALTER FUNCTION "public"."service_end_institutional_enrollment_14b"(p_actor uuid, p_enrollment uuid, p_reason text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_end_institutional_membership_14b(p_actor uuid, p_membership uuid, p_reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_row record; v_preview jsonb;
begin
  if p_reason is null or p_reason not in ('withdrawn','transfer','year_end','role_change','administrative')
    then return false; end if;
  perform private.lock_teacher_offboarding_14b(p_membership);
  select * into v_row from public.institutional_memberships where id=p_membership for update;
  if not found or (v_row.status <> 'active' and not (v_row.role='teacher' and v_row.status='archived')) or v_row.person_id=p_actor or
     not private.active_school_admin_14b(p_actor,v_row.school_id)
    then return false; end if;
  if v_row.role='teacher' then
    v_preview:=public.service_offboard_school_teacher_14b(p_actor,v_row.school_id,p_membership,'preview',p_reason,null);
    perform public.service_offboard_school_teacher_14b(p_actor,v_row.school_id,p_membership,'offboard',p_reason,v_preview->>'revision');
    return true;
  end if;
  update public.institutional_class_enrollments
    set status='ended', valid_to=greatest(now(),valid_from+interval '1 microsecond'),
        ended_by=p_actor,end_reason=p_reason
    where student_membership_id=p_membership and status='active';
  update public.teacher_assignments
    set status='ended', valid_to=greatest(now(),valid_from+interval '1 microsecond'),
        ended_by=p_actor,end_reason=p_reason
    where teacher_membership_id=p_membership and status='active';
  update public.institutional_memberships
    set status='ended',valid_to=greatest(now(),valid_from+interval '1 microsecond'),
        ended_by=p_actor,end_reason=p_reason where id=p_membership;
  return true;
end $function$;

ALTER FUNCTION "public"."service_end_institutional_membership_14b"(p_actor uuid, p_membership uuid, p_reason text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_ensure_session_item_option_order(p_session_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_session_id uuid;
  v_student_id uuid;
  v_item_id uuid;
  v_item_type text;
  v_item_version integer;
  v_order text[];
  v_algorithm text;
begin
  select p.canonical_option_order,p.algorithm_version,p.item_version_no
    into v_order,v_algorithm,v_item_version
  from private.learning_session_item_option_orders p
  where p.session_item_id=p_session_item_id;

  if found then
    return jsonb_build_object(
      'canonicalOptionOrder',to_jsonb(v_order),
      'algorithmVersion',v_algorithm,
      'itemVersionNo',v_item_version
    );
  end if;

  select lsi.session_id,ls.student_id,lsi.item_id,i.item_type::text,i.version_no
    into v_session_id,v_student_id,v_item_id,v_item_type,v_item_version
  from public.learning_session_items lsi
  join public.learning_sessions ls on ls.id=lsi.session_id
  join public.items i on i.id=lsi.item_id
  where lsi.id=p_session_item_id
  for update of lsi;

  if not found then
    raise exception 'session_item_not_found';
  end if;
  if v_item_type <> 'single_choice' then
    return null;
  end if;

  select g.option_order,g.algorithm_version
    into v_order,v_algorithm
  from private.generate_mcq_option_order(v_student_id,v_item_id) g;

  insert into private.learning_session_item_option_orders(
    session_item_id,session_id,student_id,item_id,item_version_no,
    canonical_option_order,algorithm_version,created_at
  ) values (
    p_session_item_id,v_session_id,v_student_id,v_item_id,v_item_version,
    v_order,v_algorithm,clock_timestamp()
  )
  on conflict (session_item_id) do nothing;

  select p.canonical_option_order,p.algorithm_version,p.item_version_no
    into v_order,v_algorithm,v_item_version
  from private.learning_session_item_option_orders p
  where p.session_item_id=p_session_item_id;

  return jsonb_build_object(
    'canonicalOptionOrder',to_jsonb(v_order),
    'algorithmVersion',v_algorithm,
    'itemVersionNo',v_item_version
  );
end;
$function$;

ALTER FUNCTION "public"."service_ensure_session_item_option_order"(p_session_item_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_finalize_item_exposure(p_student_id uuid, p_session_id uuid, p_session_item_id uuid, p_item_id uuid, p_attempt_id uuid, p_correct boolean, p_hint_used boolean, p_response_time_ms integer, p_answered_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare v_hint_level integer;
begin
  perform public.service_record_item_exposure(p_student_id,p_session_id,p_session_item_id,p_item_id,p_answered_at);
  select coalesce(hint_level_used,0) into v_hint_level from public.learning_session_items where id=p_session_item_id and session_id=p_session_id and item_id=p_item_id;
  update public.student_item_exposure_events
  set answered_at=coalesce(answered_at,p_answered_at), attempt_id=coalesce(attempt_id,p_attempt_id), correct=p_correct,
      help_used=help_used or p_hint_used or coalesce(v_hint_level,0)>0,
      hint_level_used=greatest(hint_level_used,coalesce(v_hint_level,0)), response_time_ms=coalesce(response_time_ms,p_response_time_ms), updated_at=now()
  where student_id=p_student_id and session_item_id=p_session_item_id and item_id=p_item_id;
end;
$function$;

ALTER FUNCTION "public"."service_finalize_item_exposure"(p_student_id uuid, p_session_id uuid, p_session_item_id uuid, p_item_id uuid, p_attempt_id uuid, p_correct boolean, p_hint_used boolean, p_response_time_ms integer, p_answered_at timestamp with time zone) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_get_misconception_review(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_definition jsonb; v_mappings jsonb; v_history jsonb; v_token text;
begin
 select to_jsonb(c) into v_definition from public.misconception_review_catalog_v c where id=p_id;
 if v_definition is null then raise exception 'misconception_not_found'; end if;
 select coalesce(jsonb_agg(jsonb_build_object(
   'itemId',i.id,'itemCode',i.code,'skillId',i.skill_id,'version',i.version_no,
   'promptHy',i.prompt_hy,'itemType',i.item_type,'itemStatus',i.status,
   'reviewStatus',i.review_status,'retiredAt',i.retired_at,
   'responseKey',mm.response_key,'mappingNote',mm.mapping_note,
   'responseText',o.content_hy
 ) order by i.code,i.id,mm.response_key),'[]'::jsonb) into v_mappings
 from public.item_misconception_mappings mm join public.items i on i.id=mm.item_id
 left join public.item_options o on o.item_id=i.id and o.option_key=mm.response_key
 where mm.misconception_id=p_id;
 select coalesce(jsonb_agg(to_jsonb(e) order by e.revision_no desc),'[]'::jsonb) into v_history
 from public.misconception_review_events e where e.misconception_id=p_id;
 v_token := md5(jsonb_build_object('definition',v_definition,'mappings',v_mappings)::text);
 return jsonb_build_object('definition',v_definition,'mappings',v_mappings,'history',v_history,'expectedToken',v_token);
end;
$function$;

ALTER FUNCTION "public"."service_get_misconception_review"(p_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_get_pilot_item_analytics(p_unit_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE STRICT SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
with scope_items as (
  select distinct
    i.id,
    i.code,
    i.skill_id,
    s.code as skill_code,
    s.name_hy as skill_name_hy,
    i.version_no,
    i.status::text as lifecycle_status,
    i.review_status,
    i.retired_at,
    i.replacement_item_id,
    i.variant_key
  from public.items i
  join public.skills s on s.id=i.skill_id
  join public.item_curriculum_scopes ics on ics.item_id=i.id and ics.is_primary=true
  join public.units u on u.id=ics.unit_id
  where u.code=p_unit_code
), exposure_ranked as (
  select
    e.*,
    ls.status as session_status,
    row_number() over(partition by e.student_id,e.item_id order by e.served_at,e.id) as repeat_ordinal
  from public.student_item_exposure_events e
  join scope_items si on si.id=e.item_id
  left join public.learning_sessions ls on ls.id=e.session_id
), item_agg as (
  select
    si.id,
    si.code,
    si.skill_id,
    si.skill_code,
    si.skill_name_hy,
    si.version_no,
    si.lifecycle_status,
    si.review_status,
    si.retired_at,
    si.replacement_item_id,
    si.variant_key,
    count(er.id)::integer as exposure_count,
    count(er.id) filter(where er.answered_at is not null)::integer as answered_count,
    count(er.id) filter(where er.correct=true)::integer as correct_count,
    count(er.id) filter(where er.correct=false)::integer as incorrect_count,
    count(er.id) filter(where er.help_used=true)::integer as help_used_count,
    count(er.id) filter(where er.help_used=true and er.answered_at is not null)::integer as answered_help_used_count,
    count(er.id) filter(where er.hint_level_used>0)::integer as hint_used_count,
    count(er.id) filter(where er.repeat_ordinal>1)::integer as exact_repeat_count,
    count(er.id) filter(where er.repeat_ordinal=1 and er.answered_at is not null)::integer as first_answered_count,
    count(er.id) filter(where er.repeat_ordinal=1 and er.correct=true)::integer as first_correct_count,
    count(er.id) filter(where er.repeat_ordinal>1 and er.answered_at is not null)::integer as repeat_answered_count,
    count(er.id) filter(where er.repeat_ordinal>1 and er.correct=true)::integer as repeat_correct_count,
    count(er.id) filter(where er.answered_at is null)::integer as unanswered_count,
    count(er.id) filter(where er.answered_at is null and er.session_status='abandoned')::integer as abandoned_unanswered_count,
    count(er.id) filter(where er.answered_at is null and er.session_status='completed')::integer as completed_unanswered_count,
    count(distinct er.student_id)::integer as distinct_students,
    round(avg(er.response_time_ms) filter(where er.response_time_ms is not null))::integer as average_response_time_ms,
    round(percentile_cont(0.5) within group(order by er.response_time_ms) filter(where er.response_time_ms is not null))::integer as median_response_time_ms,
    min(er.served_at) as first_served_at,
    max(er.served_at) as last_served_at,
    count(er.id) filter(where er.purpose='practice')::integer as practice_exposures,
    count(er.id) filter(where er.purpose='diagnostic')::integer as diagnostic_exposures,
    count(er.id) filter(where er.purpose='mastery_check')::integer as mastery_exposures
  from scope_items si
  left join exposure_ranked er on er.item_id=si.id
  group by si.id,si.code,si.skill_id,si.skill_code,si.skill_name_hy,si.version_no,
           si.lifecycle_status,si.review_status,si.retired_at,si.replacement_item_id,si.variant_key
), item_rates as (
  select a.*,
    case when answered_count>0 then round(correct_count::numeric/answered_count,4) else null end as correctness_rate,
    case when answered_count>0 then round(answered_help_used_count::numeric/answered_count,4) else null end as help_use_rate,
    case when exposure_count>0 then round(exact_repeat_count::numeric/exposure_count,4) else 0 end as exact_repeat_rate,
    case when first_answered_count>0 then round(first_correct_count::numeric/first_answered_count,4) else null end as first_time_correctness_rate,
    case when repeat_answered_count>0 then round(repeat_correct_count::numeric/repeat_answered_count,4) else null end as repeat_correctness_rate
  from item_agg a
), item_payload as (
  select coalesce(jsonb_agg(jsonb_build_object(
    'itemId',id,
    'itemCode',code,
    'skillId',skill_id,
    'skillCode',skill_code,
    'skillNameHy',skill_name_hy,
    'versionNo',version_no,
    'variantKey',variant_key,
    'lifecycleStatus',lifecycle_status,
    'reviewStatus',review_status,
    'retiredAt',retired_at,
    'replacementItemId',replacement_item_id,
    'exposureCount',exposure_count,
    'answeredCount',answered_count,
    'correctCount',correct_count,
    'incorrectCount',incorrect_count,
    'correctnessRate',correctness_rate,
    'averageResponseTimeMs',average_response_time_ms,
    'medianResponseTimeMs',median_response_time_ms,
    'helpUsedCount',help_used_count,
    'answeredHelpUsedCount',answered_help_used_count,
    'helpUseRate',help_use_rate,
    'hintUsedCount',hint_used_count,
    'exactRepeatCount',exact_repeat_count,
    'exactRepeatRate',exact_repeat_rate,
    'firstTimeCorrectnessRate',first_time_correctness_rate,
    'repeatCorrectnessRate',repeat_correctness_rate,
    'unansweredCount',unanswered_count,
    'abandonedUnansweredCount',abandoned_unanswered_count,
    'completedUnansweredCount',completed_unanswered_count,
    'distinctStudents',distinct_students,
    'practiceExposures',practice_exposures,
    'diagnosticExposures',diagnostic_exposures,
    'masteryExposures',mastery_exposures,
    'firstServedAt',first_served_at,
    'lastServedAt',last_served_at,
    'flags',to_jsonb(array_remove(array[
      case when exposure_count>=10 then 'high_exposure' end,
      case when answered_count>=5 and correctness_rate>=0.95 then 'unexpectedly_easy' end,
      case when answered_count>=5 and correctness_rate<=0.35 then 'unexpectedly_hard' end,
      case when incorrect_count>=5 then 'frequently_missed' end,
      case when answered_count>=5 and help_use_rate>=0.50 then 'high_help_use' end,
      case when exposure_count>=5 and exact_repeat_rate>=0.25 then 'high_exact_repeat' end,
      case when first_answered_count>=3 and repeat_answered_count>=3 and repeat_correctness_rate-first_time_correctness_rate>=0.25 then 'possible_memorisation_signal' end,
      case when unanswered_count>=2 then 'unanswered_signal' end
    ]::text[],null))
  ) order by skill_code,code),'[]'::jsonb) as items,
  count(*) filter(where cardinality(array_remove(array[
      case when exposure_count>=10 then 'high_exposure' end,
      case when answered_count>=5 and correctness_rate>=0.95 then 'unexpectedly_easy' end,
      case when answered_count>=5 and correctness_rate<=0.35 then 'unexpectedly_hard' end,
      case when incorrect_count>=5 then 'frequently_missed' end,
      case when answered_count>=5 and help_use_rate>=0.50 then 'high_help_use' end,
      case when exposure_count>=5 and exact_repeat_rate>=0.25 then 'high_exact_repeat' end,
      case when first_answered_count>=3 and repeat_answered_count>=3 and repeat_correctness_rate-first_time_correctness_rate>=0.25 then 'possible_memorisation_signal' end,
      case when unanswered_count>=2 then 'unanswered_signal' end
    ]::text[],null))>0)::integer as flagged_item_count
  from item_rates
), integrity as (
  select
    count(er.id)::integer as exposure_count,
    count(distinct er.student_id)::integer as distinct_students,
    count(er.id) filter(where er.repeat_ordinal>1)::integer as exact_repeat_count,
    case when count(er.id)>0 then round(count(er.id) filter(where er.repeat_ordinal>1)::numeric/count(er.id),4) else 0 end as exact_repeat_rate,
    count(er.id) filter(where exists(
      select 1
      from public.assessment_pool_items api
      join public.assessment_pools p on p.id=api.pool_id
      where api.item_id=er.item_id and api.enabled=true and p.is_protected=true and p.purpose='mastery_check'
    ))::integer as protected_pool_exposure_count,
    count(er.id) filter(where er.purpose<>'mastery_check' and exists(
      select 1
      from public.assessment_pool_items api
      join public.assessment_pools p on p.id=api.pool_id
      where api.item_id=er.item_id and api.enabled=true and p.is_protected=true and p.purpose='mastery_check'
    ))::integer as protected_pool_leak_count,
    count(er.id) filter(where er.answered_at is null)::integer as unanswered_exposure_count
  from exposure_ranked er
), fallback as (
  select
    count(lsi.id)::integer as session_item_count,
    count(lsi.id) filter(where lsi.selection_reason='pool_exhausted_exact_repeat')::integer as exact_repeat_fallback_count
  from public.learning_session_items lsi
  join public.learning_sessions ls on ls.id=lsi.session_id
  where ls.unit_code=p_unit_code
), pool_counts as (
  select coalesce(jsonb_agg(jsonb_build_object(
    'poolCode',p.code,
    'purpose',p.purpose,
    'protected',p.is_protected,
    'enabledItemCount',coalesce(x.enabled_count,0)
  ) order by p.purpose),'[]'::jsonb) pools
  from public.assessment_pools p
  left join lateral (
    select count(distinct api.item_id)::integer enabled_count
    from public.assessment_pool_items api
    where api.pool_id=p.id and api.enabled=true
  ) x on true
  where p.unit_code=p_unit_code and p.status='active'
), diagnostic_usage as (
  select coalesce(jsonb_agg(jsonb_build_object(
    'formCode',form_code,
    'formVersion',form_version,
    'sessionCount',session_count
  ) order by form_code,form_version),'[]'::jsonb) forms
  from (
    select
      coalesce(ls.metadata->>'formCode','unknown') form_code,
      coalesce((ls.metadata->>'formVersion')::integer,0) form_version,
      count(*)::integer session_count
    from public.learning_sessions ls
    where ls.unit_code=p_unit_code and ls.mode='diagnostic'
    group by 1,2
  ) q
)
select jsonb_build_object(
  'unitCode',p_unit_code,
  'generatedAt',now(),
  'evidenceLabel','pilot_operational_evidence_not_validated_psychometrics',
  'thresholds',jsonb_build_object(
    'minimumAnsweredForDifficultyFlag',5,
    'unexpectedlyEasyRate',0.95,
    'unexpectedlyHardRate',0.35,
    'highHelpUseRate',0.50,
    'highExactRepeatRate',0.25,
    'possibleMemorisationRepeatLift',0.25
  ),
  'integrity',jsonb_build_object(
    'distinctStudents',integrity.distinct_students,
    'exposureCount',integrity.exposure_count,
    'exactRepeatCount',integrity.exact_repeat_count,
    'exactRepeatRate',integrity.exact_repeat_rate,
    'exactRepeatFallbackCount',fallback.exact_repeat_fallback_count,
    'sessionItemCount',fallback.session_item_count,
    'protectedPoolExposureCount',integrity.protected_pool_exposure_count,
    'protectedPoolLeakCount',integrity.protected_pool_leak_count,
    'unansweredExposureCount',integrity.unanswered_exposure_count,
    'flaggedItemCount',item_payload.flagged_item_count
  ),
  'pools',pool_counts.pools,
  'diagnosticFormUsage',diagnostic_usage.forms,
  'items',item_payload.items
)
from integrity cross join fallback cross join pool_counts cross join diagnostic_usage cross join item_payload;
$function$;

ALTER FUNCTION "public"."service_get_pilot_item_analytics"(p_unit_code text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_governed_learning_operation(p_student_id uuid, p_auth_session_id uuid, p_session_id uuid, p_action text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.learning_sessions%rowtype; li public.learning_session_items%rowtype;
  r private.learning_answer_receipts%rowtype; result jsonb; hint_state jsonb;
begin
  if p_action='help' and p_payload ? 'hintState' then
    -- Authorize before inspecting the learner's saved state. The session lock
    -- serializes help with the governed answer and serve paths.
    s:=private.lock_governed_learning_session(p_student_id,p_auth_session_id,p_session_id);
    if s.mode not in ('practice','chapter_review') then raise exception 'help_not_available_in_assessment'; end if;
    select * into li from public.learning_session_items
    where id=(p_payload->>'sessionItemId')::uuid and session_id=s.id;
    if not found then raise exception 'learning_context_unavailable'; end if;
    hint_state:=p_payload->'hintState';
    if s.status<>'active' or coalesce(li.hint_level_used,0)>=3
      or to_jsonb(coalesce(li.hint_level_used,0)) is distinct from hint_state->'level'
      or to_jsonb(li.answered_at is not null) is distinct from hint_state->'afterAnswer'
      or (li.answered_at is null and li.ordinal<>s.answered_count+1) then
      raise exception 'hint_state_conflict' using errcode='HNT01';
    end if;
  end if;
  if p_action is distinct from 'answer' then
    return private.governed_operation_before_recovery(p_student_id,p_auth_session_id,p_session_id,p_action,p_payload);
  end if;
  s:=private.lock_governed_learning_session(p_student_id,p_auth_session_id,p_session_id);
  if s.status not in ('active','completed') or
    (p_payload->>'expectedMode' is not null and s.mode<>p_payload->>'expectedMode') then raise exception 'learning_context_unavailable'; end if;
  select * into li from public.learning_session_items where id=(p_payload->>'sessionItemId')::uuid
    and session_id=s.id and item_id=(p_payload->>'itemId')::uuid for update;
  if not found then raise exception 'learning_context_unavailable'; end if;
  select * into r from private.learning_answer_receipts where session_item_id=li.id and kind='governed';
  if found then
    if r.student_id<>p_student_id or r.request is distinct from p_payload then raise exception 'answer_response_conflict'; end if;
    return private.authorized_governed_result(p_student_id,p_auth_session_id,s.institutional_class_enrollment_id,
      s.curriculum_release_id,s.governed_unit_id,r.response || jsonb_build_object('replayed',true));
  end if;
  if li.attempt_id is not null or li.answered_at is not null then raise exception 'answer_result_unavailable'; end if;
  result:=private.governed_operation_before_recovery(p_student_id,p_auth_session_id,p_session_id,p_action,p_payload);
  insert into private.learning_answer_receipts(session_item_id,kind,student_id,session_id,item_id,attempt_id,request,response)
  values(li.id,'governed',p_student_id,s.id,li.item_id,(result->>'attemptId')::uuid,p_payload,result);
  return result;
end;
$function$;

ALTER FUNCTION "public"."service_governed_learning_operation"(p_student_id uuid, p_auth_session_id uuid, p_session_id uuid, p_action text, p_payload jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_grant_teacher_subject_14b(p_actor uuid, p_teacher_membership uuid, p_subject uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_member record; v_id uuid;
begin
  select * into v_member from public.institutional_memberships
    where id=p_teacher_membership for share;
  if not found or v_member.role<>'teacher' or v_member.status<>'active'
    or v_member.valid_from>now() or (v_member.valid_to is not null and v_member.valid_to<=now())
    or not private.active_school_admin_14b(p_actor,v_member.school_id)
    or not exists(select 1 from public.subjects where id=p_subject and status::text='published') then
    raise exception 'teacher_subject_unavailable' using errcode='P0001'; end if;
  insert into public.teacher_subject_authorizations
    (school_id,teacher_membership_id,subject_id,created_by)
  values(v_member.school_id,p_teacher_membership,p_subject,p_actor)
  returning id into v_id;
  return v_id;
end $function$;

ALTER FUNCTION "public"."service_grant_teacher_subject_14b"(p_actor uuid, p_teacher_membership uuid, p_subject uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_is_registered_legacy_learning_session(p_student_id uuid, p_session_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select exists(select 1 from public.learning_sessions s join public.legacy_learning_blueprint_mappings m on m.assessment_blueprint_id=s.assessment_blueprint_id
 where s.id=p_session_id and s.student_id=p_student_id and s.assessment_policy_binding_id is null and s.curriculum_release_id=m.curriculum_release_id and s.unit_code=m.unit_code_snapshot);
$function$;

ALTER FUNCTION "public"."service_is_registered_legacy_learning_session"(p_student_id uuid, p_session_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_issue_institutional_invitation_14b(p_actor uuid, p_recipient uuid, p_school uuid, p_role text, p_class uuid, p_assignment uuid, p_token_digest text, p_expires_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_class record; v_recipient record; v_year uuid;
  v_assignment_id uuid; v_subject_program_id uuid;
  v_admin boolean:=false; v_id uuid;
begin
  perform private.lock_teacher_offboarding_14b((select teacher_membership_id from public.teacher_assignments where id=p_assignment));
  if p_actor is null or p_recipient is null or p_school is null or
     p_token_digest !~ '^[0-9a-f]{64}$' or p_role not in ('student','teacher') or
     p_expires_at<=now() or p_expires_at>now()+interval '7 days' then
    raise exception 'invitation_invalid' using errcode='P0001';
  end if;
  select role,account_status into v_recipient from public.profiles where id=p_recipient;
  if not found or v_recipient.role::text is distinct from p_role
     or v_recipient.account_status is distinct from 'active'
     or not exists(select 1 from public.profiles where id=p_actor and account_status='active') then
    raise exception 'invitation_invalid' using errcode='P0001';
  end if;

  if p_role='student' then
    if p_class is null or p_assignment is null then
      raise exception 'invitation_invalid' using errcode='P0001';
    end if;
    select c.id,c.academic_year_id,c.subject_id,c.grade_id into v_class
    from public.classes c
    join public.academic_years y
      on y.id=c.academic_year_id and y.school_id=c.school_id
    where c.id=p_class and c.school_id=p_school and c.is_active
      and y.status='active' and current_date between y.starts_on and y.ends_on;
    if not found then raise exception 'invitation_invalid' using errcode='P0001'; end if;
    v_year:=v_class.academic_year_id;

    select a.id,a.subject_program_id into v_assignment_id,v_subject_program_id
    from public.teacher_assignments a
    join public.subject_programs sp on sp.id=a.subject_program_id
    join public.institutional_memberships tm
      on tm.id=a.teacher_membership_id and tm.school_id=a.school_id
    join public.profiles p on p.id=tm.person_id
    where a.id=p_assignment and a.school_id=p_school
      and a.academic_year_id=v_year and a.class_id=p_class
      and a.status='active' and a.valid_from<=now()
      and (a.valid_to is null or a.valid_to>now())
      and tm.person_id=p_actor and tm.role='teacher' and tm.status='active'
      and tm.valid_from<=now() and (tm.valid_to is null or tm.valid_to>now())
      and p.role='teacher' and p.account_status='active'
      and sp.subject_id=v_class.subject_id and sp.grade_id=v_class.grade_id
      and sp.status::text='published';
    if not found then
      raise exception 'invitation_not_authorized' using errcode='P0001';
    end if;
  else
    if p_class is not null or p_assignment is not null then
      raise exception 'invitation_invalid' using errcode='P0001';
    end if;
    select private.active_school_admin_14b(p_actor,p_school) into v_admin;
    if not v_admin then
      raise exception 'invitation_not_authorized' using errcode='P0001';
    end if;
  end if;

  insert into public.institutional_invitations
    (school_id,academic_year_id,class_id,teacher_assignment_id,subject_program_id,
     recipient_user_id,invited_role,token_digest,issued_by,expires_at)
  values(p_school,v_year,p_class,v_assignment_id,v_subject_program_id,
     p_recipient,p_role,p_token_digest,p_actor,p_expires_at)
  returning id into v_id;
  return v_id;
end;
$function$;

ALTER FUNCTION "public"."service_issue_institutional_invitation_14b"(p_actor uuid, p_recipient uuid, p_school uuid, p_role text, p_class uuid, p_assignment uuid, p_token_digest text, p_expires_at timestamp with time zone) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_issue_institutional_join_code_14c(p_actor uuid, p_school uuid, p_class uuid, p_assignment uuid, p_code_digest text, p_expires_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_year uuid;
  v_program uuid;
  v_id uuid;
begin
  perform private.lock_teacher_offboarding_14b((select teacher_membership_id from public.teacher_assignments where id=p_assignment));
  if p_actor is null or p_school is null or p_class is null or p_assignment is null
     or p_code_digest !~ '^[0-9a-f]{64}$'
     or p_expires_at<=now() or p_expires_at>now()+interval '7 days' then
    raise exception 'institutional_join_code_invalid' using errcode='P0001';
  end if;

  select c.academic_year_id,a.subject_program_id
    into v_year,v_program
  from public.classes c
  join public.academic_years y
    on y.id=c.academic_year_id and y.school_id=c.school_id
  join public.teacher_assignments a
    on a.id=p_assignment and a.class_id=c.id and a.school_id=c.school_id
   and a.academic_year_id=c.academic_year_id
  join public.subject_programs sp on sp.id=a.subject_program_id
  join public.subjects s on s.id=sp.subject_id
  join public.institutional_memberships tm
    on tm.id=a.teacher_membership_id and tm.school_id=a.school_id
  join public.profiles p on p.id=tm.person_id
  where p.id=p_actor and p.role='teacher' and p.account_status='active'
    and c.id=p_class and c.school_id=p_school and c.is_active
    and y.status='active' and current_date between y.starts_on and y.ends_on
    and a.status='active' and a.valid_from<=now()
    and (a.valid_to is null or a.valid_to>now())
    and tm.role='teacher' and tm.status='active' and tm.valid_from<=now()
    and (tm.valid_to is null or tm.valid_to>now())
    and sp.subject_id=c.subject_id and sp.grade_id=c.grade_id
    and sp.status::text='published' and s.status::text='published';

  if not found then
    raise exception 'institutional_join_code_not_authorized' using errcode='P0001';
  end if;

  insert into public.institutional_join_codes
    (school_id,academic_year_id,class_id,teacher_assignment_id,
     subject_program_id,code_digest,issued_by,expires_at)
  values
    (p_school,v_year,p_class,p_assignment,v_program,
     p_code_digest,p_actor,p_expires_at)
  returning id into v_id;

  return v_id;
end;
$function$;

ALTER FUNCTION "public"."service_issue_institutional_join_code_14c"(p_actor uuid, p_school uuid, p_class uuid, p_assignment uuid, p_code_digest text, p_expires_at timestamp with time zone) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_launch_governed_learning(p_student_id uuid, p_auth_session_id uuid, p_enrollment_id uuid, p_blueprint_id uuid, p_target_skill_id uuid DEFAULT NULL::uuid, p_recommendation_instance_id uuid DEFAULT NULL::uuid, p_read_only boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare bp public.assessment_blueprints%rowtype; b public.assessment_policy_bindings%rowtype; policy jsonb; code text; selected_form_id uuid;
 picked uuid[]; details jsonb; result jsonb; target uuid; binding_id uuid; entry record; n integer; state public.chapter_mastery_states%rowtype; ready jsonb; form_selection jsonb;
begin
 select * into bp from public.assessment_blueprints where id=p_blueprint_id;
 if not found then raise exception 'learning_context_unavailable'; end if;
 -- Every governed launch takes the learner lock before any pool lock, keeping
 -- old dynamic and opt-in blueprints in the same deadlock-free lock order.
 perform pg_advisory_xact_lock(hashtextextended('governed-mastery-form:'||p_student_id::text,0));
 if not p_read_only and bp.configuration_snapshot ? 'masteryFormSelection' then
   perform private.advance_mastery_form_fence('learner',p_student_id);
 end if;
 perform private.lock_student_learning_context(p_student_id,p_auth_session_id,p_enrollment_id,bp.curriculum_release_id,bp.unit_id);
 if not p_read_only then
   result:=public.service_resume_governed_learning(p_student_id,p_auth_session_id,p_enrollment_id,bp.curriculum_release_id,bp.unit_id,bp.purpose);
   if result->>'resumed'='true' then
     if p_recommendation_instance_id is not null then perform public.service_record_governed_recommendation_event(p_student_id,p_auth_session_id,p_recommendation_instance_id,'action_started','start_learning_session',(result#>>'{session,id}')::uuid); end if;
     return private.authorized_governed_result(p_student_id,p_auth_session_id,p_enrollment_id,bp.curriculum_release_id,bp.unit_id,result);
   end if;
 end if;
 policy:=private.validate_assessment_policy_v1(bp.id);
 form_selection:=private.validate_mastery_form_selection(bp.id,policy);
 perform private.validate_governed_learning_model((policy->>'learningModelConfigurationId')::uuid);
 select unit_code_snapshot into strict code from public.curriculum_release_units where curriculum_release_id=bp.curriculum_release_id and unit_id=bp.unit_id;
 select * into state from public.chapter_mastery_states where student_id=p_student_id and curriculum_release_id=bp.curriculum_release_id and unit_code=code;
 select coalesce(jsonb_agg(jsonb_build_object('skillId',i.skill_id,'requiredForReadiness',case when policy->>'schemaVersion' in ('haiedu-assessment-policy-v2','haiedu-assessment-policy-v3','haiedu-assessment-policy-v4') then coalesce(policy->'readinessSkillIds' ? i.skill_id::text,false) else true end,'ready',private.governed_skill_ready(p_student_id,bp.curriculum_release_id,i.skill_id,(policy->>'learningModelConfigurationId')::uuid)) order by i.skill_id),'[]') into ready
 from (select distinct skill_id from public.assessment_blueprint_items bi join public.items i on i.id=bi.item_id where bi.assessment_blueprint_id=bp.id) i;
 if p_read_only then return private.authorized_governed_result(p_student_id,p_auth_session_id,p_enrollment_id,bp.curriculum_release_id,bp.unit_id,jsonb_build_object('unitCode',code,'unitId',bp.unit_id,'curriculumReleaseId',bp.curriculum_release_id,'assessmentPolicy',policy,'readiness',ready,
 'baselineSessionId',private.scoped_chapter_baseline(p_student_id,bp.curriculum_release_id,bp.unit_id),'lifecycle',to_jsonb(state),'readOnly',true)); end if;
 binding_id:=public.service_bind_assessment_policy(bp.id);
 select * into strict b from public.assessment_policy_bindings where id=binding_id;
 -- Resume/completed baseline paths execute before selection, retaining bindings.
 result:=public.service_start_governed_session_atomic(p_student_id,p_auth_session_id,p_enrollment_id,b.id,null,p_target_skill_id,null);
 if p_recommendation_instance_id is not null and result#>>'{session,assessment_policy_binding_id}' is not null then perform public.service_record_governed_recommendation_event(p_student_id,p_auth_session_id,p_recommendation_instance_id,'action_started','start_learning_session',(result#>>'{session,id}')::uuid); end if;
 return private.authorized_governed_result(p_student_id,p_auth_session_id,p_enrollment_id,bp.curriculum_release_id,bp.unit_id,result);
exception when raise_exception then
 if sqlerrm<>'governed_session_items_invalid' then raise; end if;
 -- This handler is only the launcher's selection phase. The failed nested call
 -- was a subtransaction, so it has not committed a partial header or lifecycle.
 -- Reacquire: PostgreSQL released locks obtained by the failed subtransaction.
 perform pg_advisory_xact_lock(hashtextextended('governed-mastery-form:'||p_student_id::text,0));
 if bp.configuration_snapshot ? 'masteryFormSelection' then
   perform private.advance_mastery_form_fence('learner',p_student_id);
 end if;
 perform private.lock_student_learning_context(p_student_id,p_auth_session_id,p_enrollment_id,bp.curriculum_release_id,bp.unit_id);
 binding_id:=public.service_bind_assessment_policy(bp.id);
 select * into strict b from public.assessment_policy_bindings where id=binding_id;
 picked:='{}'::uuid[];
 if bp.purpose='diagnostic' then
   select f.id into selected_form_id from public.assessment_forms f where f.pool_id=bp.assessment_pool_id and f.status='active'
   and not exists(select 1 from public.assessment_form_items fi where fi.form_id=f.id and private.source_family_seen(p_student_id,private.item_source_family(fi.item_id)))
   order by md5(p_student_id::text||':'||b.subject_program_id::text||':'||b.unit_id::text||':'||f.id::text),f.id limit 1;
   if selected_form_id is null then raise exception 'source_family_forms_exhausted'; end if;
   select array_agg(fi.item_id order by md5(p_student_id::text||':'||fi.item_id::text),fi.item_id) into picked from public.assessment_form_items fi where fi.form_id=selected_form_id;
 elsif bp.purpose='mastery_check' then
   form_selection:=private.validate_mastery_form_selection(bp.id,b.policy_snapshot);
   if form_selection is not null then
     -- No mixing or reserve substitution. An exposed constituent rejects the whole form.
     select (f.value->>'formId')::uuid into selected_form_id
     from jsonb_array_elements(form_selection->'forms') with ordinality f(value,ord)
     where not exists(select 1 from jsonb_array_elements(f.value->'items') i
       where private.mastery_form_item_seen(p_student_id,(i->>'itemId')::uuid))
     order by f.ord limit 1;
     if selected_form_id is null then raise exception 'governed_mastery_forms_exhausted'; end if;
     select array_agg(fi.item_id order by md5(p_student_id::text||':'||selected_form_id::text||':'||fi.item_id::text),fi.item_id)
       into picked from public.assessment_form_items fi where fi.form_id=selected_form_id;
   else
   for entry in select * from jsonb_each_text(b.policy_snapshot->'questionCountBySkill') loop
     picked:=picked||array(select i.id from public.assessment_blueprint_items bi join public.items i on i.id=bi.item_id
       where bi.assessment_blueprint_id=bp.id and i.skill_id=entry.key::uuid
       order by exists(select 1 from public.learning_session_items old join public.learning_sessions ls on ls.id=old.session_id
          where ls.student_id=p_student_id and ls.curriculum_release_id=b.curriculum_release_id and ls.governed_unit_id=b.unit_id and ls.mode='mastery_check' and ls.status='completed' and old.item_id=i.id),
       (select count(*) from public.student_item_exposure_events e where e.student_id=p_student_id and e.curriculum_release_id=b.curriculum_release_id and e.item_id=i.id),
       (select max(served_at) from public.student_item_exposure_events e where e.student_id=p_student_id and e.curriculum_release_id=b.curriculum_release_id and e.item_id=i.id) nulls first,i.code,i.id
       limit entry.value::integer);
   end loop;
   end if;
 elsif bp.purpose='practice' then
   if p_target_skill_id is not null and not (b.skill_scope_snapshot ? p_target_skill_id::text) then raise exception 'assessment_policy_skill_scope_invalid'; end if;
   target:=p_target_skill_id;
   if target is null then
     select value::uuid into target from jsonb_array_elements_text(b.skill_scope_snapshot) skill(value)
     where not private.governed_skill_ready(p_student_id,b.curriculum_release_id,value::uuid,b.learning_model_configuration_id) order by value limit 1;
   end if;
   if target is null then return private.authorized_governed_result(p_student_id,p_auth_session_id,p_enrollment_id,bp.curriculum_release_id,bp.unit_id,jsonb_build_object('unitReadyForMasteryCheck',true,'unitId',b.unit_id)); end if;
   -- Assignments are re-selected adaptively on first delivery, then immutable.
   for n in 1..(b.policy_snapshot->>'plannedQuestionCount')::integer loop
     picked:=picked||array(select i.id from public.assessment_blueprint_items bi join public.items i on i.id=bi.item_id
     where bi.assessment_blueprint_id=bp.id and i.skill_id=target order by i.code,i.id offset ((n-1) % (select count(*) from public.assessment_blueprint_items bi join public.items i on i.id=bi.item_id where bi.assessment_blueprint_id=bp.id and i.skill_id=target)) limit 1);
   end loop;
 elsif bp.purpose='chapter_review' then
   details:=private.prepare_governed_lifecycle(p_student_id,b.id);
   -- All unused chapter questions precede exact repeats, including across skills.
   -- Within each group preserve weak/failed-skill weight, spacing and diversity.
   with candidates as (
     select i.id,i.skill_id,
       exists(select 1 from public.chapter_review_item_exposures e where e.review_cycle_id=(details->>'reviewCycleId')::uuid and e.item_id=i.id) seen,
       exists(select 1 from public.learning_sessions previous where previous.student_id=p_student_id and previous.curriculum_release_id=b.curriculum_release_id and previous.governed_unit_id=b.unit_id
         and previous.mode='mastery_check' and previous.status='completed' and previous.id=(select last.id from public.learning_sessions last where last.student_id=p_student_id and last.curriculum_release_id=b.curriculum_release_id and last.governed_unit_id=b.unit_id and last.mode='mastery_check' and last.status='completed' order by completed_at desc,id desc limit 1)
         and previous.metadata->'failedSkillIds' ? i.skill_id::text) failed,
       coalesce((select count(*) filter(where recent.correct and not recent.hint_used)::numeric/nullif(count(*) filter(where not recent.hint_used),0) from
         (select a.correct,a.hint_used from public.attempts a join public.chapter_review_sessions cr on cr.learning_session_id=a.learning_session_id
         where cr.chapter_mastery_state_id=(details->>'stateId')::uuid and a.skill_id=i.skill_id order by a.created_at desc,a.id desc limit (select (configuration#>>'{recentRecovery,recentWindow}')::integer from public.learning_model_configurations where id=b.learning_model_configuration_id)) recent),-1) skill_rank,
       (select count(*) from public.chapter_review_item_exposures e join public.chapter_review_sessions cr on cr.id=e.chapter_review_session_id where cr.chapter_mastery_state_id=(details->>'stateId')::uuid and e.item_id=i.id) exposures,
       (select count(*) from public.chapter_review_item_exposures e join public.chapter_review_sessions cr on cr.id=e.chapter_review_session_id where cr.chapter_mastery_state_id=(details->>'stateId')::uuid and e.item_template_id=i.item_template_id) template_exposures,
       (select count(*) from public.chapter_review_item_exposures e join public.chapter_review_sessions cr on cr.id=e.chapter_review_session_id where cr.chapter_mastery_state_id=(details->>'stateId')::uuid and e.item_family_id=t.item_family_id) family_exposures,
       (select max(selected_at) from public.chapter_review_item_exposures e join public.chapter_review_sessions cr on cr.id=e.chapter_review_session_id where cr.chapter_mastery_state_id=(details->>'stateId')::uuid and e.item_id=i.id) last_seen
     from public.assessment_blueprint_items bi join public.items i on i.id=bi.item_id join public.item_templates t on t.id=i.item_template_id where bi.assessment_blueprint_id=bp.id
   ), ranked as (select *,row_number() over(partition by skill_id order by seen,last_seen nulls first,template_exposures,family_exposures,exposures,id) skill_position from candidates),
   chosen as (select * from ranked order by seen,(skill_position=1) desc,failed desc,skill_rank,last_seen nulls first,template_exposures,family_exposures,exposures,id limit (b.policy_snapshot->>'plannedQuestionCount')::integer)
   select array_agg(id order by md5((details->>'stateId')||':'||(details->>'reviewCycleNumber')||':'||(details->>'reviewSessionNumber')||':'||id::text),id) into picked from chosen;
   if exists(select 1 from public.assessment_blueprint_items bi join public.items i on i.id=bi.item_id where bi.assessment_blueprint_id=bp.id and i.stimulus->>'kind'='task_set') then
     -- Prefer the normal review candidates, then consider the complete bank.
     -- Pack whole blocks only; an impossible budget fails before a session exists.
     select private.pack_task_set_items(picked||array(select bi.item_id from public.assessment_blueprint_items bi where bi.assessment_blueprint_id=bp.id and not (bi.item_id=any(picked)) order by bi.item_id),(b.policy_snapshot->>'plannedQuestionCount')::integer) into picked;
   end if;
 end if;
 result:=public.service_start_governed_session_atomic(p_student_id,p_auth_session_id,p_enrollment_id,b.id,selected_form_id,target,picked);
 if p_recommendation_instance_id is not null and result#>>'{session,assessment_policy_binding_id}' is not null then perform public.service_record_governed_recommendation_event(p_student_id,p_auth_session_id,p_recommendation_instance_id,'action_started','start_learning_session',(result#>>'{session,id}')::uuid); end if;
 return private.authorized_governed_result(p_student_id,p_auth_session_id,p_enrollment_id,bp.curriculum_release_id,bp.unit_id,result);
end;
$function$;

ALTER FUNCTION "public"."service_launch_governed_learning"(p_student_id uuid, p_auth_session_id uuid, p_enrollment_id uuid, p_blueprint_id uuid, p_target_skill_id uuid, p_recommendation_instance_id uuid, p_read_only boolean) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_learning_audio(p_actor_id uuid, p_auth_session_id uuid, p_action text, p_session_id uuid DEFAULT NULL::uuid, p_session_item_id uuid DEFAULT NULL::uuid, p_item_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.learning_sessions%rowtype; li public.learning_session_items%rowtype; i public.items%rowtype;
 a public.learning_audio_versions%rowtype; d public.learning_audio_deliveries%rowtype; stamp timestamptz:=clock_timestamp();
begin
 if not public.service_validate_active_session(p_actor_id,p_auth_session_id) then raise exception 'audio_access_denied'; end if;
 if p_action in ('preview','catalog') then
  if p_session_id is not null or p_session_item_id is not null or not exists(select 1 from public.profiles where id=p_actor_id and role::text in ('admin','content_admin')) then raise exception 'audio_access_denied'; end if;
  select * into strict i from public.items where id=p_item_id for share;
  if p_action='catalog' then
   return jsonb_build_object('versions',(select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'title',v.title,'locale',v.locale,'durationMs',v.duration_ms) order by v.title,v.id),'[]') from
    (select av.* from public.learning_audio_versions av where av.revoked_at is null and exists(
     select 1 from public.item_curriculum_scopes sc join public.curriculum_releases r on r.subject_program_id=sc.subject_program_id
      join public.curriculum_release_skills rs on rs.curriculum_release_id=r.id and rs.skill_id=i.skill_id
     where sc.item_id=i.id and sc.is_primary and sc.unit_id=av.unit_id and r.id=av.curriculum_release_id) order by av.title,av.id limit 100) v));
  end if;
  a:=private.validate_audio_reference(private.task_set_stimulus(i.stimulus,i.id),i.id);
 else
  if p_action not in ('load','fetched','started','completed','failed') or p_item_id is not null then raise exception 'audio_request_invalid'; end if;
  s:=private.lock_governed_learning_session(p_actor_id,p_auth_session_id,p_session_id);
  if s.status<>'active' or s.mode not in ('practice','chapter_review') then raise exception 'audio_mode_unavailable'; end if;
  select * into li from public.learning_session_items where id=p_session_item_id and session_id=s.id for update;
  if not found or li.answered_at is not null or li.ordinal<>s.answered_count+1
   or not exists(select 1 from public.student_item_exposure_events where session_item_id=li.id and student_id=p_actor_id)
  then raise exception 'audio_access_denied'; end if;
  select * into strict i from public.items where id=li.item_id for share;
  perform private.validate_assigned_source(li.id,i.id);
  if i.status<>'published' or not exists(select 1 from public.assessment_blueprint_items bi join public.assessment_blueprints bp on bp.id=bi.assessment_blueprint_id
   join public.assessment_pool_items pi on pi.pool_id=bp.assessment_pool_id and pi.item_id=i.id join public.assessment_pools pool on pool.id=pi.pool_id
   where bi.assessment_blueprint_id=s.assessment_blueprint_id and bi.item_id=i.id and bi.item_version_snapshot=i.version_no and pi.enabled and pool.status='active')
  then raise exception 'audio_access_denied'; end if;
  a:=private.validate_audio_reference(private.task_set_stimulus(i.stimulus,i.id),i.id,s.curriculum_release_id,s.governed_unit_id);
  if p_action='load' then
   insert into public.learning_audio_deliveries(session_item_id,student_id,audio_version_id) values(li.id,p_actor_id,a.id)
    on conflict(session_item_id) do nothing;
  end if;
  select * into d from public.learning_audio_deliveries where session_item_id=li.id and student_id=p_actor_id and audio_version_id=a.id for update;
  if not found then raise exception 'audio_not_loaded'; end if;
  if p_action='fetched' then
   update public.learning_audio_deliveries set fetched_at=stamp,failed_at=null,updated_at=stamp where session_item_id=li.id;
  elsif p_action='started' then
   if d.fetched_at is null or d.failed_at is not null then raise exception 'audio_not_loaded'; end if;
   update public.learning_audio_deliveries set started_at=coalesce(started_at,stamp),updated_at=stamp where session_item_id=li.id;
  elsif p_action='completed' then
   if d.fetched_at is null or d.started_at is null or d.failed_at is not null or stamp-d.started_at < (a.duration_ms-100)::double precision*interval '1 millisecond' then raise exception 'audio_playback_incomplete'; end if;
   update public.learning_audio_deliveries set completed_at=coalesce(completed_at,stamp),updated_at=stamp where session_item_id=li.id;
  elsif p_action='failed' then
   update public.learning_audio_deliveries set failed_at=stamp,completed_at=null,started_at=null,updated_at=stamp where session_item_id=li.id;
  end if;
 end if;
 if p_action in ('load','preview') then
  return jsonb_build_object('audioVersionId',a.id,'bucketId',a.bucket_id,'objectPath',a.object_path,'sha256',a.sha256,'mimeType',a.mime_type,'byteLength',a.byte_length,'durationMs',a.duration_ms);
 end if;
 return jsonb_build_object('recorded',true,'action',p_action);
end;
$function$;

ALTER FUNCTION "public"."service_learning_audio"(p_actor_id uuid, p_auth_session_id uuid, p_action text, p_session_id uuid, p_session_item_id uuid, p_item_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_learning_task_set(p_actor uuid, p_auth uuid, p_action text, p_item uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i public.items%rowtype;
begin
 if not public.service_validate_active_session(p_actor,p_auth) or not exists(select 1 from public.profiles where id=p_actor and role::text in ('admin','content_admin')) then raise exception 'task_set_access_denied'; end if;
 select * into i from public.items where id=p_item for share;
 if not found then raise exception 'task_set_access_denied'; end if;
 if p_action='catalog' then
  return jsonb_build_object('versions',(select coalesce(jsonb_agg(jsonb_build_object('id',t.id,'title',t.title,'locale',t.locale,'total',jsonb_array_length(t.members),'modality',t.stimulus->>'kind') order by t.title,t.id),'[]') from
   (select v.* from public.learning_task_set_versions v where v.revoked_at is null
    and exists(select 1 from jsonb_array_elements(v.members) m where m->>'itemId'=i.id::text and m->>'skillId'=i.skill_id::text and (m->>'version')::integer in (i.version_no,i.version_no+1))
    and exists(select 1 from public.item_curriculum_scopes sc join public.curriculum_releases r on r.subject_program_id=sc.subject_program_id where sc.item_id=i.id and sc.is_primary and sc.unit_id=v.unit_id and r.id=v.curriculum_release_id)
    order by v.title,v.id limit 100) t));
 elsif p_action='preview' then
  perform private.validate_task_set_reference(i.stimulus,i.id);
  return jsonb_build_object('taskSet',private.learner_task_set_context(i.id),'stimulus',private.learner_shared_stimulus(i.id));
 else raise exception 'task_set_request_invalid'; end if;
end;
$function$;

ALTER FUNCTION "public"."service_learning_task_set"(p_actor uuid, p_auth uuid, p_action text, p_item uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_legacy_answer_response(p_student_id uuid, p_auth_session_id uuid, p_kind text, p_request jsonb, p_response jsonb DEFAULT NULL::jsonb, p_telemetry jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.learning_sessions%rowtype; li public.learning_session_items%rowtype;
  r private.learning_answer_receipts%rowtype; core private.learning_answer_receipts%rowtype;
  final jsonb; event_id uuid; issued public.recommendation_events%rowtype;
begin
  if p_kind is null or p_kind not in ('legacy-answer','legacy-mastery') or jsonb_typeof(p_request) is distinct from 'object'
    then raise exception 'learning_context_unavailable'; end if;
  perform private.authorized_legacy_answer_result(p_student_id,p_auth_session_id,null);
  select * into s from public.learning_sessions where id=(p_request->>'sessionId')::uuid and student_id=p_student_id for update;
  if not found or s.assessment_policy_binding_id is not null or s.status not in ('active','completed')
    or (p_kind='legacy-mastery' and s.mode<>'mastery_check')
    or not public.service_is_registered_legacy_learning_session(p_student_id,s.id)
    then raise exception 'learning_context_unavailable'; end if;
  select * into li from public.learning_session_items where id=(p_request->>'sessionItemId')::uuid
    and session_id=s.id and item_id=(p_request->>'itemId')::uuid for update;
  if not found then raise exception 'learning_context_unavailable'; end if;
  select * into r from private.learning_answer_receipts where session_item_id=li.id and kind=p_kind;
  if found and (r.student_id<>p_student_id or r.session_id<>s.id or r.request is distinct from p_request)
    then raise exception 'answer_response_conflict'; end if;
  if r.response is not null then
    return private.authorized_legacy_answer_result(p_student_id,p_auth_session_id,jsonb_build_object('response',r.response,'replayed',true));
  end if;
  select * into core from private.learning_answer_receipts where session_item_id=li.id and kind='legacy-answer';
  if core.session_item_id is not null and core.request is distinct from p_request then raise exception 'answer_response_conflict'; end if;
  if p_response is null then
    if li.attempt_id is not null and core.session_item_id is null then raise exception 'answer_result_unavailable'; end if;
    return private.authorized_legacy_answer_result(p_student_id,p_auth_session_id,jsonb_build_object('response',null,'coreResult',core.core_result,'replayed',false));
  end if;
  if core.attempt_id is null or core.attempt_id is distinct from li.attempt_id or jsonb_typeof(p_response) is distinct from 'object'
    then raise exception 'answer_result_unavailable'; end if;
  final:=p_response;
  if p_telemetry is not null then
    if p_kind<>'legacy-answer' or s.mode in ('diagnostic','mastery_check') then raise exception 'answer_response_invalid'; end if;
    select * into issued from public.recommendation_events
      where student_id=p_student_id and attempt_id=li.attempt_id and event_type='issued'
        and policy_scope='core_after_attempt' and surface=p_telemetry->>'surface' order by id limit 1;
    if found then
      -- A SQL-before-Edge rollout may already have an issued legacy recommendation.
      event_id:=issued.recommendation_instance_id;
      final:=jsonb_set(final,'{recommendation}',(final->'recommendation')||issued.recommendation_snapshot);
    else
    begin
    event_id:=gen_random_uuid();
    insert into public.recommendation_events(recommendation_instance_id,student_id,event_type,policy_scope,surface,
      action,target_skill_id,curriculum_release_id,assessment_blueprint_id,learning_model_configuration_id,
      model_provenance_status,learning_session_id,attempt_id,state_snapshot,recommendation_snapshot)
    values(event_id,p_student_id,'issued',p_telemetry->>'policyScope',p_telemetry->>'surface',p_telemetry->>'action',
      (p_telemetry->>'targetSkillId')::uuid,s.curriculum_release_id,s.assessment_blueprint_id,s.learning_model_configuration_id,
      coalesce(p_telemetry->>'modelProvenanceStatus','unbound_legacy'),s.id,li.attempt_id,
      p_telemetry->'stateSnapshot',p_telemetry->'recommendationSnapshot');
    exception when others then
      -- Preserve the existing optional telemetry contract: a saved answer is
      -- still delivered if telemetry is unavailable. Never retry issuance on replay.
      event_id:=null;
      raise log 'answer recommendation telemetry unavailable (%)',SQLSTATE;
    end;
    end if;
    final:=jsonb_set(final,'{recommendation,instanceId}',coalesce(to_jsonb(event_id),'null'::jsonb));
  end if;
  if r.session_item_id is null then
    insert into private.learning_answer_receipts(session_item_id,kind,student_id,session_id,item_id,attempt_id,request,response)
    values(li.id,p_kind,p_student_id,s.id,li.item_id,li.attempt_id,p_request,final);
  else
    update private.learning_answer_receipts set response=final where session_item_id=li.id and kind=p_kind;
  end if;
  return private.authorized_legacy_answer_result(p_student_id,p_auth_session_id,jsonb_build_object('response',final,'replayed',false));
end;
$function$;

ALTER FUNCTION "public"."service_legacy_answer_response"(p_student_id uuid, p_auth_session_id uuid, p_kind text, p_request jsonb, p_response jsonb, p_telemetry jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_list_misconception_reviews(p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with catalog as (select * from public.misconception_review_catalog_v), filtered as (
 select * from catalog c where
 (coalesce(p_filters->>'status','')='' or c.status=p_filters->>'status') and
 (coalesce(p_filters->>'subjectId','')='' or c.subject_id::text=p_filters->>'subjectId') and
 (coalesce(p_filters->>'gradeId','')='' or c.grade_id::text=p_filters->>'gradeId') and
 (coalesce(p_filters->>'skillId','')='' or c.skill_id::text=p_filters->>'skillId') and
 (coalesce(p_filters->>'unitId','')='' or c.units @> jsonb_build_array(jsonb_build_object('id',p_filters->>'unitId'))) and
 (coalesce(p_filters->>'search','')='' or strpos(lower(c.title_hy||' '||coalesce(c.description_hy,'')||' '||c.code||' '||c.skill_code),lower(p_filters->>'search'))>0)
), page as (
 select * from filtered order by skill_code,code,id
 limit 50 offset least(100000,greatest(0,coalesce((p_filters->>'offset')::integer,0)))
)
select jsonb_build_object(
 'definitions',coalesce((select jsonb_agg(to_jsonb(p)) from page p),'[]'::jsonb),
 'total',(select count(*) from filtered),'pageSize',50,
 'counts',(select jsonb_object_agg(status,n) from (select status,count(*) n from catalog group by status)x),
 'filters',jsonb_build_object(
   'subjects',coalesce((select jsonb_agg(x order by x->>'name') from (select distinct jsonb_build_object('id',subject_id,'name',subject_name_hy) x from catalog)y),'[]'::jsonb),
   'grades',coalesce((select jsonb_agg(x order by (x->>'number')::integer) from (select distinct jsonb_build_object('id',grade_id,'name',grade_label_hy,'number',grade_number) x from catalog)y),'[]'::jsonb),
   'units',coalesce((select jsonb_agg(x order by x->>'code') from (select distinct jsonb_array_elements(units) x from catalog)y),'[]'::jsonb),
   'skills',coalesce((select jsonb_agg(x order by x->>'code') from (select distinct jsonb_build_object('id',skill_id,'code',skill_code,'name',skill_name_hy) x from catalog)y),'[]'::jsonb)
 ));
$function$;

ALTER FUNCTION "public"."service_list_misconception_reviews"(p_filters jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_list_school_admin_subjects_14b(p_actor uuid, p_school uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_options jsonb;
begin
  if not private.active_school_admin_14b(p_actor,p_school) then
    raise exception 'school_subjects_unavailable' using errcode='P0001'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'id',id,'nameHy',name_hy,'code',code) order by code),'[]'::jsonb)
    into v_options from public.subjects where status::text='published';
  return v_options;
end $function$;

ALTER FUNCTION "public"."service_list_school_admin_subjects_14b"(p_actor uuid, p_school uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_list_school_teachers_14b(p_actor uuid, p_school uuid)
 RETURNS TABLE(person_id uuid, membership_id uuid, display_name text, email text, account_status text, membership_status text, subjects jsonb, classes jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if p_actor is null or p_school is null
     or not private.active_school_admin_14b(p_actor,p_school) then
    raise exception 'school_teachers_unavailable' using errcode='P0001';
  end if;

  return query
  with selected_memberships as (
    select distinct on (m.person_id) m.*
    from public.institutional_memberships m
    where m.school_id=p_school and m.role='teacher'
    order by m.person_id,
      (m.status='active' and m.valid_from<=now()
       and (m.valid_to is null or m.valid_to>now())) desc,
      (m.status='archived') desc,m.created_at desc
  )
  select m.person_id,m.id,p.display_name,u.email::text,p.account_status,
    case
      when m.status='active' and m.valid_from<=now()
        and (m.valid_to is null or m.valid_to>now()) then 'active'
      when m.status='archived' then 'archived'
      else 'ended'
    end,
    coalesce(grants.subjects,'[]'::jsonb),
    coalesce(assigned.classes,'[]'::jsonb)
  from selected_memberships m
  left join public.profiles p on p.id=m.person_id
  left join auth.users u on u.id=m.person_id
  left join lateral (
    select jsonb_agg(jsonb_build_object('nameHy',s.name_hy)
      order by s.name_hy) as subjects
    from public.teacher_subject_authorizations g
    join public.subjects s on s.id=g.subject_id
    where g.teacher_membership_id=m.id and g.school_id=m.school_id
      and g.status='active' and g.valid_from<=now()
      and (g.valid_to is null or g.valid_to>now())
  ) grants on true
  left join lateral (
    select jsonb_agg(jsonb_build_object(
      'name',c.name,'subjectName',s.name_hy,'gradeNumber',gr.grade_number,
      'isActive',(c.is_active and y.status='active'
        and y.starts_on<=current_date and y.ends_on>=current_date),
      'academicYear',y.label)
      order by c.created_at desc) as classes
    from public.teacher_assignments a
    join public.classes c on c.id=a.class_id and c.school_id=m.school_id
      and c.teacher_id=m.person_id
    join public.academic_years y on y.id=c.academic_year_id and y.school_id=m.school_id
    join public.subjects s on s.id=c.subject_id
    join public.grades gr on gr.id=c.grade_id
    where a.teacher_membership_id=m.id and a.school_id=m.school_id
      and a.status='active' and a.valid_from<=now()
      and (a.valid_to is null or a.valid_to>now())
  ) assigned on true
  order by (m.status='active' and m.valid_from<=now()
    and (m.valid_to is null or m.valid_to>now())) desc,
    (m.status='archived') desc,u.email;
end $function$;

ALTER FUNCTION "public"."service_list_school_teachers_14b"(p_actor uuid, p_school uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_list_staff_invites_14b(p_actor uuid)
 RETURNS TABLE(invitation_id uuid, recipient_email text, kind text, school_name text, subject_name text, school_id uuid, created_at timestamp with time zone, expires_at timestamp with time zone, expired boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select i.id, u.email::text, i.kind,
    coalesce(s.name,i.school_name)::text, sub.name_hy::text, i.school_id,
    i.created_at, i.expires_at, i.expires_at<=now()
  from public.staff_account_provisioning i
  join auth.users u on u.id=i.recipient_id
  left join public.schools s on s.id=i.school_id
  left join public.subjects sub on sub.id=i.subject_id
  where i.accepted_at is null and i.revoked_at is null
    and (exists(select 1 from public.profiles p where p.id=p_actor
          and p.role='admin' and p.account_status='active')
      or (i.kind='teacher' and private.active_school_admin_14b(p_actor,i.school_id)))
  order by i.created_at desc limit 100;
$function$;

ALTER FUNCTION "public"."service_list_staff_invites_14b"(p_actor uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_list_student_onboarding_classes_14c(p_actor uuid, p_school uuid)
 RETURNS TABLE(class_id uuid, class_name text, academic_year_id uuid, academic_year_label text, teacher_assignment_id uuid, subject_program_id uuid, subject_name text, grade_number integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not exists(
    select 1 from public.profiles p
    join public.institutional_memberships tm on tm.person_id=p.id
    where p.id=p_actor and p.role='teacher' and p.account_status='active'
      and tm.school_id=p_school and tm.role='teacher' and tm.status='active'
      and tm.valid_from<=now() and (tm.valid_to is null or tm.valid_to>now())
  ) then
    raise exception 'student_onboarding_unavailable' using errcode='P0001';
  end if;
  return query
  select c.id,c.name,y.id,y.label,a.id,sp.id,
         coalesce(s.name_hy,s.name_en,s.code),g.grade_number::integer
  from public.classes c
  join public.academic_years y
    on y.id=c.academic_year_id and y.school_id=c.school_id
  join public.teacher_assignments a
    on a.class_id=c.id and a.school_id=c.school_id
   and a.academic_year_id=c.academic_year_id
  join public.subject_programs sp on sp.id=a.subject_program_id
  join public.subjects s on s.id=sp.subject_id
  join public.grades g on g.id=sp.grade_id
  join public.institutional_memberships tm
    on tm.id=a.teacher_membership_id and tm.school_id=a.school_id
  where c.school_id=p_school and c.is_active
    and tm.person_id=p_actor
    and y.status='active' and current_date between y.starts_on and y.ends_on
    and a.status='active' and a.valid_from<=now()
    and (a.valid_to is null or a.valid_to>now())
    and tm.role='teacher' and tm.status='active' and tm.valid_from<=now()
    and (tm.valid_to is null or tm.valid_to>now())
    and sp.subject_id=c.subject_id and sp.grade_id=c.grade_id
    and sp.status::text='published' and s.status::text='published'
  order by g.grade_number,s.name_hy,c.name,a.valid_from desc;
end;
$function$;

ALTER FUNCTION "public"."service_list_student_onboarding_classes_14c"(p_actor uuid, p_school uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_lookup_invitee_by_email_14b(p_email text, p_role text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id uuid;
begin
  if p_email is null or length(btrim(p_email)) < 3 or length(p_email) > 320 or
     p_role not in ('student','teacher') then return null; end if;
  select p.id into v_id from auth.users u join public.profiles p on p.id=u.id
    where lower(u.email)=lower(btrim(p_email)) and p.role::text=p_role
      and p.account_status='active' limit 1;
  return v_id;
end $function$;

ALTER FUNCTION "public"."service_lookup_invitee_by_email_14b"(p_email text, p_role text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_materialize_item_variant(p_template_code text, p_seed text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_render jsonb;
  v_qa jsonb;
  v_template public.item_templates%rowtype;
  v_family public.item_families%rowtype;
  v_item_id uuid;
  v_code text;
  v_variant_key text;
  v_difficulty integer;
  v_item_family text;
  v_source_reference text;
  v_accepted_units text[] := array[]::text[];
begin
  select * into v_template from public.item_templates where code = p_template_code and status = 'active';
  if not found then raise exception 'active_template_not_found'; end if;
  select * into v_family from public.item_families where id = v_template.item_family_id;
  if not found then raise exception 'item_family_not_found'; end if;
  v_variant_key := 'seed:' || p_seed;
  select id into v_item_id from public.items where item_template_id = v_template.id and variant_key = v_variant_key;
  if found then
    return jsonb_build_object('itemId', v_item_id, 'created', false, 'templateCode', p_template_code, 'seed', p_seed);
  end if;
  v_render := private.render_item_variant(p_template_code, p_seed);
  v_qa := private.validate_rendered_item_variant(v_render);
  if coalesce((v_qa ->> 'valid')::boolean, false) is not true then
    raise exception 'generated_variant_qa_failed:%', v_qa::text;
  end if;
  v_code := p_template_code || '-V-' || upper(substr(md5(p_seed), 1, 10));
  v_difficulty := (v_render ->> 'difficulty')::integer;
  v_item_family := coalesce(v_template.generation_config ->> 'itemFamily', 'application');
  v_source_reference := coalesce(v_template.generation_config ->> 'sourceReference', 'Generated Chapter I variant; provisional pending Sprint 11D review');
  insert into public.items(
    skill_id, item_type, prompt_hy, prompt_en, stimulus, difficulty, config, status,
    code, difficulty_band, item_family, source_reference, validation_state,
    review_status, item_template_id, variant_key, variant_seed, variant_parameters,
    variant_fingerprint
  ) values (
    v_family.skill_id,
    (v_render ->> 'itemType')::item_type,
    v_render ->> 'promptHy',
    null,
    '{}'::jsonb,
    v_difficulty,
    jsonb_build_object('bank','PHY7-U01-11C-GENERATED','pilot_ready',false,'generation','deterministic_server_side','generator',v_render ->> 'generator','generatorVersion',v_render ->> 'templateVersion','semanticFingerprint',v_render ->> 'semanticFingerprint','validation_state','provisional_no_sme_review'),
    'review'::content_status,
    v_code,
    case when v_difficulty <= 1 then 'foundation' when v_difficulty <= 3 then 'core' else 'challenge' end,
    v_item_family,
    v_source_reference,
    'provisional_no_sme_review',
    'needs_review',
    v_template.id,
    v_variant_key,
    p_seed,
    v_render -> 'parameters',
    v_render ->> 'semanticFingerprint'
  ) returning id into v_item_id;
  if jsonb_typeof(coalesce(v_render -> 'acceptedUnits','[]'::jsonb)) = 'array' then
    select coalesce(array_agg(x.value), array[]::text[]) into v_accepted_units
    from jsonb_array_elements_text(coalesce(v_render -> 'acceptedUnits','[]'::jsonb)) as x(value);
  end if;
  insert into public.item_answer_keys(item_id, answer, tolerance, canonical_unit, accepted_units, feedback_code)
  values (v_item_id, v_render -> 'answer', nullif(v_render ->> 'tolerance','')::numeric, nullif(v_render ->> 'canonicalUnit',''), v_accepted_units, 'generated_variant');
  insert into public.item_options(item_id, option_key, content_hy, display_order)
  select v_item_id, x.elem ->> 'optionKey', x.elem ->> 'contentHy', x.ord::integer
  from jsonb_array_elements(coalesce(v_render -> 'options','[]'::jsonb)) with ordinality as x(elem, ord);
  return jsonb_build_object('itemId', v_item_id, 'created', true, 'status', 'review', 'templateCode', p_template_code, 'variantKey', v_variant_key, 'seed', p_seed, 'semanticFingerprint', v_render ->> 'semanticFingerprint', 'qa', v_qa);
end;
$function$;

ALTER FUNCTION "public"."service_materialize_item_variant"(p_template_code text, p_seed text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_offboard_school_teacher_14b(p_actor uuid, p_school uuid, p_membership uuid, p_action text, p_reason text DEFAULT 'administrative'::text, p_expected_revision text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_member public.institutional_memberships%rowtype;
  v_assignments jsonb; v_subjects jsonb; v_invitations jsonb; v_codes jsonb; v_revision text; v_summary jsonb;
begin
  if p_actor is null or p_school is null or p_membership is null
     or p_action is null or p_action not in ('preview','offboard')
     or p_reason is null or p_reason not in ('withdrawn','transfer','year_end','role_change','administrative')
     or not private.active_school_admin_14b(p_actor,p_school) then
    raise exception 'school_teacher_unavailable' using errcode='P0001';
  end if;
  perform private.lock_teacher_offboarding_14b(p_membership);
  select * into v_member from public.institutional_memberships
    where id=p_membership and school_id=p_school and role='teacher' for update;
  if not found or v_member.person_id=p_actor or v_member.status not in ('active','archived')
     or not private.active_school_admin_14b(p_actor,p_school) then
    raise exception 'school_teacher_unavailable' using errcode='P0001';
  end if;
  -- Locking the membership also serializes assignment/subject creation through existing guards.
  select coalesce(jsonb_agg(a.id order by a.id),'[]'::jsonb) into v_assignments
    from public.teacher_assignments a where a.teacher_membership_id=p_membership
      and a.school_id=p_school and a.status='active';
  select coalesce(jsonb_agg(g.id order by g.id),'[]'::jsonb) into v_subjects
    from public.teacher_subject_authorizations g where g.teacher_membership_id=p_membership
      and g.school_id=p_school and g.status='active';
  select coalesce(jsonb_agg(i.id order by i.id),'[]'::jsonb) into v_invitations
    from public.institutional_invitations i join public.teacher_assignments a on a.id=i.teacher_assignment_id
    where a.teacher_membership_id=p_membership and i.school_id=p_school
      and i.issued_by=v_member.person_id and i.invited_role='student'
      and i.used_at is null and i.revoked_at is null;
  select coalesce(jsonb_agg(c.id order by c.id),'[]'::jsonb) into v_codes
    from public.institutional_join_codes c join public.teacher_assignments a on a.id=c.teacher_assignment_id
    where a.teacher_membership_id=p_membership and c.school_id=p_school
      and c.issued_by=v_member.person_id and c.used_at is null and c.revoked_at is null;
  v_revision:=md5(jsonb_build_array(v_member.id,v_member.status,v_member.valid_from,v_member.valid_to,
    v_assignments,v_subjects,v_invitations,v_codes)::text);
  v_summary:=jsonb_build_object('membershipId',v_member.id,'schoolId',p_school,'revision',v_revision,
    'activeAssignments',jsonb_array_length(v_assignments),'activeSubjectGrants',jsonb_array_length(v_subjects),
    'unusedInvitations',jsonb_array_length(v_invitations),'unusedJoinCodes',jsonb_array_length(v_codes));
  if p_action='preview' then return v_summary; end if;
  if p_expected_revision is distinct from v_revision then
    raise exception 'teacher_offboarding_preview_changed' using errcode='P0001';
  end if;

  update public.institutional_invitations set revoked_at=now()
    where id in (select value::uuid from jsonb_array_elements_text(v_invitations));
  update public.institutional_join_codes set revoked_at=now()
    where id in (select value::uuid from jsonb_array_elements_text(v_codes));
  update public.teacher_assignments set status='ended',
    valid_to=greatest(now(),valid_from+interval '1 microsecond'),ended_by=p_actor,end_reason=p_reason
    where id in (select value::uuid from jsonb_array_elements_text(v_assignments));
  update public.teacher_subject_authorizations set status='revoked',
    valid_to=greatest(now(),valid_from+interval '1 microsecond'),ended_by=p_actor
    where id in (select value::uuid from jsonb_array_elements_text(v_subjects));
  update public.institutional_memberships set status='ended',
    valid_to=greatest(now(),valid_from+interval '1 microsecond'),ended_by=p_actor,end_reason=p_reason
    where id=p_membership;
  insert into public.academic_identity_events(table_name,row_id,operation,old_value,new_value,actor_id)
    values('teacher_offboarding',p_membership,'OFFBOARD',null,v_summary||jsonb_build_object('reason',p_reason),p_actor);
  return v_summary||jsonb_build_object('ended',true);
end $function$;

ALTER FUNCTION "public"."service_offboard_school_teacher_14b"(p_actor uuid, p_school uuid, p_membership uuid, p_action text, p_reason text, p_expected_revision text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_platform_role_change_allowed_14c(p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select p_user is not null
    and not exists(select 1 from public.learning_sessions where student_id=p_user)
    and not exists(select 1 from public.attempts where student_id=p_user)
    and not exists(select 1 from public.chapter_mastery_states where student_id=p_user)
    and not exists(select 1 from public.student_skill_mastery where student_id=p_user)
    and not exists(select 1 from public.student_skill_mastery_by_release where student_id=p_user)
    and not exists(select 1 from public.student_item_exposure_events where student_id=p_user)
    and not exists(select 1 from public.remediation_events where student_id=p_user)
    and not exists(select 1 from public.recommendation_events where student_id=p_user)
    and not exists(select 1 from public.pilot_participants where student_id=p_user)
    and not exists(select 1 from public.class_memberships where student_id=p_user)
    and not exists(select 1 from public.institutional_class_enrollments where student_id=p_user)
    and not exists(select 1 from public.institutional_memberships where person_id=p_user)
    and not exists(select 1 from public.institutional_invitations where recipient_user_id=p_user)
    and not exists(select 1 from private.learning_session_item_option_orders where student_id=p_user);
$function$;

ALTER FUNCTION "public"."service_platform_role_change_allowed_14c"(p_user uuid) OWNER TO postgres;

