CREATE OR REPLACE FUNCTION public.service_record_answer_atomic(p_student_id uuid, p_item_id uuid, p_skill_id uuid, p_response jsonb, p_normalized_response jsonb, p_score numeric, p_correct boolean, p_error_code text, p_hint_used boolean, p_response_time_ms integer, p_attempted_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_attempt_id uuid; v_result jsonb;
begin
  -- Existing provenance and diagnostic prerequisite triggers still run here.
  insert into public.attempts(student_id,item_id,skill_id,response,normalized_response,
    score,correct,error_code,hint_used,response_time_ms,created_at)
  values(p_student_id,p_item_id,p_skill_id,p_response,p_normalized_response,p_score,
    p_correct,p_error_code,p_hint_used,p_response_time_ms,p_attempted_at)
  returning id into v_attempt_id;
  v_result := private.apply_configured_mastery_attempt(v_attempt_id);
  return v_result || jsonb_build_object('attemptId',v_attempt_id,'replayed',false);
end;
$function$;

ALTER FUNCTION "public"."service_record_answer_atomic"(p_student_id uuid, p_item_id uuid, p_skill_id uuid, p_response jsonb, p_normalized_response jsonb, p_score numeric, p_correct boolean, p_error_code text, p_hint_used boolean, p_response_time_ms integer, p_attempted_at timestamp with time zone) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_record_governed_recommendation_event(p_student_id uuid, p_auth_session_id uuid, p_instance_id uuid, p_event_type text, p_surface text, p_started_session_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare issued public.recommendation_events%rowtype; source_session public.learning_sessions%rowtype; started public.learning_sessions%rowtype;
begin
 if p_event_type not in ('shown','clicked','action_started') or p_surface not in ('home','progress','learning_course','physics_course','practice_auto_target','practice_feedback','diagnostic_result','start_learning_session') then raise exception 'invalid_recommendation_event'; end if;
 select * into issued from public.recommendation_events where recommendation_instance_id=p_instance_id and student_id=p_student_id and event_type='issued' limit 1;
 if not found or issued.learning_session_id is null then return false; end if;
 source_session:=private.lock_governed_learning_session(p_student_id,p_auth_session_id,issued.learning_session_id);
 if (issued.curriculum_release_id,issued.assessment_blueprint_id,issued.learning_model_configuration_id)
 is distinct from (source_session.curriculum_release_id,source_session.assessment_blueprint_id,source_session.learning_model_configuration_id)
 or issued.state_snapshot->>'unitId' is distinct from source_session.governed_unit_id::text
 or issued.state_snapshot->>'enrollmentId' is distinct from source_session.institutional_class_enrollment_id::text
 then raise exception 'recommendation_context_mismatch'; end if;
 if p_event_type='action_started' then
   if p_started_session_id is null then return false; end if;
   started:=private.lock_governed_learning_session(p_student_id,p_auth_session_id,p_started_session_id);
   if (started.curriculum_release_id,started.governed_unit_id,started.institutional_class_enrollment_id)
   is distinct from (source_session.curriculum_release_id,coalesce((issued.recommendation_snapshot->>'targetUnitId')::uuid,source_session.governed_unit_id),source_session.institutional_class_enrollment_id)
   or started.status<>'active'
   or (issued.action<>'resume_session' and (started.mode<>'practice' or started.target_skill_id is distinct from issued.target_skill_id
      or issued.action not in ('practice_skill','continue_current_skill','collect_more_evidence','advance_skill','review_prerequisite')))
   then return false; end if;
 end if;
 insert into public.recommendation_events(recommendation_instance_id,student_id,event_type,policy_scope,surface,action,target_skill_id,curriculum_release_id,assessment_blueprint_id,learning_model_configuration_id,model_provenance_status,learning_session_id,attempt_id,state_snapshot,recommendation_snapshot)
 values(issued.recommendation_instance_id,p_student_id,p_event_type,issued.policy_scope,p_surface,issued.action,issued.target_skill_id,issued.curriculum_release_id,issued.assessment_blueprint_id,issued.learning_model_configuration_id,issued.model_provenance_status,
 coalesce(p_started_session_id,issued.learning_session_id),issued.attempt_id,issued.state_snapshot,issued.recommendation_snapshot) on conflict do nothing;
 perform private.authorized_governed_result(p_student_id,p_auth_session_id,source_session.institutional_class_enrollment_id,source_session.curriculum_release_id,source_session.governed_unit_id,'{}'::jsonb);
 return true;
end;
$function$;

ALTER FUNCTION "public"."service_record_governed_recommendation_event"(p_student_id uuid, p_auth_session_id uuid, p_instance_id uuid, p_event_type text, p_surface text, p_started_session_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_record_item_exposure(p_student_id uuid, p_session_id uuid, p_session_item_id uuid, p_item_id uuid, p_served_at timestamp with time zone DEFAULT now())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_event_id uuid;
  v_purpose text;
  v_item_code text;
  v_variant_key text;
  v_template_id uuid;
  v_template_code text;
  v_family_id uuid;
  v_family_code text;
begin
  select
    ls.mode,
    i.code,
    i.variant_key,
    t.id,
    t.code,
    f.id,
    f.code
  into
    v_purpose,
    v_item_code,
    v_variant_key,
    v_template_id,
    v_template_code,
    v_family_id,
    v_family_code
  from public.learning_session_items lsi
  join public.learning_sessions ls on ls.id = lsi.session_id
  join public.items i on i.id = lsi.item_id
  join public.item_templates t on t.id = i.item_template_id
  join public.item_families f on f.id = t.item_family_id
  where lsi.id = p_session_item_id
    and lsi.session_id = p_session_id
    and lsi.item_id = p_item_id
    and ls.student_id = p_student_id
    and ls.mode in ('practice','diagnostic','mastery_check','chapter_review');

  if not found then
    raise exception 'invalid_exposure_context';
  end if;

  insert into public.student_item_exposure_events(
    student_id, item_id, item_family_id, item_template_id,
    item_code, family_code, template_code, variant_key,
    purpose, session_id, session_item_id, served_at
  ) values (
    p_student_id, p_item_id, v_family_id, v_template_id,
    coalesce(v_item_code, p_item_id::text), v_family_code, v_template_code, v_variant_key,
    v_purpose, p_session_id, p_session_item_id, p_served_at
  )
  on conflict (session_item_id) do nothing
  returning id into v_event_id;

  if v_event_id is null then
    select id into v_event_id
    from public.student_item_exposure_events
    where session_item_id = p_session_item_id;
  end if;

  return v_event_id;
end;
$function$;

ALTER FUNCTION "public"."service_record_item_exposure"(p_student_id uuid, p_session_id uuid, p_session_item_id uuid, p_item_id uuid, p_served_at timestamp with time zone) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_record_item_help(p_student_id uuid, p_session_id uuid, p_session_item_id uuid, p_item_id uuid, p_hint_level integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
begin
  perform public.service_record_item_exposure(p_student_id,p_session_id,p_session_item_id,p_item_id,now());
  update public.student_item_exposure_events
  set help_used=true, hint_level_used=greatest(hint_level_used,least(3,greatest(0,coalesce(p_hint_level,0)))), updated_at=now()
  where student_id=p_student_id and session_item_id=p_session_item_id and item_id=p_item_id;
end;
$function$;

ALTER FUNCTION "public"."service_record_item_help"(p_student_id uuid, p_session_id uuid, p_session_item_id uuid, p_item_id uuid, p_hint_level integer) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_record_session_answer_atomic(p_student_id uuid, p_session_id uuid, p_session_item_id uuid, p_item_id uuid, p_skill_id uuid, p_response jsonb, p_normalized_response jsonb, p_score numeric, p_correct boolean, p_error_code text, p_hint_used boolean, p_response_time_ms integer, p_attempted_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.learning_sessions%rowtype; li public.learning_session_items%rowtype;
  result jsonb; receipt private.learning_answer_receipts%rowtype; snapshot jsonb;
begin
  select * into s from public.learning_sessions where id=p_session_id and student_id=p_student_id for update;
  if not found then raise exception 'invalid_or_inactive_session_item'; end if;
  if s.assessment_policy_binding_id is not null then
    return private.record_session_answer_before_recovery(p_student_id,p_session_id,p_session_item_id,p_item_id,
      p_skill_id,p_response,p_normalized_response,p_score,p_correct,p_error_code,p_hint_used,p_response_time_ms,p_attempted_at);
  end if;
  select * into li from public.learning_session_items where id=p_session_item_id and session_id=s.id
    and item_id=p_item_id and skill_id=p_skill_id for update;
  if not found then raise exception 'invalid_or_inactive_session_item'; end if;
  select * into receipt from private.learning_answer_receipts where session_item_id=li.id and kind='legacy-answer';
  if found then
    -- Compatibility RPC callers still receive their original committed core state.
    -- The learner API additionally checks the exact submitted request below.
    return receipt.core_result || jsonb_build_object('replayed',true);
  end if;
  if li.attempt_id is not null then raise exception 'answer_result_unavailable'; end if;
  result:=private.record_session_answer_before_recovery(p_student_id,p_session_id,p_session_item_id,p_item_id,
    p_skill_id,p_response,p_normalized_response,p_score,p_correct,p_error_code,p_hint_used,p_response_time_ms,p_attempted_at);
  select * into strict s from public.learning_sessions where id=s.id;
  snapshot:=result || jsonb_build_object(
    'grading',jsonb_build_object('correct',p_correct,'score',p_score,'errorCode',p_error_code,
      'feedbackCode',(select feedback_code from public.item_answer_keys where item_id=p_item_id),'usedHelp',result->'hintUsed'),
    'item',jsonb_build_object('id',p_item_id,'skill_id',p_skill_id),
    'sessionAfter',jsonb_build_object('status',s.status,'planned_item_count',s.planned_item_count,
      'answered_count',s.answered_count,'correct_count',s.correct_count));
  insert into private.learning_answer_receipts(session_item_id,kind,student_id,session_id,item_id,attempt_id,request,core_result)
  values(li.id,'legacy-answer',p_student_id,s.id,p_item_id,(result->>'attemptId')::uuid,
    jsonb_build_object('sessionId',s.id,'sessionItemId',li.id,'itemId',p_item_id,'response',p_response,
      'responseTimeMs',p_response_time_ms,'hintUsed',coalesce(p_hint_used,false)),snapshot);
  return snapshot;
end;
$function$;

ALTER FUNCTION "public"."service_record_session_answer_atomic"(p_student_id uuid, p_session_id uuid, p_session_item_id uuid, p_item_id uuid, p_skill_id uuid, p_response jsonb, p_normalized_response jsonb, p_score numeric, p_correct boolean, p_error_code text, p_hint_used boolean, p_response_time_ms integer, p_attempted_at timestamp with time zone) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_redeem_institutional_invitation_14b(p_recipient uuid, p_token_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_inv record; v_member uuid; v_enrollment uuid;
  v_issuer_admin boolean; v_issuer_teacher boolean;
begin
  perform private.lock_teacher_offboarding_14b((select a.teacher_membership_id from public.institutional_invitations i join public.teacher_assignments a on a.id=i.teacher_assignment_id where i.token_digest=p_token_digest));
  select * into v_inv from public.institutional_invitations
   where token_digest=p_token_digest for update;
  if not found or v_inv.recipient_user_id<>p_recipient
     or v_inv.expires_at<=now() or v_inv.used_at is not null or v_inv.revoked_at is not null
     or not exists(select 1 from public.profiles where id=p_recipient
       and account_status='active' and role::text=v_inv.invited_role) then
    raise exception 'invitation_unavailable' using errcode='P0001';
  end if;
  select exists(select 1 from public.institutional_memberships m
    join public.profiles p on p.id=m.person_id
    where m.person_id=v_inv.issued_by and m.school_id=v_inv.school_id
      and m.role='school_admin' and m.status='active' and m.valid_from<=now()
      and (m.valid_to is null or m.valid_to>now())
      and p.role='school_admin' and p.account_status='active') into v_issuer_admin;
  select exists(select 1 from public.teacher_assignments a
    join public.institutional_memberships m
      on m.id=a.teacher_membership_id and m.school_id=a.school_id
    join public.profiles p on p.id=m.person_id
    where a.id=v_inv.teacher_assignment_id and a.school_id=v_inv.school_id
      and a.class_id=v_inv.class_id and a.academic_year_id=v_inv.academic_year_id
      and a.subject_program_id=v_inv.subject_program_id
      and a.status='active' and a.valid_from<=now()
      and (a.valid_to is null or a.valid_to>now())
      and m.person_id=v_inv.issued_by and m.role='teacher' and m.status='active'
      and m.valid_from<=now() and (m.valid_to is null or m.valid_to>now())
      and p.role='teacher' and p.account_status='active') into v_issuer_teacher;
  if (v_inv.invited_role='student' and not v_issuer_teacher)
     or (v_inv.invited_role='teacher' and not v_issuer_admin)
     or v_inv.invited_role not in ('student','teacher') then
    raise exception 'invitation_unavailable' using errcode='P0001';
  end if;
  if v_inv.invited_role='student' and not exists(
    select 1 from public.classes c
    join public.academic_years y on y.id=c.academic_year_id and y.school_id=c.school_id
    join public.teacher_assignments a on a.id=v_inv.teacher_assignment_id
      and a.school_id=c.school_id and a.class_id=c.id
      and a.academic_year_id=c.academic_year_id
    join public.subject_programs sp on sp.id=v_inv.subject_program_id
      and sp.id=a.subject_program_id
    where c.id=v_inv.class_id and c.school_id=v_inv.school_id and c.is_active
      and y.id=v_inv.academic_year_id and y.status='active'
      and current_date between y.starts_on and y.ends_on
      and a.status='active' and a.valid_from<=now()
      and (a.valid_to is null or a.valid_to>now())
      and sp.subject_id=c.subject_id and sp.grade_id=c.grade_id
  ) then raise exception 'invitation_unavailable' using errcode='P0001'; end if;
  if v_inv.invited_role='teacher' and
     (v_inv.class_id is not null or v_inv.teacher_assignment_id is not null
      or v_inv.subject_program_id is not null) then
    raise exception 'invitation_unavailable' using errcode='P0001';
  end if;
  select id into v_member from public.institutional_memberships
    where school_id=v_inv.school_id and person_id=p_recipient and role=v_inv.invited_role
      and status='active' and valid_from<=now() and (valid_to is null or valid_to>now())
    order by valid_from desc limit 1;
  if v_member is null then
    insert into public.institutional_memberships
      (school_id,person_id,role,valid_from,status,created_by)
    values(v_inv.school_id,p_recipient,v_inv.invited_role,now(),'active',v_inv.issued_by)
    returning id into v_member;
  end if;
  if v_inv.invited_role='student' then
    if exists(select 1 from public.institutional_class_enrollments
      where class_id=v_inv.class_id and student_id=p_recipient and status='active') then
      raise exception 'already_enrolled' using errcode='P0001';
    end if;
    insert into public.institutional_class_enrollments
      (school_id,academic_year_id,class_id,student_membership_id,student_id,
       invitation_id,teacher_assignment_id,subject_program_id,created_by)
    values(v_inv.school_id,v_inv.academic_year_id,v_inv.class_id,v_member,p_recipient,
       v_inv.id,v_inv.teacher_assignment_id,v_inv.subject_program_id,v_inv.issued_by)
    returning id into v_enrollment;
  end if;
  update public.institutional_invitations set used_at=now() where id=v_inv.id;
  return jsonb_build_object('schoolId',v_inv.school_id,'membershipId',v_member,
    'classEnrollmentId',v_enrollment,'subjectProgramId',v_inv.subject_program_id);
end;
$function$;

ALTER FUNCTION "public"."service_redeem_institutional_invitation_14b"(p_recipient uuid, p_token_digest text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_redeem_institutional_join_code_14c(p_recipient uuid, p_code_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_code public.institutional_join_codes%rowtype;
  v_invitation_digest text;
  v_invitation_id uuid;
  v_result jsonb;
begin
  perform private.lock_teacher_offboarding_14b((select a.teacher_membership_id from public.institutional_join_codes c join public.teacher_assignments a on a.id=c.teacher_assignment_id where c.code_digest=p_code_digest));
  if p_recipient is null or p_code_digest !~ '^[0-9a-f]{64}$' then
    raise exception 'institutional_join_code_unavailable' using errcode='P0001';
  end if;

  select * into v_code
  from public.institutional_join_codes
  where code_digest=p_code_digest
  for update;

  if not found then
    return null;
  end if;

  if v_code.expires_at<=now() or v_code.used_at is not null
     or v_code.revoked_at is not null
     or not exists(
       select 1 from public.profiles
       where id=p_recipient and role='student' and account_status='active'
     )
     or not exists(
       select 1
       from public.classes c
       join public.academic_years y
         on y.id=c.academic_year_id and y.school_id=c.school_id
       join public.teacher_assignments a
         on a.id=v_code.teacher_assignment_id and a.class_id=c.id
        and a.school_id=c.school_id and a.academic_year_id=c.academic_year_id
        and a.subject_program_id=v_code.subject_program_id
       join public.subject_programs sp on sp.id=a.subject_program_id
       join public.subjects s on s.id=sp.subject_id
       join public.institutional_memberships tm
         on tm.id=a.teacher_membership_id and tm.school_id=a.school_id
       join public.profiles p on p.id=tm.person_id
       where c.id=v_code.class_id and c.school_id=v_code.school_id
         and c.academic_year_id=v_code.academic_year_id and c.is_active
         and y.status='active' and current_date between y.starts_on and y.ends_on
         and a.status='active' and a.valid_from<=now()
         and (a.valid_to is null or a.valid_to>now())
         and tm.person_id=v_code.issued_by and tm.role='teacher'
         and tm.status='active' and tm.valid_from<=now()
         and (tm.valid_to is null or tm.valid_to>now())
         and p.role='teacher' and p.account_status='active'
         and sp.subject_id=c.subject_id and sp.grade_id=c.grade_id
         and sp.status::text='published' and s.status::text='published'
     ) then
    raise exception 'institutional_join_code_unavailable' using errcode='P0001';
  end if;

  if exists(
    select 1 from public.institutional_class_enrollments e
    where e.class_id=v_code.class_id and e.student_id=p_recipient
      and e.status='active' and e.valid_from<=now()
      and (e.valid_to is null or e.valid_to>now())
  ) then
    update public.institutional_join_codes
    set used_by=p_recipient,used_at=now()
    where id=v_code.id;
    return jsonb_build_object(
      'schoolId',v_code.school_id,
      'classId',v_code.class_id,
      'subjectProgramId',v_code.subject_program_id,
      'joinCodeId',v_code.id,
      'alreadyEnrolled',true
    );
  end if;

  v_invitation_digest:=encode(extensions.digest(
    convert_to('institutional-code:'||v_code.id::text||':'||p_recipient::text,'UTF8'),
    'sha256'
  ),'hex');

  begin
    v_invitation_id:=public.service_issue_institutional_invitation_14b(
      v_code.issued_by,p_recipient,v_code.school_id,'student',
      v_code.class_id,v_code.teacher_assignment_id,
      v_invitation_digest,v_code.expires_at
    );
    v_result:=public.service_redeem_institutional_invitation_14b(
      p_recipient,v_invitation_digest
    );
  exception when raise_exception then
    if sqlerrm<>'already_enrolled' then
      raise;
    end if;
    v_result:=jsonb_build_object(
      'schoolId',v_code.school_id,
      'classId',v_code.class_id,
      'subjectProgramId',v_code.subject_program_id,
      'alreadyEnrolled',true
    );
  end;

  update public.institutional_join_codes
  set used_by=p_recipient,used_at=now()
  where id=v_code.id;

  return coalesce(v_result,'{}'::jsonb)||jsonb_build_object(
    'classId',v_code.class_id,
    'joinCodeId',v_code.id,
    'invitationId',v_invitation_id,
    'alreadyEnrolled',coalesce((v_result->>'alreadyEnrolled')::boolean,false)
  );
end;
$function$;

ALTER FUNCTION "public"."service_redeem_institutional_join_code_14c"(p_recipient uuid, p_code_digest text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_register_staff_invite_14b(p_actor uuid, p_recipient uuid, p_email text, p_kind text, p_school uuid, p_subject uuid, p_school_name text, p_school_code text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id uuid; v_role text;
begin
  if not public.service_authorize_staff_invite_14b(p_actor,p_kind,p_school,p_subject)
    or p_recipient is null or p_email is null or length(btrim(p_email))<3 then
    raise exception 'staff_invite_unavailable' using errcode='P0001'; end if;
  if p_kind='school_admin' and (p_school_name is null or length(btrim(p_school_name))<3
      or length(btrim(p_school_name))>160) then
    raise exception 'staff_invite_unavailable' using errcode='P0001'; end if;
  if p_school_code is not null or (p_kind='teacher' and p_school_name is not null) then
    raise exception 'staff_invite_unavailable' using errcode='P0001'; end if;
  select p.role::text into v_role from public.profiles p join auth.users u on u.id=p.id
   where p.id=p_recipient and p.account_status='active'
     and lower(u.email)=lower(btrim(p_email)) and u.created_at>now()-interval '1 hour'
   for update of p;
  if v_role is distinct from 'student' or
    exists(select 1 from public.learning_sessions where student_id=p_recipient) or
    exists(select 1 from public.class_memberships where student_id=p_recipient) or
    exists(select 1 from public.institutional_memberships where person_id=p_recipient) then
    raise exception 'staff_invite_unavailable' using errcode='P0001'; end if;
  update public.staff_account_provisioning set revoked_at=now()
    where recipient_id=p_recipient and accepted_at is null and revoked_at is null
      and expires_at<=now();
  insert into public.staff_account_provisioning
    (recipient_id,issued_by,kind,school_id,subject_id,school_name,school_code,expires_at)
  values(p_recipient,p_actor,p_kind,p_school,p_subject,
    case when p_kind='school_admin' then btrim(p_school_name) end,
    null,now()+interval '7 days')
  returning id into v_id;
  return v_id;
end $function$;

ALTER FUNCTION "public"."service_register_staff_invite_14b"(p_actor uuid, p_recipient uuid, p_email text, p_kind text, p_school uuid, p_subject uuid, p_school_name text, p_school_code text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_rename_teacher_class_14b(p_actor uuid, p_class uuid, p_name text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_class record;
  v_member record;
  v_assignment record;
  v_name text := btrim(coalesce(p_name,''));
begin
  if p_actor is null or p_class is null
    or length(v_name) < 2 or length(v_name) > 120
    or not exists(
      select 1 from public.profiles
      where id=p_actor and role='teacher' and account_status='active'
    ) then
    raise exception 'teacher_class_unavailable' using errcode='P0001';
  end if;

  select id,school_id,academic_year_id,teacher_id,name
    into v_class
    from public.classes
    where id=p_class and teacher_id=p_actor and school_id is not null
    for update;
  if not found then
    raise exception 'teacher_class_unavailable' using errcode='P0001';
  end if;

  select a.*
    into v_assignment
    from public.teacher_assignments a
    where a.class_id=v_class.id
      and a.school_id=v_class.school_id
      and a.academic_year_id=v_class.academic_year_id
      and a.status='active'
      and a.valid_from<=now()
      and (a.valid_to is null or a.valid_to>now())
    order by a.valid_from desc
    limit 1
    for share;
  if not found then
    raise exception 'teacher_class_unavailable' using errcode='P0001';
  end if;

  select *
    into v_member
    from public.institutional_memberships
    where id=v_assignment.teacher_membership_id
      and person_id=p_actor
      and role='teacher'
      and school_id=v_class.school_id
      and status='active'
      and valid_from<=now()
      and (valid_to is null or valid_to>now())
    for share;
  if not found then
    raise exception 'teacher_class_unavailable' using errcode='P0001';
  end if;

  if v_class.name=v_name then
    return v_name;
  end if;

  update public.classes set name=v_name where id=v_class.id;
  insert into public.academic_identity_events
    (table_name,row_id,operation,old_value,new_value,actor_id)
  values (
    'classes',v_class.id,'UPDATE',
    jsonb_build_object('name',v_class.name),
    jsonb_build_object('name',v_name),
    p_actor
  );
  return v_name;
end $function$;

ALTER FUNCTION "public"."service_rename_teacher_class_14b"(p_actor uuid, p_class uuid, p_name text) OWNER TO postgres;

