CREATE OR REPLACE FUNCTION public.service_resume_governed_learning(p_student_id uuid, p_auth_session_id uuid, p_enrollment_id uuid, p_release_id uuid, p_unit_id uuid, p_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.learning_sessions%rowtype;
begin
 if p_mode not in ('diagnostic','practice','mastery_check','chapter_review') then raise exception 'learning_context_unavailable'; end if;
 perform private.lock_student_learning_context(p_student_id,p_auth_session_id,p_enrollment_id,p_release_id,p_unit_id);
 select * into s from public.learning_sessions where student_id=p_student_id and institutional_class_enrollment_id=p_enrollment_id
 and curriculum_release_id=p_release_id and governed_unit_id=p_unit_id and assessment_policy_binding_id is not null and status='active'
 and (p_mode<>'diagnostic' or mode not in ('practice','chapter_review')) order by started_at,id limit 1;
 if not found then return private.authorized_governed_result(p_student_id,p_auth_session_id,p_enrollment_id,p_release_id,p_unit_id,jsonb_build_object('resumed',false)); end if;
 s:=private.lock_governed_learning_session(p_student_id,p_auth_session_id,s.id);
 if s.status<>'active' then return private.authorized_governed_result(p_student_id,p_auth_session_id,p_enrollment_id,p_release_id,p_unit_id,jsonb_build_object('resumed',false)); end if;
 return private.authorized_governed_result(p_student_id,p_auth_session_id,p_enrollment_id,p_release_id,p_unit_id,jsonb_build_object('resumed',true,'session',private.learner_governed_session(to_jsonb(s)),'modeConflict',s.mode<>p_mode));
end;
$function$;

ALTER FUNCTION "public"."service_resume_governed_learning"(p_student_id uuid, p_auth_session_id uuid, p_enrollment_id uuid, p_release_id uuid, p_unit_id uuid, p_mode text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_review_misconception(p_id uuid, p_action text, p_expected_token text, p_title_hy text, p_description_hy text, p_reason text, p_actor_id uuid, p_session_id uuid, p_actor_aal text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_before jsonb; v_after jsonb; v_role text; v_revision integer;
begin
 if p_action not in ('save_draft','request_changes','approve') or p_action is null then raise exception 'invalid_action'; end if;
 select role::text into v_role from public.profiles where id=p_actor_id and account_status='active' for share;
 if v_role is null or v_role not in ('admin','content_admin') then raise exception 'content_authoring_role_required'; end if;
 if not public.service_validate_active_session(p_actor_id,p_session_id) then raise exception 'account_or_session_inactive'; end if;
 if p_actor_aal is null or p_actor_aal not in ('aal1','aal2') then raise exception 'invalid_assurance_level'; end if;
 if p_action='approve' and p_actor_aal<>'aal2' then raise exception 'mfa_required'; end if;
 if char_length(btrim(coalesce(p_reason,''))) not between 3 and 2000 then raise exception 'review_reason_required'; end if;
 perform 1 from public.misconceptions where id=p_id for update;
 if not found then raise exception 'misconception_not_found'; end if;
 v_before:=public.service_get_misconception_review(p_id);
 if p_expected_token is null or p_expected_token is distinct from v_before->>'expectedToken' then raise exception 'stale_misconception_review'; end if;
 if v_before#>>'{definition,status}'<>'draft' then raise exception 'active_definition_read_only'; end if;
 if v_before#>>'{definition,skill_status}' in ('archived','retired') then raise exception 'inactive_skill'; end if;
 if exists(select 1 from jsonb_array_elements(v_before->'mappings') m where m->>'skillId' is distinct from v_before#>>'{definition,skill_id}') then raise exception 'misconception_mapping_scope_mismatch'; end if;
 if p_action='save_draft' then
   if char_length(btrim(coalesce(p_title_hy,''))) not between 3 and 240 or
      char_length(btrim(coalesce(p_description_hy,''))) not between 5 and 4000 then raise exception 'invalid_definition'; end if;
   if btrim(p_title_hy)=v_before#>>'{definition,title_hy}' and btrim(p_description_hy)=v_before#>>'{definition,description_hy}' then raise exception 'definition_unchanged'; end if;
   update public.misconceptions set title_hy=btrim(p_title_hy), description_hy=btrim(p_description_hy),updated_at=now() where id=p_id;
 elsif p_action='approve' then
   if char_length(btrim(coalesce(v_before#>>'{definition,title_hy}',''))) not between 3 and 240 or
      char_length(btrim(coalesce(v_before#>>'{definition,description_hy}',''))) not between 5 and 4000 then raise exception 'invalid_definition'; end if;
   update public.misconceptions set status='active',updated_at=now() where id=p_id;
 end if;
 v_after:=public.service_get_misconception_review(p_id);
 v_revision:=(v_before#>>'{definition,review_revision}')::integer+1;
 insert into public.misconception_review_events(misconception_id,revision_no,action,actor_id,actor_role,actor_aal,reason,before_snapshot,after_snapshot,mapping_snapshot)
 values(p_id,v_revision,p_action,p_actor_id,v_role,p_actor_aal,btrim(p_reason),v_before->'definition',
   (v_after->'definition') || jsonb_build_object('review_revision',v_revision,'last_action',p_action),v_before->'mappings');
 return public.service_get_misconception_review(p_id);
end;
$function$;

ALTER FUNCTION "public"."service_review_misconception"(p_id uuid, p_action text, p_expected_token text, p_title_hy text, p_description_hy text, p_reason text, p_actor_id uuid, p_session_id uuid, p_actor_aal text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_revoke_institutional_invitation_14b(p_actor uuid, p_invitation uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_inv record;
begin
  select * into v_inv from public.institutional_invitations where id=p_invitation for update;
  if not found or v_inv.used_at is not null or v_inv.revoked_at is not null then return false; end if;
  if p_actor <> v_inv.issued_by and not exists (select 1 from public.institutional_memberships m
    where m.school_id=v_inv.school_id and m.person_id=p_actor and m.role='school_admin'
      and m.status='active' and m.valid_from<=now() and (m.valid_to is null or m.valid_to>now())) then
    return false;
  end if;
  update public.institutional_invitations set revoked_at=now() where id=p_invitation;
  return true;
end $function$;

ALTER FUNCTION "public"."service_revoke_institutional_invitation_14b"(p_actor uuid, p_invitation uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_revoke_institutional_join_code_14c(p_actor uuid, p_code uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_code public.institutional_join_codes%rowtype;
begin
  select * into v_code
  from public.institutional_join_codes
  where id=p_code
  for update;

  if not found or v_code.used_at is not null or v_code.revoked_at is not null then
    return false;
  end if;

  if p_actor<>v_code.issued_by and not exists(
    select 1
    from public.institutional_memberships m
    join public.profiles p on p.id=m.person_id
    where m.school_id=v_code.school_id and m.person_id=p_actor
      and m.role='school_admin' and m.status='active'
      and m.valid_from<=now() and (m.valid_to is null or m.valid_to>now())
      and p.role='school_admin' and p.account_status='active'
  ) then
    return false;
  end if;

  update public.institutional_join_codes
  set revoked_at=now()
  where id=v_code.id;

  return true;
end;
$function$;

ALTER FUNCTION "public"."service_revoke_institutional_join_code_14c"(p_actor uuid, p_code uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_revoke_staff_invite_14b(p_actor uuid, p_invitation uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v record;
begin
  select kind,school_id,accepted_at,revoked_at into v
    from public.staff_account_provisioning where id=p_invitation for update;
  if not found or v.accepted_at is not null or v.revoked_at is not null then
    return false;
  end if;
  if not exists(select 1 from public.profiles p where p.id=p_actor
        and p.role='admin' and p.account_status='active')
     and not (v.kind='teacher' and private.active_school_admin_14b(p_actor,v.school_id)) then
    return false;
  end if;
  update public.staff_account_provisioning
    set revoked_at=now(),revoked_by=p_actor where id=p_invitation;
  return true;
end $function$;

ALTER FUNCTION "public"."service_revoke_staff_invite_14b"(p_actor uuid, p_invitation uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_revoke_teacher_subject_14b(p_actor uuid, p_authorization uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v record;
begin
  select * into v from public.teacher_subject_authorizations
    where id=p_authorization for update;
  if not found or v.status<>'active' or
     not private.active_school_admin_14b(p_actor,v.school_id) then return false; end if;
  update public.teacher_assignments a
    set status='ended',valid_to=greatest(now(),a.valid_from+interval '1 microsecond'),
      ended_by=p_actor,end_reason='role_change'
    from public.subject_programs p
    where a.teacher_membership_id=v.teacher_membership_id and a.school_id=v.school_id
      and a.subject_program_id=p.id and p.subject_id=v.subject_id and a.status='active';
  update public.teacher_subject_authorizations
    set status='revoked',valid_to=greatest(now(),valid_from+interval '1 microsecond'),
      ended_by=p_actor where id=p_authorization;
  return true;
end $function$;

ALTER FUNCTION "public"."service_revoke_teacher_subject_14b"(p_actor uuid, p_authorization uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_save_item_content_revision(p_item_id uuid, p_actor_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_item public.items%rowtype;
  v_role text;
  v_template_kind text;
  v_prompt_hy text;
  v_prompt_en text;
  v_stimulus jsonb;
  v_difficulty integer;
  v_family text;
  v_source text;
  v_validation text;
  v_options jsonb;
  v_answer_key jsonb;
  v_answer jsonb;
  v_mappings jsonb;
  v_change_summary text;
  v_next_version integer;
  v_config jsonb;
  v_option_count integer;
  v_distinct_option_count integer;
  v_bad_count integer;
  v_duplicate_mapping_count integer;
  v_existing_mapping_count integer;
  v_fingerprint text;
begin
  select role::text into v_role
  from public.profiles
  where id = p_actor_id;

  if v_role is null or v_role not in ('admin','content_admin') then
    raise exception 'content_admin_required';
  end if;

  select * into v_item
  from public.items
  where id = p_item_id
  for update;

  if not found then raise exception 'item_not_found'; end if;
  if v_item.retired_at is not null then raise exception 'retired_item_not_editable'; end if;

  select t.template_kind into v_template_kind
  from public.item_templates t
  where t.id = v_item.item_template_id;

  -- Deterministically generated concrete variants must stay reproducible from template+seed.
  -- Editing their rendered prompt/answer directly would intentionally make generator QA fail.
  if v_item.variant_seed is not null and v_template_kind in ('parameterized','parallel') then
    raise exception 'generated_variant_requires_template_edit';
  end if;

  v_prompt_hy := btrim(coalesce(p_payload->>'promptHy',''));
  v_prompt_en := nullif(btrim(coalesce(p_payload->>'promptEn','')), '');
  v_stimulus := coalesce(p_payload->'stimulus', '{}'::jsonb);
  if v_stimulus = 'null'::jsonb then v_stimulus := '{}'::jsonb; end if;

  begin
    v_difficulty := (p_payload->>'difficulty')::integer;
  exception when others then
    raise exception 'invalid_difficulty';
  end;

  v_family := btrim(coalesce(p_payload->>'itemFamily',''));
  v_source := nullif(btrim(coalesce(p_payload->>'sourceReference','')), '');
  v_validation := btrim(coalesce(p_payload->>'validationState', v_item.validation_state));
  v_options := coalesce(p_payload->'options', '[]'::jsonb);
  v_answer_key := coalesce(p_payload->'answerKey', '{}'::jsonb);
  v_answer := v_answer_key->'answer';

  -- Omitted mappings mean "preserve the current governed metadata".
  -- An explicit empty array means "remove all mappings" and therefore needs
  -- an affirmative confirmation flag whenever mappings already exist.
  if p_payload ? 'misconceptions' then
    v_mappings := coalesce(p_payload->'misconceptions', '[]'::jsonb);
  else
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'code', misconception.code,
          'responseKey', mapping.response_key,
          'mappingNote', mapping.mapping_note
        )
        order by mapping.response_key, misconception.code
      ),
      '[]'::jsonb
    )
    into v_mappings
    from public.item_misconception_mappings mapping
    join public.misconceptions misconception
      on misconception.id = mapping.misconception_id
    where mapping.item_id = v_item.id;
  end if;

  v_change_summary := nullif(btrim(coalesce(p_payload->>'changeSummary','')), '');

  -- Preserve a currently attached draft misconception during ordinary item edits.
  -- Older browser bundles could render a current draft mapping with an empty select
  -- because only active misconceptions were offered as choices. If the response key
  -- identifies exactly one existing mapping, recover its code before validation.
  select coalesce(
    jsonb_agg(
      case
        when btrim(coalesce(m.value->>'code','')) <> '' then m.value
        else jsonb_set(
          m.value,
          '{code}',
          to_jsonb(coalesce((
            select case when count(*) = 1 then max(mc.code) else null end
            from public.item_misconception_mappings existing
            join public.misconceptions mc on mc.id = existing.misconception_id
            where existing.item_id = v_item.id
              and existing.response_key = coalesce(nullif(btrim(m.value->>'responseKey'),''),'*')
              and mc.status <> 'retired'
          ), '')),
          true
        )
      end
      order by m.ordinality
    ),
    '[]'::jsonb
  )
  into v_mappings
  from jsonb_array_elements(v_mappings) with ordinality as m(value, ordinality);

  if v_prompt_hy = '' then raise exception 'empty_prompt'; end if;
  if v_difficulty < 1 or v_difficulty > 5 then raise exception 'invalid_difficulty'; end if;
  if v_family = '' then raise exception 'item_family_required'; end if;
  if v_validation = '' then raise exception 'validation_state_required'; end if;
  if jsonb_typeof(v_options) <> 'array' then raise exception 'options_must_be_array'; end if;
  if jsonb_typeof(v_mappings) <> 'array' then raise exception 'misconceptions_must_be_array'; end if;

  select count(*) into v_existing_mapping_count
  from public.item_misconception_mappings
  where item_id = v_item.id;

  if v_existing_mapping_count > 0
     and jsonb_array_length(v_mappings) = 0
     and coalesce((p_payload->>'confirmEmptyMisconceptions')::boolean, false) = false then
    raise exception 'explicit_empty_misconception_confirmation_required';
  end if;

  if jsonb_typeof(v_answer_key) <> 'object' or v_answer is null or v_answer = 'null'::jsonb then
    raise exception 'answer_key_required';
  end if;

  if v_item.item_type::text = 'single_choice' then
    v_option_count := jsonb_array_length(v_options);
    if v_option_count < 2 then raise exception 'insufficient_options'; end if;

    select count(distinct btrim(o->>'key')),
           count(*) filter (where btrim(coalesce(o->>'key','')) = '' or btrim(coalesce(o->>'contentHy','')) = '')
      into v_distinct_option_count, v_bad_count
    from jsonb_array_elements(v_options) o;

    if v_distinct_option_count <> v_option_count then raise exception 'duplicate_option_key'; end if;
    if v_bad_count <> 0 then raise exception 'invalid_option'; end if;
    if jsonb_typeof(v_answer) <> 'string' then raise exception 'single_choice_answer_must_be_option_key'; end if;
    if not exists (
      select 1 from jsonb_array_elements(v_options) o
      where btrim(o->>'key') = trim(both '"' from v_answer::text)
    ) then
      raise exception 'answer_not_in_options';
    end if;
  elsif v_item.item_type::text = 'typed_fields' then
    perform private.validate_typed_key(p_payload->'responseDefinition',v_answer);
    if jsonb_array_length(v_options)<>0 then raise exception 'typed_fields_contract_invalid'; end if;
  elsif v_item.item_type::text in ('matching','ordering') then
    perform private.validate_arrangement_key(v_item.item_type::text,p_payload->'responseDefinition',v_answer);
    if jsonb_array_length(v_options)<>0 then raise exception 'arrangement_contract_invalid'; end if;
  elsif v_item.item_type::text = 'true_false' then
    if jsonb_typeof(v_answer) <> 'boolean' then raise exception 'true_false_answer_not_boolean'; end if;
  elsif v_item.item_type::text in ('numeric','quantity') then
    if jsonb_typeof(v_answer) <> 'number' then raise exception 'numeric_answer_not_number'; end if;
    if v_answer_key->>'tolerance' is null then raise exception 'numeric_tolerance_missing'; end if;
    begin
      if (v_answer_key->>'tolerance')::numeric < 0 then raise exception 'invalid_tolerance'; end if;
    exception when invalid_text_representation then
      raise exception 'invalid_tolerance';
    end;
    if v_item.item_type::text = 'quantity' then
      if nullif(btrim(coalesce(v_answer_key->>'canonicalUnit','')), '') is null then
        raise exception 'quantity_canonical_unit_missing';
      end if;
      if jsonb_typeof(coalesce(v_answer_key->'acceptedUnits','[]'::jsonb)) <> 'array'
         or jsonb_array_length(coalesce(v_answer_key->'acceptedUnits','[]'::jsonb)) = 0 then
        raise exception 'quantity_accepted_units_missing';
      end if;
      if not exists (
        select 1 from jsonb_array_elements_text(v_answer_key->'acceptedUnits') u(value)
        where btrim(u.value) = btrim(v_answer_key->>'canonicalUnit')
      ) then
        raise exception 'canonical_unit_not_in_accepted_units';
      end if;
    end if;
  else
    raise exception 'unsupported_item_type';
  end if;

  -- Every submitted misconception must be active and belong to this item's skill.
  select count(*) into v_bad_count
  from jsonb_array_elements(v_mappings) m
  where btrim(coalesce(m->>'code','')) = ''
     or not exists (
       select 1 from public.misconceptions mc
       where mc.skill_id = v_item.skill_id
         and mc.code = btrim(m->>'code')
         and (
           mc.status = 'active'
           or (
             mc.status = 'draft'
             and exists (
               select 1
               from public.item_misconception_mappings existing
               where existing.item_id = v_item.id
                 and existing.misconception_id = mc.id
             )
           )
         )
     );
  if v_bad_count <> 0 then raise exception 'invalid_misconception_code'; end if;

  select count(*) - count(distinct (btrim(m->>'code') || '|' || btrim(coalesce(m->>'responseKey','*'))))
    into v_duplicate_mapping_count
  from jsonb_array_elements(v_mappings) m;
  if v_duplicate_mapping_count <> 0 then raise exception 'duplicate_misconception_mapping'; end if;

  -- Preserve the pre-edit state under its existing version number if no snapshot exists yet.
  insert into public.item_versions(item_id, version_no, snapshot, change_summary, created_by)
  select v_item.id,
         v_item.version_no,
         jsonb_build_object(
           'item', to_jsonb(v_item),
           'options', coalesce((select jsonb_agg(to_jsonb(o) order by o.display_order,o.option_key) from public.item_options o where o.item_id=v_item.id), '[]'::jsonb),
           'answerKey', (select to_jsonb(k) from public.item_answer_keys k where k.item_id=v_item.id),
           'misconceptions', coalesce((select jsonb_agg(jsonb_build_object('responseKey',m.response_key,'mappingNote',m.mapping_note,'code',mc.code) order by mc.code,m.response_key) from public.item_misconception_mappings m join public.misconceptions mc on mc.id=m.misconception_id where m.item_id=v_item.id), '[]'::jsonb)
         ),
         'Pre-edit snapshot before: ' || coalesce(v_change_summary,'content editor revision'),
         p_actor_id
  where not exists (
    select 1 from public.item_versions iv where iv.item_id=v_item.id and iv.version_no=v_item.version_no
  );

  v_config := v_item.config;
  if v_item.item_type::text in ('typed_fields','matching','ordering') then v_config:=jsonb_set(coalesce(v_config,'{}'),'{responseDefinition}',p_payload->'responseDefinition'); end if;
  if v_config ? 'pilot_ready' then v_config := jsonb_set(v_config,'{pilot_ready}','false'::jsonb,true); end if;
  if v_config ? 'humanReviewStatus' then v_config := jsonb_set(v_config,'{humanReviewStatus}','"pending"'::jsonb,true); end if;
  if v_config ? 'technicalQaStatus' then v_config := jsonb_set(v_config,'{technicalQaStatus}','"pending"'::jsonb,true); end if;

  update public.items
  set prompt_hy = v_prompt_hy,
      prompt_en = v_prompt_en,
      stimulus = v_stimulus,
      difficulty = v_difficulty,
      difficulty_band = case when v_difficulty <= 1 then 'foundation' when v_difficulty <= 3 then 'core' else 'challenge' end,
      item_family = v_family,
      source_reference = v_source,
      validation_state = v_validation,
      config = v_config,
      review_status = 'needs_review',
      status = 'review'::public.content_status,
      last_reviewed_at = null,
      last_reviewed_by = null,
      updated_at = now()
  where id = v_item.id;

  delete from public.item_options where item_id = v_item.id;
  if v_item.item_type::text = 'single_choice' then
    insert into public.item_options(item_id, option_key, content_hy, content_en, display_order)
    select v_item.id,
           btrim(o.value->>'key'),
           btrim(o.value->>'contentHy'),
           nullif(btrim(coalesce(o.value->>'contentEn','')), ''),
           o.ordinality::integer
    from jsonb_array_elements(v_options) with ordinality as o(value, ordinality);
  end if;

  insert into public.item_answer_keys(item_id, answer, tolerance, canonical_unit, accepted_units, feedback_code, updated_at)
  values (
    v_item.id,
    v_answer,
    case when v_item.item_type::text in ('numeric','quantity') then (v_answer_key->>'tolerance')::numeric else null end,
    case when v_item.item_type::text = 'quantity' then nullif(btrim(v_answer_key->>'canonicalUnit'),'') else null end,
    case when v_item.item_type::text = 'quantity'
      then array(select btrim(value) from jsonb_array_elements_text(v_answer_key->'acceptedUnits') where btrim(value) <> '')
      else '{}'::text[] end,
    nullif(btrim(coalesce(v_answer_key->>'feedbackCode','')), ''),
    now()
  )
  on conflict (item_id) do update
  set answer=excluded.answer,
      tolerance=excluded.tolerance,
      canonical_unit=excluded.canonical_unit,
      accepted_units=excluded.accepted_units,
      feedback_code=excluded.feedback_code,
      updated_at=excluded.updated_at;

  delete from public.item_misconception_mappings where item_id = v_item.id;
  insert into public.item_misconception_mappings(item_id, misconception_id, response_key, mapping_note)
  select v_item.id,
         mc.id,
         coalesce(nullif(btrim(m.value->>'responseKey'),''),'*'),
         nullif(btrim(coalesce(m.value->>'mappingNote','')), '')
  from jsonb_array_elements(v_mappings) m(value)
  join public.misconceptions mc
    on mc.skill_id=v_item.skill_id
   and mc.code=btrim(m.value->>'code')
   -- Draft codes reached this point only if validation proved that the
   -- same mapping was already attached before the delete above.
   and mc.status in ('active', 'draft');

  -- Authored/fixed variants get a fresh semantic fingerprint after edits.
  if coalesce(v_template_kind,'fixed') = 'fixed' then
    select md5(
      v_item.skill_id::text || '|' ||
      lower(regexp_replace(v_prompt_hy, '\s+', ' ', 'g')) || '|' ||
      k.answer::text || '|' ||
      coalesce((
        select jsonb_agg(jsonb_build_object('optionKey',o.option_key,'contentHy',o.content_hy) order by o.display_order,o.option_key)::text
        from public.item_options o where o.item_id=v_item.id
      ), '[]') || case when v_item.item_type::text in ('typed_fields','matching','ordering') then '|'||(v_config->'responseDefinition')::text else '' end
    ) into v_fingerprint
    from public.item_answer_keys k
    where k.item_id=v_item.id;

    update public.items set variant_fingerprint=v_fingerprint where id=v_item.id;
  end if;

  v_next_version := v_item.version_no + 1;
  update public.items
  set version_no=v_next_version,
      review_status='needs_review',
      status='review'::public.content_status,
      updated_at=now()
  where id=v_item.id;

  -- Snapshot the new revision under the new version number.
  insert into public.item_versions(item_id, version_no, snapshot, change_summary, created_by)
  select i.id,
         v_next_version,
         jsonb_build_object(
           'item', to_jsonb(i),
           'options', coalesce((select jsonb_agg(to_jsonb(o) order by o.display_order,o.option_key) from public.item_options o where o.item_id=i.id), '[]'::jsonb),
           'answerKey', (select to_jsonb(k) from public.item_answer_keys k where k.item_id=i.id),
           'misconceptions', coalesce((select jsonb_agg(jsonb_build_object('responseKey',m.response_key,'mappingNote',m.mapping_note,'code',mc.code) order by mc.code,m.response_key) from public.item_misconception_mappings m join public.misconceptions mc on mc.id=m.misconception_id where m.item_id=i.id), '[]'::jsonb)
         ),
         coalesce(v_change_summary,'Content editor revision'),
         p_actor_id
  from public.items i
  where i.id=v_item.id;

  return jsonb_build_object(
    'itemId', v_item.id,
    'versionNo', v_next_version,
    'requiresQa', true,
    'requiresReview', true,
    'status', 'review'
  );
end;
$function$;

ALTER FUNCTION "public"."service_save_item_content_revision"(p_item_id uuid, p_actor_id uuid, p_payload jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_school_admin_suspension_blockers_14c(p_user uuid)
 RETURNS TABLE(school_id uuid, school_name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select distinct target.school_id, school.name
  from public.institutional_memberships target
  join public.schools school on school.id=target.school_id
  where target.person_id=p_user
    and target.role='school_admin'
    and target.status='active'
    and target.valid_from<=now()
    and (target.valid_to is null or target.valid_to>now())
    and not exists (
      select 1
      from public.institutional_memberships alternative
      join public.profiles profile on profile.id=alternative.person_id
      where alternative.school_id=target.school_id
        and alternative.person_id<>p_user
        and alternative.role='school_admin'
        and alternative.status='active'
        and alternative.valid_from<=now()
        and (alternative.valid_to is null or alternative.valid_to>now())
        and profile.account_status='active'
    );
$function$;

ALTER FUNCTION "public"."service_school_admin_suspension_blockers_14c"(p_user uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_set_school_teacher_archived_14b(p_actor uuid, p_school uuid, p_membership uuid, p_archived boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_member record;
begin
  if p_actor is null or p_school is null or p_membership is null or p_archived is null
     or not private.active_school_admin_14b(p_actor,p_school) then
    raise exception 'school_teacher_unavailable' using errcode='P0001';
  end if;
  select * into v_member from public.institutional_memberships
    where id=p_membership and school_id=p_school and role='teacher' for update;
  if not found or v_member.person_id=p_actor then
    raise exception 'school_teacher_unavailable' using errcode='P0001';
  end if;

  if p_archived then
    if v_member.status='archived' then return true; end if;
    if v_member.status<>'active' or v_member.valid_from>now()
       or (v_member.valid_to is not null and v_member.valid_to<=now()) then
      raise exception 'school_teacher_unavailable' using errcode='P0001';
    end if;
    update public.institutional_memberships
      set status='archived',ended_by=null,end_reason=null
      where id=v_member.id;
    return true;
  end if;

  if v_member.status='active' and v_member.valid_from<=now()
     and (v_member.valid_to is null or v_member.valid_to>now()) then return true; end if;
  if v_member.status<>'archived' or v_member.valid_from>now()
     or (v_member.valid_to is not null and v_member.valid_to<=now())
     or not exists(select 1 from public.profiles
       where id=v_member.person_id and role='teacher' and account_status='active') then
    raise exception 'school_teacher_restore_unavailable' using errcode='P0001';
  end if;
  if exists(select 1 from public.institutional_memberships m
    where m.id<>v_member.id and m.school_id=p_school
      and m.person_id=v_member.person_id and m.role='teacher'
      and m.status='active' and m.valid_from<=now()
      and (m.valid_to is null or m.valid_to>now())) then
    raise exception 'school_teacher_conflict' using errcode='P0001';
  end if;
  update public.institutional_memberships
    set status='active',ended_by=null,end_reason=null
    where id=v_member.id;
  return true;
end $function$;

ALTER FUNCTION "public"."service_set_school_teacher_archived_14b"(p_actor uuid, p_school uuid, p_membership uuid, p_archived boolean) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_set_school_year_archived_14b(p_actor uuid, p_school uuid, p_year uuid, p_archived boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_year record;
begin
  if p_actor is null or p_school is null or p_year is null or p_archived is null
     or not private.active_school_admin_14b(p_actor,p_school) then
    raise exception 'school_year_unavailable' using errcode='P0001';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('school-year:'||p_school::text,0));
  select * into v_year from public.academic_years
    where id=p_year and school_id=p_school for update;
  if not found then
    raise exception 'school_year_unavailable' using errcode='P0001';
  end if;

  if p_archived then
    if v_year.status='closed' then return true; end if;
    if v_year.status<>'active' then
      raise exception 'school_year_unavailable' using errcode='P0001';
    end if;
    update public.academic_years set status='closed' where id=v_year.id;
    return true;
  end if;

  if v_year.status='active' then return true; end if;
  if v_year.status<>'closed'
     or v_year.starts_on>current_date or v_year.ends_on<current_date then
    raise exception 'school_year_restore_unavailable' using errcode='P0001';
  end if;
  if exists(
    select 1 from public.academic_years y
    where y.school_id=p_school and y.id<>v_year.id and y.status='active'
      and daterange(y.starts_on,y.ends_on,'[]')
        && daterange(v_year.starts_on,v_year.ends_on,'[]')
  ) then
    raise exception 'school_year_overlap' using errcode='P0001';
  end if;
  update public.academic_years set status='active' where id=v_year.id;
  return true;
end $function$;

ALTER FUNCTION "public"."service_set_school_year_archived_14b"(p_actor uuid, p_school uuid, p_year uuid, p_archived boolean) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_set_teacher_class_active_14b(p_actor uuid, p_class uuid, p_active boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_class record; v_member record; v_assignment record; v_grant uuid;
begin
  if p_actor is null or p_class is null or p_active is null
    or not exists(select 1 from public.profiles
      where id=p_actor and role='teacher' and account_status='active') then
    raise exception 'teacher_class_unavailable' using errcode='P0001';
  end if;
  select * into v_class from public.classes
    where id=p_class and teacher_id=p_actor and school_id is not null for update;
  if not found then raise exception 'teacher_class_unavailable' using errcode='P0001'; end if;
  select a.* into v_assignment from public.teacher_assignments a
    where a.class_id=v_class.id and a.school_id=v_class.school_id
      and a.academic_year_id=v_class.academic_year_id and a.status='active'
      and a.valid_from<=now() and (a.valid_to is null or a.valid_to>now())
    order by a.valid_from desc limit 1 for share;
  if not found then raise exception 'teacher_class_unavailable' using errcode='P0001'; end if;
  select * into v_member from public.institutional_memberships
    where id=v_assignment.teacher_membership_id and person_id=p_actor and role='teacher'
      and school_id=v_class.school_id and status='active' and valid_from<=now()
      and (valid_to is null or valid_to>now()) for share;
  if not found then raise exception 'teacher_class_unavailable' using errcode='P0001'; end if;
  if p_active then
    if not exists(select 1 from public.academic_years
      where id=v_class.academic_year_id and school_id=v_class.school_id
        and status='active' and starts_on<=current_date and ends_on>=current_date)
      or not exists(select 1 from public.subject_programs
        where id=v_assignment.subject_program_id and status::text='published') then
      raise exception 'school_year_unavailable' using errcode='P0001';
    end if;
    select id into v_grant from public.teacher_subject_authorizations
      where teacher_membership_id=v_member.id and school_id=v_member.school_id
        and subject_id=v_class.subject_id and status='active'
        and valid_from<=now() and (valid_to is null or valid_to>now()) for share;
    if v_grant is null then raise exception 'teacher_subject_unavailable' using errcode='P0001'; end if;
  end if;
  if v_class.is_active=p_active then return true; end if;
  update public.classes set is_active=p_active where id=v_class.id;
  insert into public.academic_identity_events
    (table_name,row_id,operation,old_value,new_value,actor_id)
  values ('classes',v_class.id,'UPDATE',
    jsonb_build_object('is_active',v_class.is_active),
    jsonb_build_object('is_active',p_active),p_actor);
  return true;
end $function$;

ALTER FUNCTION "public"."service_set_teacher_class_active_14b"(p_actor uuid, p_class uuid, p_active boolean) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_start_governed_session_atomic(p_student_id uuid, p_auth_session_id uuid, p_enrollment_id uuid, p_policy_binding_id uuid, p_form_id uuid, p_target_skill_id uuid, p_item_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.assessment_policy_bindings%rowtype; e public.institutional_class_enrollments%rowtype;
  s public.learning_sessions%rowtype; code text; v_mode text; baseline uuid; policy jsonb; entry record; details jsonb; form_selection jsonb; selected_form jsonb; form_fingerprint text;
begin
  select * into b from public.assessment_policy_bindings where id=p_policy_binding_id;
  if not found then raise exception 'assessment_policy_unavailable'; end if;
  -- Serialize assignments across every governed purpose/release, including an
  -- older dynamic blueprint that could otherwise reserve the same item.
  perform pg_advisory_xact_lock(hashtextextended('governed-mastery-form:'||p_student_id::text,0));
  perform private.advance_mastery_form_fence('learner',p_student_id);
  perform private.validate_governed_learning_model(b.learning_model_configuration_id);
  v_mode:=b.policy_snapshot->>'mode';
  if v_mode not in ('diagnostic','practice','mastery_check','chapter_review') then raise exception 'unsupported_governed_mode'; end if;
  select unit_code_snapshot into code from public.curriculum_release_units where curriculum_release_id=b.curriculum_release_id and unit_id=b.unit_id;
  -- Coordinate legacy starts during migration, then lock lifetime governed identity.
  perform pg_advisory_xact_lock(hashtextextended('initial-diagnostic:'||p_student_id::text||':'||code,0));
  perform pg_advisory_xact_lock(hashtextextended('governed-diagnostic:'||p_student_id::text||':'||b.subject_program_id::text||':'||b.unit_id::text,0));
  perform pg_advisory_xact_lock(hashtextextended('governed-session:'||p_student_id::text||':'||p_enrollment_id::text||':'||b.curriculum_release_id::text||':'||b.unit_id::text,0));
  e:=private.lock_student_learning_context(p_student_id,p_auth_session_id,p_enrollment_id,b.curriculum_release_id,b.unit_id);
  -- Resume is not a policy rewrite: retain the original binding even if a new
  -- blueprint is now selected. Only current authorization is revalidated here.
  select * into s from public.learning_sessions where student_id=p_student_id
    and institutional_class_enrollment_id=p_enrollment_id and curriculum_release_id=b.curriculum_release_id
    and ((assessment_policy_binding_id is not null and governed_unit_id=b.unit_id)
      or (assessment_policy_binding_id is null and exists(select 1 from public.legacy_learning_blueprint_mappings m where m.assessment_blueprint_id=learning_sessions.assessment_blueprint_id and m.unit_id=b.unit_id and m.curriculum_release_id=b.curriculum_release_id))) and status='active'
    and (v_mode<>'diagnostic' or learning_sessions.mode not in ('practice','chapter_review'))
    order by started_at,id limit 1 for update;
  if found then return private.authorized_governed_result(p_student_id,p_auth_session_id,p_enrollment_id,b.curriculum_release_id,b.unit_id,jsonb_build_object('session',private.learner_governed_session(to_jsonb(s)),'resumed',true,'modeConflict',s.mode<>v_mode,
    'legacySession',s.assessment_policy_binding_id is null)); end if;
  baseline:=private.scoped_chapter_baseline(p_student_id,b.curriculum_release_id,b.unit_id);
  if v_mode='diagnostic' then
    if baseline is not null then return private.authorized_governed_result(p_student_id,p_auth_session_id,p_enrollment_id,b.curriculum_release_id,b.unit_id,jsonb_build_object('diagnosticCompleted',true,'baselineSessionId',baseline)); end if;
    if exists (select 1 from public.learning_sessions prior where prior.student_id=p_student_id
      and prior.mode='diagnostic' and prior.status in ('active','completed')
      and ((prior.assessment_policy_binding_id is not null and prior.subject_program_id=b.subject_program_id and prior.governed_unit_id=b.unit_id)
        or (prior.assessment_policy_binding_id is null and prior.unit_code=code and (
          prior.curriculum_release_id is null or exists (
            select 1 from public.curriculum_releases r where r.id=prior.curriculum_release_id and r.subject_program_id=b.subject_program_id))))) then
      raise exception 'diagnostic_baseline_requires_governed_mapping'; end if;
  elsif baseline is null then raise exception 'chapter_diagnostic_required'; end if;
  policy:=private.validate_assessment_policy_v1(b.assessment_blueprint_id);
  if p_item_ids is null or cardinality(p_item_ids)<>(policy->>'plannedQuestionCount')::integer
    or (v_mode<>'practice' and (select count(distinct i) from unnest(p_item_ids) i)<>cardinality(p_item_ids))
    or array_position(p_item_ids,null) is not null then raise exception 'governed_session_items_invalid'; end if;
  -- Lock selected memberships/content before validating, preventing concurrent
  -- retirement or pool removal from winning between the check and the insert.
  perform 1 from public.items where id=any(p_item_ids) order by id for share;
  perform 1 from public.assessment_pool_items where pool_id=(select assessment_pool_id from public.assessment_blueprints where id=b.assessment_blueprint_id)
    and item_id=any(p_item_ids) order by item_id for share;
  if exists (select 1 from unnest(p_item_ids) picked(id) where not exists (
    select 1 from public.assessment_blueprint_items bi join public.items i on i.id=bi.item_id
    join public.assessment_pool_items pi on pi.item_id=i.id
    join public.assessment_blueprints bp on bp.id=bi.assessment_blueprint_id and bp.assessment_pool_id=pi.pool_id
    where bp.id=b.assessment_blueprint_id and i.id=picked.id and i.status='published' and pi.enabled
      and i.version_no=bi.item_version_snapshot and (p_target_skill_id is null or i.skill_id=p_target_skill_id)))
  then raise exception 'governed_session_items_invalid'; end if;
  if v_mode='diagnostic' then
    if p_target_skill_id is not null then raise exception 'governed_session_items_invalid'; end if;
    perform 1 from public.assessment_forms where id=p_form_id for share;
    perform 1 from public.assessment_form_items where form_id=p_form_id order by item_id for share;
    if not exists (select 1 from public.assessment_forms f join public.assessment_blueprints bp on bp.assessment_pool_id=f.pool_id
      where f.id=p_form_id and f.status='active' and bp.id=b.assessment_blueprint_id)
      or (select count(*) from public.assessment_form_items where form_id=p_form_id)<>cardinality(p_item_ids)
      or exists (select 1 from public.assessment_form_items where form_id=p_form_id and not (item_id=any(p_item_ids)))
    then raise exception 'governed_diagnostic_form_invalid'; end if;
    for entry in select * from jsonb_each_text(policy->'questionCountBySkill') loop
      if (select count(*) from public.items where id=any(p_item_ids) and skill_id=entry.key::uuid)<>entry.value::integer then
        raise exception 'governed_diagnostic_coverage_invalid'; end if;
    end loop;
    if exists (select 1 from public.items where id=any(p_item_ids) and not (policy->'questionCountBySkill' ? skill_id::text)) then
      raise exception 'governed_diagnostic_coverage_invalid'; end if;
  elsif v_mode<>'mastery_check' and p_form_id is not null then raise exception 'governed_session_items_invalid'; end if;
  if v_mode='mastery_check' then
    if p_target_skill_id is not null then raise exception 'governed_session_items_invalid'; end if;
    form_selection:=private.validate_mastery_form_selection(b.assessment_blueprint_id,policy);
    if form_selection is null then
      if p_form_id is not null then raise exception 'governed_session_items_invalid'; end if;
    else
      select snapshot_fingerprint into form_fingerprint from private.mastery_form_selection_bindings
        where assessment_policy_binding_id=b.id and selection_snapshot=form_selection;
      if not found then raise exception 'mastery_form_selection_unbound'; end if;
      select value into selected_form from jsonb_array_elements(form_selection->'forms')
        where value->>'formId'=p_form_id::text;
      if selected_form is null or jsonb_array_length(selected_form->'items')<>cardinality(p_item_ids)
        or exists(select 1 from jsonb_array_elements(selected_form->'items') x where not ((x->>'itemId')::uuid=any(p_item_ids)))
      then raise exception 'governed_mastery_form_invalid'; end if;
      if exists(select 1 from unnest(p_item_ids) x where private.mastery_form_item_seen(p_student_id,x))
      then raise exception 'governed_mastery_form_exposed'; end if;
    end if;
    for entry in select * from jsonb_each_text(policy->'questionCountBySkill') loop
      if (select count(*) from public.items where id=any(p_item_ids) and skill_id=entry.key::uuid)<>entry.value::integer then raise exception 'governed_mastery_coverage_invalid'; end if;
    end loop;
  end if;
  if v_mode<>'practice' then
    -- Retain existing standalone order; normalize only when a set is selected.
    if exists(select 1 from public.items where id=any(p_item_ids) and stimulus->>'kind'='task_set') then
      p_item_ids:=private.order_task_set_items(p_item_ids,p_student_id::text||':'||coalesce(p_form_id::text,b.id::text));
    end if;
    if v_mode in ('diagnostic','mastery_check') and exists(select 1 from unnest(p_item_ids) x where private.source_family_seen(p_student_id,private.item_source_family(x))) then raise exception 'source_family_exposed_or_reserved'; end if;
  end if;
  details:=private.prepare_governed_lifecycle(p_student_id,b.id);
  if form_fingerprint is not null then
    details:=details||jsonb_build_object('masteryFormSelectionFingerprint',form_fingerprint,
      'masteryFormSelectionSchema','haiedu-mastery-form-selection-v1');
  end if;
  insert into public.learning_sessions(student_id,unit_code,mode,planned_item_count,curriculum_release_id,
    assessment_blueprint_id,institutional_class_enrollment_id,assessment_policy_binding_id,governed_unit_id,
    source_auth_session_id,target_skill_id,metadata,mastery_attempt_number)
  values(p_student_id,code,v_mode,cardinality(p_item_ids),b.curriculum_release_id,b.assessment_blueprint_id,
    p_enrollment_id,b.id,b.unit_id,p_auth_session_id,p_target_skill_id,jsonb_build_object('assessmentFormId',p_form_id)||details,(details->>'attemptNumber')::smallint) returning * into s;
  insert into public.learning_session_items(session_id,ordinal,item_id,skill_id,selection_reason)
    select s.id,x.ordinal::integer,i.id,i.skill_id,'governed-policy-assignment-v1'
    from unnest(p_item_ids) with ordinality x(id,ordinal) join public.items i on i.id=x.id where v_mode<>'practice';
  perform private.attach_governed_lifecycle(s.id,details);
  return private.authorized_governed_result(p_student_id,p_auth_session_id,p_enrollment_id,b.curriculum_release_id,b.unit_id,jsonb_build_object('session',private.learner_governed_session(to_jsonb(s)),'resumed',false)||details);
end;
$function$;

ALTER FUNCTION "public"."service_start_governed_session_atomic"(p_student_id uuid, p_auth_session_id uuid, p_enrollment_id uuid, p_policy_binding_id uuid, p_form_id uuid, p_target_skill_id uuid, p_item_ids uuid[]) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_student_learning_dashboard(p_student_id uuid, p_auth_session_id uuid, p_enrollment_id uuid, p_release_id uuid, p_unit_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.institutional_class_enrollments%rowtype; u public.curriculum_release_units%rowtype;
 bp public.assessment_blueprints%rowtype; model public.learning_model_configurations%rowtype;
 state public.chapter_mastery_states%rowtype; life public.academic_mastery_policy_versions%rowtype;
 baseline public.learning_sessions%rowtype; active public.learning_sessions%rowtype;
 modes jsonb:='{}'; policy jsonb; spec jsonb; skills jsonb; history jsonb; skill_ids uuid[];
 extension text; selected_model uuid; legacy boolean; n integer; key text; hidden boolean; result jsonb;
begin
 e:=private.lock_student_learning_context(p_student_id,p_auth_session_id,p_enrollment_id,p_release_id,p_unit_id);
 select * into strict u from public.curriculum_release_units where curriculum_release_id=p_release_id and unit_id=p_unit_id;
 select * into state from public.chapter_mastery_states where student_id=p_student_id and curriculum_release_id=p_release_id and unit_code=u.unit_code_snapshot;
 select * into baseline from public.learning_sessions where id=private.scoped_chapter_baseline(p_student_id,p_release_id,p_unit_id);
 select * into active from public.learning_sessions s where s.student_id=p_student_id and s.curriculum_release_id=p_release_id and s.status='active'
 and ((s.institutional_class_enrollment_id=p_enrollment_id and s.governed_unit_id=p_unit_id and s.assessment_policy_binding_id is not null)
 or (s.assessment_policy_binding_id is null and exists(select 1 from public.legacy_learning_blueprint_mappings m
     where m.assessment_blueprint_id=s.assessment_blueprint_id and m.curriculum_release_id=s.curriculum_release_id
     and m.unit_id=p_unit_id and m.subject_program_id=e.subject_program_id and m.unit_code_snapshot=s.unit_code)))
 order by case when baseline.id is null and s.mode='diagnostic' then 0 else 1 end,s.started_at,s.id limit 1;
 -- An active assessment must not reveal running correctness through mastery rows.
 hidden:=active.id is not null and active.mode in ('diagnostic','mastery_check');
 select array_agg(distinct i.skill_id order by i.skill_id) into skill_ids from public.assessment_blueprints b
 join public.assessment_blueprint_items bi on bi.assessment_blueprint_id=b.id
 join public.items i on i.id=bi.item_id
 where b.curriculum_release_id=p_release_id and b.unit_id=p_unit_id and b.status in ('pilot','production');
 for key in select unnest(array['diagnostic','practice','mastery_check','chapter_review']) loop
   select * into bp from public.assessment_blueprints b where b.curriculum_release_id=p_release_id and b.unit_id=p_unit_id
     and b.purpose=key and b.status in ('pilot','production') and b.published_at is not null order by b.version_number desc,b.id limit 1;
   if bp.id is null then modes:=modes||jsonb_build_object(key,jsonb_build_object('status','unconfigured'));continue;end if;
   if (select count(*) from public.assessment_blueprints b where b.curriculum_release_id=p_release_id and b.unit_id=p_unit_id
     and b.purpose=key and b.status in ('pilot','production') and b.version_number=bp.version_number)<>1 then
     raise exception 'assessment_blueprint_unavailable';end if;
   select m.extension_key into extension from public.legacy_learning_blueprint_mappings m where m.assessment_blueprint_id=bp.id
     and m.curriculum_release_id=p_release_id and m.unit_id=p_unit_id and m.subject_program_id=e.subject_program_id;
   legacy:=extension is not null and not (bp.configuration_snapshot ? 'assessmentPolicy');
   if legacy then
     select lm.* into strict model from public.learning_model_runtime_bindings rb join public.learning_model_configurations lm
       on lm.id=rb.learning_model_configuration_id where rb.curriculum_release_id=p_release_id and rb.unit_code=u.unit_code_snapshot and rb.status='active';
     -- The registered legacy extension reads its immutable model; no new policy
     -- is synthesized or attached to old sessions. Counts preserve this adapter.
     n:=case key when 'diagnostic' then cardinality(skill_ids)*(model.configuration#>>'{diagnostic,itemsPerSkill}')::integer
       when 'mastery_check' then cardinality(skill_ids)*(model.configuration#>>'{masteryCheck,itemsPerSkill}')::integer
       when 'practice' then (model.configuration#>>'{practice,plannedSessionLength}')::integer
       else (bp.configuration_snapshot->>'targetQuestions')::integer end;
     if n is null or n<1 then raise exception 'legacy_navigation_contract_unavailable';end if;
     spec:=jsonb_build_object('status','registered_legacy','extensionKey',extension,'questions',n,
       'hintsAllowed',case when key in ('diagnostic','mastery_check') then false else true end,
       'minimumPercent',case when key='mastery_check' then model.configuration#>'{masteryCheck,overallPassPercent}' else null end,
       'minimumCorrectBySkill',case when key='mastery_check' then (select jsonb_object_agg(k::text,model.configuration#>'{masteryCheck,minimumCorrectPerSkill}') from unnest(skill_ids) k) else null end,
       'learningModelConfigurationId',model.id);
     if key='mastery_check' then selected_model:=model.id;end if;
   elsif bp.configuration_snapshot ? 'assessmentPolicy' then
     policy:=private.validate_assessment_policy_v1(bp.id);
     perform private.validate_governed_learning_model((policy->>'learningModelConfigurationId')::uuid);
     spec:=jsonb_build_object('status','configured','questions',policy->'plannedQuestionCount','hintsAllowed',policy->'hintsAllowed',
       'responseTypes',policy->'responseTypes','scoringStrategy',policy->'scoringStrategy','minimumPercent',policy->'minimumPercent',
       'schemaVersion',policy->'schemaVersion','deliveredSkillIds',policy->'deliveredSkillIds','scoredSkillIds',policy->'scoredSkillIds','readinessSkillIds',policy->'readinessSkillIds','reportingGroups',policy->'reportingGroups','questionCountBySkill',policy->'questionCountBySkill',
       'minimumCorrectBySkill',policy->'minimumCorrectBySkill','policyVersion',policy->'version',
       'learningModelConfigurationId',policy->'learningModelConfigurationId','academicMasteryPolicyId',policy->'academicMasteryPolicyId');
     if key='mastery_check' then selected_model:=(policy->>'learningModelConfigurationId')::uuid;end if;
   else spec:=jsonb_build_object('status','unconfigured');end if;
   modes:=modes||jsonb_build_object(key,spec||jsonb_build_object('blueprintId',bp.id,'blueprintVersion',bp.version_number));
 end loop;
 select * into life from public.academic_mastery_policy_versions where id=coalesce(state.academic_mastery_policy_id,
   (modes#>>'{mastery_check,academicMasteryPolicyId}')::uuid);
 if life.id is null and modes#>>'{mastery_check,status}'='registered_legacy' then
   select * into strict life from public.academic_mastery_policy_versions where status='active';
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',rs.skill_id,'code',rs.skill_code_snapshot,'nameHy',rs.name_hy_snapshot,
   'layer',rs.layer_snapshot,'sequenceOrder',rs.sequence_order_snapshot,
   'requiredForReadiness',case when modes#>>'{mastery_check,schemaVersion}' in ('haiedu-assessment-policy-v2','haiedu-assessment-policy-v3','haiedu-assessment-policy-v4') then modes#>'{mastery_check,readinessSkillIds}' ? rs.skill_id::text else true end,
   'ready',case when selected_model is null or hidden then null else private.governed_skill_ready(p_student_id,p_release_id,rs.skill_id,selected_model) end,
   'mastery',case when hidden or m.skill_id is null then null else jsonb_build_object('score',m.mastery_score,'percent',round(100*m.mastery_score),
     'evidenceCount',m.evidence_count,'status',m.status,'scope','learner_release_skill','modelId',selected_model) end) order by rs.sequence_order_snapshot,rs.skill_id),'[]') into skills
 from public.curriculum_release_skills rs left join public.student_skill_mastery_by_release m
   on m.student_id=p_student_id and m.curriculum_release_id=rs.curriculum_release_id and m.skill_id=rs.skill_id
 where rs.curriculum_release_id=p_release_id and rs.skill_id=any(skill_ids);
 select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'mode',s.mode,'status',s.status,'answered',s.answered_count,'planned',s.planned_item_count,
   'assessmentResult',s.metadata->'assessmentResultReporting','correct',s.correct_count,'percent',coalesce((s.metadata#>>'{assessmentResultReporting,score,percent}')::numeric,(s.metadata#>>'{assessmentResultReporting,overallScore,percent}')::numeric,s.score_percent,round(100.0*s.correct_count/nullif(s.answered_count,0))),
   'result',s.assessment_result,'attemptNumber',s.mastery_attempt_number,'completedAt',s.completed_at,
   'curriculumReleaseId',s.curriculum_release_id,'blueprintId',s.assessment_blueprint_id,'policyBindingId',s.assessment_policy_binding_id,
   'modelId',s.learning_model_configuration_id,'runtimeBuildId',s.runtime_build_id,'academicMasteryPolicyId',s.academic_mastery_policy_id,
   'provenanceStatus',s.provenance_status,'modelProvenanceStatus',s.model_provenance_status,'runtimeProvenanceStatus',s.runtime_provenance_status)
   order by s.completed_at desc,s.id),'[]') into history from
 (select s.* from public.learning_sessions s where s.student_id=p_student_id and s.curriculum_release_id=p_release_id and s.status='completed'
 and ((s.institutional_class_enrollment_id=p_enrollment_id and s.governed_unit_id=p_unit_id)
 or (s.assessment_policy_binding_id is null and exists(select 1 from public.legacy_learning_blueprint_mappings m
   where m.assessment_blueprint_id=s.assessment_blueprint_id and m.unit_id=p_unit_id and m.subject_program_id=e.subject_program_id and m.curriculum_release_id=s.curriculum_release_id)))
 order by s.completed_at desc,s.id limit 50) s;
 result:=jsonb_build_object('dashboardVersion','authorized-learning-dashboard-v1','modes',modes,'skills',skills,
   'practiceAccess',jsonb_build_object('unlocked',baseline.id is not null,'reason',case when baseline.id is null then 'chapter_diagnostic_required' end),
   'baseline',case when baseline.id is null then null else jsonb_build_object('id',baseline.id,'assessmentResult',baseline.metadata->'assessmentResultReporting','correct',baseline.correct_count,'answered',baseline.answered_count,
     'percent',coalesce((baseline.metadata#>>'{assessmentResultReporting,overallScore,percent}')::numeric,round(100.0*baseline.correct_count/nullif(baseline.answered_count,0))),'completedAt',baseline.completed_at,
     'curriculumReleaseId',baseline.curriculum_release_id,'provenanceStatus',baseline.provenance_status,'policyBindingId',baseline.assessment_policy_binding_id) end,
   'activeSession',case when active.id is null then null else jsonb_build_object('id',active.id,'mode',active.mode,'answered',active.answered_count,
     'planned',active.planned_item_count,'policyBindingId',active.assessment_policy_binding_id,'targetSkillId',active.target_skill_id) end,
   'lifecycle',case when state.id is null then null else jsonb_build_object('state',state.lifecycle_state,'attemptsUsed',state.attempts_used,
     'passedOnAttempt',state.passed_on_attempt,'policyId',state.academic_mastery_policy_id,'historyProvenance',state.history_provenance) end,
   'maximumAttempts',life.maximum_mastery_attempts,'history',history,'readOnly',true);
 return private.authorized_governed_result(p_student_id,p_auth_session_id,p_enrollment_id,p_release_id,p_unit_id,result);
end;
$function$;

ALTER FUNCTION "public"."service_student_learning_dashboard"(p_student_id uuid, p_auth_session_id uuid, p_enrollment_id uuid, p_release_id uuid, p_unit_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.service_student_learning_navigation(p_student_id uuid, p_auth_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record; contexts jsonb:='[]'; context jsonb; c jsonb;
begin
 perform private.assert_student_dashboard_session(p_student_id,p_auth_session_id);
 for r in
 select e.id enrollment_id,cr.id release_id,u.unit_id
 from public.institutional_class_enrollments e
 join public.curriculum_releases cr on cr.subject_program_id=e.subject_program_id
 join public.curriculum_release_units u on u.curriculum_release_id=cr.id
 where e.student_id=p_student_id and e.status='active' and cr.status in ('pilot','production')
 order by e.id,cr.release_number,u.sequence_order_snapshot,u.unit_id
 loop
   begin
     perform private.lock_student_learning_context(p_student_id,p_auth_session_id,r.enrollment_id,r.release_id,r.unit_id);
   exception when raise_exception then
     if sqlerrm<>'learning_context_unavailable' then raise; end if;
     continue;
   end;
   select jsonb_build_object('enrollmentId',e.id,'schoolId',e.school_id,'schoolName',sch.name,
     'academicYearId',e.academic_year_id,'academicYearLabel',y.label,'classId',e.class_id,'className',cl.name,
     'teacherAssignmentId',e.teacher_assignment_id,'subjectProgramId',e.subject_program_id,
     'subjectId',sp.subject_id,'subjectCode',s.code,'subjectNameHy',s.name_hy,'gradeId',sp.grade_id,
     'gradeNumber',g.grade_number,'gradeLabelHy',g.label_hy,'curriculumReleaseId',r.release_id,
     'releaseNumber',cr.release_number,'unitId',ru.unit_id,'unitCode',ru.unit_code_snapshot,
     'unitTitleHy',ru.title_hy_snapshot,'unitSequence',ru.sequence_order_snapshot,
     'extensionKey',(select min(m.extension_key) from public.legacy_learning_blueprint_mappings m
       where m.curriculum_release_id=r.release_id and m.unit_id=r.unit_id and m.subject_program_id=e.subject_program_id
       having count(distinct m.extension_key)=1),
     'hasPublishedAssessment',exists(select 1 from public.assessment_blueprints bp where bp.curriculum_release_id=r.release_id
       and bp.unit_id=r.unit_id and bp.status in ('pilot','production') and bp.published_at is not null)) into context
   from public.institutional_class_enrollments e join public.classes cl on cl.id=e.class_id
   join public.schools sch on sch.id=e.school_id join public.academic_years y on y.id=e.academic_year_id
   join public.subject_programs sp on sp.id=e.subject_program_id join public.subjects s on s.id=sp.subject_id
   join public.grades g on g.id=sp.grade_id join public.curriculum_releases cr on cr.id=r.release_id
   join public.curriculum_release_units ru on ru.curriculum_release_id=cr.id and ru.unit_id=r.unit_id where e.id=r.enrollment_id;
   contexts:=contexts||jsonb_build_array(context);
 end loop;
 -- Recheck the clock for every returned entitlement, even after later lock waits.
 for c in select value from jsonb_array_elements(contexts) loop
   perform private.lock_student_learning_context(p_student_id,p_auth_session_id,(c->>'enrollmentId')::uuid,
     (c->>'curriculumReleaseId')::uuid,(c->>'unitId')::uuid);
 end loop;
 perform private.assert_student_dashboard_session(p_student_id,p_auth_session_id);
 return jsonb_build_object('navigationVersion','authorized-learning-navigation-v1','contexts',contexts,'readOnly',true);
end;
$function$;

ALTER FUNCTION "public"."service_student_learning_navigation"(p_student_id uuid, p_auth_session_id uuid) OWNER TO postgres;

