CREATE OR REPLACE FUNCTION public.stamp_learning_session_academic_context_14c()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_ids uuid[]; v_active_context_count integer; v_context record;
begin
  if new.assessment_policy_binding_id is not null then return new; end if;
  if new.academic_context_status is not null
     or new.institutional_class_enrollment_id is not null or new.school_id is not null
     or new.academic_year_id is not null or new.class_id is not null
     or new.teacher_assignment_id is not null or new.subject_program_id is not null then
    raise exception 'academic context is server-derived' using errcode='P0001';
  end if;
  select array_agg(e.id order by e.valid_from desc,e.id)
           filter (where r.id is not null),
         count(*)
    into v_ids,v_active_context_count
  from public.institutional_class_enrollments e
  join public.classes c on c.id=e.class_id and c.school_id=e.school_id
    and c.academic_year_id=e.academic_year_id
  join public.academic_years y on y.id=e.academic_year_id and y.school_id=e.school_id
  join public.teacher_assignments a on a.id=e.teacher_assignment_id
    and a.school_id=e.school_id and a.class_id=e.class_id
    and a.academic_year_id=e.academic_year_id and a.subject_program_id=e.subject_program_id
  left join public.curriculum_releases r on r.id=new.curriculum_release_id
    and r.subject_program_id=e.subject_program_id
  where e.student_id=new.student_id and e.status='active' and e.valid_from<=now()
    and (e.valid_to is null or e.valid_to>now())
    and c.is_active and y.status='active'
    and current_date between y.starts_on and y.ends_on
    and a.status='active' and a.valid_from<=now()
    and (a.valid_to is null or a.valid_to>now());
  if coalesce(cardinality(v_ids),0)>1 then
    raise exception 'ambiguous student academic context' using errcode='P0001';
  end if;
  if coalesce(cardinality(v_ids),0)=1 then
    select * into v_context from public.institutional_class_enrollments where id=v_ids[1];
    new.institutional_class_enrollment_id:=v_context.id;
    new.school_id:=v_context.school_id;
    new.academic_year_id:=v_context.academic_year_id;
    new.class_id:=v_context.class_id;
    new.teacher_assignment_id:=v_context.teacher_assignment_id;
    new.subject_program_id:=v_context.subject_program_id;
    new.academic_context_status:='exact';
  elsif v_active_context_count>0 then
    raise exception 'institutional academic context unavailable' using errcode='P0001';
  else
    new.academic_context_status:='unbound_noninstitutional';
  end if;
  return new;
end;
$function$;

ALTER FUNCTION "public"."stamp_learning_session_academic_context_14c"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.stamp_learning_session_model_configuration()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  active_model_id uuid;
  active_runtime_id uuid;
  configured_release_id uuid;
begin
  if new.assessment_policy_binding_id is not null then return new; end if;
  select b.learning_model_configuration_id, b.runtime_build_id
    into active_model_id, active_runtime_id
  from public.learning_model_runtime_bindings b
  where b.curriculum_release_id=new.curriculum_release_id
    and b.unit_code=new.unit_code and b.status='active'
  limit 1;

  if active_model_id is null or active_runtime_id is null then
    raise exception 'No complete active model/runtime binding for release % / unit %',
      new.curriculum_release_id, new.unit_code;
  end if;
  if new.learning_model_configuration_id is not null
     and new.learning_model_configuration_id<>active_model_id then
    raise exception 'Session model configuration does not match active runtime binding';
  end if;
  if new.runtime_build_id is not null and new.runtime_build_id<>active_runtime_id then
    raise exception 'Session runtime build does not match active runtime binding';
  end if;

  select reference_curriculum_release_id into configured_release_id
  from public.learning_model_configurations where id=active_model_id;
  if configured_release_id is not null and configured_release_id<>new.curriculum_release_id then
    raise exception 'Active learning-model configuration is not bound to the session curriculum release';
  end if;

  new.learning_model_configuration_id:=active_model_id;
  new.model_provenance_status:='exact';
  new.runtime_build_id:=active_runtime_id;
  new.runtime_provenance_status:='exact';
  return new;
end;
$function$;

ALTER FUNCTION "public"."stamp_learning_session_model_configuration"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.start_chapter_review_atomic(p_student_id uuid, p_curriculum_release_id uuid, p_assessment_blueprint_id uuid, p_unit_code text, p_metadata jsonb, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_state public.chapter_mastery_states%rowtype;
  v_policy public.academic_mastery_policy_versions%rowtype;
  v_requirement public.chapter_review_requirements%rowtype;
  v_existing public.learning_sessions%rowtype;
  v_review public.chapter_review_sessions%rowtype;
  v_session public.learning_sessions%rowtype;
  v_context text;
  v_target integer;
  v_item_count integer;
begin
  if jsonb_typeof(p_items)<>'array' then raise exception 'invalid_review_items'; end if;
  perform pg_advisory_xact_lock(hashtextextended(
    p_student_id::text || '|' || p_curriculum_release_id::text || '|' || p_unit_code,0
  ));

  select * into v_state from public.chapter_mastery_states
  where student_id=p_student_id and curriculum_release_id=p_curriculum_release_id and unit_code=p_unit_code
  for update;
  if not found then raise exception 'chapter_mastery_state_not_found'; end if;
  select * into v_policy from public.academic_mastery_policy_versions where id=v_state.academic_mastery_policy_id;

  select ls.* into v_existing
  from public.chapter_review_sessions crs
  join public.learning_sessions ls on ls.id=crs.learning_session_id
  where crs.chapter_mastery_state_id=v_state.id and crs.status='active'
  limit 1 for update of crs,ls;
  if found then
    select * into v_review from public.chapter_review_sessions where learning_session_id=v_existing.id;
    return jsonb_build_object(
      'sessionId',v_existing.id,'reviewSessionId',v_review.id,
      'reviewContext',v_review.review_context,'required',v_review.review_requirement_id is not null,'resumed',true
    );
  end if;

  if v_state.lifecycle_state='review_required_attempt_2' then
    v_context:='required_after_attempt_1_failure';
  elsif v_state.lifecycle_state='review_required_attempt_3' then
    v_context:='required_after_attempt_2_failure';
  elsif v_state.lifecycle_state='mastery_passed' then
    v_context:='voluntary_after_mastery_pass';
  elsif v_state.lifecycle_state='mastery_failed_final' then
    v_context:='voluntary_after_final_failure';
  else
    raise exception 'chapter_review_not_available:%',v_state.lifecycle_state;
  end if;

  if v_context like 'required_%' then
    select * into v_requirement from public.chapter_review_requirements
    where chapter_mastery_state_id=v_state.id and status='required' for update;
    if not found then raise exception 'chapter_review_requirement_not_found'; end if;
  end if;

  v_target:=least(v_policy.target_review_question_count,jsonb_array_length(p_items));
  if v_target<1 or jsonb_array_length(p_items)<>v_target then raise exception 'invalid_review_item_count'; end if;

  insert into public.learning_sessions(
    student_id,curriculum_release_id,assessment_blueprint_id,unit_code,
    mode,planned_item_count,metadata,academic_mastery_policy_id
  ) values (
    p_student_id,p_curriculum_release_id,p_assessment_blueprint_id,p_unit_code,
    'chapter_review',v_target,coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('reviewContext',v_context),
    v_policy.id
  ) returning * into v_session;

  insert into public.learning_session_items(session_id,ordinal,skill_id,item_id,selection_reason)
  select v_session.id,x.ordinal,x.skill_id,x.item_id,x.selection_reason
  from jsonb_to_recordset(p_items) as x(ordinal integer,skill_id uuid,item_id uuid,selection_reason text);

  insert into public.chapter_review_sessions(
    learning_session_id,chapter_mastery_state_id,review_requirement_id,
    academic_mastery_policy_id,review_context,target_question_count
  ) values (
    v_session.id,v_state.id,case when v_context like 'required_%' then v_requirement.id else null end,
    v_policy.id,v_context,v_target
  ) returning * into v_review;

  return jsonb_build_object(
    'sessionId',v_session.id,'reviewSessionId',v_review.id,
    'reviewContext',v_context,'required',v_review.review_requirement_id is not null,'resumed',false
  );
end;
$function$;

ALTER FUNCTION "public"."start_chapter_review_atomic"(p_student_id uuid, p_curriculum_release_id uuid, p_assessment_blueprint_id uuid, p_unit_code text, p_metadata jsonb, p_items jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.start_chapter_review_atomic(p_student_id uuid, p_curriculum_release_id uuid, p_assessment_blueprint_id uuid, p_unit_code text, p_metadata jsonb, p_items jsonb, p_eligible_pool_size integer, p_expected_cycle_number integer, p_expected_session_number integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_state public.chapter_mastery_states%rowtype;
  v_policy public.academic_mastery_policy_versions%rowtype;
  v_requirement public.chapter_review_requirements%rowtype;
  v_existing public.learning_sessions%rowtype;
  v_review public.chapter_review_sessions%rowtype;
  v_session public.learning_sessions%rowtype;
  v_cycle public.chapter_review_cycles%rowtype;
  v_context text; v_target integer; v_cycle_seen integer; v_cycle_number integer;
  v_session_number integer; v_preceding_attempt smallint;
begin
  if jsonb_typeof(p_items)<>'array' then raise exception 'invalid_review_items'; end if;
  if p_eligible_pool_size<1 then raise exception 'invalid_review_pool_size'; end if;
  perform pg_advisory_xact_lock(hashtextextended(
    p_student_id::text||'|'||p_curriculum_release_id::text||'|'||p_unit_code,0));

  select * into v_state from public.chapter_mastery_states
  where student_id=p_student_id and curriculum_release_id=p_curriculum_release_id and unit_code=p_unit_code for update;
  if not found then raise exception 'chapter_mastery_state_not_found'; end if;
  select * into v_policy from public.academic_mastery_policy_versions where id=v_state.academic_mastery_policy_id;

  select ls.* into v_existing from public.chapter_review_sessions crs
  join public.learning_sessions ls on ls.id=crs.learning_session_id
  where crs.chapter_mastery_state_id=v_state.id and crs.status='active' limit 1 for update of crs,ls;
  if found then
    select * into v_review from public.chapter_review_sessions where learning_session_id=v_existing.id;
    return jsonb_build_object('sessionId',v_existing.id,'reviewSessionId',v_review.id,
      'reviewContext',v_review.review_context,'required',v_review.review_requirement_id is not null,
      'reviewCycleNumber',v_review.review_cycle_number,'reviewSessionNumber',v_review.review_session_number,'resumed',true);
  end if;

  if v_state.lifecycle_state='review_required_attempt_2' then v_context:='required_after_attempt_1_failure'; v_preceding_attempt:=1;
  elsif v_state.lifecycle_state='review_required_attempt_3' then v_context:='required_after_attempt_2_failure'; v_preceding_attempt:=2;
  elsif v_state.lifecycle_state='mastery_passed' then v_context:='voluntary_after_mastery_pass'; v_preceding_attempt:=v_state.passed_on_attempt;
  elsif v_state.lifecycle_state='mastery_failed_final' then v_context:='voluntary_after_final_failure'; v_preceding_attempt:=v_state.attempts_used;
  else raise exception 'chapter_review_not_available:%',v_state.lifecycle_state; end if;

  if v_context like 'required_%' then
    select * into v_requirement from public.chapter_review_requirements
    where chapter_mastery_state_id=v_state.id and status='required' for update;
    if not found then raise exception 'chapter_review_requirement_not_found'; end if;
  end if;

  v_target:=least(v_policy.target_review_question_count,p_eligible_pool_size);
  if jsonb_array_length(p_items)<>v_target then raise exception 'invalid_review_item_count'; end if;
  if (select count(distinct x.item_id) from jsonb_to_recordset(p_items) x(item_id uuid))<>v_target then
    raise exception 'duplicate_review_item';
  end if;

  select * into v_cycle from public.chapter_review_cycles
  where chapter_mastery_state_id=v_state.id and status='active' for update;
  if found then
    select count(distinct item_id) into v_cycle_seen from public.chapter_review_item_exposures where review_cycle_id=v_cycle.id;
    if v_cycle.eligible_pool_size<>p_eligible_pool_size or v_cycle_seen>=v_cycle.eligible_pool_size then
      update public.chapter_review_cycles set status='completed',completed_at=now() where id=v_cycle.id;
      v_cycle.id:=null;
    end if;
  end if;
  if v_cycle.id is null then
    select coalesce(max(cycle_number),0)+1 into v_cycle_number from public.chapter_review_cycles
      where chapter_mastery_state_id=v_state.id;
    insert into public.chapter_review_cycles(chapter_mastery_state_id,curriculum_release_id,unit_code,cycle_number,eligible_pool_size)
      values(v_state.id,p_curriculum_release_id,p_unit_code,v_cycle_number,p_eligible_pool_size) returning * into v_cycle;
  end if;
  v_cycle_number:=v_cycle.cycle_number;
  select coalesce(max(review_session_number),0)+1 into v_session_number
    from public.chapter_review_sessions where review_cycle_id=v_cycle.id;
  if p_expected_cycle_number<>v_cycle_number or p_expected_session_number<>v_session_number then
    raise exception 'stale_review_selection_context';
  end if;

  insert into public.learning_sessions(student_id,curriculum_release_id,assessment_blueprint_id,unit_code,
    mode,planned_item_count,metadata,academic_mastery_policy_id)
  values(p_student_id,p_curriculum_release_id,p_assessment_blueprint_id,p_unit_code,'chapter_review',v_target,
    coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('reviewContext',v_context,'reviewCycleNumber',v_cycle_number,
      'reviewSessionNumber',v_session_number,'eligiblePoolSize',p_eligible_pool_size),v_policy.id)
  returning * into v_session;

  insert into public.learning_session_items(session_id,ordinal,skill_id,item_id,selection_reason)
  select v_session.id,x.ordinal,x.skill_id,x.item_id,x.selection_reason
  from jsonb_to_recordset(p_items) x(ordinal integer,skill_id uuid,item_id uuid,selection_reason text);

  insert into public.chapter_review_sessions(learning_session_id,chapter_mastery_state_id,review_requirement_id,
    academic_mastery_policy_id,review_context,target_question_count,review_cycle_id,review_cycle_number,
    review_session_number,preceding_mastery_attempt_number,eligible_pool_size)
  values(v_session.id,v_state.id,case when v_context like 'required_%' then v_requirement.id else null end,
    v_policy.id,v_context,v_target,v_cycle.id,v_cycle_number,v_session_number,v_preceding_attempt,p_eligible_pool_size)
  returning * into v_review;

  insert into public.chapter_review_item_exposures(chapter_review_session_id,review_cycle_id,learning_session_item_id,
    item_id,item_code,item_version,item_template_id,template_code,item_family_id,family_code,variant_key,skill_id,
    selection_reason,prior_exposure_count,seen_in_current_cycle,exact_repeat,pool_exhausted)
  select v_review.id,v_cycle.id,lsi.id,i.id,i.code,i.version_no,i.item_template_id,t.code,t.item_family_id,f.code,
    i.variant_key,i.skill_id,lsi.selection_reason,
    (select count(*) from public.chapter_review_item_exposures pe join public.chapter_review_sessions prs on prs.id=pe.chapter_review_session_id
      where prs.chapter_mastery_state_id=v_state.id and pe.item_id=i.id),
    exists(select 1 from public.chapter_review_item_exposures ce where ce.review_cycle_id=v_cycle.id and ce.item_id=i.id),
    exists(select 1 from public.chapter_review_item_exposures ce where ce.review_cycle_id=v_cycle.id and ce.item_id=i.id),
    x.pool_exhausted
  from public.learning_session_items lsi
  join jsonb_to_recordset(p_items) x(ordinal integer,skill_id uuid,item_id uuid,selection_reason text,pool_exhausted boolean)
    on x.ordinal=lsi.ordinal and x.item_id=lsi.item_id
  join public.items i on i.id=lsi.item_id
  left join public.item_templates t on t.id=i.item_template_id left join public.item_families f on f.id=t.item_family_id
  where lsi.session_id=v_session.id;

  if exists(select 1 from public.chapter_review_item_exposures where chapter_review_session_id=v_review.id and exact_repeat and not pool_exhausted) then
    raise exception 'review_repeat_before_pool_exhaustion';
  end if;

  return jsonb_build_object('sessionId',v_session.id,'reviewSessionId',v_review.id,'reviewContext',v_context,
    'required',v_review.review_requirement_id is not null,'reviewCycleNumber',v_cycle_number,
    'reviewSessionNumber',v_session_number,'resumed',false);
end;
$function$;

ALTER FUNCTION "public"."start_chapter_review_atomic"(p_student_id uuid, p_curriculum_release_id uuid, p_assessment_blueprint_id uuid, p_unit_code text, p_metadata jsonb, p_items jsonb, p_eligible_pool_size integer, p_expected_cycle_number integer, p_expected_session_number integer) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.start_initial_diagnostic_atomic(p_student_id uuid, p_unit_code text, p_curriculum_release_id uuid, p_assessment_blueprint_id uuid, p_form_id uuid, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_session public.learning_sessions%rowtype;
  v_form public.assessment_forms%rowtype;
  v_pool public.assessment_pools%rowtype;
  v_count integer;
begin
  if p_student_id is null or p_unit_code is null then raise exception 'invalid_diagnostic_context'; end if;
  perform pg_advisory_xact_lock(hashtextextended('initial-diagnostic:' || p_student_id::text || ':' || p_unit_code, 0));
  select * into v_session from public.learning_sessions
    where student_id = p_student_id and unit_code = p_unit_code and mode = 'diagnostic' and status = 'completed'
    order by completed_at, id limit 1;
  if found then
    return jsonb_build_object('diagnosticCompleted', true, 'baselineSessionId', v_session.id);
  end if;
  select * into v_session from public.learning_sessions
    where student_id = p_student_id and unit_code = p_unit_code and status = 'active'
      and mode not in ('practice', 'chapter_review')
    order by started_at, id limit 1;
  if found then
    if v_session.mode = 'diagnostic' then
      return jsonb_build_object('session', to_jsonb(v_session), 'resumed', true);
    end if;
    return jsonb_build_object('activeSession', to_jsonb(v_session));
  end if;

  select * into v_form from public.assessment_forms where id = p_form_id and status = 'active';
  if not found then raise exception 'invalid_diagnostic_form'; end if;
  select * into v_pool from public.assessment_pools
    where id = v_form.pool_id and unit_code = p_unit_code and purpose = 'diagnostic' and status = 'active';
  if not found then raise exception 'invalid_diagnostic_pool'; end if;
  if not exists (select 1 from public.assessment_blueprints b join public.units u on u.id = b.unit_id
    where b.id = p_assessment_blueprint_id and b.curriculum_release_id = p_curriculum_release_id
      and b.assessment_pool_id = v_pool.id and b.purpose = 'diagnostic'
      and b.status in ('pilot', 'production') and u.code = p_unit_code) then
    raise exception 'invalid_diagnostic_blueprint';
  end if;
  if jsonb_typeof(p_items) is distinct from 'array' then raise exception 'invalid_diagnostic_items'; end if;
  select count(*) into v_count from public.assessment_form_items where form_id = p_form_id;
  if v_count = 0 or jsonb_array_length(p_items) <> v_count then raise exception 'incomplete_diagnostic_form'; end if;
  if (select count(distinct (value->>'item_id')) from jsonb_array_elements(p_items)) <> v_count then
    raise exception 'duplicate_diagnostic_items';
  end if;
  if exists (select 1 from jsonb_array_elements(p_items) entry
    where not exists (select 1 from public.assessment_form_items fi
      join public.items i on i.id = fi.item_id
      join public.assessment_blueprint_items bi on bi.item_id = i.id and bi.assessment_blueprint_id = p_assessment_blueprint_id
      where fi.form_id = p_form_id and i.id = (entry->>'item_id')::uuid
        and i.skill_id = (entry->>'skill_id')::uuid and i.status = 'published')) then
    raise exception 'ineligible_diagnostic_item';
  end if;
  -- Retain the existing two-items-per-skill diagnostic blueprint contract.
  if exists (select 1 from jsonb_array_elements(p_items) entry group by entry->>'skill_id' having count(*) <> 2) then
    raise exception 'invalid_diagnostic_skill_coverage';
  end if;

  insert into public.learning_sessions
    (student_id, unit_code, mode, curriculum_release_id, assessment_blueprint_id, planned_item_count, metadata)
  values (p_student_id, p_unit_code, 'diagnostic', p_curriculum_release_id, p_assessment_blueprint_id, v_count,
    jsonb_build_object('itemsPerSkill', 2, 'noRepeats', true, 'poolCode', v_pool.code,
      'selectionPolicyVersion', 'single-initial-diagnostic-v1', 'formCode', v_form.code,
      'formVersion', v_form.form_version, 'formSelectionReason', 'stable_student_chapter_assignment',
      'provisionalParallelism', true, 'maximumCompletedAttempts', 1))
    returning * into v_session;
  insert into public.learning_session_items (session_id, ordinal, skill_id, item_id, selection_reason)
    select v_session.id, ord::integer, (entry->>'skill_id')::uuid, (entry->>'item_id')::uuid,
      'diagnostic_initial_assignment:' || v_form.code
    from jsonb_array_elements(p_items) with ordinality as x(entry, ord);
  return jsonb_build_object('session', to_jsonb(v_session), 'resumed', false);
end;
$function$;

ALTER FUNCTION "public"."start_initial_diagnostic_atomic"(p_student_id uuid, p_unit_code text, p_curriculum_release_id uuid, p_assessment_blueprint_id uuid, p_form_id uuid, p_items jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.start_mastery_check_atomic(p_student_id uuid, p_curriculum_release_id uuid, p_assessment_blueprint_id uuid, p_unit_code text, p_planned_item_count integer, p_metadata jsonb, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_policy public.academic_mastery_policy_versions%rowtype;
  v_state public.chapter_mastery_states%rowtype;
  v_existing public.learning_sessions%rowtype;
  v_session public.learning_sessions%rowtype;
  v_attempt smallint;
  v_expected_items integer;
  v_review_id uuid;
begin
  if p_student_id is null or p_curriculum_release_id is null
     or p_assessment_blueprint_id is null or nullif(trim(p_unit_code),'') is null then
    raise exception 'missing_mastery_context';
  end if;
  if p_planned_item_count < 1 or p_planned_item_count > 100 then
    raise exception 'invalid_planned_item_count';
  end if;
  if jsonb_typeof(p_items)<>'array' then raise exception 'invalid_mastery_items'; end if;

  perform pg_advisory_xact_lock(hashtextextended(
    p_student_id::text || '|' || p_curriculum_release_id::text || '|' || p_unit_code,0
  ));

  select p.* into v_policy
  from public.academic_mastery_policy_activation a
  join public.academic_mastery_policy_versions p on p.id=a.policy_id
  where a.singleton=true;
  if not found then raise exception 'active_mastery_policy_not_found'; end if;

  select * into v_existing from public.learning_sessions
  where student_id=p_student_id and curriculum_release_id=p_curriculum_release_id
    and unit_code=p_unit_code and mode='mastery_check' and status='active'
  order by created_at desc limit 1 for update;
  if found then
    return jsonb_build_object('sessionId',v_existing.id,'attemptNumber',v_existing.mastery_attempt_number,'resumed',true);
  end if;

  select * into v_state from public.chapter_mastery_states
  where student_id=p_student_id and curriculum_release_id=p_curriculum_release_id and unit_code=p_unit_code
  for update;
  if not found then
    insert into public.chapter_mastery_states(
      student_id,curriculum_release_id,unit_code,academic_mastery_policy_id,lifecycle_state
    ) values (p_student_id,p_curriculum_release_id,p_unit_code,v_policy.id,'mastery_ready')
    returning * into v_state;
  end if;

  if v_state.academic_mastery_policy_id<>v_policy.id then
    select * into v_policy from public.academic_mastery_policy_versions where id=v_state.academic_mastery_policy_id;
  end if;

  v_attempt:=case v_state.lifecycle_state
    when 'mastery_ready' then 1
    when 'mastery_retry_2_ready' then 2
    when 'mastery_retry_3_ready' then 3
    else null
  end;
  if v_attempt is null then raise exception 'mastery_check_not_allowed:%',v_state.lifecycle_state; end if;
  if v_attempt>v_policy.maximum_mastery_attempts then raise exception 'mastery_attempt_limit_reached'; end if;
  if v_attempt<>v_state.attempts_used+1 then raise exception 'mastery_attempt_sequence_invalid'; end if;

  if v_attempt>1 then
    select crs.id into v_review_id
    from public.chapter_review_requirements r
    join public.chapter_review_sessions crs on crs.id=r.qualifying_review_session_id
    where r.chapter_mastery_state_id=v_state.id
      and r.required_after_attempt=v_attempt-1
      and r.status='satisfied'
      and crs.qualifying=true and crs.status='completed';
    if v_review_id is null then raise exception 'qualifying_chapter_review_required'; end if;
  end if;

  select count(*) into v_expected_items from jsonb_array_elements(p_items);
  if v_expected_items<>p_planned_item_count then raise exception 'mastery_item_count_mismatch'; end if;

  insert into public.learning_sessions(
    student_id,curriculum_release_id,assessment_blueprint_id,unit_code,
    mode,planned_item_count,metadata,academic_mastery_policy_id,mastery_attempt_number
  ) values (
    p_student_id,p_curriculum_release_id,p_assessment_blueprint_id,p_unit_code,
    'mastery_check',p_planned_item_count,coalesce(p_metadata,'{}'::jsonb),
    v_policy.id,v_attempt
  ) returning * into v_session;

  insert into public.learning_session_items(session_id,ordinal,skill_id,item_id,selection_reason)
  select v_session.id,x.ordinal,x.skill_id,x.item_id,x.selection_reason
  from jsonb_to_recordset(p_items) as x(ordinal integer,skill_id uuid,item_id uuid,selection_reason text);

  insert into public.mastery_check_attempts(
    chapter_mastery_state_id,learning_session_id,attempt_number,
    academic_mastery_policy_id,preceding_required_review_id,status,started_at
  ) values (v_state.id,v_session.id,v_attempt,v_policy.id,v_review_id,'active',v_session.started_at);

  return jsonb_build_object('sessionId',v_session.id,'attemptNumber',v_attempt,'resumed',false);
end;
$function$;

ALTER FUNCTION "public"."start_mastery_check_atomic"(p_student_id uuid, p_curriculum_release_id uuid, p_assessment_blueprint_id uuid, p_unit_code text, p_planned_item_count integer, p_metadata jsonb, p_items jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.validate_calibration_change_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  scope_row public.calibration_analysis_scopes%rowtype;
  baseline_row public.learning_model_configurations%rowtype;
  approved_row public.learning_model_configurations%rowtype;
  contract_model_id uuid;
  contract_version text;
  metric_set_version text;
  pilot_run_key text;
begin
  select * into scope_row
  from public.calibration_analysis_scopes
  where id = new.analysis_scope_id;

  select c.reference_model_configuration_id, c.version_label, m.version_label, p.run_key
  into contract_model_id, contract_version, metric_set_version, pilot_run_key
  from public.calibration_evidence_contracts c
  join public.calibration_metric_sets m on m.id = scope_row.calibration_metric_set_id
  join public.pilot_runs p on p.id = scope_row.pilot_run_id
  where c.id = scope_row.calibration_evidence_contract_id;

  if contract_model_id is distinct from new.baseline_model_configuration_id then
    raise exception 'decision baseline must match the analysis scope contract baseline';
  end if;

  if new.eligible_evidence ->> 'analysisScopeKey' is distinct from scope_row.scope_key
     or new.eligible_evidence ->> 'contractVersion' is distinct from contract_version
     or new.eligible_evidence ->> 'metricSetVersion' is distinct from metric_set_version
     or new.eligible_evidence ->> 'pilotRunKey' is distinct from pilot_run_key then
    raise exception 'eligible evidence provenance must match the bound analysis scope';
  end if;

  select * into baseline_row
  from public.learning_model_configurations
  where id = new.baseline_model_configuration_id;

  if new.disposition = 'approved_change' then
    select * into approved_row
    from public.learning_model_configurations
    where id = new.approved_model_configuration_id;

    if approved_row.id is null
       or approved_row.configuration_kind <> 'approved'
       or approved_row.predecessor_id is distinct from baseline_row.id
       or approved_row.model_key is distinct from baseline_row.model_key
       or approved_row.reference_curriculum_release_id is distinct from baseline_row.reference_curriculum_release_id
       or approved_row.snapshot_fingerprint = baseline_row.snapshot_fingerprint then
      raise exception 'approved change must reference a distinct approved successor of the reviewed baseline';
    end if;
  end if;

  return new;
end;
$function$;

ALTER FUNCTION "public"."validate_calibration_change_decision"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.validate_institutional_enrollment_14b()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_member record; v_inv record;
begin
  if new.status <> 'active' then return new; end if;
  select person_id, role, school_id, status, valid_from, valid_to into v_member
    from public.institutional_memberships where id=new.student_membership_id for share;
  select recipient_user_id, school_id, class_id, academic_year_id, used_at, revoked_at
    into v_inv from public.institutional_invitations where id=new.invitation_id;
  if v_member.person_id is distinct from new.student_id or v_member.role is distinct from 'student'
     or v_member.school_id is distinct from new.school_id or v_member.status is distinct from 'active'
     or v_member.valid_from > now() or (v_member.valid_to is not null and v_member.valid_to <= now())
     or v_inv.recipient_user_id is distinct from new.student_id
     or v_inv.school_id is distinct from new.school_id
     or v_inv.class_id is distinct from new.class_id
     or v_inv.academic_year_id is distinct from new.academic_year_id
     or v_inv.revoked_at is not null then
    raise exception 'enrollment_identity_invalid' using errcode='23514';
  end if;
  return new;
end $function$;

ALTER FUNCTION "public"."validate_institutional_enrollment_14b"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.validate_item_curriculum_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_unit_program uuid; v_program_subject uuid; v_program_grade uuid; v_skill_subject uuid; v_skill_grade uuid;
begin
  select u.subject_program_id into v_unit_program from public.units u where u.id = new.unit_id;
  if v_unit_program is distinct from new.subject_program_id then raise exception 'curriculum_scope_unit_program_mismatch'; end if;
  select sp.subject_id, sp.grade_id into v_program_subject, v_program_grade from public.subject_programs sp where sp.id = new.subject_program_id;
  select s.subject_id, s.grade_id into v_skill_subject, v_skill_grade from public.items i join public.skills s on s.id = i.skill_id where i.id = new.item_id;
  if v_skill_subject is distinct from v_program_subject or v_skill_grade is distinct from v_program_grade then raise exception 'curriculum_scope_skill_program_mismatch'; end if;
  return new;
end; $function$;

ALTER FUNCTION "public"."validate_item_curriculum_scope"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.validate_mastery_attempt_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_session public.learning_sessions%rowtype;
  v_review public.chapter_review_sessions%rowtype;
  v_requirement public.chapter_review_requirements%rowtype;
begin
  select * into v_session from public.learning_sessions where id=new.learning_session_id;
  if not found or v_session.mode<>'mastery_check' then
    raise exception 'mastery_attempt_requires_mastery_session';
  end if;
  if v_session.mastery_attempt_number is distinct from new.attempt_number
     or v_session.academic_mastery_policy_id is distinct from new.academic_mastery_policy_id then
    raise exception 'mastery_attempt_session_identity_mismatch';
  end if;

  if new.attempt_number=1 then
    if new.preceding_required_review_id is not null then
      raise exception 'attempt_1_must_not_reference_review';
    end if;
  else
    if new.preceding_required_review_id is null then
      raise exception 'retry_requires_preceding_review';
    end if;
    select * into v_review from public.chapter_review_sessions
      where id=new.preceding_required_review_id;
    if not found
       or v_review.chapter_mastery_state_id<>new.chapter_mastery_state_id
       or v_review.status<>'completed'
       or not v_review.qualifying
       or v_review.preceding_mastery_attempt_number<>new.attempt_number-1 then
      raise exception 'invalid_preceding_review';
    end if;
    select * into v_requirement from public.chapter_review_requirements
      where id=v_review.review_requirement_id;
    if not found
       or v_requirement.chapter_mastery_state_id<>new.chapter_mastery_state_id
       or v_requirement.required_after_attempt<>new.attempt_number-1
       or v_requirement.status<>'satisfied'
       or v_requirement.qualifying_review_session_id<>v_review.id then
      raise exception 'invalid_satisfied_review_requirement';
    end if;
  end if;
  return new;
end;
$function$;

ALTER FUNCTION "public"."validate_mastery_attempt_integrity"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.validate_teacher_assignment_14a()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare m record; c record; p record; v_grant uuid;
begin
  select role,status,valid_from,valid_to into m from public.institutional_memberships
    where id=new.teacher_membership_id and school_id=new.school_id for share;
  select subject_id,grade_id into c from public.classes
    where id=new.class_id and school_id=new.school_id and academic_year_id=new.academic_year_id;
  select subject_id,grade_id into p from public.subject_programs where id=new.subject_program_id;
  if m.role is distinct from 'teacher' or c.subject_id is distinct from p.subject_id
     or c.grade_id is distinct from p.grade_id or c.subject_id is null then
    raise exception 'assignment_identity_mismatch' using errcode='23514'; end if;
  if new.status='active' then
    if m.status is distinct from 'active' or m.valid_from>now()
       or (m.valid_to is not null and m.valid_to<=now()) or new.valid_from<m.valid_from
       or (m.valid_to is not null and (new.valid_to is null or new.valid_to>m.valid_to)) then
      raise exception 'assignment_outside_teacher_membership' using errcode='23514'; end if;
    select id into v_grant from public.teacher_subject_authorizations
      where teacher_membership_id=new.teacher_membership_id
        and school_id=new.school_id and subject_id=p.subject_id
        and status='active' and valid_from<=now()
        and (valid_to is null or valid_to>now()) for share;
    if v_grant is null then
      raise exception 'assignment_outside_subject_authorization' using errcode='23514'; end if;
  end if;
  return new;
end $function$;

ALTER FUNCTION "public"."validate_teacher_assignment_14a"() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.version_skill_remediation_guide()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if row(
    new.skill_id,
    new.misconception_code,
    new.title_hy,
    new.strategy_hy,
    new.hint_1_hy,
    new.hint_2_hy,
    new.worked_example_hy,
    new.status,
    new.metadata
  ) is distinct from row(
    old.skill_id,
    old.misconception_code,
    old.title_hy,
    old.strategy_hy,
    old.hint_1_hy,
    old.hint_2_hy,
    old.worked_example_hy,
    old.status,
    old.metadata
  ) then
    new.guide_version := old.guide_version + 1;
  else
    new.guide_version := old.guide_version;
  end if;
  new.updated_at := now();
  return new;
end;
$function$;

ALTER FUNCTION "public"."version_skill_remediation_guide"() OWNER TO postgres;

