CREATE VIEW "private"."actor_rate_maintenance_health" ("job_present", "job_active", "schedule", "last_success_at", "failures_last_day", "counter_rows", "eligible_expired_rows", "oldest_eligible_expiry", "counter_storage_bytes", "maintenance_status") WITH (security_invoker=true) AS
 WITH job AS (
         SELECT job.jobid,
            job.active,
            job.schedule
           FROM cron.job
          WHERE ((job.jobname = 'haiedu-bf16-counter-maintenance'::text) AND (job.username = CURRENT_USER) AND (job.database = current_database()))
        ), runs AS (
         SELECT max(job_run_details.end_time) FILTER (WHERE (job_run_details.status = 'succeeded'::text)) AS last_success_at,
            count(*) FILTER (WHERE ((job_run_details.status = 'failed'::text) AND (job_run_details.start_time > (clock_timestamp() - '24:00:00'::interval)))) AS failures_last_day
           FROM cron.job_run_details
          WHERE (job_run_details.jobid = ( SELECT job.jobid
                   FROM job))
        ), counters AS (
         SELECT count(*) AS counter_rows,
            count(*) FILTER (WHERE ((actor_rate_buckets.expires_at <= clock_timestamp()) AND (actor_rate_buckets.debt_until_us <= ((EXTRACT(epoch FROM clock_timestamp()) * (1000000)::numeric))::bigint))) AS eligible_expired_rows,
            min(actor_rate_buckets.expires_at) FILTER (WHERE ((actor_rate_buckets.expires_at <= clock_timestamp()) AND (actor_rate_buckets.debt_until_us <= ((EXTRACT(epoch FROM clock_timestamp()) * (1000000)::numeric))::bigint))) AS oldest_eligible_expiry
           FROM private.actor_rate_buckets
        )
 SELECT (EXISTS ( SELECT 1
           FROM job)) AS job_present,
    COALESCE(( SELECT job.active
           FROM job), false) AS job_active,
    ( SELECT job.schedule
           FROM job) AS schedule,
    r.last_success_at,
    r.failures_last_day,
    c.counter_rows,
    c.eligible_expired_rows,
    c.oldest_eligible_expiry,
    pg_total_relation_size('private.actor_rate_buckets'::regclass) AS counter_storage_bytes,
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM job))) THEN 'job_missing'::text
            WHEN (NOT ( SELECT job.active
               FROM job)) THEN 'job_paused'::text
            WHEN (r.last_success_at IS NULL) THEN 'awaiting_first_success'::text
            WHEN (r.last_success_at < (clock_timestamp() - '00:45:00'::interval)) THEN 'cleanup_overdue'::text
            WHEN (r.failures_last_day > 0) THEN 'recent_failure'::text
            WHEN (c.oldest_eligible_expiry < (clock_timestamp() - '01:00:00'::interval)) THEN 'expired_backlog'::text
            ELSE 'ok'::text
        END AS maintenance_status
   FROM (runs r
     CROSS JOIN counters c);

ALTER VIEW "private"."actor_rate_maintenance_health" OWNER TO postgres;

CREATE VIEW "public"."assessment_item_purpose_eligibility_v" ("curriculum_release_id", "unit_id", "item_id", "practice_eligible", "review_eligible", "mastery_check_eligible", "eligible_purposes") WITH (security_invoker=true) AS
 SELECT ab.curriculum_release_id,
    ab.unit_id,
    abi.item_id,
    bool_or((ab.purpose = 'practice'::text)) AS practice_eligible,
    bool_or((ab.purpose = 'chapter_review'::text)) AS review_eligible,
    bool_or((ab.purpose = 'mastery_check'::text)) AS mastery_check_eligible,
    array_agg(DISTINCT ab.purpose ORDER BY ab.purpose) AS eligible_purposes
   FROM (public.assessment_blueprints ab
     JOIN public.assessment_blueprint_items abi ON ((abi.assessment_blueprint_id = ab.id)))
  WHERE (ab.status = ANY (ARRAY['pilot'::text, 'production'::text]))
  GROUP BY ab.curriculum_release_id, ab.unit_id, abi.item_id;

ALTER VIEW "public"."assessment_item_purpose_eligibility_v" OWNER TO postgres;

CREATE VIEW "public"."chapter_mastery_history_provenance_v" ("chapter_mastery_state_id", "student_id", "curriculum_release_id", "unit_code", "lifecycle_state", "attempts_used", "passed_on_attempt", "history_provenance", "recorded_attempts", "legacy_attempt_records", "attempt_numbers_valid") WITH (security_invoker=true) AS
 SELECT s.id AS chapter_mastery_state_id,
    s.student_id,
    s.curriculum_release_id,
    s.unit_code,
    s.lifecycle_state,
    s.attempts_used,
    s.passed_on_attempt,
    s.history_provenance,
    (count(a.id))::integer AS recorded_attempts,
    (count(*) FILTER (WHERE (a.provenance_status = 'legacy_attempt_history'::text)))::integer AS legacy_attempt_records,
    bool_and(((a.attempt_number >= 1) AND (a.attempt_number <= 3))) FILTER (WHERE (a.id IS NOT NULL)) AS attempt_numbers_valid
   FROM (public.chapter_mastery_states s
     LEFT JOIN public.mastery_check_attempts a ON ((a.chapter_mastery_state_id = s.id)))
  GROUP BY s.id, s.student_id, s.curriculum_release_id, s.unit_code, s.lifecycle_state, s.attempts_used, s.passed_on_attempt, s.history_provenance;

ALTER VIEW "public"."chapter_mastery_history_provenance_v" OWNER TO postgres;

CREATE VIEW "public"."chapter_review_coverage_v" ("chapter_mastery_state_id", "student_id", "curriculum_release_id", "unit_code", "current_cycle_number", "current_cycle_unique_items_seen", "current_cycle_eligible_pool_size", "current_cycle_coverage_percent", "lifetime_unique_items_seen", "total_item_exposures", "exact_repeat_count", "pool_exhaustion_event_count") WITH (security_invoker=true) AS
 WITH exposure AS (
         SELECT crs.chapter_mastery_state_id,
            (count(*))::integer AS total_item_exposures,
            (count(DISTINCT e_1.item_id))::integer AS lifetime_unique_items_seen,
            (count(*) FILTER (WHERE e_1.exact_repeat))::integer AS exact_repeat_count,
            (count(*) FILTER (WHERE e_1.pool_exhausted))::integer AS pool_exhaustion_event_count
           FROM (public.chapter_review_item_exposures e_1
             JOIN public.chapter_review_sessions crs ON ((crs.id = e_1.chapter_review_session_id)))
          GROUP BY crs.chapter_mastery_state_id
        ), current_cycle AS (
         SELECT c_1.chapter_mastery_state_id,
            c_1.cycle_number,
            c_1.eligible_pool_size,
            (count(DISTINCT e_1.item_id))::integer AS unique_items_seen
           FROM (public.chapter_review_cycles c_1
             LEFT JOIN public.chapter_review_item_exposures e_1 ON ((e_1.review_cycle_id = c_1.id)))
          WHERE (c_1.status = 'active'::text)
          GROUP BY c_1.chapter_mastery_state_id, c_1.cycle_number, c_1.eligible_pool_size
        )
 SELECT s.id AS chapter_mastery_state_id,
    s.student_id,
    s.curriculum_release_id,
    s.unit_code,
    c.cycle_number AS current_cycle_number,
    COALESCE(c.unique_items_seen, 0) AS current_cycle_unique_items_seen,
    c.eligible_pool_size AS current_cycle_eligible_pool_size,
        CASE
            WHEN ((c.eligible_pool_size IS NULL) OR (c.eligible_pool_size = 0)) THEN NULL::numeric
            ELSE round((((c.unique_items_seen)::numeric / (c.eligible_pool_size)::numeric) * (100)::numeric))
        END AS current_cycle_coverage_percent,
    COALESCE(e.lifetime_unique_items_seen, 0) AS lifetime_unique_items_seen,
    COALESCE(e.total_item_exposures, 0) AS total_item_exposures,
    COALESCE(e.exact_repeat_count, 0) AS exact_repeat_count,
    COALESCE(e.pool_exhaustion_event_count, 0) AS pool_exhaustion_event_count
   FROM ((public.chapter_mastery_states s
     LEFT JOIN exposure e ON ((e.chapter_mastery_state_id = s.id)))
     LEFT JOIN current_cycle c ON ((c.chapter_mastery_state_id = s.id)));

ALTER VIEW "public"."chapter_review_coverage_v" OWNER TO postgres;

CREATE VIEW "public"."chapter_review_item_catalog_v" ("item_id", "item_code", "item_version", "skill_id", "item_template_id", "template_code", "item_family_id", "family_code", "variant_key") WITH (security_invoker=true) AS
 SELECT i.id AS item_id,
    i.code AS item_code,
    i.version_no AS item_version,
    i.skill_id,
    i.item_template_id,
    t.code AS template_code,
    t.item_family_id,
    f.code AS family_code,
    i.variant_key
   FROM ((public.items i
     LEFT JOIN public.item_templates t ON ((t.id = i.item_template_id)))
     LEFT JOIN public.item_families f ON ((f.id = t.item_family_id)))
  WHERE (i.status = 'published'::public.content_status);

ALTER VIEW "public"."chapter_review_item_catalog_v" OWNER TO postgres;

CREATE VIEW "public"."chapter_review_item_evidence_v" ("id", "chapter_review_session_id", "review_cycle_id", "chapter_mastery_state_id", "review_context", "review_cycle_number", "review_session_number", "preceding_mastery_attempt_number", "learning_session_item_id", "item_id", "item_code", "item_version", "item_template_id", "template_code", "item_family_id", "family_code", "variant_key", "skill_id", "selection_reason", "prior_exposure_count", "seen_in_current_cycle", "exact_repeat", "pool_exhausted", "selected_at", "hint_level_used", "hint_used", "response_time_ms", "correct", "answered_at", "independent", "assisted") WITH (security_invoker=true) AS
 SELECT e.id,
    e.chapter_review_session_id,
    e.review_cycle_id,
    crs.chapter_mastery_state_id,
    crs.review_context,
    crs.review_cycle_number,
    crs.review_session_number,
    crs.preceding_mastery_attempt_number,
    e.learning_session_item_id,
    e.item_id,
    e.item_code,
    e.item_version,
    e.item_template_id,
    e.template_code,
    e.item_family_id,
    e.family_code,
    e.variant_key,
    e.skill_id,
    e.selection_reason,
    e.prior_exposure_count,
    e.seen_in_current_cycle,
    e.exact_repeat,
    e.pool_exhausted,
    e.selected_at,
    lsi.hint_level_used,
    a.hint_used,
    a.response_time_ms,
    a.correct,
    a.created_at AS answered_at,
        CASE
            WHEN (a.id IS NULL) THEN NULL::boolean
            ELSE (NOT COALESCE(a.hint_used, false))
        END AS independent,
        CASE
            WHEN (a.id IS NULL) THEN NULL::boolean
            ELSE COALESCE(a.hint_used, false)
        END AS assisted
   FROM (((public.chapter_review_item_exposures e
     JOIN public.chapter_review_sessions crs ON ((crs.id = e.chapter_review_session_id)))
     JOIN public.learning_session_items lsi ON ((lsi.id = e.learning_session_item_id)))
     LEFT JOIN public.attempts a ON ((a.id = lsi.attempt_id)));

ALTER VIEW "public"."chapter_review_item_evidence_v" OWNER TO postgres;

CREATE VIEW "public"."learning_evidence_stream_v" ("learning_session_id", "student_id", "curriculum_release_id", "unit_code", "mode", "status", "mastery_attempt_number", "review_context", "evidence_stream", "counts_toward_initial_practice_burden", "excluded_from_initial_practice_burden") WITH (security_invoker=true) AS
 SELECT ls.id AS learning_session_id,
    ls.student_id,
    ls.curriculum_release_id,
    ls.unit_code,
    ls.mode,
    ls.status,
    ls.mastery_attempt_number,
    crs.review_context,
        CASE
            WHEN (ls.mode = 'diagnostic'::text) THEN 'diagnostic'::text
            WHEN (ls.mode = 'practice'::text) THEN 'pre_mastery_practice'::text
            WHEN (ls.mode = 'mastery_check'::text) THEN 'mastery_check'::text
            WHEN (crs.review_context = ANY (ARRAY['required_after_attempt_1_failure'::text, 'required_after_attempt_2_failure'::text])) THEN 'required_post_failure_chapter_review'::text
            WHEN (crs.review_context = 'voluntary_after_mastery_pass'::text) THEN 'optional_post_pass_chapter_review'::text
            WHEN (crs.review_context = 'voluntary_after_final_failure'::text) THEN 'optional_post_final_failure_chapter_review'::text
            ELSE 'unclassified'::text
        END AS evidence_stream,
    (ls.mode = 'practice'::text) AS counts_toward_initial_practice_burden,
    (ls.mode = 'chapter_review'::text) AS excluded_from_initial_practice_burden
   FROM (public.learning_sessions ls
     LEFT JOIN public.chapter_review_sessions crs ON ((crs.learning_session_id = ls.id)));

ALTER VIEW "public"."learning_evidence_stream_v" OWNER TO postgres;

CREATE VIEW "public"."misconception_review_catalog_v" ("id", "skill_id", "code", "title_hy", "description_hy", "status", "created_at", "updated_at", "skill_code", "skill_name_hy", "skill_status", "subject_id", "subject_name_hy", "grade_id", "grade_number", "grade_label_hy", "units", "mapping_count", "review_revision", "last_action") WITH (security_invoker=true) AS
 SELECT m.id,
    m.skill_id,
    m.code,
    m.title_hy,
    m.description_hy,
    m.status,
    m.created_at,
    m.updated_at,
    s.code AS skill_code,
    s.name_hy AS skill_name_hy,
    (s.status)::text AS skill_status,
    sub.id AS subject_id,
    sub.name_hy AS subject_name_hy,
    g.id AS grade_id,
    g.grade_number,
    g.label_hy AS grade_label_hy,
    COALESCE(ctx.units, '[]'::jsonb) AS units,
    ( SELECT count(*) AS count
           FROM public.item_misconception_mappings mm
          WHERE (mm.misconception_id = m.id)) AS mapping_count,
    COALESCE(ev.revision_no, 0) AS review_revision,
    ev.action AS last_action
   FROM (((((public.misconceptions m
     JOIN public.skills s ON ((s.id = m.skill_id)))
     JOIN public.subjects sub ON ((sub.id = s.subject_id)))
     JOIN public.grades g ON ((g.id = s.grade_id)))
     LEFT JOIN LATERAL ( SELECT jsonb_agg(DISTINCT jsonb_build_object('id', u.id, 'code', u.code, 'titleHy', u.title_hy)) AS units
           FROM (((public.skill_outcomes so
             JOIN public.learning_outcomes lo ON ((lo.id = so.learning_outcome_id)))
             JOIN public.topics t ON ((t.id = lo.topic_id)))
             JOIN public.units u ON ((u.id = t.unit_id)))
          WHERE (so.skill_id = s.id)) ctx ON (true))
     LEFT JOIN LATERAL ( SELECT misconception_review_events.revision_no,
            misconception_review_events.action
           FROM public.misconception_review_events
          WHERE (misconception_review_events.misconception_id = m.id)
          ORDER BY misconception_review_events.revision_no DESC
         LIMIT 1) ev ON (true));

ALTER VIEW "public"."misconception_review_catalog_v" OWNER TO postgres;

CREATE VIEW "public"."pilot_entry_readiness_v" ("pilot_run_id", "run_key", "recorded_status", "target_release_key", "entry_gate_count", "passed_entry_gate_count", "open_entry_gate_count", "entry_ready", "closure_gate_count", "passed_closure_gate_count", "open_closure_gate_count", "closure_ready") WITH (security_invoker=true) AS
 SELECT pr.id AS pilot_run_id,
    pr.run_key,
    pr.status AS recorded_status,
    cr.release_key AS target_release_key,
    count(*) FILTER (WHERE (pgc.gate_stage = 'entry'::text)) AS entry_gate_count,
    count(*) FILTER (WHERE ((pgc.gate_stage = 'entry'::text) AND (pgc.status = 'passed'::text))) AS passed_entry_gate_count,
    count(*) FILTER (WHERE ((pgc.gate_stage = 'entry'::text) AND (pgc.status <> 'passed'::text))) AS open_entry_gate_count,
    bool_and((pgc.status = 'passed'::text)) FILTER (WHERE (pgc.gate_stage = 'entry'::text)) AS entry_ready,
    count(*) FILTER (WHERE (pgc.gate_stage = 'closure'::text)) AS closure_gate_count,
    count(*) FILTER (WHERE ((pgc.gate_stage = 'closure'::text) AND (pgc.status = 'passed'::text))) AS passed_closure_gate_count,
    count(*) FILTER (WHERE ((pgc.gate_stage = 'closure'::text) AND (pgc.status <> 'passed'::text))) AS open_closure_gate_count,
    bool_and((pgc.status = 'passed'::text)) AS closure_ready
   FROM ((public.pilot_runs pr
     JOIN public.curriculum_releases cr ON ((cr.id = pr.target_curriculum_release_id)))
     JOIN public.pilot_gate_checks pgc ON ((pgc.pilot_run_id = pr.id)))
  GROUP BY pr.id, pr.run_key, pr.status, cr.release_key;

ALTER VIEW "public"."pilot_entry_readiness_v" OWNER TO postgres;

CREATE VIEW "public"."pilot_evidence_detail_v" ("pilot_run_id", "run_key", "target_release_key", "learning_session_id", "source_release_key", "mode", "session_status", "provenance_status", "classification", "reason_code", "rationale", "closure_eligible", "attempt_count", "exposure_count", "classified_at", "calibration_eligible", "calibration_reason") WITH (security_invoker=true) AS
 WITH classified AS (
         SELECT pr.id AS pilot_run_id,
            pr.run_key,
            target_release.release_key AS target_release_key,
            s.id AS learning_session_id,
            source_release.release_key AS source_release_key,
            s.mode,
            s.status AS session_status,
            s.provenance_status,
            pec.classification,
            pec.reason_code,
            pec.rationale,
            ((pec.classification = 'compatible'::text) AND (s.curriculum_release_id = pr.target_curriculum_release_id) AND (s.provenance_status = 'exact'::text) AND (s.status = 'completed'::text) AND (NOT (s.metadata ? 'qaDisposition'::text)) AND (EXISTS ( SELECT 1
                   FROM public.pilot_gate_checks g
                  WHERE ((g.pilot_run_id = pr.id) AND (g.gate_code = 'participation_authorized'::text) AND (g.status = 'passed'::text)))) AND (EXISTS ( SELECT 1
                   FROM public.pilot_gate_checks g
                  WHERE ((g.pilot_run_id = pr.id) AND (g.gate_code = 'cohort_enrolled'::text) AND (g.status = 'passed'::text))))) AS closure_eligible,
            ( SELECT count(*) AS count
                   FROM public.attempts a
                  WHERE (a.learning_session_id = s.id)) AS attempt_count,
            ( SELECT count(*) AS count
                   FROM public.student_item_exposure_events e
                  WHERE (e.session_id = s.id)) AS exposure_count,
            pec.classified_at,
            false AS calibration_eligible,
            'metric_specific_rule_required'::text AS calibration_reason
           FROM ((((public.pilot_evidence_classifications pec
             JOIN public.pilot_runs pr ON ((pr.id = pec.pilot_run_id)))
             JOIN public.learning_sessions s ON ((s.id = pec.learning_session_id)))
             JOIN public.curriculum_releases target_release ON ((target_release.id = pr.target_curriculum_release_id)))
             JOIN public.curriculum_releases source_release ON ((source_release.id = s.curriculum_release_id)))
        ), unclassified AS (
         SELECT pr.id AS pilot_run_id,
            pr.run_key,
            target_release.release_key AS target_release_key,
            s.id AS learning_session_id,
            source_release.release_key AS source_release_key,
            s.mode,
            s.status AS session_status,
            s.provenance_status,
            'unclassified'::text AS classification,
            'classification_pending'::text AS reason_code,
            'Session is visible but excluded until pilot evidence classification is recorded.'::text AS rationale,
            false AS closure_eligible,
            ( SELECT count(*) AS count
                   FROM public.attempts a
                  WHERE (a.learning_session_id = s.id)) AS attempt_count,
            ( SELECT count(*) AS count
                   FROM public.student_item_exposure_events e
                  WHERE (e.session_id = s.id)) AS exposure_count,
            NULL::timestamp with time zone AS classified_at,
            false AS calibration_eligible,
            'classification_pending'::text AS calibration_reason
           FROM (((public.learning_sessions s
             JOIN public.pilot_runs pr ON ((pr.target_curriculum_release_id = s.curriculum_release_id)))
             JOIN public.curriculum_releases target_release ON ((target_release.id = pr.target_curriculum_release_id)))
             JOIN public.curriculum_releases source_release ON ((source_release.id = s.curriculum_release_id)))
          WHERE (NOT (EXISTS ( SELECT 1
                   FROM public.pilot_evidence_classifications pec
                  WHERE (pec.learning_session_id = s.id))))
        )
 SELECT classified.pilot_run_id,
    classified.run_key,
    classified.target_release_key,
    classified.learning_session_id,
    classified.source_release_key,
    classified.mode,
    classified.session_status,
    classified.provenance_status,
    classified.classification,
    classified.reason_code,
    classified.rationale,
    classified.closure_eligible,
    classified.attempt_count,
    classified.exposure_count,
    classified.classified_at,
    classified.calibration_eligible,
    classified.calibration_reason
   FROM classified
UNION ALL
 SELECT unclassified.pilot_run_id,
    unclassified.run_key,
    unclassified.target_release_key,
    unclassified.learning_session_id,
    unclassified.source_release_key,
    unclassified.mode,
    unclassified.session_status,
    unclassified.provenance_status,
    unclassified.classification,
    unclassified.reason_code,
    unclassified.rationale,
    unclassified.closure_eligible,
    unclassified.attempt_count,
    unclassified.exposure_count,
    unclassified.classified_at,
    unclassified.calibration_eligible,
    unclassified.calibration_reason
   FROM unclassified;

ALTER VIEW "public"."pilot_evidence_detail_v" OWNER TO postgres;

CREATE VIEW "public"."pilot_participant_status_v" ("pilot_participant_id", "pilot_run_id", "run_key", "student_id", "adult_confirmed", "authorization_policy_version", "evidence_start_at", "planned_end_date", "operational_owner_id", "supervising_teacher_id", "participant_status", "prospective_session_count") WITH (security_invoker=true) AS
 SELECT pp.id AS pilot_participant_id,
    pp.pilot_run_id,
    pr.run_key,
    pp.student_id,
    pp.adult_confirmed,
    pp.authorization_policy_version,
    pp.evidence_start_at,
    pp.planned_end_date,
    pp.operational_owner_id,
    pp.supervising_teacher_id,
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM public.pilot_participant_events e
              WHERE ((e.pilot_participant_id = pp.id) AND (e.event_type = 'withdrawn'::text)))) THEN 'withdrawn'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.pilot_participant_events e
              WHERE ((e.pilot_participant_id = pp.id) AND (e.event_type = 'suspended'::text) AND (NOT (EXISTS ( SELECT 1
                       FROM public.pilot_participant_events r
                      WHERE ((r.pilot_participant_id = pp.id) AND (r.event_type = 'resumed'::text) AND (r.effective_at > e.effective_at)))))))) THEN 'suspended'::text
            ELSE 'active'::text
        END AS participant_status,
    ( SELECT count(*) AS count
           FROM public.learning_sessions ls
          WHERE ((ls.student_id = pp.student_id) AND (ls.started_at >= pp.evidence_start_at))) AS prospective_session_count
   FROM (public.pilot_participants pp
     JOIN public.pilot_runs pr ON ((pr.id = pp.pilot_run_id)));

ALTER VIEW "public"."pilot_participant_status_v" OWNER TO postgres;

CREATE VIEW "public"."remediation_guide_authoring_catalog_v" ("guide_scope", "guide_source_id", "subject_id", "subject_code", "subject_name_hy", "grade_id", "grade_number", "grade_label_hy", "programmes", "units", "skill_id", "skill_code", "skill_name_hy", "item_template_id", "item_template_code", "specialization_code", "runtime_version", "runtime_status", "runtime_content", "runtime_reference_metadata", "authoring_version", "lifecycle_status", "authoring_content", "reference_metadata", "change_rationale", "actor_id", "actor_role", "actor_aal", "authoring_updated_at") WITH (security_invoker=true) AS
 WITH skill_context AS (
         SELECT s.id AS skill_id,
            s.code AS skill_code,
            s.name_hy AS skill_name_hy,
            sub.id AS subject_id,
            sub.code AS subject_code,
            sub.name_hy AS subject_name_hy,
            gr.id AS grade_id,
            gr.grade_number,
            gr.label_hy AS grade_label_hy,
            COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', u.id, 'code', u.code, 'titleHy', u.title_hy)) FILTER (WHERE (u.id IS NOT NULL)), '[]'::jsonb) AS units,
            COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', sp.id, 'versionLabel', sp.version_label)) FILTER (WHERE (sp.id IS NOT NULL)), '[]'::jsonb) AS programmes
           FROM (((((((public.skills s
             JOIN public.subjects sub ON ((sub.id = s.subject_id)))
             JOIN public.grades gr ON ((gr.id = s.grade_id)))
             LEFT JOIN public.skill_outcomes so ON ((so.skill_id = s.id)))
             LEFT JOIN public.learning_outcomes lo ON ((lo.id = so.learning_outcome_id)))
             LEFT JOIN public.topics t ON ((t.id = lo.topic_id)))
             LEFT JOIN public.units u ON ((u.id = t.unit_id)))
             LEFT JOIN public.subject_programs sp ON ((sp.id = u.subject_program_id)))
          GROUP BY s.id, s.code, s.name_hy, sub.id, sub.code, sub.name_hy, gr.id, gr.grade_number, gr.label_hy
        ), latest_authoring AS (
         SELECT DISTINCT ON (v.guide_scope, v.guide_source_id) v.id,
            v.guide_scope,
            v.guide_source_id,
            v.authoring_version,
            v.lifecycle_status,
            v.content_snapshot,
            v.reference_metadata,
            v.change_rationale,
            v.actor_id,
            v.actor_role,
            v.actor_aal,
            v.parent_version_id,
            v.published_runtime_version,
            v.created_at
           FROM public.remediation_guide_authoring_versions v
          ORDER BY v.guide_scope, v.guide_source_id, v.authoring_version DESC
        ), skill_rows AS (
         SELECT 'skill'::text AS guide_scope,
            g.id AS guide_source_id,
            sc.subject_id,
            sc.subject_code,
            sc.subject_name_hy,
            sc.grade_id,
            sc.grade_number,
            sc.grade_label_hy,
            sc.programmes,
            sc.units,
            sc.skill_id,
            sc.skill_code,
            sc.skill_name_hy,
            NULL::uuid AS item_template_id,
            NULL::text AS item_template_code,
            g.misconception_code AS specialization_code,
            g.guide_version AS runtime_version,
            g.status AS runtime_status,
            jsonb_build_object('skillId', g.skill_id, 'misconceptionCode', g.misconception_code, 'titleHy', g.title_hy, 'strategyHy', g.strategy_hy, 'hint1Hy', g.hint_1_hy, 'hint2Hy', g.hint_2_hy, 'workedExampleHy', g.worked_example_hy, 'allowedParameterKeys', '[]'::jsonb, 'metadata', g.metadata) AS runtime_content,
            COALESCE((g.metadata -> 'referenceMetadata'::text), '{}'::jsonb) AS runtime_reference_metadata
           FROM (public.skill_remediation_guides g
             JOIN skill_context sc ON ((sc.skill_id = g.skill_id)))
        ), template_rows AS (
         SELECT 'template'::text AS guide_scope,
            g.id AS guide_source_id,
            sc.subject_id,
            sc.subject_code,
            sc.subject_name_hy,
            sc.grade_id,
            sc.grade_number,
            sc.grade_label_hy,
            sc.programmes,
            sc.units,
            sc.skill_id,
            sc.skill_code,
            sc.skill_name_hy,
            it.id AS item_template_id,
            it.code AS item_template_code,
            g.trigger_error_code AS specialization_code,
            g.guide_version AS runtime_version,
            g.status AS runtime_status,
            jsonb_build_object('itemTemplateId', g.item_template_id, 'triggerErrorCode', g.trigger_error_code, 'titleHy', g.title_hy, 'strategyHy', g.strategy_hy, 'hint1Hy', g.hint_1_hy, 'hint2Hy', g.hint_2_hy, 'workedExampleHy', g.worked_example_hy, 'allowedParameterKeys', to_jsonb(g.allowed_parameter_keys), 'metadata', g.metadata) AS runtime_content,
            COALESCE((g.metadata -> 'referenceMetadata'::text), '{}'::jsonb) AS runtime_reference_metadata
           FROM (((public.item_template_remediation_guides g
             JOIN public.item_templates it ON ((it.id = g.item_template_id)))
             JOIN public.item_families f ON ((f.id = it.item_family_id)))
             JOIN skill_context sc ON ((sc.skill_id = f.skill_id)))
        )
 SELECT r.guide_scope,
    r.guide_source_id,
    r.subject_id,
    r.subject_code,
    r.subject_name_hy,
    r.grade_id,
    r.grade_number,
    r.grade_label_hy,
    r.programmes,
    r.units,
    r.skill_id,
    r.skill_code,
    r.skill_name_hy,
    r.item_template_id,
    r.item_template_code,
    r.specialization_code,
    r.runtime_version,
    r.runtime_status,
    r.runtime_content,
    r.runtime_reference_metadata,
    COALESCE(a.authoring_version, 0) AS authoring_version,
    COALESCE(a.lifecycle_status, r.runtime_status) AS lifecycle_status,
    COALESCE(a.content_snapshot, r.runtime_content) AS authoring_content,
    COALESCE(a.reference_metadata, r.runtime_reference_metadata) AS reference_metadata,
    a.change_rationale,
    a.actor_id,
    a.actor_role,
    a.actor_aal,
    a.created_at AS authoring_updated_at
   FROM (( SELECT skill_rows.guide_scope,
            skill_rows.guide_source_id,
            skill_rows.subject_id,
            skill_rows.subject_code,
            skill_rows.subject_name_hy,
            skill_rows.grade_id,
            skill_rows.grade_number,
            skill_rows.grade_label_hy,
            skill_rows.programmes,
            skill_rows.units,
            skill_rows.skill_id,
            skill_rows.skill_code,
            skill_rows.skill_name_hy,
            skill_rows.item_template_id,
            skill_rows.item_template_code,
            skill_rows.specialization_code,
            skill_rows.runtime_version,
            skill_rows.runtime_status,
            skill_rows.runtime_content,
            skill_rows.runtime_reference_metadata
           FROM skill_rows
        UNION ALL
         SELECT template_rows.guide_scope,
            template_rows.guide_source_id,
            template_rows.subject_id,
            template_rows.subject_code,
            template_rows.subject_name_hy,
            template_rows.grade_id,
            template_rows.grade_number,
            template_rows.grade_label_hy,
            template_rows.programmes,
            template_rows.units,
            template_rows.skill_id,
            template_rows.skill_code,
            template_rows.skill_name_hy,
            template_rows.item_template_id,
            template_rows.item_template_code,
            template_rows.specialization_code,
            template_rows.runtime_version,
            template_rows.runtime_status,
            template_rows.runtime_content,
            template_rows.runtime_reference_metadata
           FROM template_rows) r
     LEFT JOIN latest_authoring a ON (((a.guide_scope = r.guide_scope) AND (a.guide_source_id = r.guide_source_id))));

ALTER VIEW "public"."remediation_guide_authoring_catalog_v" OWNER TO postgres;

CREATE VIEW "public"."calibration_session_eligibility_v" ("analysis_scope_id", "scope_key", "contract_id", "contract_version", "metric_set_id", "metric_set_version", "pilot_run_id", "run_key", "pilot_status", "all_entry_gates_passed", "required_human_gates_passed", "gate_statuses", "learning_session_id", "student_id", "unit_code", "mode", "session_status", "target_skill_id", "started_at", "completed_at", "answered_count", "correct_count", "curriculum_release_id", "release_key", "assessment_blueprint_id", "blueprint_key", "blueprint_purpose", "provenance_status", "learning_model_configuration_id", "model_version", "model_provenance_status", "runtime_build_id", "runtime_build_key", "runtime_provenance_status", "classification", "classification_reason", "classification_rationale", "classified_at", "release_matches_contract", "blueprint_matches_session", "model_matches_contract", "is_qa_artifact", "classification_pending", "exclusion_reasons", "base_eligibility_reason", "base_formal_eligible", "governance_tier", "practice_burden_eligible", "mastery_evidence_to_secure_eligible", "hint_assistance_effect_eligible", "item_difficulty_response_time_eligible", "repeat_pool_exhaustion_influence_eligible", "threshold_sensitivity_eligible", "diagnostic_predictive_alignment_eligible", "mastery_check_outcome_eligible", "mastery_check_skill_failure_eligible", "recent_recovery_stability_eligible", "recommendation_path_accuracy_eligible") WITH (security_invoker=true) AS
 WITH operative AS (
         SELECT s.id AS analysis_scope_id,
            s.scope_key,
            c.id AS contract_id,
            c.version_label AS contract_version,
            c.target_curriculum_release_id,
            c.reference_model_configuration_id,
            m.id AS metric_set_id,
            m.version_label AS metric_set_version,
            p.id AS pilot_run_id,
            p.run_key,
            p.status AS pilot_status
           FROM (((public.calibration_analysis_scopes s
             JOIN public.calibration_evidence_contracts c ON ((c.id = s.calibration_evidence_contract_id)))
             JOIN public.calibration_metric_sets m ON ((m.id = s.calibration_metric_set_id)))
             JOIN public.pilot_runs p ON ((p.id = s.pilot_run_id)))
          WHERE (s.scope_key = 'physics7-u01-12a4-r2'::text)
        ), gates AS (
         SELECT o.pilot_run_id,
            COALESCE(bool_and((pg.status = 'passed'::text)) FILTER (WHERE (pg.gate_stage = 'entry'::text)), false) AS all_entry_gates_passed,
            COALESCE(bool_and((pg.status = 'passed'::text)) FILTER (WHERE (pg.gate_code = ANY (ARRAY['cohort_enrolled'::text, 'participation_authorized'::text]))), false) AS required_human_gates_passed,
            COALESCE(jsonb_object_agg(pg.gate_code, pg.status) FILTER (WHERE (pg.gate_code IS NOT NULL)), '{}'::jsonb) AS gate_statuses
           FROM (operative o
             LEFT JOIN public.pilot_gate_checks pg ON ((pg.pilot_run_id = o.pilot_run_id)))
          GROUP BY o.pilot_run_id
        ), base AS (
         SELECT o.analysis_scope_id,
            o.scope_key,
            o.contract_id,
            o.contract_version,
            o.metric_set_id,
            o.metric_set_version,
            o.pilot_run_id,
            o.run_key,
            o.pilot_status,
            g.all_entry_gates_passed,
            g.required_human_gates_passed,
            g.gate_statuses,
            ls.id AS learning_session_id,
            ls.student_id,
            ls.unit_code,
            ls.mode,
            ls.status AS session_status,
            ls.target_skill_id,
            ls.started_at,
            ls.completed_at,
            ls.answered_count,
            ls.correct_count,
            ls.curriculum_release_id,
            cr.release_key,
            ls.assessment_blueprint_id,
            ab.blueprint_key,
            ab.purpose AS blueprint_purpose,
            ls.provenance_status,
            ls.learning_model_configuration_id,
            lm.version_label AS model_version,
            ls.model_provenance_status,
            ls.runtime_build_id,
            rb.build_key AS runtime_build_key,
            ls.runtime_provenance_status,
            ped.classification,
            ped.reason_code AS classification_reason,
            ped.rationale AS classification_rationale,
            ped.classified_at,
            (ls.curriculum_release_id = o.target_curriculum_release_id) AS release_matches_contract,
            ((ab.curriculum_release_id = ls.curriculum_release_id) AND (ab.purpose = ls.mode)) AS blueprint_matches_session,
            (ls.learning_model_configuration_id = o.reference_model_configuration_id) AS model_matches_contract,
            COALESCE(((ls.metadata ->> 'qa_artifact'::text))::boolean, false) AS is_qa_artifact
           FROM (((((((public.learning_sessions ls
             CROSS JOIN operative o)
             CROSS JOIN gates g)
             LEFT JOIN public.curriculum_releases cr ON ((cr.id = ls.curriculum_release_id)))
             LEFT JOIN public.assessment_blueprints ab ON ((ab.id = ls.assessment_blueprint_id)))
             LEFT JOIN public.learning_model_configurations lm ON ((lm.id = ls.learning_model_configuration_id)))
             LEFT JOIN public.runtime_builds rb ON ((rb.id = ls.runtime_build_id)))
             LEFT JOIN public.pilot_evidence_detail_v ped ON (((ped.pilot_run_id = o.pilot_run_id) AND (ped.learning_session_id = ls.id))))
        ), reasons AS (
         SELECT b.analysis_scope_id,
            b.scope_key,
            b.contract_id,
            b.contract_version,
            b.metric_set_id,
            b.metric_set_version,
            b.pilot_run_id,
            b.run_key,
            b.pilot_status,
            b.all_entry_gates_passed,
            b.required_human_gates_passed,
            b.gate_statuses,
            b.learning_session_id,
            b.student_id,
            b.unit_code,
            b.mode,
            b.session_status,
            b.target_skill_id,
            b.started_at,
            b.completed_at,
            b.answered_count,
            b.correct_count,
            b.curriculum_release_id,
            b.release_key,
            b.assessment_blueprint_id,
            b.blueprint_key,
            b.blueprint_purpose,
            b.provenance_status,
            b.learning_model_configuration_id,
            b.model_version,
            b.model_provenance_status,
            b.runtime_build_id,
            b.runtime_build_key,
            b.runtime_provenance_status,
            b.classification,
            b.classification_reason,
            b.classification_rationale,
            b.classified_at,
            b.release_matches_contract,
            b.blueprint_matches_session,
            b.model_matches_contract,
            b.is_qa_artifact,
            (b.classification IS NULL) AS classification_pending,
            array_remove(ARRAY[
                CASE
                    WHEN (b.classification IS NULL) THEN 'classification_pending'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (b.is_qa_artifact OR (b.classification_reason = 'qa_artifact'::text)) THEN 'qa_artifact'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (b.pilot_status <> ALL (ARRAY['running'::text, 'observing'::text, 'closed'::text])) THEN 'pilot_status_not_allowed'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT b.all_entry_gates_passed) THEN 'pilot_entry_not_ready'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT b.required_human_gates_passed) THEN 'participation_gates_blocked'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (b.classification_reason = 'outside_cohort'::text) THEN 'outside_cohort'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT b.release_matches_contract) THEN 'release_mismatch'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT b.blueprint_matches_session) THEN 'blueprint_mismatch'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (b.provenance_status <> 'exact'::text) THEN 'session_provenance_not_exact'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((NOT b.model_matches_contract) OR (b.model_provenance_status <> 'exact'::text)) THEN 'model_provenance_not_exact'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((b.runtime_build_id IS NULL) OR (b.runtime_provenance_status <> 'exact'::text)) THEN 'runtime_provenance_not_exact'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((b.classification IS NOT NULL) AND (b.classification <> 'compatible'::text) AND (b.classification_reason <> 'exact_release_noncompleted'::text)) THEN 'pilot_classification_excluded'::text
                    ELSE NULL::text
                END], NULL::text) AS exclusion_reasons
           FROM base b
        ), judged AS (
         SELECT r.analysis_scope_id,
            r.scope_key,
            r.contract_id,
            r.contract_version,
            r.metric_set_id,
            r.metric_set_version,
            r.pilot_run_id,
            r.run_key,
            r.pilot_status,
            r.all_entry_gates_passed,
            r.required_human_gates_passed,
            r.gate_statuses,
            r.learning_session_id,
            r.student_id,
            r.unit_code,
            r.mode,
            r.session_status,
            r.target_skill_id,
            r.started_at,
            r.completed_at,
            r.answered_count,
            r.correct_count,
            r.curriculum_release_id,
            r.release_key,
            r.assessment_blueprint_id,
            r.blueprint_key,
            r.blueprint_purpose,
            r.provenance_status,
            r.learning_model_configuration_id,
            r.model_version,
            r.model_provenance_status,
            r.runtime_build_id,
            r.runtime_build_key,
            r.runtime_provenance_status,
            r.classification,
            r.classification_reason,
            r.classification_rationale,
            r.classified_at,
            r.release_matches_contract,
            r.blueprint_matches_session,
            r.model_matches_contract,
            r.is_qa_artifact,
            r.classification_pending,
            r.exclusion_reasons,
                CASE
                    WHEN r.classification_pending THEN 'classification_pending'::text
                    WHEN (r.is_qa_artifact OR (r.classification_reason = 'qa_artifact'::text)) THEN 'qa_artifact'::text
                    WHEN (r.pilot_status <> ALL (ARRAY['running'::text, 'observing'::text, 'closed'::text])) THEN 'pilot_status_not_allowed'::text
                    WHEN (NOT r.all_entry_gates_passed) THEN 'pilot_entry_not_ready'::text
                    WHEN (NOT r.required_human_gates_passed) THEN 'participation_gates_blocked'::text
                    WHEN (r.classification_reason = 'outside_cohort'::text) THEN 'outside_cohort'::text
                    WHEN (NOT r.release_matches_contract) THEN 'release_mismatch'::text
                    WHEN (NOT r.blueprint_matches_session) THEN 'blueprint_mismatch'::text
                    WHEN (r.provenance_status <> 'exact'::text) THEN 'session_provenance_not_exact'::text
                    WHEN ((NOT r.model_matches_contract) OR (r.model_provenance_status <> 'exact'::text)) THEN 'model_provenance_not_exact'::text
                    WHEN ((r.runtime_build_id IS NULL) OR (r.runtime_provenance_status <> 'exact'::text)) THEN 'runtime_provenance_not_exact'::text
                    WHEN ((r.classification <> 'compatible'::text) AND (r.classification_reason <> 'exact_release_noncompleted'::text)) THEN 'pilot_classification_excluded'::text
                    ELSE 'eligible'::text
                END AS base_eligibility_reason
           FROM reasons r
        )
 SELECT analysis_scope_id,
    scope_key,
    contract_id,
    contract_version,
    metric_set_id,
    metric_set_version,
    pilot_run_id,
    run_key,
    pilot_status,
    all_entry_gates_passed,
    required_human_gates_passed,
    gate_statuses,
    learning_session_id,
    student_id,
    unit_code,
    mode,
    session_status,
    target_skill_id,
    started_at,
    completed_at,
    answered_count,
    correct_count,
    curriculum_release_id,
    release_key,
    assessment_blueprint_id,
    blueprint_key,
    blueprint_purpose,
    provenance_status,
    learning_model_configuration_id,
    model_version,
    model_provenance_status,
    runtime_build_id,
    runtime_build_key,
    runtime_provenance_status,
    classification,
    classification_reason,
    classification_rationale,
    classified_at,
    release_matches_contract,
    blueprint_matches_session,
    model_matches_contract,
    is_qa_artifact,
    classification_pending,
    exclusion_reasons,
    base_eligibility_reason,
    (base_eligibility_reason = 'eligible'::text) AS base_formal_eligible,
        CASE
            WHEN (base_eligibility_reason = 'eligible'::text) THEN 'core_calibration'::text
            WHEN ((classification = 'partially_compatible'::text) AND (NOT is_qa_artifact)) THEN 'context_only'::text
            ELSE 'excluded'::text
        END AS governance_tier,
    ((base_eligibility_reason = 'eligible'::text) AND (mode = 'practice'::text) AND (session_status = ANY (ARRAY['completed'::text, 'active'::text, 'abandoned'::text]))) AS practice_burden_eligible,
    ((base_eligibility_reason = 'eligible'::text) AND (mode = 'practice'::text) AND (session_status = ANY (ARRAY['completed'::text, 'active'::text, 'abandoned'::text]))) AS mastery_evidence_to_secure_eligible,
    ((base_eligibility_reason = 'eligible'::text) AND (session_status = ANY (ARRAY['completed'::text, 'active'::text, 'abandoned'::text]))) AS hint_assistance_effect_eligible,
    ((base_eligibility_reason = 'eligible'::text) AND (session_status = ANY (ARRAY['completed'::text, 'active'::text, 'abandoned'::text]))) AS item_difficulty_response_time_eligible,
    ((base_eligibility_reason = 'eligible'::text) AND (session_status = ANY (ARRAY['completed'::text, 'active'::text, 'abandoned'::text]))) AS repeat_pool_exhaustion_influence_eligible,
    ((base_eligibility_reason = 'eligible'::text) AND (session_status = ANY (ARRAY['completed'::text, 'active'::text, 'abandoned'::text]))) AS threshold_sensitivity_eligible,
    ((base_eligibility_reason = 'eligible'::text) AND (mode = 'diagnostic'::text) AND (session_status = 'completed'::text)) AS diagnostic_predictive_alignment_eligible,
    ((base_eligibility_reason = 'eligible'::text) AND (mode = 'mastery_check'::text) AND (session_status = 'completed'::text)) AS mastery_check_outcome_eligible,
    ((base_eligibility_reason = 'eligible'::text) AND (mode = 'mastery_check'::text) AND (session_status = 'completed'::text)) AS mastery_check_skill_failure_eligible,
    (base_eligibility_reason = 'eligible'::text) AS recent_recovery_stability_eligible,
    (base_eligibility_reason = 'eligible'::text) AS recommendation_path_accuracy_eligible
   FROM judged j;

ALTER VIEW "public"."calibration_session_eligibility_v" OWNER TO postgres;

CREATE VIEW "public"."chapter_review_skill_attention_inputs_v" ("chapter_mastery_state_id", "student_id", "curriculum_release_id", "unit_code", "skill_id", "skill_code", "skill_name_hy", "review_observations", "independent_observations", "independent_correct", "hint_assisted_responses", "repeat_errors", "recent_independent_observations", "recent_independent_correct", "last_seen_at", "failed_latest_mastery", "attention_state", "attention_policy_status") WITH (security_invoker=true) AS
 WITH ranked_review AS (
         SELECT e.id,
            e.chapter_review_session_id,
            e.review_cycle_id,
            e.chapter_mastery_state_id,
            e.review_context,
            e.review_cycle_number,
            e.review_session_number,
            e.preceding_mastery_attempt_number,
            e.learning_session_item_id,
            e.item_id,
            e.item_code,
            e.item_version,
            e.item_template_id,
            e.template_code,
            e.item_family_id,
            e.family_code,
            e.variant_key,
            e.skill_id,
            e.selection_reason,
            e.prior_exposure_count,
            e.seen_in_current_cycle,
            e.exact_repeat,
            e.pool_exhausted,
            e.selected_at,
            e.hint_level_used,
            e.hint_used,
            e.response_time_ms,
            e.correct,
            e.answered_at,
            e.independent,
            e.assisted,
            row_number() OVER (PARTITION BY e.chapter_mastery_state_id, e.skill_id ORDER BY e.answered_at DESC NULLS LAST, e.selected_at DESC) AS recent_rank
           FROM public.chapter_review_item_evidence_v e
        ), latest_mastery_attempt AS (
         SELECT DISTINCT ON (m.chapter_mastery_state_id) m.chapter_mastery_state_id,
            m.learning_session_id,
            m.result
           FROM public.mastery_check_attempts m
          WHERE (m.status = 'completed'::text)
          ORDER BY m.chapter_mastery_state_id, m.attempt_number DESC
        ), failed_mastery_skill AS (
         SELECT l.chapter_mastery_state_id,
            lsi.skill_id,
            true AS failed_latest_mastery
           FROM (latest_mastery_attempt l
             JOIN public.learning_session_items lsi ON ((lsi.session_id = l.learning_session_id)))
          WHERE ((l.result = 'failed'::text) AND (lsi.correct = false))
          GROUP BY l.chapter_mastery_state_id, lsi.skill_id
        )
 SELECT r.chapter_mastery_state_id,
    s.student_id,
    s.curriculum_release_id,
    s.unit_code,
    r.skill_id,
    sk.code AS skill_code,
    sk.name_hy AS skill_name_hy,
    (count(*) FILTER (WHERE (r.answered_at IS NOT NULL)))::integer AS review_observations,
    (count(*) FILTER (WHERE ((r.answered_at IS NOT NULL) AND r.independent)))::integer AS independent_observations,
    (count(*) FILTER (WHERE ((r.answered_at IS NOT NULL) AND r.independent AND r.correct)))::integer AS independent_correct,
    (count(*) FILTER (WHERE ((r.answered_at IS NOT NULL) AND r.assisted)))::integer AS hint_assisted_responses,
    (count(*) FILTER (WHERE ((r.answered_at IS NOT NULL) AND (NOT r.correct) AND r.exact_repeat)))::integer AS repeat_errors,
    (count(*) FILTER (WHERE ((r.recent_rank <= 10) AND (r.answered_at IS NOT NULL) AND r.independent)))::integer AS recent_independent_observations,
    (count(*) FILTER (WHERE ((r.recent_rank <= 10) AND (r.answered_at IS NOT NULL) AND r.independent AND r.correct)))::integer AS recent_independent_correct,
    max(r.answered_at) AS last_seen_at,
    COALESCE(f.failed_latest_mastery, false) AS failed_latest_mastery,
    'insufficient_review_evidence'::text AS attention_state,
    'thresholds_not_governed'::text AS attention_policy_status
   FROM (((ranked_review r
     JOIN public.chapter_mastery_states s ON ((s.id = r.chapter_mastery_state_id)))
     JOIN public.skills sk ON ((sk.id = r.skill_id)))
     LEFT JOIN failed_mastery_skill f ON (((f.chapter_mastery_state_id = r.chapter_mastery_state_id) AND (f.skill_id = r.skill_id))))
  GROUP BY r.chapter_mastery_state_id, s.student_id, s.curriculum_release_id, s.unit_code, r.skill_id, sk.code, sk.name_hy, f.failed_latest_mastery;

ALTER VIEW "public"."chapter_review_skill_attention_inputs_v" OWNER TO postgres;

CREATE VIEW "public"."chapter_review_summary_v" ("chapter_mastery_state_id", "student_id", "curriculum_release_id", "unit_code", "lifecycle_state", "attempts_used", "passed_on_attempt", "maximum_mastery_attempts", "required_reviews_completed", "optional_reviews_completed", "total_reviews_completed", "last_review_at", "current_review_cycle", "current_cycle_unique_seen", "current_cycle_eligible_pool_size", "review_independent_answered", "review_independent_correct", "review_independent_accuracy_percent", "hint_assisted_responses") WITH (security_invoker=true) AS
 WITH completed_reviews AS (
         SELECT crs.chapter_mastery_state_id,
            (count(*) FILTER (WHERE (crs.status = 'completed'::text)))::integer AS total_reviews_completed,
            (count(*) FILTER (WHERE ((crs.status = 'completed'::text) AND crs.qualifying)))::integer AS required_reviews_completed,
            (count(*) FILTER (WHERE ((crs.status = 'completed'::text) AND (NOT crs.qualifying))))::integer AS optional_reviews_completed,
            max(crs.completed_at) FILTER (WHERE (crs.status = 'completed'::text)) AS last_review_at
           FROM public.chapter_review_sessions crs
          GROUP BY crs.chapter_mastery_state_id
        ), review_evidence AS (
         SELECT e_1.chapter_mastery_state_id,
            (count(*) FILTER (WHERE ((e_1.answered_at IS NOT NULL) AND e_1.independent)))::integer AS independent_answered,
            (count(*) FILTER (WHERE ((e_1.answered_at IS NOT NULL) AND e_1.independent AND e_1.correct)))::integer AS independent_correct,
            (count(*) FILTER (WHERE ((e_1.answered_at IS NOT NULL) AND e_1.assisted)))::integer AS hint_assisted_responses
           FROM public.chapter_review_item_evidence_v e_1
          GROUP BY e_1.chapter_mastery_state_id
        ), current_cycle AS (
         SELECT c_1.chapter_mastery_state_id,
            c_1.cycle_number,
            c_1.eligible_pool_size,
            (count(DISTINCT e_1.item_id))::integer AS unique_items_seen
           FROM (public.chapter_review_cycles c_1
             LEFT JOIN public.chapter_review_item_exposures e_1 ON ((e_1.review_cycle_id = c_1.id)))
          WHERE (c_1.status = 'active'::text)
          GROUP BY c_1.chapter_mastery_state_id, c_1.cycle_number, c_1.eligible_pool_size
        )
 SELECT s.id AS chapter_mastery_state_id,
    s.student_id,
    s.curriculum_release_id,
    s.unit_code,
    s.lifecycle_state,
    s.attempts_used,
    s.passed_on_attempt,
    p.maximum_mastery_attempts,
    COALESCE(r.required_reviews_completed, 0) AS required_reviews_completed,
    COALESCE(r.optional_reviews_completed, 0) AS optional_reviews_completed,
    COALESCE(r.total_reviews_completed, 0) AS total_reviews_completed,
    r.last_review_at,
    c.cycle_number AS current_review_cycle,
    c.unique_items_seen AS current_cycle_unique_seen,
    c.eligible_pool_size AS current_cycle_eligible_pool_size,
    COALESCE(e.independent_answered, 0) AS review_independent_answered,
    COALESCE(e.independent_correct, 0) AS review_independent_correct,
        CASE
            WHEN (COALESCE(e.independent_answered, 0) = 0) THEN NULL::numeric
            ELSE round((((e.independent_correct)::numeric / (e.independent_answered)::numeric) * (100)::numeric))
        END AS review_independent_accuracy_percent,
    COALESCE(e.hint_assisted_responses, 0) AS hint_assisted_responses
   FROM ((((public.chapter_mastery_states s
     JOIN public.academic_mastery_policy_versions p ON ((p.id = s.academic_mastery_policy_id)))
     LEFT JOIN completed_reviews r ON ((r.chapter_mastery_state_id = s.id)))
     LEFT JOIN review_evidence e ON ((e.chapter_mastery_state_id = s.id)))
     LEFT JOIN current_cycle c ON ((c.chapter_mastery_state_id = s.id)));

ALTER VIEW "public"."chapter_review_summary_v" OWNER TO postgres;

CREATE VIEW "public"."pilot_evidence_summary_v" ("pilot_run_id", "run_key", "target_release_key", "classified_sessions", "compatible_sessions", "partially_compatible_sessions", "incompatible_sessions", "closure_eligible_sessions", "eligible_attempts", "eligible_exposures") WITH (security_invoker=true) AS
 SELECT pilot_run_id,
    run_key,
    target_release_key,
    count(*) AS classified_sessions,
    count(*) FILTER (WHERE (classification = 'compatible'::text)) AS compatible_sessions,
    count(*) FILTER (WHERE (classification = 'partially_compatible'::text)) AS partially_compatible_sessions,
    count(*) FILTER (WHERE (classification = 'incompatible'::text)) AS incompatible_sessions,
    count(*) FILTER (WHERE closure_eligible) AS closure_eligible_sessions,
    COALESCE(sum(attempt_count) FILTER (WHERE closure_eligible), (0)::numeric) AS eligible_attempts,
    COALESCE(sum(exposure_count) FILTER (WHERE closure_eligible), (0)::numeric) AS eligible_exposures
   FROM public.pilot_evidence_detail_v
  GROUP BY pilot_run_id, run_key, target_release_key;

ALTER VIEW "public"."pilot_evidence_summary_v" OWNER TO postgres;

CREATE VIEW "public"."calibration_attempt_evidence_v" ("contract_id", "contract_version", "metric_set_id", "metric_set_version", "pilot_run_id", "run_key", "governance_tier", "base_formal_eligible", "base_eligibility_reason", "learning_session_id", "student_id", "unit_code", "mode", "session_status", "curriculum_release_id", "release_key", "assessment_blueprint_id", "blueprint_key", "learning_model_configuration_id", "model_version", "runtime_build_id", "runtime_build_key", "attempt_id", "attempted_at", "skill_id", "skill_code", "item_id", "item_code", "item_template_id", "item_family", "difficulty", "difficulty_band", "correct", "score", "error_code", "hint_used", "response_time_ms", "session_item_id", "ordinal", "selection_reason", "exposure_event_id", "served_at", "family_code", "template_code", "variant_key", "attempt_provenance_exact", "exposure_provenance_exact", "item_response_formal_eligible", "item_response_eligibility_reason", "repeat_pool_formal_eligible", "repeat_pool_eligibility_reason", "has_prior_incorrect_attempt") WITH (security_invoker=true) AS
 SELECT se.contract_id,
    se.contract_version,
    se.metric_set_id,
    se.metric_set_version,
    se.pilot_run_id,
    se.run_key,
    se.governance_tier,
    se.base_formal_eligible,
    se.base_eligibility_reason,
    se.learning_session_id,
    se.student_id,
    se.unit_code,
    se.mode,
    se.session_status,
    se.curriculum_release_id,
    se.release_key,
    se.assessment_blueprint_id,
    se.blueprint_key,
    se.learning_model_configuration_id,
    se.model_version,
    se.runtime_build_id,
    se.runtime_build_key,
    a.id AS attempt_id,
    a.created_at AS attempted_at,
    a.skill_id,
    sk.code AS skill_code,
    a.item_id,
    i.code AS item_code,
    i.item_template_id,
    i.item_family,
    i.difficulty,
    i.difficulty_band,
    a.correct,
    a.score,
    a.error_code,
    a.hint_used,
    a.response_time_ms,
    lsi.id AS session_item_id,
    lsi.ordinal,
    lsi.selection_reason,
    ex.id AS exposure_event_id,
    ex.served_at,
    ex.family_code,
    ex.template_code,
    ex.variant_key,
    ((a.curriculum_release_id = se.curriculum_release_id) AND (a.assessment_blueprint_id = se.assessment_blueprint_id) AND (a.provenance_status = 'exact'::text)) AS attempt_provenance_exact,
    ((ex.id IS NOT NULL) AND (ex.provenance_status = 'exact'::text)) AS exposure_provenance_exact,
    (se.item_difficulty_response_time_eligible AND (a.provenance_status = 'exact'::text)) AS item_response_formal_eligible,
        CASE
            WHEN (NOT se.item_difficulty_response_time_eligible) THEN se.base_eligibility_reason
            WHEN (a.provenance_status <> 'exact'::text) THEN 'attempt_provenance_not_exact'::text
            ELSE 'eligible'::text
        END AS item_response_eligibility_reason,
    (se.repeat_pool_exhaustion_influence_eligible AND (ex.id IS NOT NULL) AND (lsi.selection_reason IS NOT NULL) AND (ex.provenance_status = 'exact'::text)) AS repeat_pool_formal_eligible,
        CASE
            WHEN (NOT se.repeat_pool_exhaustion_influence_eligible) THEN se.base_eligibility_reason
            WHEN ((ex.id IS NULL) OR (lsi.selection_reason IS NULL)) THEN 'selection_telemetry_missing'::text
            WHEN (ex.provenance_status <> 'exact'::text) THEN 'exposure_provenance_not_exact'::text
            ELSE 'eligible'::text
        END AS repeat_pool_eligibility_reason,
    (EXISTS ( SELECT 1
           FROM public.attempts prior
          WHERE ((prior.student_id = a.student_id) AND (prior.skill_id = a.skill_id) AND (NOT prior.correct) AND (prior.created_at < a.created_at)))) AS has_prior_incorrect_attempt
   FROM (((((public.calibration_session_eligibility_v se
     JOIN public.attempts a ON ((a.learning_session_id = se.learning_session_id)))
     LEFT JOIN public.learning_session_items lsi ON ((lsi.id = a.learning_session_item_id)))
     LEFT JOIN public.student_item_exposure_events ex ON ((ex.attempt_id = a.id)))
     LEFT JOIN public.items i ON ((i.id = a.item_id)))
     LEFT JOIN public.skills sk ON ((sk.id = a.skill_id)));

ALTER VIEW "public"."calibration_attempt_evidence_v" OWNER TO postgres;

CREATE VIEW "public"."calibration_hint_evidence_v" ("contract_id", "contract_version", "metric_set_id", "metric_set_version", "pilot_run_id", "run_key", "governance_tier", "base_eligibility_reason", "learning_session_id", "student_id", "remediation_event_id", "event_at", "session_item_id", "skill_id", "item_id", "stage", "hint_level", "guide_scope", "guide_source_id", "guide_version", "guide_snapshot_id", "item_template_id", "error_code", "exact_rendered_guide_recorded", "formal_eligible", "eligibility_reason") WITH (security_invoker=true) AS
 SELECT se.contract_id,
    se.contract_version,
    se.metric_set_id,
    se.metric_set_version,
    se.pilot_run_id,
    se.run_key,
    se.governance_tier,
    se.base_eligibility_reason,
    se.learning_session_id,
    re.student_id,
    re.id AS remediation_event_id,
    re.created_at AS event_at,
    re.session_item_id,
    re.skill_id,
    re.item_id,
    re.stage,
    re.hint_level,
    re.guide_scope,
    re.guide_source_id,
    re.guide_version,
    re.guide_snapshot_id,
    re.item_template_id,
    re.error_code,
    ((re.guide_snapshot_id IS NOT NULL) AND (re.rendered_content_hy IS NOT NULL)) AS exact_rendered_guide_recorded,
    (se.hint_assistance_effect_eligible AND (re.guide_snapshot_id IS NOT NULL) AND (re.rendered_content_hy IS NOT NULL)) AS formal_eligible,
        CASE
            WHEN (NOT se.hint_assistance_effect_eligible) THEN se.base_eligibility_reason
            WHEN ((re.guide_snapshot_id IS NULL) OR (re.rendered_content_hy IS NULL)) THEN 'exact_guide_snapshot_missing'::text
            ELSE 'eligible'::text
        END AS eligibility_reason
   FROM (public.remediation_events re
     JOIN public.calibration_session_eligibility_v se ON ((se.learning_session_id = re.session_id)));

ALTER VIEW "public"."calibration_hint_evidence_v" OWNER TO postgres;

CREATE VIEW "public"."calibration_recommendation_paths_v" ("contract_id", "contract_version", "metric_set_id", "metric_set_version", "recommendation_instance_id", "student_id", "issued_at", "shown_at", "clicked_at", "action_started_at", "policy_scope", "surface", "action", "target_skill_id", "curriculum_release_id", "assessment_blueprint_id", "learning_model_configuration_id", "model_provenance_status", "started_session_id", "event_count", "governance_tier", "base_eligibility_reason", "formal_eligible", "eligibility_reason") WITH (security_invoker=true) AS
 WITH paths AS (
         SELECT recommendation_events.recommendation_instance_id,
            recommendation_events.student_id,
            min(recommendation_events.created_at) FILTER (WHERE (recommendation_events.event_type = 'issued'::text)) AS issued_at,
            min(recommendation_events.created_at) FILTER (WHERE (recommendation_events.event_type = 'shown'::text)) AS shown_at,
            min(recommendation_events.created_at) FILTER (WHERE (recommendation_events.event_type = 'clicked'::text)) AS clicked_at,
            min(recommendation_events.created_at) FILTER (WHERE (recommendation_events.event_type = 'action_started'::text)) AS action_started_at,
            (array_agg(recommendation_events.policy_scope ORDER BY recommendation_events.created_at) FILTER (WHERE (recommendation_events.event_type = 'issued'::text)))[1] AS policy_scope,
            (array_agg(recommendation_events.surface ORDER BY recommendation_events.created_at) FILTER (WHERE (recommendation_events.event_type = 'issued'::text)))[1] AS surface,
            (array_agg(recommendation_events.action ORDER BY recommendation_events.created_at) FILTER (WHERE (recommendation_events.event_type = 'issued'::text)))[1] AS action,
            (array_agg(recommendation_events.target_skill_id ORDER BY recommendation_events.created_at) FILTER (WHERE (recommendation_events.event_type = 'issued'::text)))[1] AS target_skill_id,
            (array_agg(recommendation_events.curriculum_release_id ORDER BY recommendation_events.created_at) FILTER (WHERE (recommendation_events.event_type = 'issued'::text)))[1] AS curriculum_release_id,
            (array_agg(recommendation_events.assessment_blueprint_id ORDER BY recommendation_events.created_at) FILTER (WHERE (recommendation_events.event_type = 'issued'::text)))[1] AS assessment_blueprint_id,
            (array_agg(recommendation_events.learning_model_configuration_id ORDER BY recommendation_events.created_at) FILTER (WHERE (recommendation_events.event_type = 'issued'::text)))[1] AS learning_model_configuration_id,
            (array_agg(recommendation_events.model_provenance_status ORDER BY recommendation_events.created_at) FILTER (WHERE (recommendation_events.event_type = 'issued'::text)))[1] AS model_provenance_status,
            (array_agg(recommendation_events.learning_session_id ORDER BY recommendation_events.created_at) FILTER (WHERE (recommendation_events.event_type = 'action_started'::text)))[1] AS started_session_id,
            count(*) AS event_count
           FROM public.recommendation_events
          GROUP BY recommendation_events.recommendation_instance_id, recommendation_events.student_id
        ), operative AS (
         SELECT c.id AS contract_id,
            c.version_label AS contract_version,
            c.target_curriculum_release_id,
            c.reference_model_configuration_id,
            m.id AS metric_set_id,
            m.version_label AS metric_set_version
           FROM ((public.calibration_analysis_scopes s
             JOIN public.calibration_evidence_contracts c ON ((c.id = s.calibration_evidence_contract_id)))
             JOIN public.calibration_metric_sets m ON ((m.id = s.calibration_metric_set_id)))
          WHERE (s.scope_key = 'physics7-u01-12a4-r2'::text)
        )
 SELECT o.contract_id,
    o.contract_version,
    o.metric_set_id,
    o.metric_set_version,
    p.recommendation_instance_id,
    p.student_id,
    p.issued_at,
    p.shown_at,
    p.clicked_at,
    p.action_started_at,
    p.policy_scope,
    p.surface,
    p.action,
    p.target_skill_id,
    p.curriculum_release_id,
    p.assessment_blueprint_id,
    p.learning_model_configuration_id,
    p.model_provenance_status,
    p.started_session_id,
    p.event_count,
    se.governance_tier,
    se.base_eligibility_reason,
    ((p.issued_at IS NOT NULL) AND (p.action_started_at IS NOT NULL) AND (p.model_provenance_status = 'exact'::text) AND (p.curriculum_release_id = o.target_curriculum_release_id) AND (p.learning_model_configuration_id = o.reference_model_configuration_id) AND COALESCE(se.recommendation_path_accuracy_eligible, false)) AS formal_eligible,
        CASE
            WHEN (p.issued_at IS NULL) THEN 'issued_event_missing'::text
            WHEN (p.action_started_at IS NULL) THEN 'server_confirmed_action_missing'::text
            WHEN (p.model_provenance_status <> 'exact'::text) THEN 'model_provenance_not_exact'::text
            WHEN (p.curriculum_release_id <> o.target_curriculum_release_id) THEN 'release_mismatch'::text
            WHEN (p.learning_model_configuration_id <> o.reference_model_configuration_id) THEN 'model_mismatch'::text
            WHEN (se.learning_session_id IS NULL) THEN 'started_session_unclassified'::text
            WHEN (NOT se.recommendation_path_accuracy_eligible) THEN se.base_eligibility_reason
            ELSE 'eligible'::text
        END AS eligibility_reason
   FROM ((paths p
     CROSS JOIN operative o)
     LEFT JOIN public.calibration_session_eligibility_v se ON ((se.learning_session_id = p.started_session_id)));

ALTER VIEW "public"."calibration_recommendation_paths_v" OWNER TO postgres;

CREATE VIEW "public"."calibration_hint_followup_v" ("contract_id", "contract_version", "metric_set_id", "metric_set_version", "pilot_run_id", "run_key", "governance_tier", "base_eligibility_reason", "learning_session_id", "student_id", "remediation_event_id", "event_at", "session_item_id", "skill_id", "item_id", "stage", "hint_level", "guide_scope", "guide_source_id", "guide_version", "guide_snapshot_id", "item_template_id", "error_code", "exact_rendered_guide_recorded", "formal_eligible", "eligibility_reason", "next_independent_attempt_id", "next_independent_attempt_at", "next_independent_correct", "followup_observed") WITH (security_invoker=true) AS
 SELECT he.contract_id,
    he.contract_version,
    he.metric_set_id,
    he.metric_set_version,
    he.pilot_run_id,
    he.run_key,
    he.governance_tier,
    he.base_eligibility_reason,
    he.learning_session_id,
    he.student_id,
    he.remediation_event_id,
    he.event_at,
    he.session_item_id,
    he.skill_id,
    he.item_id,
    he.stage,
    he.hint_level,
    he.guide_scope,
    he.guide_source_id,
    he.guide_version,
    he.guide_snapshot_id,
    he.item_template_id,
    he.error_code,
    he.exact_rendered_guide_recorded,
    he.formal_eligible,
    he.eligibility_reason,
    nxt.attempt_id AS next_independent_attempt_id,
    nxt.attempted_at AS next_independent_attempt_at,
    nxt.correct AS next_independent_correct,
    (nxt.attempt_id IS NOT NULL) AS followup_observed
   FROM (public.calibration_hint_evidence_v he
     LEFT JOIN LATERAL ( SELECT ae.attempt_id,
            ae.attempted_at,
            ae.correct
           FROM public.calibration_attempt_evidence_v ae
          WHERE ((ae.student_id = he.student_id) AND (ae.skill_id = he.skill_id) AND (ae.attempted_at > he.event_at) AND (NOT ae.hint_used))
          ORDER BY ae.attempted_at, ae.attempt_id
         LIMIT 1) nxt ON (true));

ALTER VIEW "public"."calibration_hint_followup_v" OWNER TO postgres;

CREATE VIEW "public"."calibration_item_analysis_v" ("item_id", "item_code", "item_template_id", "template_code", "difficulty", "difficulty_band", "distinct_learners", "attempt_count", "raw_correct_rate", "learner_aggregated_correct_rate", "median_response_time_ms", "hint_rate", "formal_eligible", "contract_version", "metric_set_version") WITH (security_invoker=true) AS
 SELECT item_id,
    item_code,
    item_template_id,
    template_code,
    difficulty,
    difficulty_band,
    count(DISTINCT student_id) AS distinct_learners,
    count(*) AS attempt_count,
    avg((correct)::integer) AS raw_correct_rate,
    avg(learner_correct_rate) AS learner_aggregated_correct_rate,
    percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((response_time_ms)::double precision)) AS median_response_time_ms,
    avg((hint_used)::integer) AS hint_rate,
    bool_and(item_response_formal_eligible) AS formal_eligible,
    min(contract_version) AS contract_version,
    min(metric_set_version) AS metric_set_version
   FROM ( SELECT ae.contract_id,
            ae.contract_version,
            ae.metric_set_id,
            ae.metric_set_version,
            ae.pilot_run_id,
            ae.run_key,
            ae.governance_tier,
            ae.base_formal_eligible,
            ae.base_eligibility_reason,
            ae.learning_session_id,
            ae.student_id,
            ae.unit_code,
            ae.mode,
            ae.session_status,
            ae.curriculum_release_id,
            ae.release_key,
            ae.assessment_blueprint_id,
            ae.blueprint_key,
            ae.learning_model_configuration_id,
            ae.model_version,
            ae.runtime_build_id,
            ae.runtime_build_key,
            ae.attempt_id,
            ae.attempted_at,
            ae.skill_id,
            ae.skill_code,
            ae.item_id,
            ae.item_code,
            ae.item_template_id,
            ae.item_family,
            ae.difficulty,
            ae.difficulty_band,
            ae.correct,
            ae.score,
            ae.error_code,
            ae.hint_used,
            ae.response_time_ms,
            ae.session_item_id,
            ae.ordinal,
            ae.selection_reason,
            ae.exposure_event_id,
            ae.served_at,
            ae.family_code,
            ae.template_code,
            ae.variant_key,
            ae.attempt_provenance_exact,
            ae.exposure_provenance_exact,
            ae.item_response_formal_eligible,
            ae.item_response_eligibility_reason,
            ae.repeat_pool_formal_eligible,
            ae.repeat_pool_eligibility_reason,
            ae.has_prior_incorrect_attempt,
            avg((ae.correct)::integer) OVER (PARTITION BY ae.item_id, ae.student_id) AS learner_correct_rate
           FROM public.calibration_attempt_evidence_v ae) x
  GROUP BY item_id, item_code, item_template_id, template_code, difficulty, difficulty_band;

ALTER VIEW "public"."calibration_item_analysis_v" OWNER TO postgres;

CREATE VIEW "public"."calibration_mastery_replay_v" ("contract_id", "contract_version", "metric_set_id", "metric_set_version", "pilot_run_id", "run_key", "governance_tier", "base_formal_eligible", "base_eligibility_reason", "learning_session_id", "student_id", "unit_code", "mode", "session_status", "curriculum_release_id", "release_key", "assessment_blueprint_id", "blueprint_key", "learning_model_configuration_id", "model_version", "runtime_build_id", "runtime_build_key", "attempt_id", "attempted_at", "skill_id", "skill_code", "item_id", "item_code", "item_template_id", "item_family", "difficulty", "difficulty_band", "correct", "score", "error_code", "hint_used", "response_time_ms", "session_item_id", "ordinal", "selection_reason", "exposure_event_id", "served_at", "family_code", "template_code", "variant_key", "attempt_provenance_exact", "exposure_provenance_exact", "item_response_formal_eligible", "item_response_eligibility_reason", "repeat_pool_formal_eligible", "repeat_pool_eligibility_reason", "has_prior_incorrect_attempt", "evidence_number", "difficulty_weight", "alpha_after", "beta_after", "mastery_score_after", "secure_after_attempt") WITH (security_invoker=true) AS
 WITH ordered AS (
         SELECT ae.contract_id,
            ae.contract_version,
            ae.metric_set_id,
            ae.metric_set_version,
            ae.pilot_run_id,
            ae.run_key,
            ae.governance_tier,
            ae.base_formal_eligible,
            ae.base_eligibility_reason,
            ae.learning_session_id,
            ae.student_id,
            ae.unit_code,
            ae.mode,
            ae.session_status,
            ae.curriculum_release_id,
            ae.release_key,
            ae.assessment_blueprint_id,
            ae.blueprint_key,
            ae.learning_model_configuration_id,
            ae.model_version,
            ae.runtime_build_id,
            ae.runtime_build_key,
            ae.attempt_id,
            ae.attempted_at,
            ae.skill_id,
            ae.skill_code,
            ae.item_id,
            ae.item_code,
            ae.item_template_id,
            ae.item_family,
            ae.difficulty,
            ae.difficulty_band,
            ae.correct,
            ae.score,
            ae.error_code,
            ae.hint_used,
            ae.response_time_ms,
            ae.session_item_id,
            ae.ordinal,
            ae.selection_reason,
            ae.exposure_event_id,
            ae.served_at,
            ae.family_code,
            ae.template_code,
            ae.variant_key,
            ae.attempt_provenance_exact,
            ae.exposure_provenance_exact,
            ae.item_response_formal_eligible,
            ae.item_response_eligibility_reason,
            ae.repeat_pool_formal_eligible,
            ae.repeat_pool_eligibility_reason,
            ae.has_prior_incorrect_attempt,
            row_number() OVER (PARTITION BY ae.student_id, ae.skill_id ORDER BY ae.attempted_at, ae.attempt_id) AS evidence_number,
            (0.8 + (0.1 * (GREATEST(1, LEAST(5, (ae.difficulty)::integer)))::numeric)) AS difficulty_weight
           FROM public.calibration_attempt_evidence_v ae
          WHERE ae.item_response_formal_eligible
        ), replay AS (
         SELECT o.contract_id,
            o.contract_version,
            o.metric_set_id,
            o.metric_set_version,
            o.pilot_run_id,
            o.run_key,
            o.governance_tier,
            o.base_formal_eligible,
            o.base_eligibility_reason,
            o.learning_session_id,
            o.student_id,
            o.unit_code,
            o.mode,
            o.session_status,
            o.curriculum_release_id,
            o.release_key,
            o.assessment_blueprint_id,
            o.blueprint_key,
            o.learning_model_configuration_id,
            o.model_version,
            o.runtime_build_id,
            o.runtime_build_key,
            o.attempt_id,
            o.attempted_at,
            o.skill_id,
            o.skill_code,
            o.item_id,
            o.item_code,
            o.item_template_id,
            o.item_family,
            o.difficulty,
            o.difficulty_band,
            o.correct,
            o.score,
            o.error_code,
            o.hint_used,
            o.response_time_ms,
            o.session_item_id,
            o.ordinal,
            o.selection_reason,
            o.exposure_event_id,
            o.served_at,
            o.family_code,
            o.template_code,
            o.variant_key,
            o.attempt_provenance_exact,
            o.exposure_provenance_exact,
            o.item_response_formal_eligible,
            o.item_response_eligibility_reason,
            o.repeat_pool_formal_eligible,
            o.repeat_pool_eligibility_reason,
            o.has_prior_incorrect_attempt,
            o.evidence_number,
            o.difficulty_weight,
            ((2)::numeric + sum(((GREATEST((0)::numeric, LEAST((1)::numeric, o.score)) * o.difficulty_weight) *
                CASE
                    WHEN (o.hint_used AND (o.score > (0)::numeric)) THEN 0.65
                    ELSE (1)::numeric
                END)) OVER (PARTITION BY o.student_id, o.skill_id ORDER BY o.attempted_at, o.attempt_id)) AS alpha_after,
            ((2)::numeric + sum((((1)::numeric - GREATEST((0)::numeric, LEAST((1)::numeric, o.score))) * o.difficulty_weight)) OVER (PARTITION BY o.student_id, o.skill_id ORDER BY o.attempted_at, o.attempt_id)) AS beta_after
           FROM ordered o
        )
 SELECT contract_id,
    contract_version,
    metric_set_id,
    metric_set_version,
    pilot_run_id,
    run_key,
    governance_tier,
    base_formal_eligible,
    base_eligibility_reason,
    learning_session_id,
    student_id,
    unit_code,
    mode,
    session_status,
    curriculum_release_id,
    release_key,
    assessment_blueprint_id,
    blueprint_key,
    learning_model_configuration_id,
    model_version,
    runtime_build_id,
    runtime_build_key,
    attempt_id,
    attempted_at,
    skill_id,
    skill_code,
    item_id,
    item_code,
    item_template_id,
    item_family,
    difficulty,
    difficulty_band,
    correct,
    score,
    error_code,
    hint_used,
    response_time_ms,
    session_item_id,
    ordinal,
    selection_reason,
    exposure_event_id,
    served_at,
    family_code,
    template_code,
    variant_key,
    attempt_provenance_exact,
    exposure_provenance_exact,
    item_response_formal_eligible,
    item_response_eligibility_reason,
    repeat_pool_formal_eligible,
    repeat_pool_eligibility_reason,
    has_prior_incorrect_attempt,
    evidence_number,
    difficulty_weight,
    alpha_after,
    beta_after,
    (alpha_after / (alpha_after + beta_after)) AS mastery_score_after,
    ((evidence_number >= 3) AND ((alpha_after / (alpha_after + beta_after)) >= 0.72)) AS secure_after_attempt
   FROM replay r;

ALTER VIEW "public"."calibration_mastery_replay_v" OWNER TO postgres;

CREATE VIEW "public"."calibration_practice_burden_v" ("student_id", "skill_id", "contract_version", "metric_set_version", "practice_sessions", "practice_attempts", "independent_attempts", "hinted_attempts", "active_learning_response_time_ms", "completed_sessions", "censored_sessions", "formal_eligible", "eligibility_reasons") WITH (security_invoker=true) AS
 SELECT se.student_id,
    se.target_skill_id AS skill_id,
    se.contract_version,
    se.metric_set_version,
    count(DISTINCT se.learning_session_id) AS practice_sessions,
    count(ae.attempt_id) AS practice_attempts,
    count(ae.attempt_id) FILTER (WHERE (NOT ae.hint_used)) AS independent_attempts,
    count(ae.attempt_id) FILTER (WHERE ae.hint_used) AS hinted_attempts,
    COALESCE(sum(ae.response_time_ms), (0)::bigint) AS active_learning_response_time_ms,
    count(DISTINCT se.learning_session_id) FILTER (WHERE (se.session_status = 'completed'::text)) AS completed_sessions,
    count(DISTINCT se.learning_session_id) FILTER (WHERE (se.session_status <> 'completed'::text)) AS censored_sessions,
    bool_and(se.practice_burden_eligible) AS formal_eligible,
    array_agg(DISTINCT se.base_eligibility_reason) AS eligibility_reasons
   FROM (public.calibration_session_eligibility_v se
     LEFT JOIN public.calibration_attempt_evidence_v ae ON ((ae.learning_session_id = se.learning_session_id)))
  WHERE (se.mode = 'practice'::text)
  GROUP BY se.student_id, se.target_skill_id, se.contract_version, se.metric_set_version;

ALTER VIEW "public"."calibration_practice_burden_v" OWNER TO postgres;

CREATE VIEW "public"."calibration_recent_recovery_events_v" ("student_id", "skill_id", "recovery_attempt_id", "recovery_at", "learning_session_id", "window_attempts", "window_unique_items", "window_independent_correct", "next_independent_attempt_id", "next_independent_attempt_at", "next_independent_correct", "followup_observed", "formal_eligible", "eligibility_reason", "contract_version", "metric_set_version", "release_key", "blueprint_key", "model_version", "runtime_build_key") WITH (security_invoker=true) AS
 WITH ordered AS (
         SELECT ae.contract_id,
            ae.contract_version,
            ae.metric_set_id,
            ae.metric_set_version,
            ae.pilot_run_id,
            ae.run_key,
            ae.governance_tier,
            ae.base_formal_eligible,
            ae.base_eligibility_reason,
            ae.learning_session_id,
            ae.student_id,
            ae.unit_code,
            ae.mode,
            ae.session_status,
            ae.curriculum_release_id,
            ae.release_key,
            ae.assessment_blueprint_id,
            ae.blueprint_key,
            ae.learning_model_configuration_id,
            ae.model_version,
            ae.runtime_build_id,
            ae.runtime_build_key,
            ae.attempt_id,
            ae.attempted_at,
            ae.skill_id,
            ae.skill_code,
            ae.item_id,
            ae.item_code,
            ae.item_template_id,
            ae.item_family,
            ae.difficulty,
            ae.difficulty_band,
            ae.correct,
            ae.score,
            ae.error_code,
            ae.hint_used,
            ae.response_time_ms,
            ae.session_item_id,
            ae.ordinal,
            ae.selection_reason,
            ae.exposure_event_id,
            ae.served_at,
            ae.family_code,
            ae.template_code,
            ae.variant_key,
            ae.attempt_provenance_exact,
            ae.exposure_provenance_exact,
            ae.item_response_formal_eligible,
            ae.item_response_eligibility_reason,
            ae.repeat_pool_formal_eligible,
            ae.repeat_pool_eligibility_reason,
            ae.has_prior_incorrect_attempt,
            row_number() OVER (PARTITION BY ae.student_id, ae.skill_id ORDER BY ae.attempted_at, ae.attempt_id) AS rn
           FROM public.calibration_attempt_evidence_v ae
        ), windows AS (
         SELECT cur.contract_id,
            cur.contract_version,
            cur.metric_set_id,
            cur.metric_set_version,
            cur.pilot_run_id,
            cur.run_key,
            cur.governance_tier,
            cur.base_formal_eligible,
            cur.base_eligibility_reason,
            cur.learning_session_id,
            cur.student_id,
            cur.unit_code,
            cur.mode,
            cur.session_status,
            cur.curriculum_release_id,
            cur.release_key,
            cur.assessment_blueprint_id,
            cur.blueprint_key,
            cur.learning_model_configuration_id,
            cur.model_version,
            cur.runtime_build_id,
            cur.runtime_build_key,
            cur.attempt_id,
            cur.attempted_at,
            cur.skill_id,
            cur.skill_code,
            cur.item_id,
            cur.item_code,
            cur.item_template_id,
            cur.item_family,
            cur.difficulty,
            cur.difficulty_band,
            cur.correct,
            cur.score,
            cur.error_code,
            cur.hint_used,
            cur.response_time_ms,
            cur.session_item_id,
            cur.ordinal,
            cur.selection_reason,
            cur.exposure_event_id,
            cur.served_at,
            cur.family_code,
            cur.template_code,
            cur.variant_key,
            cur.attempt_provenance_exact,
            cur.exposure_provenance_exact,
            cur.item_response_formal_eligible,
            cur.item_response_eligibility_reason,
            cur.repeat_pool_formal_eligible,
            cur.repeat_pool_eligibility_reason,
            cur.has_prior_incorrect_attempt,
            cur.rn,
            count(prev.attempt_id) AS window_attempts,
            count(DISTINCT prev.item_id) AS window_unique_items,
            count(prev.attempt_id) FILTER (WHERE (prev.correct AND (NOT prev.hint_used))) AS window_independent_correct
           FROM (ordered cur
             JOIN ordered prev ON (((prev.student_id = cur.student_id) AND (prev.skill_id = cur.skill_id) AND ((prev.rn >= (cur.rn - 4)) AND (prev.rn <= cur.rn)))))
          GROUP BY cur.contract_id, cur.contract_version, cur.metric_set_id, cur.metric_set_version, cur.pilot_run_id, cur.run_key, cur.governance_tier, cur.base_formal_eligible, cur.base_eligibility_reason, cur.learning_session_id, cur.student_id, cur.unit_code, cur.mode, cur.session_status, cur.curriculum_release_id, cur.release_key, cur.assessment_blueprint_id, cur.blueprint_key, cur.learning_model_configuration_id, cur.model_version, cur.runtime_build_id, cur.runtime_build_key, cur.attempt_id, cur.attempted_at, cur.skill_id, cur.skill_code, cur.item_id, cur.item_code, cur.item_template_id, cur.item_family, cur.difficulty, cur.difficulty_band, cur.correct, cur.score, cur.error_code, cur.hint_used, cur.response_time_ms, cur.session_item_id, cur.ordinal, cur.selection_reason, cur.exposure_event_id, cur.served_at, cur.family_code, cur.template_code, cur.variant_key, cur.attempt_provenance_exact, cur.exposure_provenance_exact, cur.item_response_formal_eligible, cur.item_response_eligibility_reason, cur.repeat_pool_formal_eligible, cur.repeat_pool_eligibility_reason, cur.has_prior_incorrect_attempt, cur.rn
        ), qualified AS (
         SELECT w.contract_id,
            w.contract_version,
            w.metric_set_id,
            w.metric_set_version,
            w.pilot_run_id,
            w.run_key,
            w.governance_tier,
            w.base_formal_eligible,
            w.base_eligibility_reason,
            w.learning_session_id,
            w.student_id,
            w.unit_code,
            w.mode,
            w.session_status,
            w.curriculum_release_id,
            w.release_key,
            w.assessment_blueprint_id,
            w.blueprint_key,
            w.learning_model_configuration_id,
            w.model_version,
            w.runtime_build_id,
            w.runtime_build_key,
            w.attempt_id,
            w.attempted_at,
            w.skill_id,
            w.skill_code,
            w.item_id,
            w.item_code,
            w.item_template_id,
            w.item_family,
            w.difficulty,
            w.difficulty_band,
            w.correct,
            w.score,
            w.error_code,
            w.hint_used,
            w.response_time_ms,
            w.session_item_id,
            w.ordinal,
            w.selection_reason,
            w.exposure_event_id,
            w.served_at,
            w.family_code,
            w.template_code,
            w.variant_key,
            w.attempt_provenance_exact,
            w.exposure_provenance_exact,
            w.item_response_formal_eligible,
            w.item_response_eligibility_reason,
            w.repeat_pool_formal_eligible,
            w.repeat_pool_eligibility_reason,
            w.has_prior_incorrect_attempt,
            w.rn,
            w.window_attempts,
            w.window_unique_items,
            w.window_independent_correct,
            ((w.window_attempts = 5) AND (w.window_unique_items >= 4) AND (w.window_independent_correct >= 4)) AS recovery_qualified
           FROM windows w
        ), events AS (
         SELECT q.contract_id,
            q.contract_version,
            q.metric_set_id,
            q.metric_set_version,
            q.pilot_run_id,
            q.run_key,
            q.governance_tier,
            q.base_formal_eligible,
            q.base_eligibility_reason,
            q.learning_session_id,
            q.student_id,
            q.unit_code,
            q.mode,
            q.session_status,
            q.curriculum_release_id,
            q.release_key,
            q.assessment_blueprint_id,
            q.blueprint_key,
            q.learning_model_configuration_id,
            q.model_version,
            q.runtime_build_id,
            q.runtime_build_key,
            q.attempt_id,
            q.attempted_at,
            q.skill_id,
            q.skill_code,
            q.item_id,
            q.item_code,
            q.item_template_id,
            q.item_family,
            q.difficulty,
            q.difficulty_band,
            q.correct,
            q.score,
            q.error_code,
            q.hint_used,
            q.response_time_ms,
            q.session_item_id,
            q.ordinal,
            q.selection_reason,
            q.exposure_event_id,
            q.served_at,
            q.family_code,
            q.template_code,
            q.variant_key,
            q.attempt_provenance_exact,
            q.exposure_provenance_exact,
            q.item_response_formal_eligible,
            q.item_response_eligibility_reason,
            q.repeat_pool_formal_eligible,
            q.repeat_pool_eligibility_reason,
            q.has_prior_incorrect_attempt,
            q.rn,
            q.window_attempts,
            q.window_unique_items,
            q.window_independent_correct,
            q.recovery_qualified,
            COALESCE(lag(q.recovery_qualified) OVER (PARTITION BY q.student_id, q.skill_id ORDER BY q.rn), false) AS prior_qualified
           FROM qualified q
        )
 SELECT e.student_id,
    e.skill_id,
    e.attempt_id AS recovery_attempt_id,
    e.attempted_at AS recovery_at,
    e.learning_session_id,
    e.window_attempts,
    e.window_unique_items,
    e.window_independent_correct,
    nxt.attempt_id AS next_independent_attempt_id,
    nxt.attempted_at AS next_independent_attempt_at,
    nxt.correct AS next_independent_correct,
    (nxt.attempt_id IS NOT NULL) AS followup_observed,
    (e.base_formal_eligible AND e.recovery_qualified AND (NOT e.prior_qualified)) AS formal_eligible,
        CASE
            WHEN (NOT e.base_formal_eligible) THEN e.base_eligibility_reason
            WHEN ((NOT e.recovery_qualified) OR e.prior_qualified) THEN 'not_new_recovery_event'::text
            WHEN (nxt.attempt_id IS NULL) THEN 'eligible_recovery_followup_pending'::text
            ELSE 'eligible'::text
        END AS eligibility_reason,
    e.contract_version,
    e.metric_set_version,
    e.release_key,
    e.blueprint_key,
    e.model_version,
    e.runtime_build_key
   FROM (events e
     LEFT JOIN LATERAL ( SELECT x.attempt_id,
            x.attempted_at,
            x.correct
           FROM ordered x
          WHERE ((x.student_id = e.student_id) AND (x.skill_id = e.skill_id) AND (x.rn > e.rn) AND (NOT x.hint_used))
          ORDER BY x.rn
         LIMIT 1) nxt ON (true))
  WHERE (e.recovery_qualified AND (NOT e.prior_qualified));

ALTER VIEW "public"."calibration_recent_recovery_events_v" OWNER TO postgres;

CREATE VIEW "public"."calibration_repeat_influence_v" ("student_id", "learning_session_id", "mode", "exposure_attempts", "repeat_or_exhaustion_attempts", "repeat_or_exhaustion_rate", "repeat_correct_rate", "nonrepeat_correct_rate", "formal_eligible", "contract_version", "metric_set_version") WITH (security_invoker=true) AS
 SELECT student_id,
    learning_session_id,
    mode,
    count(*) AS exposure_attempts,
    count(*) FILTER (WHERE ((selection_reason ~~ '%repeat%'::text) OR (selection_reason ~~ '%exhaust%'::text))) AS repeat_or_exhaustion_attempts,
    avg((((selection_reason ~~ '%repeat%'::text) OR (selection_reason ~~ '%exhaust%'::text)))::integer) AS repeat_or_exhaustion_rate,
    avg((correct)::integer) FILTER (WHERE ((selection_reason ~~ '%repeat%'::text) OR (selection_reason ~~ '%exhaust%'::text))) AS repeat_correct_rate,
    avg((correct)::integer) FILTER (WHERE ((selection_reason IS NULL) OR ((selection_reason !~~ '%repeat%'::text) AND (selection_reason !~~ '%exhaust%'::text)))) AS nonrepeat_correct_rate,
    bool_and(repeat_pool_formal_eligible) AS formal_eligible,
    min(contract_version) AS contract_version,
    min(metric_set_version) AS metric_set_version
   FROM public.calibration_attempt_evidence_v
  GROUP BY student_id, learning_session_id, mode;

ALTER VIEW "public"."calibration_repeat_influence_v" OWNER TO postgres;

CREATE VIEW "public"."calibration_mastery_trajectory_v" ("student_id", "skill_id", "contract_version", "metric_set_version", "attempts_observed", "independent_attempts", "hinted_attempts", "trajectory_started_at", "trajectory_last_at", "attempts_to_first_secure", "first_secure_at", "secure_event_observed", "right_censored", "elapsed_seconds_to_secure") WITH (security_invoker=true) AS
 SELECT student_id,
    skill_id,
    min(contract_version) AS contract_version,
    min(metric_set_version) AS metric_set_version,
    count(*) AS attempts_observed,
    count(*) FILTER (WHERE (NOT hint_used)) AS independent_attempts,
    count(*) FILTER (WHERE hint_used) AS hinted_attempts,
    min(attempted_at) AS trajectory_started_at,
    max(attempted_at) AS trajectory_last_at,
    min(evidence_number) FILTER (WHERE secure_after_attempt) AS attempts_to_first_secure,
    min(attempted_at) FILTER (WHERE secure_after_attempt) AS first_secure_at,
    bool_or(secure_after_attempt) AS secure_event_observed,
    (NOT bool_or(secure_after_attempt)) AS right_censored,
    EXTRACT(epoch FROM (min(attempted_at) FILTER (WHERE secure_after_attempt) - min(attempted_at))) AS elapsed_seconds_to_secure
   FROM public.calibration_mastery_replay_v
  GROUP BY student_id, skill_id;

ALTER VIEW "public"."calibration_mastery_trajectory_v" OWNER TO postgres;

CREATE VIEW "public"."calibration_metric_observations_v" ("metric_key", "observation_id", "student_id", "learning_session_id", "skill_id", "item_id", "item_template_id", "observed_at", "governance_tier", "formal_eligible", "eligibility_reason", "right_censored", "contract_version", "metric_set_version", "release_key", "blueprint_key", "model_version", "runtime_build_key") WITH (security_invoker=true) AS
 SELECT metric_key,
    observation_id,
    student_id,
    learning_session_id,
    skill_id,
    item_id,
    item_template_id,
    observed_at,
    governance_tier,
    formal_eligible,
    eligibility_reason,
    right_censored,
    contract_version,
    metric_set_version,
    release_key,
    blueprint_key,
    model_version,
    runtime_build_key
   FROM ( SELECT 'practice_burden'::text AS metric_key,
            (se.learning_session_id)::text AS observation_id,
            se.student_id,
            se.learning_session_id,
            se.target_skill_id AS skill_id,
            NULL::uuid AS item_id,
            NULL::uuid AS item_template_id,
            se.started_at AS observed_at,
            se.governance_tier,
            se.practice_burden_eligible AS formal_eligible,
                CASE
                    WHEN se.practice_burden_eligible THEN 'eligible'::text
                    ELSE se.base_eligibility_reason
                END AS eligibility_reason,
            (se.session_status <> 'completed'::text) AS right_censored,
            se.contract_version,
            se.metric_set_version,
            se.release_key,
            se.blueprint_key,
            se.model_version,
            se.runtime_build_key
           FROM public.calibration_session_eligibility_v se
          WHERE (se.mode = 'practice'::text)
        UNION ALL
         SELECT 'mastery_evidence_to_secure'::text,
            (((t.student_id)::text || ':'::text) || (t.skill_id)::text),
            t.student_id,
            NULL::uuid,
            t.skill_id,
            NULL::uuid,
            NULL::uuid,
            t.trajectory_started_at,
            'core_calibration'::text,
            true,
            'eligible'::text,
            t.right_censored,
            t.contract_version,
            t.metric_set_version,
            NULL::text,
            NULL::text,
            NULL::text,
            NULL::text
           FROM public.calibration_mastery_trajectory_v t
        UNION ALL
         SELECT 'hint_assistance_effect'::text,
            (h.remediation_event_id)::text AS remediation_event_id,
            h.student_id,
            h.learning_session_id,
            h.skill_id,
            h.item_id,
            h.item_template_id,
            h.event_at,
            h.governance_tier,
            h.formal_eligible,
            h.eligibility_reason,
            false,
            h.contract_version,
            h.metric_set_version,
            NULL::text,
            NULL::text,
            NULL::text,
            NULL::text
           FROM public.calibration_hint_evidence_v h
        UNION ALL
         SELECT 'item_difficulty_response_time'::text,
            (a.attempt_id)::text AS attempt_id,
            a.student_id,
            a.learning_session_id,
            a.skill_id,
            a.item_id,
            a.item_template_id,
            a.attempted_at,
            a.governance_tier,
            a.item_response_formal_eligible,
            a.item_response_eligibility_reason,
            false,
            a.contract_version,
            a.metric_set_version,
            a.release_key,
            a.blueprint_key,
            a.model_version,
            a.runtime_build_key
           FROM public.calibration_attempt_evidence_v a
        UNION ALL
         SELECT 'repeat_pool_exhaustion_influence'::text,
            (a.attempt_id)::text AS attempt_id,
            a.student_id,
            a.learning_session_id,
            a.skill_id,
            a.item_id,
            a.item_template_id,
            a.attempted_at,
            a.governance_tier,
            a.repeat_pool_formal_eligible,
            a.repeat_pool_eligibility_reason,
            false,
            a.contract_version,
            a.metric_set_version,
            a.release_key,
            a.blueprint_key,
            a.model_version,
            a.runtime_build_key
           FROM public.calibration_attempt_evidence_v a
        UNION ALL
         SELECT 'threshold_sensitivity'::text,
            (a.attempt_id)::text AS attempt_id,
            a.student_id,
            a.learning_session_id,
            a.skill_id,
            a.item_id,
            a.item_template_id,
            a.attempted_at,
            a.governance_tier,
            a.item_response_formal_eligible,
            a.item_response_eligibility_reason,
            false,
            a.contract_version,
            a.metric_set_version,
            a.release_key,
            a.blueprint_key,
            a.model_version,
            a.runtime_build_key
           FROM public.calibration_attempt_evidence_v a
        UNION ALL
         SELECT 'recent_recovery_stability'::text,
            (r.recovery_attempt_id)::text AS recovery_attempt_id,
            r.student_id,
            r.learning_session_id,
            r.skill_id,
            NULL::uuid,
            NULL::uuid,
            r.recovery_at,
                CASE
                    WHEN r.formal_eligible THEN 'core_calibration'::text
                    ELSE 'excluded'::text
                END AS "case",
            r.formal_eligible,
            r.eligibility_reason,
            (NOT r.followup_observed),
            r.contract_version,
            r.metric_set_version,
            r.release_key,
            r.blueprint_key,
            r.model_version,
            r.runtime_build_key
           FROM public.calibration_recent_recovery_events_v r
        UNION ALL
         SELECT 'recommendation_path_accuracy'::text,
            (p.recommendation_instance_id)::text AS recommendation_instance_id,
            p.student_id,
            p.started_session_id,
            p.target_skill_id,
            NULL::uuid,
            NULL::uuid,
            p.issued_at,
            COALESCE(p.governance_tier, 'excluded'::text) AS "coalesce",
            p.formal_eligible,
            p.eligibility_reason,
            false,
            p.contract_version,
            p.metric_set_version,
            NULL::text,
            NULL::text,
            NULL::text,
            NULL::text
           FROM public.calibration_recommendation_paths_v p
        UNION ALL
         SELECT 'diagnostic_predictive_alignment'::text,
            (se.learning_session_id)::text AS learning_session_id,
            se.student_id,
            se.learning_session_id,
            se.target_skill_id,
            NULL::uuid,
            NULL::uuid,
            se.completed_at,
            se.governance_tier,
            false,
                CASE
                    WHEN (NOT se.diagnostic_predictive_alignment_eligible) THEN se.base_eligibility_reason
                    ELSE 'downstream_outcome_required'::text
                END AS "case",
            false,
            se.contract_version,
            se.metric_set_version,
            se.release_key,
            se.blueprint_key,
            se.model_version,
            se.runtime_build_key
           FROM public.calibration_session_eligibility_v se
          WHERE (se.mode = 'diagnostic'::text)
        UNION ALL
         SELECT 'mastery_check_outcome'::text,
            (se.learning_session_id)::text AS learning_session_id,
            se.student_id,
            se.learning_session_id,
            se.target_skill_id,
            NULL::uuid,
            NULL::uuid,
            se.completed_at,
            se.governance_tier,
            se.mastery_check_outcome_eligible,
                CASE
                    WHEN se.mastery_check_outcome_eligible THEN 'eligible'::text
                    ELSE se.base_eligibility_reason
                END AS base_eligibility_reason,
            false,
            se.contract_version,
            se.metric_set_version,
            se.release_key,
            se.blueprint_key,
            se.model_version,
            se.runtime_build_key
           FROM public.calibration_session_eligibility_v se
          WHERE (se.mode = 'mastery_check'::text)
        UNION ALL
         SELECT 'mastery_check_skill_failure'::text,
            (a.attempt_id)::text AS attempt_id,
            a.student_id,
            a.learning_session_id,
            a.skill_id,
            a.item_id,
            a.item_template_id,
            a.attempted_at,
            a.governance_tier,
            (a.base_formal_eligible AND (a.mode = 'mastery_check'::text) AND (a.session_status = 'completed'::text)),
                CASE
                    WHEN (a.base_formal_eligible AND (a.mode = 'mastery_check'::text) AND (a.session_status = 'completed'::text)) THEN 'eligible'::text
                    ELSE a.base_eligibility_reason
                END AS base_eligibility_reason,
            false,
            a.contract_version,
            a.metric_set_version,
            a.release_key,
            a.blueprint_key,
            a.model_version,
            a.runtime_build_key
           FROM public.calibration_attempt_evidence_v a
          WHERE (a.mode = 'mastery_check'::text)) q;

ALTER VIEW "public"."calibration_metric_observations_v" OWNER TO postgres;

CREATE VIEW "public"."calibration_decision_evidence_snapshot_v" ("analysis_scope_id", "scope_key", "contract_version", "metric_set_version", "pilot_run_key", "pilot_status", "metric_key", "formal_observation_count", "learner_count", "learner_skill_count", "session_count", "skill_count", "first_formal_observation_at", "last_formal_observation_at", "automatically_sufficient", "sufficiency_status") WITH (security_invoker=true) AS
 WITH operative AS (
         SELECT s.id AS analysis_scope_id,
            s.scope_key,
            c.version_label AS contract_version,
            m.id AS metric_set_id,
            m.version_label AS metric_set_version,
            p.run_key AS pilot_run_key,
            p.status AS pilot_status,
            jsonb_object_keys(m.definitions) AS metric_key
           FROM (((public.calibration_analysis_scopes s
             JOIN public.calibration_evidence_contracts c ON ((c.id = s.calibration_evidence_contract_id)))
             JOIN public.calibration_metric_sets m ON ((m.id = s.calibration_metric_set_id)))
             JOIN public.pilot_runs p ON ((p.id = s.pilot_run_id)))
          WHERE (s.scope_key = 'physics7-u01-12a4-r2'::text)
        ), observed AS (
         SELECT calibration_metric_observations_v.metric_key,
            count(*) FILTER (WHERE calibration_metric_observations_v.formal_eligible) AS formal_observation_count,
            count(DISTINCT calibration_metric_observations_v.student_id) FILTER (WHERE calibration_metric_observations_v.formal_eligible) AS learner_count,
            count(DISTINCT ROW(calibration_metric_observations_v.student_id, calibration_metric_observations_v.skill_id)) FILTER (WHERE calibration_metric_observations_v.formal_eligible) AS learner_skill_count,
            count(DISTINCT calibration_metric_observations_v.learning_session_id) FILTER (WHERE calibration_metric_observations_v.formal_eligible) AS session_count,
            count(DISTINCT calibration_metric_observations_v.skill_id) FILTER (WHERE calibration_metric_observations_v.formal_eligible) AS skill_count,
            min(calibration_metric_observations_v.observed_at) FILTER (WHERE calibration_metric_observations_v.formal_eligible) AS first_formal_observation_at,
            max(calibration_metric_observations_v.observed_at) FILTER (WHERE calibration_metric_observations_v.formal_eligible) AS last_formal_observation_at
           FROM public.calibration_metric_observations_v
          GROUP BY calibration_metric_observations_v.metric_key
        )
 SELECT o.analysis_scope_id,
    o.scope_key,
    o.contract_version,
    o.metric_set_version,
    o.pilot_run_key,
    o.pilot_status,
    o.metric_key,
    COALESCE(x.formal_observation_count, (0)::bigint) AS formal_observation_count,
    COALESCE(x.learner_count, (0)::bigint) AS learner_count,
    COALESCE(x.learner_skill_count, (0)::bigint) AS learner_skill_count,
    COALESCE(x.session_count, (0)::bigint) AS session_count,
    COALESCE(x.skill_count, (0)::bigint) AS skill_count,
    x.first_formal_observation_at,
    x.last_formal_observation_at,
    false AS automatically_sufficient,
    'human_metric_specific_review_required'::text AS sufficiency_status
   FROM (operative o
     LEFT JOIN observed x ON ((x.metric_key = o.metric_key)));

ALTER VIEW "public"."calibration_decision_evidence_snapshot_v" OWNER TO postgres;

CREATE VIEW "public"."calibration_metric_sample_summary_v" ("metric_key", "contract_version", "metric_set_version", "observations_total", "observations_formal", "observations_context_only", "observations_excluded", "distinct_learners", "learner_skill_trajectories", "sessions", "skills", "items", "item_templates", "window_start", "window_end", "right_censored_observations", "release_keys", "blueprint_keys", "model_versions", "runtime_builds") WITH (security_invoker=true) AS
 WITH metric_catalog(metric_key) AS (
         VALUES ('practice_burden'::text), ('mastery_evidence_to_secure'::text), ('hint_assistance_effect'::text), ('item_difficulty_response_time'::text), ('repeat_pool_exhaustion_influence'::text), ('threshold_sensitivity'::text), ('diagnostic_predictive_alignment'::text), ('mastery_check_outcome'::text), ('mastery_check_skill_failure'::text), ('recent_recovery_stability'::text), ('recommendation_path_accuracy'::text)
        )
 SELECT mc.metric_key,
    max(o.contract_version) AS contract_version,
    max(o.metric_set_version) AS metric_set_version,
    count(o.observation_id) AS observations_total,
    count(o.observation_id) FILTER (WHERE o.formal_eligible) AS observations_formal,
    count(o.observation_id) FILTER (WHERE (o.governance_tier = 'context_only'::text)) AS observations_context_only,
    count(o.observation_id) FILTER (WHERE (o.governance_tier = 'excluded'::text)) AS observations_excluded,
    count(DISTINCT o.student_id) AS distinct_learners,
    count(DISTINCT ROW(o.student_id, o.skill_id)) FILTER (WHERE (o.skill_id IS NOT NULL)) AS learner_skill_trajectories,
    count(DISTINCT o.learning_session_id) AS sessions,
    count(DISTINCT o.skill_id) AS skills,
    count(DISTINCT o.item_id) AS items,
    count(DISTINCT o.item_template_id) AS item_templates,
    min(o.observed_at) AS window_start,
    max(o.observed_at) AS window_end,
    count(o.observation_id) FILTER (WHERE o.right_censored) AS right_censored_observations,
    COALESCE(array_agg(DISTINCT o.release_key) FILTER (WHERE (o.release_key IS NOT NULL)), '{}'::text[]) AS release_keys,
    COALESCE(array_agg(DISTINCT o.blueprint_key) FILTER (WHERE (o.blueprint_key IS NOT NULL)), '{}'::text[]) AS blueprint_keys,
    COALESCE(array_agg(DISTINCT o.model_version) FILTER (WHERE (o.model_version IS NOT NULL)), '{}'::text[]) AS model_versions,
    COALESCE(array_agg(DISTINCT o.runtime_build_key) FILTER (WHERE (o.runtime_build_key IS NOT NULL)), '{}'::text[]) AS runtime_builds
   FROM (metric_catalog mc
     LEFT JOIN public.calibration_metric_observations_v o ON ((o.metric_key = mc.metric_key)))
  GROUP BY mc.metric_key;

ALTER VIEW "public"."calibration_metric_sample_summary_v" OWNER TO postgres;

